-- [Cmd_estoque_dia : TADOCommand]
insert into  estoque_produto_dia (Epd_data,Epd_hora,Epd_Codnosso,Epd_Acabamento,Epd_estoque,EstTp_Codigo)
select :data, :hora, Epr_Codnosso,Epr_Acabamento,Epr_estoque, estoque_produto.EstTp_Codigo from estoque_produto where Epr_estoque <> 0

-- [Qryobras : TADOQuery]
SELECT  dbo.Municipio.mun_nome     , dbo.Municipio.mun_nome AS cidadecor, dbo.Obras.Cli_codigo, dbo.Obras.Obr_Descricao, dbo.Obras.Obr_Endereco, dbo.Obras.Obr_numero, 
                         dbo.Obras.Obr_complemento, dbo.Obras.Obr_Bairro, dbo.Obras.Obr_CEP, dbo.Obras.Obr_Codigo, dbo.Municipio.mun_uf, dbo.Clientes.Cli_Nome, 
                         dbo.CategoriaCliente.CatCli_Descricao,
Clientes.Cli_TipoConsumidor, dbo.Clientes.cli_isento

FROM            dbo.Obras INNER JOIN
                         dbo.Clientes ON dbo.Obras.Cli_codigo = dbo.Clientes.Cli_Codigo LEFT OUTER JOIN
                         dbo.CategoriaCliente ON dbo.Clientes.CatCli_Codigo = dbo.CategoriaCliente.CatCli_Codigo LEFT OUTER JOIN
                         dbo.Municipio ON dbo.Obras.mun_codigo = dbo.Municipio.mun_codigo
where Obras.obr_codigo=:codigo

-- [QryProdutosValores_log : TADOQuery]
select * from Preco_Produto_Log where PreLog_Codnosso=''

-- [QryValorCredito : TADOQuery]
SELECT     (SELECT     SUM(Credito_Valor) AS TotalCred
                       FROM          dbo.Credito AS C1
                       WHERE      (Credito_TipoVinculo = dbo.Credito.Credito_TipoVinculo) AND (Credito_CodigoVinculo = dbo.Credito.Credito_CodigoVinculo) AND 
                                              (Credito_Operacao = 'C') AND (Credito_Situacao = 'A')) AS SomaCred,
                          (SELECT     SUM(Credito_Valor) AS TotalDebit
                            FROM          dbo.Credito AS C2
                            WHERE      (Credito_TipoVinculo = dbo.Credito.Credito_TipoVinculo) AND (Credito_CodigoVinculo = dbo.Credito.Credito_CodigoVinculo) AND 
                                                   (Credito_Operacao = 'D') AND (Credito_Situacao = 'A')) AS SomaDebit
FROM        Credito
WHERE     (Credito.Credito_TipoVinculo =:PCredito_TipoVinculo) and Credito.Credito_Situacao='A' and Credito.Credito_CodigoVinculo=:PCredito_CodigoVinculo

-- [BDS_banc_caixa : TADOQuery]
SELECT     dbo.Contas_Bancarias.Cba_codigo, dbo.Contas_Bancarias.Bcx_codigo, dbo.Contas_Bancarias.Emp_codigo, dbo.Bancos_Caixas.Bcx_Nome, 
                      dbo.Contas_Bancarias.Cba_numero, dbo.Contas_Bancarias.Cba_numero + ' - ' + dbo.Bancos_Caixas.Bcx_Nome AS nome_conta
FROM         dbo.Bancos_Caixas INNER JOIN
                      dbo.Contas_Bancarias ON dbo.Bancos_Caixas.Bcx_codigo = dbo.Contas_Bancarias.Bcx_codigo AND 
                      dbo.Bancos_Caixas.Bcx_codigo = dbo.Contas_Bancarias.Bcx_codigo AND dbo.Bancos_Caixas.Bcx_codigo = dbo.Contas_Bancarias.Bcx_codigo AND 
                      dbo.Bancos_Caixas.Bcx_codigo = dbo.Contas_Bancarias.Bcx_codigo AND dbo.Bancos_Caixas.Emp_codigo = dbo.Contas_Bancarias.Emp_codigo AND
                       dbo.Bancos_Caixas.Emp_codigo = dbo.Contas_Bancarias.Emp_codigo AND 
                      dbo.Bancos_Caixas.Emp_codigo = dbo.Contas_Bancarias.Emp_codigo AND dbo.Bancos_Caixas.Emp_codigo = dbo.Contas_Bancarias.Emp_codigo

