   FORM: DMAcertoComEletrecistas   
   ============================================================ */

-- [badoEletrecistas : TBetterADODataSet]
SELECT Fun_CPF, Fun_Nome
, fun_codigo FROM Funcionario WHERE COD_ATIVID = 52
 ORDER BY Fun_Nome

-- [badoProjetos : TBetterADODataSet]
SELECT DISTINCT dbo.acerto_eletrecistas.ael_codigo, dbo.Venda.Ven_codigo, dbo.Venda.Ven_CodigoPre, dbo.Venda.Ven_CodVinculo, dbo.Venda.Ven_DataEmissao, 
                      dbo.Venda.Ven_DescontoPorcServ, dbo.Venda.ParSV_serie, dbo.Clientes.Cli_Nome
FROM         dbo.VendaServico INNER JOIN
                      dbo.Venda ON dbo.VendaServico.Ven_codigopre = dbo.Venda.Ven_CodigoPre INNER JOIN
                      dbo.Clientes ON dbo.Venda.Ven_CodVinculo = dbo.Clientes.Cli_Codigo FULL OUTER JOIN
                      dbo.acerto_eletrecistas ON dbo.Venda.Ven_codigo = dbo.acerto_eletrecistas.ped_ped_codigo
WHERE     (venda.Ven_Eletricista = :CodEletricista) 
AND (venda.ven_situacao = 'A') and venda.ven_tipo ='P'
AND (acerto_eletrecistas.ael_codigo IS NULL) and Venda.ParSV_serie < 3
 ORDER BY VENDA.ven_codigo desc

-- [badoPesquisaAcertos : TBetterADODataSet]
SELECT     TOP (100) PERCENT dbo.acerto_eletrecistas.ael_codigo, dbo.acerto_eletrecistas.ael_concluido, dbo.acerto_eletrecistas.ped_ped_codigo, dbo.Venda.Ven_CodigoPre, 
                      dbo.Funcionario.Fun_Nome, dbo.Clientes.Cli_Nome, venda.ParSV_serie
FROM         dbo.acerto_eletrecistas INNER JOIN
                      dbo.Venda ON dbo.acerto_eletrecistas.ped_ped_codigo = dbo.Venda.Ven_codigo and acerto_eletrecistas.ParSV_serie = Venda.ParSV_serie INNER JOIN
                      dbo.Funcionario ON dbo.Venda.Ven_Eletricista = dbo.Funcionario.Fun_codigo INNER JOIN
                      dbo.Clientes ON dbo.Venda.Ven_CodVinculo = dbo.Clientes.Cli_Codigo
WHERE     (dbo.Venda.Ven_Situacao = 'A')  and venda.ven_tipo ='P'
 ORDER BY dbo.acerto_eletrecistas.ael_codigo desc

-- [badoDadosAcerto : TBetterADODataSet]
SELECT     dbo.Venda.Ven_codigo, dbo.Funcionario.Fun_Nome, dbo.Venda.ParSV_serie, dbo.Clientes.Cli_Nome, dbo.Obras.Obr_Descricao
FROM         dbo.Venda LEFT OUTER JOIN
                      dbo.Clientes ON dbo.Venda.Ven_CodVinculo = dbo.Clientes.Cli_Codigo LEFT OUTER JOIN
                      dbo.Funcionario ON dbo.Venda.Ven_Eletricista = dbo.Funcionario.Fun_codigo LEFT OUTER JOIN
                      dbo.Obras ON dbo.Venda.Obr_codigo = dbo.Obras.Obr_Codigo
WHERE     (dbo.Venda.Ven_Situacao = 'A') AND (dbo.Venda.Ven_codigo = :CodPedido) AND (dbo.Venda.Ven_Tipo = 'P')

-- [badoAcerto : TBetterADODataSet]
SELECT * FROM acerto_eletrecistas 
WHERE ael_codigo = :ael_codigo

-- [badoAcertoDetalhe : TBetterADODataSet]
SELECT * FROM acerto_eletrecistas_det

-- [badoServicosAcerto : TBetterADODataSet]
SELECT * FROM acerto_eletrecistas_servicos
 WHERE ped_codigo_pre = :CodPedido

-- [badoSelecionaServicos : TBetterADODataSet]
SELECT     VendaServico.ven_codigopre, VendaServico.VenSer_quantidade, VendaServico.VenSer_VlEletricista, VendaServico.VenSer_item,
                      venda.ven_codigo, Servicos.Serv_tipo, VendaServico.Sev_cod,Servicos.Serv_Desc,Venda.ParSV_serie,
VendaServico.VenSer_DescPorc, Servicos.Serv_Pc_Eletricista
FROM  VendaServico INNER JOIN
                      venda ON VendaServico.ven_codigopre = venda.ven_codigopre INNER JOIN
                      Servicos ON VendaServico.Sev_cod = Servicos.sev_cod
WHERE     (venda.ven_codigo =:CodPedido) AND (Servicos.Serv_tipo = 'ELETRICISTA') AND (venda.ven_situacao = 'A') 
and venda.ven_tipo ='P'
 ORDER BY VendaServico.VenSer_item


