-- [Qryprodutos : TADOQuery]
SELECT     dbo.produtos.Pro_AliqICMS, dbo.produtos.Trib_Codigo, dbo.produtos.Pro_codnosso, dbo.ProdutosFornecedores.For_codigo, 
                      dbo.produtos.Pro_tp_produto, dbo.produtos.Pro_tp_peca, dbo.produtos.Pro_descricao, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto
, dbo.produtosfornecedores.ProdFor_CodigoProduto, dbo.produtos.Pro_foto, dbo.produtos.Pro_unidade, dbo.produtos.GrupoProduto_codigo, dbo.produtos.Pro_CodEspecial, dbo.produtos.Pro_lamp_reator, 
                      dbo.produtos.pro_tempoInstalacao, dbo.GrupoProduto.GrupoProduto_Descricao, dbo.produtos.Pro_ativo, dbo.fornecedor.For_Nome
,produtos.pro_ncm, Pro_CodReduzido,produtosfornecedores.ProdFor_Situacao
FROM         dbo.produtos INNER JOIN
	     dbo.ProdutosFornecedores ON dbo.produtos.Pro_codnosso = ProdutosFornecedores.Pro_codnosso INNER JOIN
                      dbo.fornecedor ON dbo.produtosfornecedores.For_codigo = dbo.fornecedor.For_codigo LEFT OUTER JOIN
                      dbo.GrupoProduto ON dbo.produtos.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo

where  produtos.For_codigo =:forne and  produtos.GrupoProduto_codigo <>:produto 
and ProdutosFornecedores.ProdFor_Situacao =  1
ORDER BY produtos.Pro_codnosso

-- [Qryacabamento : TADOQuery]
SELECT * FROM Acabamento

-- [Qrypreco : TADOQuery]
SELECT  produtos.Pro_codnosso, ProdutosFornecedores.ProdFor_CodigoProduto, ProdutosFornecedores.For_codigo, produtos.GrupoProduto_codigo, produtos.Pro_tp_peca, 
                produtos.Pro_descricao, produtos.Pro_quant_minima, produtos.Pro_unidade, Preco_Produto.Pre_Venda, 
                Preco_Produto.Pre_Acabamento, Estoque_produto.Epr_estoque, ProdutosFornecedores.ProdFor_prazo_entrega, Preco_Produto.Pre_Codindice
FROM      produtos WITH (NOLOCK) INNER JOIN
                ProdutosFornecedores ON produtos.Pro_codnosso = ProdutosFornecedores.Pro_codnosso INNER JOIN
                Preco_Produto WITH (NOLOCK) ON ProdutosFornecedores.Pro_codnosso = Preco_Produto.Pre_Codnosso INNER JOIN
                Estoque_produto WITH (NOLOCK) ON Preco_Produto.Pre_Acabamento = Estoque_produto.Epr_Acabamento AND 
                Preco_Produto.Pre_Codnosso = Estoque_produto.Epr_Codnosso 

WHERE (((produtos.Pro_codnosso)=:PRODUTO))  AND Preco_Produto.pre_ativo='S'
and Estoque_produto.EstTp_Codigo=1 and ProdutosFornecedores.ProdFor_Situacao=1 and ProdFor_Padrao=1

-- [Qryinclusao : TADOQuery]
SELECT * FROM produtos WITH (NOLOCK)

-- [Qryfornecedor : TADOQuery]
select * from fornecedor  WITH (NOLOCK) where for_classificacao = 'F' order by For_nome

-- [Qryrelacionado : TADOQuery]
SELECT        dbo.ProdutosRelacionadosDet.Pro_codnosso, dbo.ProdutosRelacionadosDet.CodAcabamento, dbo.ProdutosRelacionadosDet.ProdRelDet_Quantidade, dbo.ProdutosRelacionadosDet.ProdRelDet_padrao, 
                         dbo.ProdutosRelacionadosCadProdutos.ProdRelCadProd_situacao, dbo.ProdutosRelacionadosCadProdutos.ProdRelCadProd_padrao, dbo.produtos.GrupoProduto_codigo, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, 
                         dbo.ProdutosFornecedores.ProdFor_DescricaoProduto, dbo.fornecedor.For_Nome, dbo.produtos.Pro_tp_peca, dbo.produtos.Pro_descricao, dbo.produtos.Pro_unidade, dbo.produtos.Pro_CodReduzido, 
                         dbo.produtos.Pro_CodEspecial, dbo.Preco_Produto.Pre_Venda, dbo.GrupoProduto.GrupoProduto_Descricao
FROM            dbo.ProdutosRelacionadosCadProdutos INNER JOIN
                         dbo.ProdutosRelacionados ON dbo.ProdutosRelacionadosCadProdutos.ProdRel_codigo = dbo.ProdutosRelacionados.ProdRel_codigo AND 
                         dbo.ProdutosRelacionadosCadProdutos.Emp_codigo = dbo.ProdutosRelacionados.Emp_codigo INNER JOIN
                         dbo.ProdutosRelacionadosDet ON dbo.ProdutosRelacionados.ProdRel_codigo = dbo.ProdutosRelacionadosDet.ProdRel_codigo AND 
                         dbo.ProdutosRelacionados.Emp_codigo = dbo.ProdutosRelacionadosDet.Emp_codigo INNER JOIN
                         dbo.produtos ON dbo.ProdutosRelacionadosDet.Pro_codnosso = dbo.produtos.Pro_codnosso AND dbo.ProdutosRelacionadosDet.Emp_codigo = dbo.produtos.Emp_codigo INNER JOIN
                         dbo.ProdutosFornecedores ON dbo.produtos.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso INNER JOIN
                         dbo.fornecedor ON dbo.ProdutosFornecedores.For_codigo = dbo.fornecedor.For_codigo INNER JOIN
                         dbo.Preco_Produto ON dbo.ProdutosRelacionadosDet.Pro_codnosso = dbo.Preco_Produto.Pre_Codnosso AND dbo.ProdutosRelacionadosDet.CodAcabamento = dbo.Preco_Produto.Pre_Acabamento INNER JOIN
                         dbo.GrupoProduto ON dbo.produtos.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo

WHERE        (dbo.ProdutosRelacionadosDet.ProdRelDet_padrao = 1) AND (dbo.ProdutosRelacionadosCadProdutos.ProdRelCadProd_situacao = 1) AND (dbo.ProdutosRelacionadosCadProdutos.ProdRelCadProd_padrao = 1)
and dbo.ProdutosRelacionadosCadProdutos.Pro_codnosso =:pPro_codnosso  and  produtos.GrupoProduto_codigo in (:pGrupoProduto_codigo)
and  (dbo.ProdutosFornecedores.ProdFor_Padrao = 1) AND (dbo.ProdutosFornecedores.ProdFor_Situacao = 1)

