SELECT Indice_preco.Ipr_descricao,Indice_preco.for_codigo, Indice_preco.Ipr_Indice,Indice_preco.Ipr_desconto,Indice_preco.Ipr_vl_com_inter,Indice_preco.Ipr_vl_com_exter ,Custo.Cus_Nome, 
Custo.Cus_desconto1, Custo.Cus_desconto2, Custo.Cus_desconto3, Custo.Cus_desconto4, Custo.Cus_IPI, Custo.Cus_Frete, Custo.Cus_Icms, Custo.Cus_Embalagens, Custo.Cus_Financeira, Custo.Cus_Simples, Custo.Cus_outros 
,Custo.Cus_IcmsDESTINO,Custo.Cus_MargValAgreg,Custo.Cus_TributacaoICMS, Custo.Cus_importacao, Custo.Cus_cambio ,
Custo.Cus_TpVlNFo,Custo.Cus_NFoICMS, Custo.Cus_NFoOutros  , Custo.Cus_NFoIPI , Custo.Cus_NFoSimples , Custo.Cus_NFoEmbalagem , Custo.Cus_NFoFinanceiro ,Custo.Cus_NFoFrete ,Custo.Cus_NFoDesconto
FROM Indice_preco INNER JOIN Custo ON Indice_preco.Ipr_custo = Custo.Cus_codigo 
where Indice_preco.for_codigo =:fornecedor and Indice_preco.Ipr_descricao=:descricao

-- [QryDescAcabamento : TADOQuery]
SELECT     

case when acab_tipo =  'E' then 'Ext.:' else
case when acab_tipo =  'T' then 'Ext. e Inter.:' else
''
end
end   + DescAcabamento + '  ' + case when acab_tipo2 =  'I' then 'Inter.:' else '' end + case when DescAcabamento2 is null then '' else DescAcabamento2 end

as descricao




FROM           dbo.Acabamento 
WHERE    CodAcabamento =:pCodAcabamento


/* ============================================================
   FORM: FrmAlterarDataEntrega   Alterar Data de Entrega
   ============================================================ */

-- [QryAlterar : TADOQuery]
SELECT dbo.VendaProduto.Pro_codnosso, dbo.VendaProduto.CodAcabamento, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto, dbo.VendaProduto.VenPro_DataEntrega
FROM     dbo.VendaProduto INNER JOIN
                  dbo.ProdutosFornecedores ON dbo.VendaProduto.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso
where VendaProduto.Ven_CodigoPre =:pVen_CodigoPre

GROUP BY dbo.VendaProduto.Pro_codnosso, dbo.VendaProduto.CodAcabamento, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto, dbo.VendaProduto.VenPro_DataEntrega

-- [QryGravar : TADOQuery]
SELECT dbo.VendaProduto.Pro_codnosso, dbo.VendaProduto.CodAcabamento, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto, dbo.VendaProduto.VenPro_DataEntrega
FROM     dbo.VendaProduto INNER JOIN
                  dbo.ProdutosFornecedores ON dbo.VendaProduto.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso
where VendaProduto.Ven_CodigoPre =:pVen_CodigoPre

GROUP BY dbo.VendaProduto.Pro_codnosso, dbo.VendaProduto.CodAcabamento, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto, dbo.VendaProduto.VenPro_DataEntrega


