-- [QryForma_pag : TADOQuery]
SELECT  Forma_Pagamento_Parcela.*, Forma_Pagamento.* 
FROM Forma_Pagamento INNER JOIN Forma_Pagamento_Parcela ON Forma_Pagamento.Fpg_codigo = Forma_Pagamento_Parcela.Fpg_codigo 
where Forma_Pagamento.Fpg_codigo=:codigo order by Forma_Pagamento_Parcela.Fpp_parcela

