-- [Qryestoque_ma : TADOQuery]
SELECT max(avulso_materiais_det.ama_codindice) as ama_codindice  , avulso_materiais_det.Pro_codnosso, avulso_materiais_det.ama_acabamento, Sum([avulso_materiais_det].[ama_quantidade]) AS total, avulso_materiais_det.avu_codigo_pre,Estoque_produto.Epr_estoque
FROM avulso_materiais_det INNER JOIN Estoque_produto ON (avulso_materiais_det.ama_acabamento = Estoque_produto.Epr_Acabamento) AND (avulso_materiais_det.Pro_codnosso = Estoque_produto.Epr_Codnosso)
where avulso_materiais_det.avu_codigo_pre=:codigo
and Estoque_produto.EstTp_Codigo=1


GROUP BY avulso_materiais_det.Pro_codnosso, avulso_materiais_det.ama_acabamento, avulso_materiais_det.avu_codigo_pre, Estoque_produto.Epr_estoque, avulso_materiais_det.avu_codigo_pre

-- [Qryestoque_lu : TADOQuery]
SELECT     max(Avulso_luminaria_det.ald_codindice) as ald_codindice, dbo.Avulso_luminaria_det.avu_codigo_pre, dbo.Avulso_luminaria_det.Pro_codnosso, 
                      dbo.Avulso_luminaria_det.ald_acabamento, SUM(dbo.Avulso_luminaria_det.ald_quantidade) AS total, dbo.Estoque_produto.Epr_estoque
FROM         dbo.Avulso_luminaria_det INNER JOIN
                      dbo.Estoque_produto ON dbo.Avulso_luminaria_det.Pro_codnosso = dbo.Estoque_produto.Epr_Codnosso AND 
                      dbo.Avulso_luminaria_det.ald_acabamento = dbo.Estoque_produto.Epr_Acabamento
where      (Avulso_luminaria_det.avu_codigo_pre =:codigo) 
and Estoque_produto.EstTp_Codigo=1
GROUP BY dbo.Avulso_luminaria_det.avu_codigo_pre, dbo.Avulso_luminaria_det.Pro_codnosso, dbo.Avulso_luminaria_det.ald_acabamento, 
                      dbo.Estoque_produto.Epr_estoque

-- [ADOQuery1 : TADOQuery]
SELECT pedido_luminaria_det.ped_codigo_pre, pedido_luminaria_det.Pro_codnosso, pedido_luminaria_det.pld_acabamento, ((Sum(pedido_luminaria_det.pld_quantidade))) AS total,Estoque_produto.Epr_estoque
FROM pedido_luminaria_det INNER JOIN Estoque_produto ON (pedido_luminaria_det.Pro_codnosso = Estoque_produto.Epr_Codnosso) AND (pedido_luminaria_det.pld_acabamento = Estoque_produto.Epr_Acabamento)
GROUP BY pedido_luminaria_det.ped_codigo_pre, pedido_luminaria_det.Pro_codnosso, pedido_luminaria_det.pld_acabamento, Estoque_produto.Epr_estoque
HAVING pedido_luminaria_det.ped_codigo_pre=:codigo

-- [ADOQuery2 : TADOQuery]
SELECT pedido_materiais_det.Pro_codnosso, pedido_materiais_det.pma_acabamento, (Sum([pedido_materiais_det].[pma_quantidade]))AS total, pedido_materiais_det.ped_codigo_pre,[Estoque_produto].[Epr_estoque] 
FROM pedido_materiais_det INNER JOIN Estoque_produto ON (pedido_materiais_det.pma_acabamento = Estoque_produto.Epr_Acabamento) AND (pedido_materiais_det.Pro_codnosso = Estoque_produto.Epr_Codnosso)
GROUP BY pedido_materiais_det.Pro_codnosso, pedido_materiais_det.pma_acabamento, pedido_materiais_det.ped_codigo_pre, Estoque_produto.Epr_estoque, pedido_materiais_det.ped_codigo_pre
having pedido_materiais_det.ped_codigo_pre=:codigo

