SELECT top 1        dbo.unidades.uni_descricao, dbo.GrupoProduto.GrupoProduto_Descricao, dbo.ProdutosFornecedores.ProdFor_CodigoProduto AS Pro_Codbase, dbo.produtos.Pro_descricao, ProdutosFornecedores.ProdFor_DescricaoProduto as Pro_descricao_for, 
                         dbo.produtos.Pro_CodEspecial, dbo.fornecedor.For_Nome, dbo.TipoPeca.TpPeca_Codigo, dbo.produtos.Pro_unidade, dbo.produtos.Pro_codnosso, dbo.Preco_Produto.Pre_Acabamento, 
                         dbo.ProdutosFornecedores.ProdFor_DescricaoProduto
FROM            dbo.ProdutosFornecedores INNER JOIN
