                  dbo.Bancos_Caixas.Bcx_Nome, dbo.Bancos.Ban_Codigo, dbo.Bancos.Ban_Nome, dbo.Contas_Bancarias.Cba_CodigoCedente, dbo.Contas_BancariasCobranca.CbaCob_SistemaCobranca, dbo.Contas_Bancarias.Cba_DigitoConta, 
                  dbo.Bancos_Caixas.Bcx_DigitoAgencia, dbo.Contas_Bancarias.Cba_CodigoTransmissao, dbo.Contas_Bancarias.Cba_CodigoModalidade, dbo.Contas_Bancarias.CbaLayoutremessa, 
                  dbo.Contas_BancariasCobranca.CbaCob_CodigoInstrucao1, dbo.Contas_BancariasCobranca.CbaCob_CodigoInstrucao2, dbo.Contas_BancariasCobranca.CbaCob_Instrucao, dbo.Contas_BancariasCobranca.CbaCob_ValorMulta, 
                  dbo.Contas_BancariasCobranca.CbaCob_DataMulta, dbo.Contas_BancariasCobranca.CbaCob_ValorDesconto, dbo.Contas_BancariasCobranca.CbaCob_DataDesconto, dbo.Contas_BancariasCobranca.CbaCob_ValorAbatimento, 
                  dbo.Contas_BancariasCobranca.CbaCob_DataAbatimento, dbo.Contas_BancariasCobranca.CbaCob_PorcentagemMulta, dbo.Contas_BancariasCobranca.CbaCob_DataProtesto

,dbo.Contas_BancariasCobranca.CbaCob_DiasMulta, 
                  dbo.Contas_BancariasCobranca.CbaCob_DiasDesconto, dbo.Contas_BancariasCobranca.CbaCob_DiasAbatimento, dbo.Contas_BancariasCobranca.CbaCob_DiasProtesto



FROM            dbo.Contas_Bancarias INNER JOIN
                         dbo.Contas_BancariasCobranca ON dbo.Contas_Bancarias.Cba_codigo = dbo.Contas_BancariasCobranca.Cba_codigo AND dbo.Contas_Bancarias.Bcx_codigo = dbo.Contas_BancariasCobranca.Bcx_codigo AND 
                         dbo.Contas_Bancarias.Emp_codigo = dbo.Contas_BancariasCobranca.Emp_codigo INNER JOIN
                         dbo.Bancos_Caixas ON dbo.Contas_Bancarias.Bcx_codigo = dbo.Bancos_Caixas.Bcx_codigo AND dbo.Contas_Bancarias.Bcx_codigo = dbo.Bancos_Caixas.Bcx_codigo AND 
                         dbo.Contas_Bancarias.Bcx_codigo = dbo.Bancos_Caixas.Bcx_codigo AND dbo.Contas_Bancarias.Bcx_codigo = dbo.Bancos_Caixas.Bcx_codigo AND 
                         dbo.Contas_Bancarias.Emp_codigo = dbo.Bancos_Caixas.Emp_codigo AND dbo.Contas_Bancarias.Emp_codigo = dbo.Bancos_Caixas.Emp_codigo AND 
                         dbo.Contas_Bancarias.Emp_codigo = dbo.Bancos_Caixas.Emp_codigo AND dbo.Contas_Bancarias.Emp_codigo = dbo.Bancos_Caixas.Emp_codigo INNER JOIN
                         dbo.Bancos ON dbo.Bancos_Caixas.Ban_codigo = dbo.Bancos.Ban_Codigo

where Contas_BancariasCobranca.CbaCob_codigo =:pCbaCob_codigo

ORDER BY dbo.Bancos.Ban_Nome

