-- [QryRESERVA : TADOQuery]
SELECT     dbo.ordem_compra.Ocp_dt_envio, dbo.Reserva_Estoque.Res_Ordem, dbo.Reserva_Estoque.Res_Projeto, dbo.Reserva_Estoque.Res_VendaAvulsa, 
                      dbo.Reserva_Estoque.Res_CodigoProduto, dbo.Reserva_Estoque.Res_Acabamento, dbo.Reserva_Estoque.Res_Quantidade, 
                      dbo.ordem_compra.Ocp_fornecedor, dbo.pedido.cli_codigo, dbo.Avulso.cli_codigo AS cli_codigo_avulsa, dbo.produtos.Pro_descricao, 
                      dbo.ordem_compra_det.Ocd_quantidade_solicit,Reserva_Estoque.Res_Ordemitem
FROM         dbo.pedido RIGHT OUTER JOIN
                      dbo.ordem_compra_det INNER JOIN
                      dbo.ordem_compra ON dbo.ordem_compra_det.Ocp_codigo = dbo.ordem_compra.Ocp_codigo INNER JOIN
                      dbo.produtos INNER JOIN
                      dbo.Reserva_Estoque ON dbo.produtos.Pro_codnosso = dbo.Reserva_Estoque.Res_CodigoProduto ON 
                      dbo.ordem_compra_det.Ocp_codigo = dbo.Reserva_Estoque.Res_Ordem AND 
                      dbo.ordem_compra_det.Ocd_item = dbo.Reserva_Estoque.Res_OrdemItem LEFT OUTER JOIN
                      dbo.Avulso ON dbo.Reserva_Estoque.Res_VendaAvulsa = dbo.Avulso.avu_codigo ON 
                      dbo.pedido.ped_codigo = dbo.Reserva_Estoque.Res_Projeto
WHERE     (dbo.ordem_compra.Ocp_status = 'A')


