-- [Qrycliente : TADOQuery]
SELECT TOP (100) PERCENT dbo.Clientes.Cli_Codigo, dbo.Clientes.Cli_Nome
FROM     dbo.Assistencia_Tecnica INNER JOIN
                  dbo.Clientes ON dbo.Assistencia_Tecnica.Cli_Codigo = dbo.Clientes.Cli_Codigo
GROUP BY dbo.Clientes.Cli_Codigo, dbo.Clientes.Cli_Nome
ORDER BY dbo.Clientes.Cli_Nome

-- [QryAssistencia : TADOQuery]
SELECT TOP (100) PERCENT dbo.Clientes.Cli_Codigo, dbo.Clientes.Cli_Nome, dbo.Venda.Ven_codigo, dbo.Venda.ParSV_serie, dbo.Assistencia_Tecnica.ASTEC_Codigo, dbo.Assistencia_Tecnica.ASTEC_Data, 
                  dbo.Assistencia_Tecnica.ASTEC_Situacao
FROM     dbo.Assistencia_Tecnica INNER JOIN
                  dbo.Clientes ON dbo.Assistencia_Tecnica.Cli_Codigo = dbo.Clientes.Cli_Codigo INNER JOIN
                  dbo.Venda ON dbo.Assistencia_Tecnica.Ven_CodigoPre = dbo.Venda.Ven_CodigoPre
WHERE  (dbo.Assistencia_Tecnica.ASTEC_Situacao = 1) and Clientes.Cli_Codigo =:pcli_codigo
ORDER BY Assistencia_Tecnica.ASTEC_Codigo

-- [QryProdutos : TADOQuery]
SELECT dbo.Assistencia_Tecnica.Ven_CodigoPre, dbo.Assistencia_Tecnica.ASTEC_Codigo, dbo.Assistencia_TecnicaProdutos.ASTECProd_Codigo, dbo.Assistencia_TecnicaProdutos.Pro_codnosso, 
                  dbo.Assistencia_TecnicaProdutos.CodAcabamento, dbo.Assistencia_TecnicaProdutos.ASTECProd_quantidade,
                      (SELECT TOP (1) Pre_Venda
                       FROM      dbo.Preco_Produto
                       WHERE   (Pre_Codnosso = dbo.Assistencia_TecnicaProdutos.Pro_codnosso) AND (Pre_Acabamento = dbo.Assistencia_TecnicaProdutos.CodAcabamento) AND (Pre_Ativo = 'S')) AS Pre_Venda
FROM     dbo.Assistencia_Tecnica INNER JOIN
                  dbo.Assistencia_TecnicaProdutos ON dbo.Assistencia_Tecnica.ASTEC_Codigo = dbo.Assistencia_TecnicaProdutos.ASTEC_Codigo
where Assistencia_Tecnica.ASTEC_Codigo =:pASTEC_Codigo

