                         dbo.Contas_BancariasCobranca.CbaCob_MensagemLocalPag, dbo.Bancos_Caixas.Bcx_agencia, dbo.Bancos_Caixas.Bcx_Nome, dbo.Bancos.Ban_Codigo, dbo.Bancos.Ban_Nome
, Contas_Bancarias.Cba_CodigoCedente, Contas_BancariasCobranca.CbaCob_SistemaCobranca




FROM            dbo.Contas_Bancarias INNER JOIN
                         dbo.Contas_BancariasCobranca ON dbo.Contas_Bancarias.Cba_codigo = dbo.Contas_BancariasCobranca.Cba_codigo AND dbo.Contas_Bancarias.Bcx_codigo = dbo.Contas_BancariasCobranca.Bcx_codigo AND 
