                         dbo.Obras.Obr_Bairro, dbo.Obras.Obr_CEP, dbo.Obras.Obr_Codigo, dbo.Municipio.mun_uf, dbo.CategoriaCliente.CatCli_Descricao, Municipio.mun_codigo
