/* ============================================================
   FORM: FrmCon_EscolheProduto   Escolha o Produto
   ============================================================ */

-- [Qrypreco : TADOQuery]
SELECT        dbo.produtos.Pro_codnosso, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, dbo.ProdutosFornecedores.For_codigo, dbo.produtos.GrupoProduto_codigo, dbo.produtos.Pro_tp_peca, dbo.produtos.Pro_descricao, 
                         dbo.produtos.Pro_quant_minima, dbo.produtos.Pro_unidade, dbo.Preco_Produto.Pre_Venda, dbo.Preco_Produto.Pre_Acabamento, dbo.Estoque_produto.Epr_estoque, dbo.ProdutosFornecedores.ProdFor_prazo_entrega, 
                         dbo.Preco_Produto.Pre_Codindice, dbo.Preco_Produto.Tam_codigo, produtos.Pro_ForaLinha
, Preco_Produto.Pre_CodBarra

FROM            dbo.produtos WITH (NOLOCK) INNER JOIN
                         dbo.ProdutosFornecedores ON dbo.produtos.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso INNER JOIN
                         dbo.Preco_Produto WITH (NOLOCK) ON dbo.ProdutosFornecedores.Pro_codnosso = dbo.Preco_Produto.Pre_Codnosso LEFT OUTER JOIN
                         dbo.Estoque_produto WITH (NOLOCK) ON dbo.Preco_Produto.Pre_Acabamento = dbo.Estoque_produto.Epr_Acabamento AND dbo.Preco_Produto.Pre_Codnosso = dbo.Estoque_produto.Epr_Codnosso  
WHERE (((produtos.Pro_codnosso)=:PRODUTO))  AND Preco_Produto.pre_ativo='S'
and Estoque_produto.EstTp_Codigo=1 and ProdutosFornecedores.ProdFor_Padrao =1

-- [Qryfornecedor : TADOQuery]
select * from fornecedor  WITH (NOLOCK) where for_classificacao = 'F' and for_situacao ='A' order by For_nome

-- [Qryprodutos : TADOQuery]
SELECT dbo.produtos.Pro_AliqICMS, dbo.produtos.Trib_Codigo, dbo.produtos.Pro_codnosso, dbo.ProdutosFornecedores.For_codigo, dbo.produtos.Pro_tp_produto, dbo.produtos.Pro_tp_peca, dbo.produtos.Pro_descricao, 
                  dbo.ProdutosFornecedores.ProdFor_DescricaoProduto, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, dbo.produtos.Pro_foto, dbo.produtos.Pro_unidade, dbo.produtos.GrupoProduto_codigo, dbo.produtos.Pro_CodEspecial, 
                  dbo.produtos.Pro_lamp_reator, dbo.produtos.pro_tempoInstalacao, dbo.GrupoProduto.GrupoProduto_Descricao, dbo.produtos.Pro_ativo, dbo.fornecedor.For_Nome, dbo.produtos.pro_NCM, dbo.produtos.Pro_CodReduzido, 
                  (CASE WHEN
                      (SELECT Promocao.Prom_Codigo
                       FROM      dbo.Promocao INNER JOIN
                                         dbo.PromocaoProdutos ON dbo.Promocao.Prom_Codigo = dbo.PromocaoProdutos.Prom_Codigo
                       WHERE   dbo.Promocao.Prom_DataInicial <= getdate() AND dbo.Promocao.Prom_DataFinal >= getdate() AND (dbo.PromocaoProdutos.Pro_codnosso = produtos.Pro_codnosso)) > 0 THEN 1 ELSE 0 END) AS comissao, 
                  dbo.produtos.Pro_ForaLinha, dbo.Marca.Marca_Descricao
FROM     dbo.produtos INNER JOIN
                  dbo.ProdutosFornecedores ON dbo.produtos.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso INNER JOIN
                  dbo.fornecedor ON dbo.ProdutosFornecedores.For_codigo = dbo.fornecedor.For_codigo LEFT OUTER JOIN
                  dbo.Marca ON dbo.produtos.Marca_Codigo = dbo.Marca.Marca_Codigo LEFT OUTER JOIN
                  dbo.GrupoProduto ON dbo.produtos.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo
where  produtos.For_codigo =:forne and  produtos.GrupoProduto_codigo <>:produto ORDER BY produtos.Pro_codnosso

-- [Qryrelacionado : TADOQuery]
SELECT        dbo.ProdutosRelacionadosDet.ProdRelDet_padrao, dbo.ProdutosRelacionadosDet.Pro_codnosso, dbo.ProdutosRelacionadosDet.CodAcabamento, dbo.ProdutosRelacionadosDet.ProdRelDet_Quantidade, 
                         dbo.ProdutosFornecedores.ProdFor_CodigoProduto, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto, dbo.ProdutosFornecedores.For_codigo, dbo.ProdutosFornecedores.ProdFor_Padrao, 
                         dbo.ProdutosFornecedores.ProdFor_CodigoBarra, dbo.produtos.Pro_descricao, dbo.produtos.Pro_tp_peca, dbo.produtos.Pro_tp_produto, dbo.produtos.Pro_unidade, dbo.produtos.Pro_AliqICMS, 
                         dbo.produtos.pro_NCM, dbo.fornecedor.For_Nome, dbo.GrupoProduto.GrupoProduto_Descricao, dbo.produtos.GrupoProduto_codigo, Preco_Produto.Pre_Venda,produtos.pro_tempoInstalacao,
Pro_lamp_reator, Pro_CodEspecial, Pre_codindice,
Pro_CodReduzido, Preco_Produto.tam_codigo
FROM            dbo.ProdutosRelacionadosCadProdutos INNER JOIN
                         dbo.ProdutosRelacionados ON dbo.ProdutosRelacionadosCadProdutos.ProdRel_codigo = dbo.ProdutosRelacionados.ProdRel_codigo INNER JOIN
                         dbo.ProdutosRelacionadosDet ON dbo.ProdutosRelacionados.ProdRel_codigo = dbo.ProdutosRelacionadosDet.ProdRel_codigo INNER JOIN
                         dbo.produtos ON dbo.ProdutosRelacionadosDet.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                         dbo.ProdutosFornecedores ON dbo.produtos.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso INNER JOIN
                         dbo.Preco_Produto ON dbo.produtos.Pro_codnosso = dbo.Preco_Produto.Pre_Codnosso AND dbo.ProdutosRelacionadosDet.CodAcabamento = dbo.Preco_Produto.Pre_Acabamento INNER JOIN
                         dbo.GrupoProduto ON dbo.produtos.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo INNER JOIN
                         dbo.fornecedor ON dbo.ProdutosFornecedores.For_codigo = dbo.fornecedor.For_codigo
WHERE        (dbo.ProdutosRelacionadosCadProdutos.Pro_codnosso =:produto) AND (dbo.ProdutosRelacionadosCadProdutos.ProdRelCadProd_padrao = 1) AND (dbo.ProdutosRelacionados.ProdRel_Situacao = 1) AND 
                         (dbo.ProdutosRelacionadosDet.ProdRelDet_padrao = 1) AND (dbo.ProdutosFornecedores.ProdFor_Padrao = 1)

and Preco_Produto.Pre_Ativo = 'S'

