-- [Qrypromocao : TADOQuery]
SELECT        CASE WHEN
                             (SELECT        SUM(VenPro_Quantidade) AS Expr1
                               FROM            dbo.Venda INNER JOIN
                                                         dbo.VendaProduto ON dbo.Venda.Ven_CodigoPre = dbo.VendaProduto.Ven_CodigoPre
                               WHERE        (dbo.Venda.Ven_Tipo = 'P') AND (dbo.Venda.Ven_Situacao = 'A') AND (dbo.PromocaoProdutos.Prom_Codigo = prom_codigo) AND (dbo.PromocaoProdutos.Pro_codnosso = Pro_codnosso) AND 
                                                         (dbo.PromocaoProdutos.CodAcabamento = CodAcabamento)) > 0 THEN (dbo.PromocaoEstoque.PromEst_Quantidade) -
                             (SELECT        SUM(VenPro_Quantidade) AS Expr1
                               FROM            dbo.VendaProduto
                               WHERE        (dbo.PromocaoProdutos.Prom_Codigo = prom_codigo) AND (dbo.PromocaoProdutos.Pro_codnosso = Pro_codnosso) AND (dbo.PromocaoProdutos.CodAcabamento = CodAcabamento)) 
                         ELSE (PromocaoEstoque.PromEst_Quantidade) END AS QuantRest, dbo.PromocaoProdutos.PromProd_Vlpromocional, Promocao.Prom_Codigo
FROM            dbo.Promocao INNER JOIN
                         dbo.PromocaoProdutos ON dbo.Promocao.Prom_Codigo = dbo.PromocaoProdutos.Prom_Codigo INNER JOIN
                         dbo.PromocaoEstoque ON dbo.PromocaoProdutos.Prom_Codigo = dbo.PromocaoEstoque.Prom_Codigo AND dbo.PromocaoProdutos.Pro_codnosso = dbo.PromocaoEstoque.Pro_codnosso AND 
                         dbo.PromocaoProdutos.CodAcabamento = dbo.PromocaoEstoque.CodAcabamento
WHERE        dbo.Promocao.Prom_DataInicial <=:pProm_DataInicial  AND dbo.Promocao.Prom_DataFinal >=:pProm_DataFinal AND 
                         (dbo.PromocaoProdutos.Pro_codnosso =:pPro_codnosso) AND (dbo.PromocaoProdutos.CodAcabamento =:pCodAcabamento)

