SELECT        dbo.ProdutosRelacionadosCadProdutos.Pro_codnosso, dbo.ProdutosRelacionadosDet.Pro_codnosso AS Pro_codnossoFilho, dbo.ProdutosRelacionadosDet.CodAcabamento, 
                         dbo.ProdutosRelacionadosDet.ProdRelDet_Quantidade, dbo.ProdutosFornecedores.ProdFor_Padrao, dbo.ProdutosFornecedores.ProdFor_Situacao, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, 
                         dbo.ProdutosFornecedores.ProdFor_DescricaoProduto, dbo.ProdutosFornecedores.ProdFor_CodigoBarra, dbo.produtos.Pro_descricao, dbo.produtos.Pro_tp_peca, dbo.produtos.Pro_unidade, dbo.produtos.Pro_CodEspecial, 
                         dbo.GrupoProduto.GrupoProduto_Descricao, dbo.produtos.Pro_quant_minima, dbo.produtos.Pro_lamp_reator, dbo.produtos.pro_tempoInstalacao, dbo.fornecedor.For_Nome
FROM            dbo.ProdutosFornecedores INNER JOIN
                         dbo.produtos ON dbo.ProdutosFornecedores.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                         dbo.GrupoProduto ON dbo.produtos.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo INNER JOIN
                         dbo.ProdutosRelacionadosCadProdutos INNER JOIN
                         dbo.ProdutosRelacionados ON dbo.ProdutosRelacionadosCadProdutos.ProdRel_codigo = dbo.ProdutosRelacionados.ProdRel_codigo INNER JOIN
                         dbo.ProdutosRelacionadosDet ON dbo.ProdutosRelacionados.ProdRel_codigo = dbo.ProdutosRelacionadosDet.ProdRel_codigo ON dbo.produtos.Pro_codnosso = dbo.ProdutosRelacionadosDet.Pro_codnosso INNER JOIN
                         dbo.fornecedor ON dbo.ProdutosFornecedores.For_codigo = dbo.fornecedor.For_codigo
WHERE        (dbo.ProdutosRelacionadosCadProdutos.Pro_codnosso =:codigo) AND (dbo.ProdutosFornecedores.ProdFor_Padrao = 1) AND (dbo.ProdutosFornecedores.ProdFor_Situacao = 1)
order by produtos.pro_codnosso

