                         dbo.Preco_Produto.Pre_Venda, dbo.Preco_Produto.Pre_Lucro, dbo.Preco_Produto.Pre_Venda AS Expr1, dbo.Preco_Produto.Pre_Lucro AS Expr2, dbo.Preco_Produto.Pre_PorLucro, dbo.Estoque_produto.Epr_estoque
