                         dbo.produtos.Pro_unidade, dbo.Preco_Produto.Pre_Venda, dbo.Preco_Produto.Pre_Acabamento, dbo.Estoque_produto.Epr_estoque, dbo.fornecedor.For_prazo_entrega, dbo.Preco_Produto.Pre_Codindice
, Preco_Produto.Pre_PorLucro, tamanho.Tam_descricao, dbo.tamanho.Tam_codigo

FROM            dbo.produtos WITH (NOLOCK) INNER JOIN
                         dbo.Preco_Produto ON dbo.produtos.Pro_codnosso = dbo.Preco_Produto.Pre_Codnosso INNER JOIN
                         dbo.Estoque_produto WITH (NOLOCK) ON dbo.Preco_Produto.Pre_Acabamento = dbo.Estoque_produto.Epr_Acabamento AND dbo.Preco_Produto.Pre_Codnosso = dbo.Estoque_produto.Epr_Codnosso INNER JOIN
                         dbo.ProdutosFornecedores ON dbo.produtos.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso INNER JOIN
                         dbo.fornecedor WITH (NOLOCK) ON dbo.ProdutosFornecedores.For_codigo = dbo.fornecedor.For_codigo LEFT OUTER JOIN
                         dbo.tamanho ON dbo.Preco_Produto.Tam_codigo = dbo.tamanho.Tam_codigo



WHERE (((produtos.Pro_codnosso)=:PRODUTO))  AND Preco_Produto.pre_ativo='S'
