-- [Qryrelacionado : TADOQuery]
SELECT     dbo.produtos.Pro_AliqICMS, dbo.produtos.Trib_Codigo, dbo.Preco_Produto.Pre_Codindice, dbo.Produto_Relacionados.pre_nao_relacionado, 
                      dbo.Produto_Relacionados.Pre_Cod_Prod_Pai, dbo.Produto_Relacionados.pre_quantidade, dbo.produtos.Pro_codnosso, dbo.produtos.pro_tempoInstalacao, 
                      dbo.produtos.Pro_Codbase, dbo.produtos.For_codigo, dbo.produtos.GrupoProduto_codigo, dbo.produtos.Pro_lamp_reator, dbo.produtos.Pro_tp_peca, 
                      dbo.produtos.Pro_descricao, dbo.produtos.Pro_quant_minima, dbo.produtos.Pro_unidade, MAX(dbo.Preco_Produto.Pre_Acabamento) AS Pre_Acabamento, 
                      MAX(dbo.Preco_Produto.Pre_Venda) AS Pre_Venda, dbo.Produto_Relacionados.pre_padrao, dbo.Produto_Relacionados.pre_nao_relacionado AS Expr1, 
                      dbo.fornecedor.For_Nome, dbo.GrupoProduto.GrupoProduto_Descricao,produtos.Pro_descricao_for,produtos.Pro_CodEspecial
FROM         dbo.Produto_Relacionados WITH (NOLOCK) INNER JOIN
                      dbo.produtos WITH (NOLOCK) ON dbo.Produto_Relacionados.Pre_Cod_Prod_filho = dbo.produtos.Pro_codnosso AND 
                      dbo.Produto_Relacionados.pre_codigofor_filho = dbo.produtos.For_codigo INNER JOIN
                      dbo.Preco_Produto WITH (NOLOCK) ON dbo.produtos.Pro_codnosso = dbo.Preco_Produto.Pre_Codnosso INNER JOIN
                      dbo.fornecedor ON dbo.produtos.For_codigo = dbo.fornecedor.For_codigo INNER JOIN
                      dbo.GrupoProduto ON dbo.produtos.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo
where (((Produto_Relacionados.Pre_Cod_Prod_Pai)=:produto) AND ((Produto_Relacionados.pre_padrao)=:SIM))  and Produto_Relacionados.pre_codigofor_pai =:for_codigo
and Produto_Relacionados.pre_situacao is null and Preco_Produto.Pre_Ativo = 'S'
GROUP BY dbo.Produto_Relacionados.Pre_Cod_Prod_Pai, dbo.Produto_Relacionados.pre_quantidade, dbo.produtos.Pro_codnosso, dbo.produtos.Pro_Codbase, 
                      dbo.produtos.For_codigo, dbo.produtos.GrupoProduto_codigo, dbo.produtos.Pro_tp_peca, dbo.produtos.Pro_descricao, dbo.produtos.Pro_quant_minima, 
                      dbo.produtos.Pro_lamp_reator, dbo.produtos.Pro_unidade, dbo.Produto_Relacionados.pre_padrao, dbo.Produto_Relacionados.pre_nao_relacionado, 
                      dbo.Preco_Produto.Pre_Codindice, dbo.produtos.pro_tempoInstalacao, dbo.produtos.Pro_AliqICMS, dbo.produtos.Trib_Codigo, 
                      dbo.Produto_Relacionados.pre_situacao, dbo.fornecedor.For_Nome, dbo.GrupoProduto.GrupoProduto_Descricao,produtos.Pro_descricao_for,produtos.Pro_CodEspecial


