-- [Qrybanco : TADOQuery]
SELECT CAST(CAST(Bancos.Ban_Codigo AS INT) AS VARCHAR(20)) as Ban_Codigo

, dbo.Bancos.Ban_Nome, 
CAST(CAST(dbo.Bancos_Caixas.Bcx_agencia AS INT) AS VARCHAR(20)) +'-'+case when Bancos_Caixas.Bcx_DigitoAgencia is null then '0' else CAST(CAST(dbo.Bancos_Caixas.Bcx_DigitoAgencia AS INT) AS VARCHAR(20)) end as agencia
, CAST(CAST(Contas_Bancarias.Cba_numero AS INT) AS VARCHAR(20)) +'-'+ CAST(CAST(Contas_Bancarias.Cba_DigitoConta AS INT) AS VARCHAR(20)) as conta
,  dbo.Contas_Bancarias.Cba_situacao, dbo.Contas_Bancarias.Cba_codigo
FROM     dbo.Bancos INNER JOIN
                  dbo.Bancos_Caixas ON dbo.Bancos.Ban_Codigo = dbo.Bancos_Caixas.Ban_codigo INNER JOIN
                  dbo.Contas_Bancarias ON dbo.Bancos_Caixas.Bcx_codigo = dbo.Contas_Bancarias.Bcx_codigo AND dbo.Bancos_Caixas.Bcx_codigo = dbo.Contas_Bancarias.Bcx_codigo AND 
                  dbo.Bancos_Caixas.Bcx_codigo = dbo.Contas_Bancarias.Bcx_codigo AND dbo.Bancos_Caixas.Bcx_codigo = dbo.Contas_Bancarias.Bcx_codigo AND dbo.Bancos_Caixas.Emp_codigo = dbo.Contas_Bancarias.Emp_codigo AND 
                  dbo.Bancos_Caixas.Emp_codigo = dbo.Contas_Bancarias.Emp_codigo AND dbo.Bancos_Caixas.Emp_codigo = dbo.Contas_Bancarias.Emp_codigo AND dbo.Bancos_Caixas.Emp_codigo = dbo.Contas_Bancarias.Emp_codigo
ORDER BY dbo.Bancos.Ban_Nome

-- [QryBuscaBanco : TADOQuery]
SELECT CAST(CAST(Bancos.Ban_Codigo AS INT) AS VARCHAR(20)) as Ban_Codigo

, dbo.Bancos.Ban_Nome, 
CAST(CAST(dbo.Bancos_Caixas.Bcx_agencia AS INT) AS VARCHAR(20)) +'-'+case when Bancos_Caixas.Bcx_DigitoAgencia is null then '0' else CAST(CAST(dbo.Bancos_Caixas.Bcx_DigitoAgencia AS INT) AS VARCHAR(20)) end as agencia
, CAST(CAST(Contas_Bancarias.Cba_numero AS INT) AS VARCHAR(20)) +'-'+ CAST(CAST(Contas_Bancarias.Cba_DigitoConta AS INT) AS VARCHAR(20)) as conta
,  dbo.Contas_Bancarias.Cba_situacao, dbo.Contas_Bancarias.Cba_codigo
FROM     dbo.Bancos INNER JOIN
                  dbo.Bancos_Caixas ON dbo.Bancos.Ban_Codigo = dbo.Bancos_Caixas.Ban_codigo INNER JOIN
                  dbo.Contas_Bancarias ON dbo.Bancos_Caixas.Bcx_codigo = dbo.Contas_Bancarias.Bcx_codigo AND dbo.Bancos_Caixas.Bcx_codigo = dbo.Contas_Bancarias.Bcx_codigo AND 
                  dbo.Bancos_Caixas.Bcx_codigo = dbo.Contas_Bancarias.Bcx_codigo AND dbo.Bancos_Caixas.Bcx_codigo = dbo.Contas_Bancarias.Bcx_codigo AND dbo.Bancos_Caixas.Emp_codigo = dbo.Contas_Bancarias.Emp_codigo AND 
                  dbo.Bancos_Caixas.Emp_codigo = dbo.Contas_Bancarias.Emp_codigo AND dbo.Bancos_Caixas.Emp_codigo = dbo.Contas_Bancarias.Emp_codigo AND dbo.Bancos_Caixas.Emp_codigo = dbo.Contas_Bancarias.Emp_codigo

where Contas_Bancarias.Cba_codigo =:pcba_codigo

