   FORM: Frmcons_ped_ordem   Consulta de Produtos 
   ============================================================ */

-- [Qryprodutos : TADOQuery]
SELECT DISTINCT 0 as  selecionar, 
                         dbo.fornecedor.For_codigo, dbo.pedido_compra.Pcp_status, dbo.Pedido_compra_det.Pro_codnosso, dbo.Pedido_compra_det.Pcd_acabamento, dbo.Pedido_compra_det.Pcd_destino, 
                         dbo.Pedido_compra_det.Pcd_quantidade_solicit, dbo.pedido_compra.Pcp_codigo, dbo.Pedido_compra_det.pcd_codindice, dbo.pedido_compra.Pcp_ped_av_fan, dbo.pedido_compra.Pcp_pedido_venda, 
                         dbo.pedido_compra.Pcp_modo, dbo.pedido_compra.Pcp_dt_pedido, dbo.Pedido_compra_det.Pcd_item, dbo.produtos.Pro_unidade, dbo.produtos.Pro_descricao, dbo.produtos.Pro_Codbase, 
                         dbo.produtos.Pro_descricao_for, dbo.produtos.Pro_CodEspecial, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto,

CASE WHEN acab_tipo = 'E' THEN 'Ext.:' ELSE CASE WHEN acab_tipo = 'T' THEN 'Ext. e Inter.:' ELSE '' END END + dbo.Acabamento.DescAcabamento + '  ' + CASE WHEN acab_tipo2 = 'I' THEN 'Inter.:' ELSE '' END + CASE WHEN
                          DescAcabamento2 IS NULL THEN '' ELSE DescAcabamento2 END AS descricaoacabamento
, dbo.tamanho.Tam_descricao, dbo.ordem_compra_det.Tam_codigo


FROM     dbo.tamanho RIGHT OUTER JOIN
                  dbo.ordem_compra_det ON dbo.tamanho.Tam_codigo = dbo.ordem_compra_det.Tam_codigo RIGHT OUTER JOIN
                  dbo.ProdutosFornecedores INNER JOIN
                  dbo.fornecedor ON dbo.ProdutosFornecedores.For_codigo = dbo.fornecedor.For_codigo INNER JOIN
                  dbo.pedido_compra INNER JOIN
                  dbo.Pedido_compra_det ON dbo.pedido_compra.Pcp_codigo = dbo.Pedido_compra_det.Pcp_codigo INNER JOIN
                  dbo.produtos ON dbo.Pedido_compra_det.Pro_codnosso = dbo.produtos.Pro_codnosso ON dbo.ProdutosFornecedores.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                  dbo.Acabamento ON dbo.Pedido_compra_det.Pcd_acabamento = dbo.Acabamento.CodAcabamento ON dbo.ordem_compra_det.Pro_codnosso = dbo.Pedido_compra_det.Pro_codnosso AND 
                  dbo.ordem_compra_det.Ocd_acabamento = dbo.Pedido_compra_det.Pcd_acabamento AND dbo.ordem_compra_det.Ocd_item_ped = dbo.Pedido_compra_det.Pcd_item AND 
                  dbo.ordem_compra_det.Ocd_cod_pedido = dbo.Pedido_compra_det.Pcp_codigo

WHERE fornecedor.For_codigo = 4 AND pedido_compra.Pcp_status = 'A'

-- [Qryobs : TADOQuery]
select pedido_compra.Pcp_obs from pedido_compra where Pcp_codigo=:codigo

-- [Qry_ProdutosExt : TADOQuery]
SELECT    DISTINCT  dbo.fornecedor.For_codigo, dbo.OrdemCompraDetExt.Pro_codnosso, dbo.OrdemCompraDetExt.Ocdex_acabamento, dbo.produtos.Pro_descricao, dbo.Filiais.Fil_fantasia, 
                      dbo.OrdemCompraExt.Ocpex_status, dbo.OrdemCompraDetExt.Pro_codnosso AS Expr1, dbo.OrdemCompraDetExt.Ocdex_acabamento AS Expr2, 
                      dbo.OrdemCompraDetExt.Ocdex_destino, dbo.OrdemCompraDetExt.Ocdex_quantidade_solicit, dbo.OrdemCompraExt.Ocpex_codigo, 
                      dbo.OrdemCompraDetExt.ocdex_codindice, dbo.OrdemCompraDetExt.ocdex_ped_av_fan, dbo.OrdemCompraExt.Ocpex_modo, 
                      dbo.OrdemCompraDetExt.Ocdex_dt_ped_compra, dbo.OrdemCompraDetExt.Ocdex_item, dbo.OrdemCompraDetExt.Ocdex_cod_venda, 
                      dbo.produtos.Pro_unidade, dbo.produtos.Pro_Codbase,  dbo.OrdemCompraDetExt.Ocdex_cod_venda, dbo.OrdemCompraDetExt.Ocpex_codigo, 
                      dbo.OrdemCompraDetExt.Ocpex_cnpj,  dbo.OrdemCompraDetExt.Ocdex_item  , produtos.Pro_descricao_for, produtos.Pro_CodEspecial 
FROM         dbo.fornecedor INNER JOIN
                      dbo.Filiais INNER JOIN
                      dbo.OrdemCompraExt INNER JOIN
                      dbo.OrdemCompraDetExt ON dbo.OrdemCompraExt.Ocpex_codigo = dbo.OrdemCompraDetExt.Ocpex_codigo AND 
                      dbo.OrdemCompraExt.Ocpex_cnpj = dbo.OrdemCompraDetExt.Ocpex_cnpj ON dbo.Filiais.Fil_cnpj = dbo.OrdemCompraExt.Ocpex_cnpj INNER JOIN
                      dbo.produtos ON dbo.OrdemCompraDetExt.Pro_codnosso = dbo.produtos.Pro_codnosso ON 
                      dbo.fornecedor.For_codigo = dbo.produtos.For_codigo LEFT OUTER JOIN
                      dbo.ordem_compra_det ON dbo.OrdemCompraDetExt.Ocpex_codigo = dbo.ordem_compra_det.Ocpex_codigo AND 
                      dbo.OrdemCompraDetExt.Ocpex_cnpj = dbo.ordem_compra_det.Ocpex_cnpj AND 
                      dbo.OrdemCompraDetExt.Ocdex_item = dbo.ordem_compra_det.Ocdex_item
WHERE     fornecedor.For_codigo=:codigo                                                                                  
  AND OrdemCompraExt.Ocpex_status= 'A' AND (ordem_compra_det.Ocd_acabamento IS NULL)                                 
  AND (ordem_compra_det.Ocd_item_ped IS NULL)                        
  AND (ordem_compra_det.Pro_codnosso IS NULL)

-- [ADOCmdExclusao : TADOCommand]
delete pedido_compra_det where Pcp_codigo =:pPcp_codigo and Pcd_item=:pPcd_item and Pro_codnosso=:pPro_codnosso and Pcd_acabamento=:pPcd_acabamento


