                      dbo.VendaServico.usr_dt_hr_alteracao, dbo.VendaServico.VenSer_VlEletricista, dbo.VendaServico.ain_codigo, dbo.Servicos.Serv_Desc, dbo.Servicos.Serv_tipo, 
