-- [Qrypedido : TADOQuery]
SELECT '' as tipo, Venda.ParSV_serie as serie, Clientes.Cli_Nome as nome, Venda.Ven_codigo as codigo, Venda.Pasta_codigo as pasta
,CLIENTES.CLI_CODIGO , venda.ven_codigopre as codigo_pre
,0 AS requisicao
,venda.Ven_TipoEntrega
