/* ============================================================
   FORM: FrmConsProdEst   Consultar Compras para o Estoque
   ============================================================ */

-- [QryCONSULTA : TADOQuery]
SELECT    dbo.ordem_compra.Ocp_dt_envio, dbo.produtos.Pro_descricao, dbo.ordem_compra_det.Ocd_quantidade_solicit, 
                      dbo.ordem_compra_det.Pro_codnosso, dbo.ordem_compra_det.Ocd_acabamento,
dbo.ordem_compra.Ocp_codigo,  dbo.ordem_compra.Ocp_dt_prevista,
                          (SELECT     SUM(Res_Quantidade) AS TOTAL
                            FROM          dbo.Reserva_Estoque AS ER
                            WHERE      (Res_Ordem = dbo.ordem_compra_det.Ocp_codigo) AND (Res_OrdemItem = dbo.ordem_compra_det.Ocd_item) AND 
                                                   (Res_CodigoProduto = dbo.ordem_compra_det.Pro_codnosso) AND (Res_Acabamento = dbo.ordem_compra_det.Ocd_acabamento)) 
                      AS QUANT_UTILIZADA,
    (SELECT     SUM(dbo.nota_entrada_det.Ned_quantidade_recebida) AS TotalNota
                            FROM          dbo.nota_entrada_det INNER JOIN
                                                   dbo.Nota_entrada ON dbo.nota_entrada_det.Nen_codigo = dbo.Nota_entrada.Nen_codigo
                            WHERE      (dbo.Nota_entrada.Nen_status <> 'C') AND (dbo.nota_entrada_det.Ned_cod_ordem = dbo.ordem_compra_det.Ocp_codigo) AND 
                                                   (dbo.nota_entrada_det.Ned_item_ordem = dbo.ordem_compra_det.Ocd_item)) AS Quant_Nota
FROM         dbo.ordem_compra_det INNER JOIN
                      dbo.ordem_compra ON dbo.ordem_compra_det.Ocp_codigo = dbo.ordem_compra.Ocp_codigo INNER JOIN
                      dbo.produtos ON dbo.ordem_compra_det.Pro_codnosso = dbo.produtos.Pro_codnosso
WHERE     (dbo.ordem_compra.Ocp_status = 'A') AND (dbo.ordem_compra_det.Ocd_destino = 'ESTOQUE') 
AND (dbo.ordem_compra_det.Pro_codnosso=:PPro_codnosso) AND (dbo.ordem_compra_det.Ocd_acabamento=:POcd_acabamento)
and ((dbo.ordem_compra_det.Ocd_recebimento IS NULL) OR  (dbo.ordem_compra_det.Ocd_recebimento <> 'INTEGRAL') )
ORDER BY dbo.ordem_compra.Ocp_dt_prevista


/* ============================================================
   FORM: FrmConsProdEstVenda   Consultar Compras 
   ============================================================ */

-- [Qryordem : TADOQuery]
SELECT     dbo.produtos.For_codigo, dbo.Preco_Produto.Pre_Acabamento, dbo.Estoque_produto.Epr_estoque, dbo.produtos.Pro_codnosso, 
                      dbo.produtos.Pro_descricao
FROM         dbo.produtos INNER JOIN
                      dbo.Preco_Produto ON dbo.produtos.Pro_codnosso = dbo.Preco_Produto.Pre_Codnosso INNER JOIN
                      dbo.Estoque_produto ON dbo.Preco_Produto.Pre_Codnosso = dbo.Estoque_produto.Epr_Codnosso AND 
                      dbo.Preco_Produto.Pre_Acabamento = dbo.Estoque_produto.Epr_Acabamento
where produtos.For_codigo=:codigo order by produtos.Pro_codnosso


/* ============================================================
   FORM: FrmConsProdOrcProj   Os produtos abaixo estão desativados ou com saldo de estoque zerado ou negativo.
   ============================================================ */

-- [QryCONSULTA : TADOQuery]
SELECT     1 AS ordem, VendaProduto.VenPro_seq AS SEG, VendaProduto.VenPro_seqitem AS ITEM, 
                      VendaProduto.codambiente AS AMBIENTE, VendaProduto.Pro_codnosso AS CODIGO, 
                      VendaProduto.codacabamento AS ACABAMENTO, dbo.Preco_Produto.Pre_Ativo AS PREATIVO, dbo.produtos.Pro_ativo AS ATIVO, 
                      dbo.Estoque_produto.Epr_estoque AS ESTOQUE, dbo.produtos.Pro_tp_produto AS TIPOPRODUTO, dbo.produtos.Pro_tp_peca AS TIPOPECA, 
                      dbo.produtos.Pro_descricao AS DESCRICAO,VendaProduto.VenPro_quantidade AS QUANTIDADE
, VendaProduto.prom_codigo, venda.Ven_CodigoPre, produtos.Pro_ForaLinha as ForaLinha


FROM         dbo.Preco_Produto INNER JOIN
                      dbo.produtos ON dbo.Preco_Produto.Pre_Codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                      dbo.venda INNER JOIN
                      dbo.VendaProduto ON Venda.ven_codigopre = VendaProduto.ven_codigopre ON 
                      dbo.Preco_Produto.Pre_Codnosso = VendaProduto.Pro_codnosso AND 
                      dbo.Preco_Produto.Pre_Acabamento = VendaProduto.codacabamento INNER JOIN
                      dbo.Estoque_produto ON VendaProduto.Pro_codnosso = dbo.Estoque_produto.Epr_Codnosso AND 
                      VendaProduto.codacabamento = dbo.Estoque_produto.Epr_Acabamento

WHERE     ((dbo.Preco_Produto.Pre_Ativo = 'N') OR
                      (dbo.produtos.Pro_ativo = N'N') OR 
                      (dbo.Estoque_produto.Epr_estoque <= 0))  AND venda.ven_codigo =:Pven_codigo   and   venda.ParSV_serie =:pParSV_serie   AND Estoque_produto.EstTp_Codigo=1
and venda.ven_situacao ='A' AND VENDA.VEN_tipo='O' AND  VendaProduto.VenPro_quantidade > 0

order by seg, item, ordem

-- [Qrydesativado : TADOQuery]
SELECT     Pre_Ativo
FROM         dbo.Preco_Produto
WHERE     (Pre_Ativo = 'S') AND Pre_Codnosso =:PPre_Codnosso AND Pre_Acabamento =:PPre_Acabamento

-- [Qrypromocao : TADOQuery]
SELECT        CASE WHEN
                             (SELECT        SUM(VenPro_Quantidade) AS Expr1
                               FROM            dbo.Venda INNER JOIN
                                                         dbo.VendaProduto ON dbo.Venda.Ven_CodigoPre = dbo.VendaProduto.Ven_CodigoPre
                               WHERE        (dbo.Venda.Ven_Tipo = 'P') AND (dbo.Venda.Ven_Situacao = 'A') AND (dbo.PromocaoProdutos.Prom_Codigo = prom_codigo) AND (dbo.PromocaoProdutos.Pro_codnosso = Pro_codnosso) AND 
                                                         (dbo.PromocaoProdutos.CodAcabamento = CodAcabamento)) > 0 THEN (dbo.PromocaoEstoque.PromEst_Quantidade) -
                             (SELECT        SUM(VenPro_Quantidade) AS Expr1
                               FROM            dbo.VendaProduto
                               WHERE        (dbo.PromocaoProdutos.Prom_Codigo = prom_codigo) AND (dbo.PromocaoProdutos.Pro_codnosso = Pro_codnosso) AND (dbo.PromocaoProdutos.CodAcabamento = CodAcabamento)) 
                         ELSE (PromocaoEstoque.PromEst_Quantidade) END AS QuantRest, dbo.PromocaoProdutos.PromProd_Vlpromocional, Promocao.Prom_Codigo
FROM            dbo.Promocao INNER JOIN
                         dbo.PromocaoProdutos ON dbo.Promocao.Prom_Codigo = dbo.PromocaoProdutos.Prom_Codigo INNER JOIN
                         dbo.PromocaoEstoque ON dbo.PromocaoProdutos.Prom_Codigo = dbo.PromocaoEstoque.Prom_Codigo AND dbo.PromocaoProdutos.Pro_codnosso = dbo.PromocaoEstoque.Pro_codnosso AND 
                         dbo.PromocaoProdutos.CodAcabamento = dbo.PromocaoEstoque.CodAcabamento
WHERE        dbo.Promocao.Prom_DataInicial <=:pProm_DataInicial  AND dbo.Promocao.Prom_DataFinal >=:pProm_DataFinal AND 
                         (dbo.PromocaoProdutos.Pro_codnosso =:pPro_codnosso) AND (dbo.PromocaoProdutos.CodAcabamento =:pCodAcabamento)


