   FORM: FrmConsulta_chegada_produto   Consultar previsão chegada de produtos
   ============================================================ */

-- [Qryproduto : TADOQuery]
SELECT       dbo.Preco_Produto.Pre_Acabamento, MAX(dbo.Estoque_produto.Epr_estoque) AS Epr_estoque, dbo.produtos.Pro_codnosso, dbo.produtos.Pro_descricao, 
                         dbo.ProdutosFornecedores.ProdFor_CodigoProduto AS Pro_Codbase, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto AS Pro_descricao_for, dbo.produtos.Pro_CodEspecial, 
                         dbo.ProdutosFornecedores.For_codigo
FROM            dbo.produtos INNER JOIN
                         dbo.Preco_Produto ON dbo.produtos.Pro_codnosso = dbo.Preco_Produto.Pre_Codnosso INNER JOIN
                         dbo.Estoque_produto ON dbo.Preco_Produto.Pre_Codnosso = dbo.Estoque_produto.Epr_Codnosso AND dbo.Preco_Produto.Pre_Acabamento = dbo.Estoque_produto.Epr_Acabamento INNER JOIN
                         dbo.ProdutosFornecedores ON dbo.produtos.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso
WHERE        (dbo.ProdutosFornecedores.For_codigo =:codigo  )
GROUP BY dbo.Preco_Produto.Pre_Acabamento, dbo.Estoque_produto.Epr_estoque, dbo.produtos.Pro_codnosso, dbo.produtos.Pro_descricao, dbo.produtos.Pro_Codbase, dbo.produtos.Pro_descricao_for, 
                         dbo.produtos.Pro_CodEspecial, dbo.ProdutosFornecedores.For_codigo, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto
ORDER BY dbo.produtos.Pro_codnosso

-- [Qryordem : TADOQuery]
SELECT     dbo.produtos.For_codigo, dbo.Preco_Produto.Pre_Acabamento, dbo.Estoque_produto.Epr_estoque, dbo.produtos.Pro_codnosso, 
                      dbo.produtos.Pro_descricao
FROM         dbo.produtos INNER JOIN
                      dbo.Preco_Produto ON dbo.produtos.Pro_codnosso = dbo.Preco_Produto.Pre_Codnosso INNER JOIN
                      dbo.Estoque_produto ON dbo.Preco_Produto.Pre_Codnosso = dbo.Estoque_produto.Epr_Codnosso AND 
                      dbo.Preco_Produto.Pre_Acabamento = dbo.Estoque_produto.Epr_Acabamento
where produtos.For_codigo=:codigo order by produtos.Pro_codnosso

