SELECT dbo.Estoque_produto.Epr_estoque, dbo.Estoque_produto.EstTp_Codigo, dbo.produtos.Pro_CodEspecial, dbo.produtos.Pro_unidade, dbo.produtos.Pro_Codbase, dbo.produtos.Pro_descricao_for, dbo.produtos.Pro_foto, 
                  dbo.produtos.For_codigo, dbo.produtos.Pro_descricao, dbo.Preco_Produto.Pre_Venda, dbo.produtos.Pro_tp_peca, dbo.GrupoProduto.GrupoProduto_Descricao, dbo.Preco_Produto.Pre_Acabamento, dbo.EstoqueTipo.EstTp_Descricao, 
                  dbo.fornecedor.For_Nome, dbo.produtos.Pro_codnosso, dbo.produtos.Pro_ativo, dbo.Fabrica.Fab_Descricao, dbo.produtos.Pro_CodReduzido, dbo.tamanho.Tam_descricao, dbo.Preco_Produto.Pre_CodBarra, 
                  dbo.Marca.Marca_Descricao
,dbo.ProdutosLocEstoque.ProdLocEst_Predio, dbo.ProdutosLocEstoque.ProdLocEst_Rua, dbo.ProdutosLocEstoque.ProdLocEst_Apto, dbo.ProdutosLocEstoque.ProdLocEst_Numero



FROM     dbo.ProdutosFornecedores INNER JOIN
                  dbo.fornecedor ON dbo.ProdutosFornecedores.For_codigo = dbo.fornecedor.For_codigo INNER JOIN
                  dbo.produtos WITH (NOLOCK) INNER JOIN
                  dbo.Estoque_produto ON dbo.produtos.Pro_codnosso = dbo.Estoque_produto.Epr_Codnosso INNER JOIN
                  dbo.Preco_Produto WITH (NOLOCK) ON dbo.Estoque_produto.Epr_Codnosso = dbo.Preco_Produto.Pre_Codnosso AND dbo.Estoque_produto.Epr_Acabamento = dbo.Preco_Produto.Pre_Acabamento INNER JOIN
                  dbo.GrupoProduto ON dbo.produtos.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo INNER JOIN
                  dbo.EstoqueTipo ON dbo.Estoque_produto.EstTp_Codigo = dbo.EstoqueTipo.EstTp_Codigo ON dbo.ProdutosFornecedores.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                  dbo.empresa ON dbo.Estoque_produto.Emp_codigo = dbo.empresa.CODLANC LEFT OUTER JOIN
                  dbo.ProdutosLocEstoque ON dbo.Estoque_produto.Epr_Codnosso = dbo.ProdutosLocEstoque.Pro_codnosso AND dbo.Estoque_produto.Epr_Acabamento = dbo.ProdutosLocEstoque.CodAcabamento AND 
                  dbo.Estoque_produto.EstTp_Codigo = dbo.ProdutosLocEstoque.EstTp_Codigo LEFT OUTER JOIN
                  dbo.Marca ON dbo.produtos.Marca_Codigo = dbo.Marca.Marca_Codigo LEFT OUTER JOIN
                  dbo.tamanho ON dbo.Estoque_produto.Tam_codigo = dbo.tamanho.Tam_codigo LEFT OUTER JOIN
                  dbo.Fabrica ON dbo.produtos.Fab_Codigo = dbo.Fabrica.Fab_Codigo

