   FORM: FrmConsulta_reserva   Participação
   ============================================================ */

-- [Qryconsulta : TADOQuery]
SELECT     dbo.Venda.Ven_codigo, dbo.Venda.ParSV_serie, dbo.Venda.Ven_CodigoPre, dbo.Pasta.Pasta_Descricao, dbo.Pasta.Pasta_codigo, dbo.Clientes.Cli_Nome, 
                      dbo.Obras.Obr_Descricao, dbo.VendaIndicacao.VenInd_TpDoc, dbo.Indicacoes.Ind_Nome, dbo.Venda.Ven_DataEmissao
FROM         dbo.Venda INNER JOIN
                      dbo.Obras ON dbo.Venda.Obr_codigo = dbo.Obras.Obr_Codigo INNER JOIN
                      dbo.Clientes ON dbo.Venda.Ven_CodVinculo = dbo.Clientes.Cli_Codigo INNER JOIN
                      dbo.VendaIndicacao ON dbo.Venda.Ven_CodigoPre = dbo.VendaIndicacao.VenInd_NDocPre INNER JOIN
                      dbo.Indicacoes ON dbo.VendaIndicacao.Ind_Codigo = dbo.Indicacoes.Ind_codigo LEFT OUTER JOIN
                      dbo.Pasta ON dbo.Venda.Pasta_codigo = dbo.Pasta.Pasta_codigo
WHERE     (dbo.Venda.Ven_CodigoPre NOT IN
                          (SELECT     Venda_1.Ven_CodigoPre
                            FROM          dbo.Venda AS Venda_1 INNER JOIN
                                                   dbo.Reserva_tecnica ON Venda_1.Ven_codigo = dbo.Reserva_tecnica.Ret_projeto_avulsa AND 
                                                   Venda_1.ParSV_serie = dbo.Reserva_tecnica.ParSV_serie
                            WHERE      (dbo.Reserva_tecnica.Ret_tipo = N'PROJETO') AND (dbo.Reserva_tecnica.Ret_situacao = N'ATIVO'))) AND (dbo.VendaIndicacao.VenInd_TpDoc = 'PRO')


/* ============================================================
   FORM: FrmConsultaComissao   Consultar Ganhos Sobre Vendas
   ============================================================ */

-- [QryConsulta : TADOQuery]
SELECT  CASE WHEN FechamentoComissao.FechComis_Situacao = 'A' THEN 'ABERTO' ELSE 'FECHADO' END AS situacao,
 CASE WHEN ControleRH.CtrlRH_TpDocOri = 1002 THEN (SELECT avu_dt_emissao FROM Avulso
 wHERE avu_codigo = ControleRH.CtrlRH_codDocOri) ELSE CASE 
WHEN ControleRH.CtrlRH_TpDocOri = 1001 THEN 
(SELECT ped_dt_fechamento FROM pedido WHERE ped_codigo = ControleRH.CtrlRH_codDocOri) 
ELSE CASE WHEN ControleRH.CtrlRH_TpDocOri = 1017 THEN 
(SELECT edv_data FROM Ent_devolucao WHERE edv_codigo = ControleRH.CtrlRH_codDocOri)
 ELSE CASE WHEN ControleRH.CtrlRH_TpDocOri = 1018 THEN
 (SELECT Scp_data FROM Saida_complementacao WHERE Scp_codigo = ControleRH.CtrlRH_codDocOri)
 ELSE CASE WHEN ControleRH.CtrlRH_TpDocOri = 1009 THEN 
(SELECT Fact_DtEmissao FROM Factura WHERE Fact_Codigo = ControleRH.CtrlRH_codDocOri AND Fact_Tipo = 'FCT')
 ELSE CASE WHEN ControleRH.CtrlRH_TpDocOri = 1012 THEN 
(SELECT Fact_DtEmissao FROM Factura WHERE Fact_Codigo = ControleRH.CtrlRH_codDocOri AND Fact_Tipo = 'VDI')
 END END END END END END AS datavend, 
Funcionario.Fun_Nome, ControleRH.CtrlRH_Valor, dbo.ControleRH.CtrlRH_Operacao, 
CASE WHEN ControleRH.Tpd_codigo = 1014 THEN 'COMISSÃO' ELSE CASE WHEN ControleRH.Tpd_codigo = 1015 
THEN 'PREMIAÇÃO' ELSE CASE WHEN ControleRH.Tpd_codigo = 1019 THEN 'PARTICIPAÇÃO' ELSE 'RATEIO' END END END
 AS tipo, dbo.contas_apagar_det.Ctp_dt_vencimento, ControleRH.CtrlRH_CodDocOri,  (SELECT SUM(CtrlRH_Valor) AS Expr1 FROM ControleRH AS ControleRHC WHERE (CtrlRH_Operacao = 'C') 
AND (FechComis_Codigo = dbo.ControleRH.FechComis_Codigo)) AS TotalCredito, 
(SELECT SUM(CtrlRH_Valor) AS Expr1 FROM ControleRH AS ControleRHD WHERE (CtrlRH_Operacao = 'D') AND
 (FechComis_Codigo = dbo.ControleRH.FechComis_Codigo)) AS TotalDebito 
,CASE WHEN ControleRH.CtrlRH_TpDocOri = 1002 THEN 'VENDA AVULSA' ELSE CASE 
WHEN ControleRH.CtrlRH_TpDocOri = 1001 THEN 
'PROJETO'
ELSE CASE WHEN ControleRH.CtrlRH_TpDocOri = 1017 THEN 
'ENTRADA POR DEVOLUÇÃO'
 ELSE CASE WHEN ControleRH.CtrlRH_TpDocOri = 1018 THEN
 'SAÍDA POR COMPLEMENTAÇÃO'	
 ELSE CASE WHEN ControleRH.CtrlRH_TpDocOri = 1009 THEN 
'FACTURA'
 ELSE CASE WHEN ControleRH.CtrlRH_TpDocOri = 1012 THEN 
'VENDA A DINHEIRO'
 END END END END END END AS TIPOVENDA, 0.00  AS TotalCreditoBloq, 0.00  AS TotalDEBITOBloq
 ,case when ControleRH.CtrlRH_ContaRefVincDet is not null and ControleRH.CtrlRH_Pendente is null then 'B' else ' ' end as sitlanc 
, ControleRH.CtrlRH_ComPreCondTP, ControleRH.ComPre_codigo, ComissaoPremiacao.ComPre_Descricao,
ControleRH.CtrlRH_TpDocOri,ControleRH.ParSV_serie

FROM ControleRH INNER JOIN
    FechamentoComissao ON ControleRH.FechComis_Codigo = FechamentoComissao.FechComis_Codigo INNER JOIN
    Funcionario ON ControleRH.Fun_Codigo = Funcionario.Fun_CPF INNER JOIN
    contas_apagar_det ON FechamentoComissao.FechComis_ContaUnica = contas_apagar_det.Ctp_codigo LEFT OUTER JOIN
    ComissaoPremiacao ON ControleRH.ComPre_codigo = ComissaoPremiacao.ComPre_codigo


 WHERE (ControleRH.CtrlRH_VendaExcluida IS NULL OR ControleRH.CtrlRH_VendaExcluida = 'N')

-- [QryData : TADOQuery]
SELECT  CASE WHEN FechamentoComissao.FechComis_Situacao = 'A' THEN 'ABERTO' ELSE 'FECHADO' END AS situacao,
 CASE WHEN ControleRH.CtrlRH_TpDocOri = 1002 THEN (SELECT avu_dt_emissao FROM Avulso
 wHERE avu_codigo = ControleRH.CtrlRH_codDocOri) ELSE CASE 
WHEN ControleRH.CtrlRH_TpDocOri = 1001 THEN 
(SELECT ped_dt_fechamento FROM pedido WHERE ped_codigo = ControleRH.CtrlRH_codDocOri) 
ELSE CASE WHEN ControleRH.CtrlRH_TpDocOri = 1017 THEN 
(SELECT edv_data FROM Ent_devolucao WHERE edv_codigo = ControleRH.CtrlRH_codDocOri)
 ELSE CASE WHEN ControleRH.CtrlRH_TpDocOri = 1018 THEN
 (SELECT Scp_data FROM Saida_complementacao WHERE Scp_codigo = ControleRH.CtrlRH_codDocOri)
 ELSE CASE WHEN ControleRH.CtrlRH_TpDocOri = 1009 THEN 
(SELECT Fact_DtEmissao FROM Factura WHERE Fact_Codigo = ControleRH.CtrlRH_codDocOri AND Fact_Tipo = 'FCT')
 ELSE CASE WHEN ControleRH.CtrlRH_TpDocOri = 1012 THEN 
(SELECT Fact_DtEmissao FROM Factura WHERE Fact_Codigo = ControleRH.CtrlRH_codDocOri AND Fact_Tipo = 'VDI')
 END END END END END END AS datavend, 
Funcionario.Fun_Nome, ControleRH.CtrlRH_Valor, dbo.ControleRH.CtrlRH_Operacao, 
CASE WHEN ControleRH.Tpd_codigo = 1014 THEN 'COMISSÃO' ELSE CASE WHEN ControleRH.Tpd_codigo = 1015 
THEN 'PREMIAÇÃO' ELSE CASE WHEN ControleRH.Tpd_codigo = 1019 THEN 'PARTICIPAÇÃO' ELSE 'RATEIO' END END END
 AS tipo, dbo.contas_apagar_det.Ctp_dt_vencimento, ControleRH.CtrlRH_CodDocOri,  (SELECT SUM(CtrlRH_Valor) AS Expr1 FROM ControleRH AS ControleRHC WHERE (CtrlRH_Operacao = 'C') 
AND (FechComis_Codigo = dbo.ControleRH.FechComis_Codigo)) AS TotalCredito, 
(SELECT SUM(CtrlRH_Valor) AS Expr1 FROM ControleRH AS ControleRHD WHERE (CtrlRH_Operacao = 'D') AND
 (FechComis_Codigo = dbo.ControleRH.FechComis_Codigo)) AS TotalDebito 
,CASE WHEN ControleRH.CtrlRH_TpDocOri = 1002 THEN 'VENDA AVULSA' ELSE CASE 
WHEN ControleRH.CtrlRH_TpDocOri = 1001 THEN 
'PROJETO'
ELSE CASE WHEN ControleRH.CtrlRH_TpDocOri = 1017 THEN 
'ENTRADA POR DEVOLUÇÃO'
 ELSE CASE WHEN ControleRH.CtrlRH_TpDocOri = 1018 THEN
 'SAÍDA POR COMPLEMENTAÇÃO'	
 ELSE CASE WHEN ControleRH.CtrlRH_TpDocOri = 1009 THEN 
'FACTURA'
 ELSE CASE WHEN ControleRH.CtrlRH_TpDocOri = 1012 THEN 
'VENDA A DINHEIRO'
 END END END END END END AS TIPOVENDA, 0.00  AS TotalCreditoBloq, 0.00  AS TotalDEBITOBloq
 ,case when ControleRH.CtrlRH_ContaRefVincDet is not null and ControleRH.CtrlRH_Pendente is null then 'B' else ' ' end as sitlanc 
, ControleRH.CtrlRH_ComPreCondTP, ControleRH.ComPre_codigo, ComissaoPremiacao.ComPre_Descricao,
ControleRH.CtrlRH_TpDocOri,ControleRH.ParSV_serie

FROM ControleRH INNER JOIN
    FechamentoComissao ON ControleRH.FechComis_Codigo = FechamentoComissao.FechComis_Codigo INNER JOIN
    Funcionario ON ControleRH.Fun_Codigo = Funcionario.Fun_CPF INNER JOIN
    contas_apagar_det ON FechamentoComissao.FechComis_ContaUnica = contas_apagar_det.Ctp_codigo LEFT OUTER JOIN
    ComissaoPremiacao ON ControleRH.ComPre_codigo = ComissaoPremiacao.ComPre_codigo


 WHERE (ControleRH.CtrlRH_VendaExcluida IS NULL OR ControleRH.CtrlRH_VendaExcluida = 'N')


/* ============================================================
   FORM: FrmConsultaCreditoCliente   Consultar Crédito do Cliente
   ============================================================ */

-- [QryCliente : TADOQuery]
select cli_codigo, cli_nome from clientes order by cli_nome

-- [QryConfirmado : TADOQuery]
sELECT     dbo.Credito.Credito_Situacao, dbo.Credito.Credito_Codigo, dbo.Credito.Credito_TipoVinculo, dbo.Clientes.Cli_Nome, dbo.Credito.Credito_Operacao, 
                      dbo.Credito.Credito_Valor, dbo.Credito.Credito_Data, dbo.Credito.Credito_CodigoDoc, dbo.Tipo_documento.Tpd_descricao,
dbo.Credito.Credito_TpdcodigoOrigem,dbo.Credito.Credito_CodigoVinculo,
case when Credito.Credito_TpdcodigoOrigem  =1013 then (

SELECT     dbo.Venda.Ven_codigo
FROM         dbo.Venda INNER JOIN
                      dbo.Devolucao ON dbo.Venda.Ven_CodigoPre = dbo.Devolucao.ven_codigopre
where devolucao.dev_codigo =Credito.Credito_CodigoDoc
) 
else
null
end as DocVinculado
,
case when Credito.Credito_TpdcodigoOrigem  =1013 then 
(
SELECT Devolucao.Dev_descricao
FROM Venda INNER JOIN
dbo.Devolucao ON dbo.Venda.Ven_CodigoPre = dbo.Devolucao.ven_codigopre
where devolucao.dev_codigo =Credito.Credito_CodigoDoc
)

else
case when Credito.Credito_TpdcodigoOrigem  =1001 then
(
SELECt top 1 dbo.Venda.Ven_DescricaoVenda
FROM Venda 
 where venda.ven_codigo =CAST(Credito.Credito_CodigoDoc AS FLOAT)  and venda.ParSV_serie = Credito.ParSV_serie and Ven_Tipo='P'
 AND VENDA.Ven_ValorCredito = Credito.Credito_Valor
)
end



end as Ven_DescricaoVenda


FROM         dbo.Credito INNER JOIN
                      dbo.Clientes ON dbo.Credito.Credito_CodigoVinculo = dbo.Clientes.Cli_Codigo LEFT OUTER JOIN
                      dbo.Tipo_documento ON dbo.Credito.Credito_TpdcodigoOrigem = dbo.Tipo_documento.Tpd_codigo
WHERE     (dbo.Credito.Credito_TipoVinculo = 'C') and Credito.Credito_Situacao='A' and Credito.Credito_CodigoVinculo=:PCredito_CodigoVinculo

-- [QryNaoConfirmado : TADOQuery]
select Ven_codigo,Ven_CodigoPre,ParSV_serie, (Ven_Total - 
case when (select sum(Dev_Total) from devolucao where devolucao.ven_codigopre = venda.ven_codigopre and Dev_situacao =1) > 0 then 
(select sum(Dev_Total) from devolucao where devolucao.ven_codigopre = venda.ven_codigopre and Dev_situacao =1) else 0 end) as total
 from venda where ven_tipo ='P' AND VEN_SITUACAO ='A'
and Ven_DataConclusao is null and Ven_CodVinculo =:pVen_CodVinculo
and  year(Ven_DataEmissao) >=2006


/* ============================================================
   FORM: FrmConsultaCreditoFornecedor   Consulta de Crédito junto ao Fornecedor
   ============================================================ */

-- [QryFor : TADOQuery]
SELECT For_codigo, For_Nome
FROM            dbo.fornecedor
WHERE        (for_classificacao = 'F')
ORDER BY For_Nome

-- [QryConfirmado : TADOQuery]
SELECT        dbo.Credito.Credito_Situacao, dbo.Credito.Credito_Codigo, dbo.Credito.Credito_TipoVinculo, dbo.Credito.Credito_Operacao, dbo.Credito.Credito_Valor, dbo.Credito.Credito_Data, dbo.Credito.Credito_CodigoDoc, 
                         dbo.Tipo_documento.Tpd_descricao, dbo.Credito.Credito_TpdcodigoOrigem, dbo.Credito.Credito_CodigoVinculo, CASE WHEN Credito.Credito_TpdcodigoOrigem = 1003 THEN
                             (SELECT        Nen_numero_nota
                               FROM            Nota_entrada
                               WHERE        Nota_entrada.Nen_codigo = Credito.Credito_CodigoDoc) ELSE NULL END AS DocVinculado
FROM            dbo.Credito INNER JOIN
                         dbo.fornecedor ON dbo.Credito.Credito_CodigoVinculo = dbo.fornecedor.For_codigo LEFT OUTER JOIN
                         dbo.Tipo_documento ON dbo.Credito.Credito_TpdcodigoOrigem = dbo.Tipo_documento.Tpd_codigo
WHERE        (dbo.Credito.Credito_TipoVinculo = 'F') AND (dbo.Credito.Credito_Situacao = 'A') and Credito.Credito_CodigoVinculo=:PCredito_CodigoVinculo


/* ============================================================
   FORM: FrmConsultaEstCompras   Consulta Produtos à Solicitar
   ============================================================ */

-- [Qrybalanco : TADOQuery]
SELECT     dbo.Estoque_produto.*, produtos.Pro_Codbase, produtos.Pro_descricao_for, produtos.pro_foto,dbo.produtos.For_codigo AS For_codigo, dbo.produtos.Pro_descricao AS Pro_descricao, 
                      dbo.Preco_Produto.Pre_Venda AS Pre_Venda, dbo.produtos.Pro_tp_peca AS Pro_tp_peca, dbo.produtos.Pro_tp_produto AS Pro_tp_produto
FROM         dbo.produtos WITH (NOLOCK) INNER JOIN
                      dbo.Estoque_produto ON dbo.produtos.Pro_codnosso = dbo.Estoque_produto.Epr_Codnosso INNER JOIN
                      dbo.Preco_Produto WITH (NOLOCK) ON dbo.Estoque_produto.Epr_Codnosso = dbo.Preco_Produto.Pre_Codnosso AND 
                      dbo.Estoque_produto.Epr_Acabamento = dbo.Preco_Produto.Pre_Acabamento

-- [Qryfornecedor : TADOQuery]
select * from fornecedor where for_classificacao = 'F' order by For_nome

-- [Qrycompras : TADOQuery]
SELECT       dbo.Preco_Produto.Pre_Codnosso, dbo.Preco_Produto.Pre_Acabamento, dbo.Preco_Produto.Pre_Codindice, dbo.Preco_Produto.Pre_EstMinCalcular, dbo.Preco_Produto.pre_codigo, 
                         dbo.Preco_Produto.Pre_Ativo, dbo.produtos.Pro_descricao, dbo.produtos.Pro_descricao_for, dbo.produtos.Pro_Codbase, dbo.TipoPeca.TpPeca_Codigo, dbo.GrupoProduto.GrupoProduto_Descricao, 
                         dbo.Preco_Produto.Pre_est_min, dbo.Estoque_produto.Epr_estoque, dbo.CompraEstoque(dbo.Preco_Produto.Pre_Codnosso, dbo.Preco_Produto.Pre_Acabamento, 'G') AS ComprasEstoque, dbo.produtos.Pro_foto, 
                         CASE WHEN (dbo.Estoque_produto.Epr_estoque + dbo.CompraEstoque(dbo.Preco_Produto.Pre_Codnosso, dbo.Preco_Produto.Pre_Acabamento, 'G')) 
                         > dbo.Preco_Produto.Pre_est_min THEN 0 ELSE CASE WHEN (dbo.Estoque_produto.Epr_estoque + dbo.CompraEstoque(dbo.Preco_Produto.Pre_Codnosso, dbo.Preco_Produto.Pre_Acabamento, 'G')) 
                         - dbo.Preco_Produto.Pre_est_min < 0 THEN ((dbo.Estoque_produto.Epr_estoque + dbo.CompraEstoque(dbo.Preco_Produto.Pre_Codnosso, dbo.Preco_Produto.Pre_Acabamento, 'G')) 
                         - dbo.Preco_Produto.Pre_est_min) * - 1 ELSE (dbo.Estoque_produto.Epr_estoque + dbo.CompraEstoque(dbo.Preco_Produto.Pre_Codnosso, dbo.Preco_Produto.Pre_Acabamento, 'G')) 
                         - dbo.Preco_Produto.Pre_est_min END END AS RESULTADO, dbo.produtos.Pro_CodEspecial, dbo.produtos.Pro_unidade, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, 
                         dbo.ProdutosFornecedores.ProdFor_DescricaoProduto, dbo.ProdutosFornecedores.For_codigo
FROM            dbo.ProdutosFornecedores INNER JOIN
                         dbo.Estoque_produto INNER JOIN
                         dbo.Preco_Produto INNER JOIN
                         dbo.produtos ON dbo.Preco_Produto.Pre_Codnosso = dbo.produtos.Pro_codnosso ON dbo.Estoque_produto.Epr_Codnosso = dbo.Preco_Produto.Pre_Codnosso AND 
                         dbo.Estoque_produto.Epr_Acabamento = dbo.Preco_Produto.Pre_Acabamento ON dbo.ProdutosFornecedores.Pro_codnosso = dbo.produtos.Pro_codnosso LEFT OUTER JOIN
                         dbo.TipoPeca ON dbo.produtos.Pro_tp_peca = dbo.TipoPeca.TpPeca_Codigo LEFT OUTER JOIN
                         dbo.GrupoProduto ON dbo.TipoPeca.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo
WHERE        (dbo.Preco_Produto.Pre_Ativo = 'S') AND (dbo.produtos.Pro_ativo = 'S') AND (dbo.ProdutosFornecedores.For_codigo = 1)
ORDER BY RESULTADO DESC


