SELECT dbo.Venda.Ven_codigo, dbo.Venda.ParSV_serie, dbo.Venda.Ven_CodigoPre, dbo.Venda.Pasta_codigo, dbo.Venda.Ven_DataEmissao, dbo.Venda.Ven_DataConclusao, dbo.Clientes.Cli_Nome, dbo.Venda.Ven_Total, 
                  dbo.Venda.Ven_Desconto, dbo.Venda.Ven_DescontoPorc, dbo.Venda.Ven_SubTotal, dbo.MostrarAtendentes(dbo.Venda.Ven_CodigoPre, 'PRO') AS nomeatendente, dbo.MostrarIndicacao(dbo.Venda.Ven_CodigoPre,'PRO') AS nomeindicacao
FROM     dbo.Clientes INNER JOIN
                  dbo.Venda ON dbo.Clientes.Cli_Codigo = dbo.Venda.Ven_CodVinculo
where Venda.Ven_CodigoPre =:PVen_CodigoPre

-- [Qryproduto : TADOQuery]
SELECT dbo.VendaProduto.Pro_codnosso, dbo.VendaProduto.CodAcabamento, dbo.produtos.Pro_tp_peca, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto, 
                  SUM(dbo.VendaProduto.VenPro_Quantidade) AS VenPro_Quantidade, produtos.Pro_CodEspecial,produtos.Pro_descricao, fornecedor.For_Nome

FROM     dbo.produtos INNER JOIN
                  dbo.ProdutosFornecedores ON dbo.produtos.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso INNER JOIN
                  dbo.VendaProduto ON dbo.produtos.Pro_codnosso = dbo.VendaProduto.Pro_codnosso INNER JOIN
                  dbo.fornecedor ON dbo.ProdutosFornecedores.For_codigo = dbo.fornecedor.For_codigo

where Ven_CodigoPre =:PVen_CodigoPre and ProdutosFornecedores.ProdFor_Padrao = 1
GROUP BY dbo.VendaProduto.Pro_codnosso, dbo.VendaProduto.CodAcabamento, dbo.produtos.Pro_tp_peca, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto
,produtos.Pro_CodEspecial,produtos.Pro_descricao,fornecedor.For_Nome

-- [QryProduto2 : TADOQuery]
SELECT dbo.VendaProduto.Pro_codnosso, dbo.VendaProduto.CodAcabamento, dbo.produtos.Pro_tp_peca, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto, 
                  SUM(dbo.VendaProduto.VenPro_Quantidade) AS VenPro_Quantidade, produtos.Pro_CodEspecial,produtos.Pro_descricao, fornecedor.For_Nome

FROM     dbo.produtos INNER JOIN
                  dbo.ProdutosFornecedores ON dbo.produtos.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso INNER JOIN
                  dbo.VendaProduto ON dbo.produtos.Pro_codnosso = dbo.VendaProduto.Pro_codnosso INNER JOIN
                  dbo.fornecedor ON dbo.ProdutosFornecedores.For_codigo = dbo.fornecedor.For_codigo

where Ven_CodigoPre =:PVen_CodigoPre and ProdutosFornecedores.ProdFor_Padrao = 1
GROUP BY dbo.VendaProduto.Pro_codnosso, dbo.VendaProduto.CodAcabamento, dbo.produtos.Pro_tp_peca, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto
