   FORM: FrmContasapagar   Contas a Pagar
   ============================================================ */

-- [QryContasaPagar : TADOQuery]
SELECT      contas_apagar.*, Tipo_documento.Tpd_descricao AS desc_doc,  
			TipoContaFinanceira.Tcf_descricao, contas_apagar_det.*, 
			Modo.Mdo_nome AS desc_modo, plano_contas.pco_descricao AS plano_contas

FROM		contas_apagar, Tipo_documento, TipoContaFinanceira , contas_apagar_det, Modo, plano_contas

WHERE		contas_apagar.Tpd_codigo = Tipo_documento.Tpd_codigo AND
			contas_apagar.Tcf_codigo = TipoContaFinanceira.Tcf_codigo AND
			contas_apagar.pco_codigo = plano_contas.pco_codigo AND
			contas_apagar.ctp_codigo = contas_apagar_det.ctp_codigo AND
			contas_apagar_det.Mdo_codigo = Modo.Mdo_codigo

-- [Qrypagamento : TADOQuery]
SELECT  contas_apagar_pag.*, Modo.Mdo_nome AS desc_modo
FROM  contas_apagar_pag INNER JOIN
             Modo ON dbo.contas_apagar_pag.Mdo_codigo = Modo.Mdo_codigo
WHERE   (contas_apagar_pag.Ctp_codigo =:codigo) AND (contas_apagar_pag.Ctp_codigo_det =:cod_det )

-- [QrySomaTotal : TADOQuery]
SELECT      SUM(Ctp_valor_vencimento) AS Valor_Total
			
FROM		contas_apagar, Tipo_documento, TipoContaFinanceira , contas_apagar_det, Modo, plano_contas

WHERE		contas_apagar.Tpd_codigo = Tipo_documento.Tpd_codigo AND
			contas_apagar.Tcf_codigo = TipoContaFinanceira.Tcf_codigo AND
			contas_apagar.pco_codigo = plano_contas.pco_codigo AND
			contas_apagar.ctp_codigo = contas_apagar_det.ctp_codigo AND
			contas_apagar_det.Mdo_codigo = Modo.Mdo_codigo

-- [QryValorRecebido : TADOQuery]
SELECT      SUM(Ctp_valor_vencimento) AS Valor_Recebido
			
FROM		contas_apagar, Tipo_documento, TipoContaFinanceira , contas_apagar_det, Modo, plano_contas

WHERE		contas_apagar.Tpd_codigo = Tipo_documento.Tpd_codigo AND
			contas_apagar.Tcf_codigo = TipoContaFinanceira.Tcf_codigo AND
			contas_apagar.pco_codigo = plano_contas.pco_codigo AND
			contas_apagar.ctp_codigo = contas_apagar_det.ctp_codigo AND
			contas_apagar_det.Mdo_codigo = Modo.Mdo_codigo AND ctp_situacao='S'

-- [QryValorNaoRecebido : TADOQuery]
SELECT      SUM(Ctp_valor_vencimento) AS Valor_NaoRecebido
			
FROM		contas_apagar, Tipo_documento, TipoContaFinanceira , contas_apagar_det, Modo, plano_contas

WHERE		contas_apagar.Tpd_codigo = Tipo_documento.Tpd_codigo AND
			contas_apagar.Tcf_codigo = TipoContaFinanceira.Tcf_codigo AND
			contas_apagar.pco_codigo = plano_contas.pco_codigo AND
			contas_apagar.ctp_codigo = contas_apagar_det.ctp_codigo AND
			contas_apagar_det.Mdo_codigo = Modo.Mdo_codigo  and (ctp_situacao='N' OR ctp_situacao is null)

