   FORM: FrmControleCheque   Controle de Cheque
   ============================================================ */

-- [QryControleDet : TADOQuery]
select * from ControleChequeDet where  ControlChequeDet_codigo =:PControlChequeDet_codigo

-- [QryControle : TADOQuery]
select * from ControleCheque where ControlCheque_codigo =:PControlCheque_codigo

-- [QryDevolucao : TADOQuery]
select * from ControleChequeDev 
where ControlChequeDet_codigo =:PControlChequeDet_codigo

-- [QryTroca : TADOQuery]
SELECT     CASE WHEN ControleChequeDet.ControlChequeDet_Vinculo = 'OUTROS' THEN ControleChequeDet.ControlChequeDet_emitente WHEN ControleChequeDet.ControlChequeDet_Vinculo
                       = 'CLIENTE' THEN
                          (SELECT     cli_nome
                            FROM          clientes
                            WHERE      clientes.cli_codigo = ControleChequeDet.ControlChequeDet_vinculocodigo) 
                      WHEN ControleChequeDet.ControlChequeDet_Vinculo = 'INDICAÇÃO' THEN
                          (SELECT     ind_nome
                            FROM          indicacoes
                            WHERE      indicacoes.ind_codigo = ControleChequeDet.ControlChequeDet_vinculocodigo) 
                      WHEN ControleChequeDet.ControlChequeDet_Vinculo = 'FORNECEDOR' THEN
                          (SELECT     for_nome
                            FROM          fornecedor
                            WHERE      fornecedor.for_codigo = ControleChequeDet.ControlChequeDet_vinculocodigo) 
                      WHEN ControleChequeDet.ControlChequeDet_Vinculo = ' PESSOAL ' THEN
                          (SELECT     fun_nome
                            FROM          funcionario
                            WHERE      funcionario.fun_cpf = ControleChequeDet.ControlChequeDet_vinculocodigo) 
                      WHEN ControleChequeDet.ControlChequeDet_Vinculo = 'MATRIZ/FILIAL' THEN
                          (SELECT     fil_fantasia
                            FROM          filiais
                            WHERE      filiais.fil_codigo = ControleChequeDet.ControlChequeDet_vinculocodigo) END AS nome, 
                      CASE WHEN dbo.ControleChequedet.ControlChequedet_tipo = 'P' THEN 'PRÉ-DATADO' WHEN dbo.ControleChequedet.ControlChequedet_tipo = 'C' THEN
                       'NORMAL (A VISTA)' END AS tipo, dbo.ControleChequeDet.ControlChequeDet_Vinculo AS vinculo, 
                      dbo.ControleChequeDet.ControlChequeDet_NumCheque AS numcheque, dbo.ControleChequeDet.ControlChequeDet_Conta AS Conta, 
                      dbo.ControleChequeDet.ControlChequeDet_Agencia AS agencia, dbo.Bancos.Ban_Nome AS banco, dbo.ControleChequeDet.ControlChequeDet_Codigo, 
                      dbo.ControleChequeDet.ControlChequeDet_Situacao AS situacao, dbo.ControleChequeDet.ControlChequeDet_EmitCNPJCPF
FROM         dbo.ControleCheque INNER JOIN
                      dbo.ControleChequeDet ON dbo.ControleCheque.ControlCheque_codigo = dbo.ControleChequeDet.ControlCheque_Codigo LEFT OUTER JOIN
                      dbo.Bancos ON dbo.ControleChequeDet.Ban_Codigo = dbo.Bancos.Ban_Codigo
where   (ControleChequeDet.ControlChequeDet_Situacao = 'TROCADO POR CHEQUE') 
and (ControleCheque.ControlCheque_CodPagamento=:PControlCheque_CodPagamento)

