-- [QryCabecalho : TADOQuery]
SELECT     CASE WHEN contas_receber.ctr_vinculo = 'OUTROS ' THEN contas_receber.ctr_nome WHEN contas_receber.ctr_vinculo = 'CLIENTE' THEN
                          (SELECT     cli_nome
                            FROM          clientes
                            WHERE      clientes.cli_codigo = contas_receber.ctr_codigo_vinculo) WHEN contas_receber.ctr_vinculo = 'INDICAÇÃO' THEN
                          (SELECT     ind_nome
                            FROM          indicacoes
                            WHERE      indicacoes.ind_codigo = contas_receber.ctr_codigo_vinculo) WHEN contas_receber.ctr_vinculo = 'FORNECEDOR' THEN
                          (SELECT     for_nome
                            FROM          fornecedor
                            WHERE      fornecedor.for_codigo = contas_receber.ctr_codigo_vinculo) WHEN contas_receber.ctr_vinculo = 'PESSOAL' THEN
                          (SELECT     fun_nome
                            FROM          funcionario
                            WHERE      funcionario.fun_cpf = contas_receber.ctr_codigo_vinculo) WHEN contas_receber.ctr_vinculo = 'MATRIZ/FILIAL' THEN
                          (SELECT     fil_fantasia
                            FROM          filiais
                            WHERE      filiais.fil_codigo = contas_receber.ctr_codigo_vinculo) END AS nomeconta, 'A RECEBER ' AS tipo, 
                      dbo.Tipo_documento.Tpd_descricao AS documento, dbo.contas_receber.Ctr_cod_documento AS codigodocumento, 
                      dbo.contas_receber.Ctr_vinculo AS vinculo, dbo.contas_receber.Ctr_codigo_vinculo AS codigovinculo, 
                      dbo.Contas_receber_pag.Ctr_parcelas AS parcela, dbo.Contas_receber_pag.Crp_data_pagamento AS data, 
                      dbo.Contas_receber_pag.Crp_valor_pago AS valor,  contas_receber.Tpd_codigo,Contas_receber_pag.ctr_codigo_det as contadet,
Contas_receber_pag.cba_codigo
FROM         dbo.ControleCheque INNER JOIN
                      dbo.Contas_receber_pag ON dbo.ControleCheque.ControlCheque_CodPagamento = dbo.Contas_receber_pag.Crp_cod_pag INNER JOIN
                      dbo.contas_receber ON dbo.Contas_receber_pag.Ctr_codigo = dbo.contas_receber.Ctr_codigo LEFT OUTER JOIN
                      dbo.Tipo_documento ON dbo.contas_receber.Tpd_codigo = dbo.Tipo_documento.Tpd_codigo
WHERE     (dbo.ControleCheque.ControlCheque_tipo = 'R')

