Bancos_Caixas.Emp_codigo = Contas_Bancarias.Emp_codigo AND Bancos_Caixas.Emp_codigo = Contas_Bancarias.Emp_codigo AND 
Bancos_Caixas.Emp_codigo = Contas_Bancarias.Emp_codigo AND Bancos_Caixas.Emp_codigo = Contas_Bancarias.Emp_codigo 
