-- [QryLuminaria : TADOQuery]
SELECT        dbo.controle_entrega_prod.cen_codigo_pre, dbo.controle_entrega_prod.Pro_codnosso, dbo.controle_entrega_prod.cep_acabamento, dbo.controle_entrega_prod.cep_tipo, 
                         dbo.controle_entrega_prod.cep_quantidade_entregue, dbo.controle_entrega_prod.cep_quantidade, dbo.controle_entrega_prod.CodAmbiente, dbo.controle_entrega_prod.cep_quantidade_separada, 
                         dbo.controle_entrega_prod.cep_quantidade_separadaRet, dbo.controle_entrega_prod.cep_quantidade_entregueRET, dbo.controle_entrega_prod.CEP_QuantidadeDevolvida, 
                         dbo.controle_entrega_prod.CEP_QuantidadeDevolvidaEst, dbo.controle_entrega_prod.Cep_VendItem, dbo.controle_entrega_prod.Cep_VendSequencia, dbo.controle_entrega_prod.Cep_VendSequenciaItem, 
                         dbo.VendaAmbiente.VenAmb_Descricao, dbo.produtos.Pro_Codbase, dbo.produtos.Pro_descricao, dbo.produtos.Pro_descricao_for, dbo.produtos.Pro_CodEspecial,
controle_entrega_prod.Cep_TipoEntrega, controle_entrega_prod.CEP_CODIGO, controle_entrega_prod.CEP_obs

FROM            dbo.controle_entrega_prod INNER JOIN
                         dbo.Controle_entrega ON dbo.Controle_entrega.cen_codigo_pre = dbo.controle_entrega_prod.cen_codigo_pre INNER JOIN
                         dbo.Venda ON dbo.Controle_entrega.cen_pedido_avulso = dbo.Venda.Ven_codigo AND dbo.Controle_entrega.ParSV_serie = dbo.Venda.ParSV_serie INNER JOIN
                         dbo.VendaProduto ON dbo.Venda.Ven_CodigoPre = dbo.VendaProduto.Ven_CodigoPre AND dbo.controle_entrega_prod.Pro_codnosso = dbo.VendaProduto.Pro_codnosso AND 
                         dbo.controle_entrega_prod.CodAmbiente = dbo.VendaProduto.CodAmbiente AND dbo.controle_entrega_prod.cep_acabamento = dbo.VendaProduto.CodAcabamento AND 
                         dbo.controle_entrega_prod.cep_quantidade = dbo.VendaProduto.VenPro_Quantidade INNER JOIN
                         dbo.VendaAmbiente ON dbo.VendaProduto.Ven_CodigoPre = dbo.VendaAmbiente.VenAmb_NDocPre AND dbo.VendaProduto.CodAmbiente = dbo.VendaAmbiente.CodAmbiente INNER JOIN
                         dbo.produtos ON dbo.VendaProduto.Pro_codnosso = dbo.produtos.Pro_codnosso

WHERE        (dbo.controle_entrega_prod.cep_quantidade > 0) AND (dbo.Venda.Ven_Tipo = 'P') AND (dbo.Venda.Ven_Situacao = 'A') AND 
                         (dbo.VendaAmbiente.VenAmb_TpDoc = 'PRO')

