-- [QryConclusaoPedido : TADOQuery]
update VENDA SET  Ven_DataConclusao = GETDATE() 
WHERE VENDA.Ven_CodigoPre =:pVen_CodigoPre AND  NOT EXISTS(select controle_entrega_prod .* 
 FROM     dbo.Controle_entrega INNER JOIN
                  dbo.controle_entrega_prod ON dbo.Controle_entrega.cen_codigo_pre = dbo.controle_entrega_prod.cen_codigo_pre INNER JOIN
                  dbo.Venda  AS VD ON dbo.Controle_entrega.ParSV_serie = VD.ParSV_serie AND dbo.Controle_entrega.cen_pedido_avulso = VD.Ven_codigo
WHERE  (VD.Ven_Tipo = 'P') AND (VD.Ven_Situacao = 'A') AND (VD.Ven_CodigoPre = VENDA.Ven_CodigoPre)
AND cep_quantidade_entregue + case when CEP_QuantidadeDevolvidaEst is null then 0 else CEP_QuantidadeDevolvidaEst end < cep_quantidade)

