SELECT dbo.controle_entrega_prod.cen_codigo_pre, dbo.controle_entrega_prod.Pro_codnosso, dbo.controle_entrega_prod.cep_acabamento, dbo.controle_entrega_prod.cep_tipo, dbo.controle_entrega_prod.cep_quantidade_entregue, 
                  dbo.controle_entrega_prod.cep_quantidade,  dbo.controle_entrega_prod.cep_quantidade_separada, dbo.controle_entrega_prod.cep_quantidade_separadaRet, 
                  dbo.controle_entrega_prod.cep_quantidade_entregueRET, dbo.controle_entrega_prod.CEP_QuantidadeDevolvida, dbo.controle_entrega_prod.CEP_QuantidadeDevolvidaEst, 
                   dbo.controle_entrega_prod.Cep_TipoEntrega, dbo.controle_entrega_prod.cep_codigo, dbo.controle_entrega_prod.CEP_Obs, 
                  dbo.controle_entrega_prod.Cep_Servico, dbo.Servicos.Serv_Desc
FROM     dbo.controle_entrega_prod INNER JOIN
                  dbo.Controle_entrega ON dbo.Controle_entrega.cen_codigo_pre = dbo.controle_entrega_prod.cen_codigo_pre INNER JOIN
                  dbo.Venda ON dbo.Controle_entrega.cen_pedido_avulso = dbo.Venda.Ven_codigo AND dbo.Controle_entrega.ParSV_serie = dbo.Venda.ParSV_serie INNER JOIN
                  dbo.VendaServico ON dbo.Venda.Ven_CodigoPre = dbo.VendaServico.Ven_codigopre AND dbo.controle_entrega_prod.Pro_codnosso = dbo.VendaServico.Sev_cod INNER JOIN
                  dbo.Servicos ON dbo.VendaServico.Sev_cod = dbo.Servicos.sev_cod
WHERE  (dbo.controle_entrega_prod.Cep_Servico = 1)
and        (dbo.controle_entrega_prod.cep_quantidade > 0) AND (dbo.Venda.Ven_Tipo = 'P') AND (dbo.Venda.Ven_Situacao = 'A')


