FROM ((produtos INNER JOIN Preco_Produto ON produtos.Pro_codnosso = Preco_Produto.Pre_Codnosso) INNER JOIN Indice_preco ON (produtos.For_codigo = Indice_preco.for_codigo) AND (Preco_Produto.Pre_Codindice = Indice_preco.Ipr_descricao)) INNER JOIN fornecedor ON produtos.For_codigo = fornecedor.For_codigo
GROUP BY produtos.Pro_codnosso, produtos.Pro_descricao, Preco_Produto.Pre_Codindice, produtos.Pro_comissao, Indice_preco.Ipr_vl_com_inter, fornecedor.For_Nome
HAVING (((produtos.Pro_comissao)<>[Indice_preco].[Ipr_vl_com_inter])) order by fornecedor.For_Nome,produtos.Pro_descricao

