/* ============================================================
   FORM: FrmDemostracao   Demostração
   ============================================================ */

-- [QryVendaProd : TADOQuery]
select vendaproduto.* ,

case when substring(vendaproduto.Pro_codnosso, 1,18)='999999999999999999' then vendaproduto.VenPro_PreProduto else ProdutosFornecedores.ProdFor_DescricaoProduto end ProdFor_DescricaoProduto,

case when substring(vendaproduto.Pro_codnosso, 1,18)='999999999999999999' then vendaproduto.VenPro_PreProduto else produtos.Pro_descricao end Pro_descricao

,ProdutosFornecedores.ProdFor_CodigoProduto, dbo.produtos.Pro_tp_peca, dbo.GrupoProduto.GrupoProduto_Descricao,  
                      dbo.produtos.Pro_unidade, dbo.produtos.Pro_CodEspecial, dbo.fornecedor.For_Nome, produtos.pro_tempoInstalacao, GrupoProduto.GrupoProduto_codigo
, produtos.Pro_CodReduzido

FROM         dbo.VendaProduto INNER JOIN
                      dbo.produtos ON dbo.VendaProduto.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                      dbo.GrupoProduto ON dbo.produtos.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo INNER JOIN
					  dbo.ProdutosFornecedores ON dbo.produtos.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso INNER JOIN
                      dbo.fornecedor ON dbo.ProdutosFornecedores.For_codigo = dbo.fornecedor.For_codigo

 where vendaproduto.Ven_CodigoPre=:pVen_CodigoPre and vendaproduto.VenPro_Quantidade > 0 and ProdutosFornecedores.ProdFor_Padrao= 1

