 dbo.produtos.Pro_unidade, dbo.produtos.Pro_CodEspecial, dbo.fornecedor.For_Nome, produtos.pro_tempoInstalacao
, produtos.GrupoProduto_codigo,
                       REPLICATE('0', 2 - LEN(dbo.DevolucaoProduto.DevPro_Seq)) + CAST(dbo.DevolucaoProduto.DevPro_Seq AS varchar(2)) 
                      + ' - ' + dbo.VendaAmbiente.VenAmb_Descricao AS Nomeambiente

FROM            dbo.DevolucaoProduto INNER JOIN
                         dbo.produtos ON dbo.DevolucaoProduto.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                         dbo.GrupoProduto ON dbo.produtos.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo INNER JOIN
                         dbo.ProdutosFornecedores ON dbo.produtos.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso INNER JOIN
                         dbo.VendaAmbiente ON dbo.DevolucaoProduto.CodAmbiente = dbo.VendaAmbiente.CodAmbiente INNER JOIN
                         dbo.fornecedor ON dbo.ProdutosFornecedores.For_codigo = dbo.fornecedor.For_codigo

 where DevolucaoProduto.dev_CodigoPre =:pdev_CodigoPre and VendaAmbiente.VenAmb_NDocPre =:pVenAmb_NDocPre AND (dbo.ProdutosFornecedores.ProdFor_Padrao = 1)

