-- [QryConsulta : TADOQuery]
SELECT     ordem_compra_det.ocd_item_ped, ordem_compra_det.ocd_cod_pedido, dbo.Venda.Ven_codigo, dbo.Venda.ParSV_serie, dbo.pedido_compra_det.pcp_codigo, dbo.pedido_compra_det.pro_codnosso, dbo.pedido_compra_det.pcd_acabamento,
			dbo.pedido_compra_det.pcd_quantidade_solicit AS QtdePedido, dbo.ordem_compra_det.ocd_quantidade_solicit AS QtdeOrdem, dbo.ordem_compra.ocp_codigo, dbo.ordem_compra.ocp_dt_envio, dbo.pedido_compra.Pcp_pedido_venda, dbo.ordem_compra_det.Ocd_cod_venda

,pedido_compra_det.Pcd_item
FROM         dbo.pedido_compra INNER JOIN
                      dbo.Venda ON dbo.pedido_compra.Pcp_pedido_venda = dbo.Venda.Ven_CodigoPre INNER JOIN
                      dbo.Pedido_compra_det ON dbo.pedido_compra.Pcp_codigo = dbo.Pedido_compra_det.Pcp_codigo INNER JOIN
                      dbo.ordem_compra_det ON dbo.Pedido_compra_det.Pcd_item = dbo.ordem_compra_det.Ocd_item_ped AND 
                      dbo.Pedido_compra_det.Pcp_codigo = dbo.ordem_compra_det.Ocd_cod_pedido AND 
                      dbo.Pedido_compra_det.Pro_codnosso = dbo.ordem_compra_det.Pro_codnosso AND 
                      dbo.Pedido_compra_det.Pcd_acabamento = dbo.ordem_compra_det.Ocd_acabamento INNER JOIN
                      dbo.ordem_compra ON dbo.ordem_compra_det.Ocp_codigo = dbo.ordem_compra.Ocp_codigo
where venda.ven_codigopre =:codigo and pedido_compra_det.pro_codnosso = :pro_codnosso  and dbo.pedido_compra_det.pcd_acabamento=:acabamento and ocp_dt_envio is null

-- [QryConsultaPedVend : TADOQuery]
SELECT     dbo.Venda.Ven_codigo, dbo.Venda.ParSV_serie, dbo.Pedido_compra_det.Pcp_codigo, dbo.Pedido_compra_det.Pro_codnosso, 
                      dbo.Pedido_compra_det.Pcd_acabamento, dbo.Pedido_compra_det.Pcd_quantidade_solicit AS QtdePedido, dbo.pedido_compra.Pcp_pedido_venda,Pedido_compra_det.Pcd_item

FROM         dbo.pedido_compra INNER JOIN
                      dbo.Venda ON dbo.pedido_compra.Pcp_pedido_venda = dbo.Venda.Ven_CodigoPre INNER JOIN
                      dbo.Pedido_compra_det ON dbo.pedido_compra.Pcp_codigo = dbo.Pedido_compra_det.Pcp_codigo

WHERE  

venda.ven_codigopre =:codigo and pedido_compra_det.pro_codnosso = :pro_codnosso  and dbo.pedido_compra_det.pcd_acabamento=:acabamento 



and

   ((SELECT  top 1   dbo.ordem_compra_det.Ocd_cod_venda
                         FROM         dbo.pedido_compra AS pedido_compra_1 INNER JOIN
                                               dbo.Venda AS Venda_1 ON pedido_compra_1.Pcp_pedido_venda = Venda_1.Ven_CodigoPre INNER JOIN
                                               dbo.Pedido_compra_det AS Pedido_compra_det_1 ON pedido_compra_1.Pcp_codigo = Pedido_compra_det_1.Pcp_codigo INNER JOIN
                                               dbo.ordem_compra_det ON Pedido_compra_det_1.Pcd_item = dbo.ordem_compra_det.Ocd_item_ped AND 
                                               Pedido_compra_det_1.Pcp_codigo = dbo.ordem_compra_det.Ocd_cod_pedido AND 
                                               Pedido_compra_det_1.Pro_codnosso = dbo.ordem_compra_det.Pro_codnosso AND 
                                               Pedido_compra_det_1.Pcd_acabamento = dbo.ordem_compra_det.Ocd_acabamento INNER JOIN
                                               dbo.ordem_compra ON dbo.ordem_compra_det.Ocp_codigo = dbo.ordem_compra.Ocp_codigo
                         WHERE     (Venda_1.Ven_CodigoPre = dbo.Venda.Ven_CodigoPre) AND (Pedido_compra_det_1.Pro_codnosso = pedido_compra_det.pro_codnosso) AND 
                                               (Pedido_compra_det_1.Pcd_acabamento = dbo.pedido_compra_det.pcd_acabamento)) IS NULL)

