/* ============================================================
   FORM: FrmDuplicataRecibo   Controle de Duplicata e Recibo
   ============================================================ */

-- [Qryduplicata : TADOQuery]
SELECT  case when ctr_vinculo = 'CLIENTE' then (select cli_nome from clientes where clientes.cli_codigo = contas_receber.Ctr_codigo_vinculo) else
case when ctr_vinculo ='FORNECEDOR' THEN (select for_nome from fornecedor where fornecedor.for_codigo = contas_receber.Ctr_codigo_vinculo) else
case when ctr_vinculo ='PESSOAL' THEN (select FUN_nome from funcionario where funcionario.fun_cpf = contas_receber.Ctr_codigo_vinculo) else
case when ctr_vinculo ='INDICAÇÃO' THEN (select IND_nome from Indicacoes where Indicacoes.ind_codigo = contas_receber.Ctr_codigo_vinculo) else
case when ctr_vinculo ='OUTROS' THEN  contas_receber.Ctr_nome
end end end end end as nome, contas_Receber_det.ctr_codigo_det,
CASE WHEN contas_Receber_det.Ctr_duplicataImp IS NULL THEN 0 ELSE contas_Receber_det.Ctr_duplicataImp END AS Impressao,
contas_receber.Ctr_cod_documento , contas_receber.Ctr_vinculo , contas_receber.Ctr_codigo_vinculo ,
contas_Receber_det.Ctr_parcela as parcela ,  contas_Receber_det.Ctr_dt_vencimento as data,
contas_Receber_det.Ctr_valor_vencimento as valor, contas_Receber_det.Ctr_duplicata as numero,
contas_Receber_det.Ctr_duplicataImpData as ImpData , contas_receber.Ctr_codigo,Tipo_documento.Tpd_descricao
, contas_Receber.emp_codigo,  contas_receber.Tpd_codigo
,case when contas_Receber_det.Ctr_situacao is null or contas_Receber_det.Ctr_situacao = '' then 'N'
else case when contas_Receber_det.Ctr_situacao ='N' then 'N' else 'S' end end as Ctr_situacao



FROM contas_receber INNER JOIN
contas_Receber_det ON contas_receber.Ctr_codigo = contas_Receber_det.Ctr_codigo INNER JOIN
Tipo_documento ON dbo.contas_receber.Tpd_codigo = Tipo_documento.Tpd_codigo

-- [Qrycliente : TADOQuery]
select * from clientes where cli_Nome is not null order by cli_Nome

-- [QryRecibo : TADOQuery]
SELECT CASE WHEN ctr_vinculo = 'CLIENTE' THEN  (SELECT cli_nome FROM  clientes
WHERE clientes.cli_codigo = contas_receber.Ctr_codigo_vinculo) ELSE CASE WHEN ctr_vinculo = 'FORNECEDOR' THEN
(SELECT  for_nome FROM fornecedor wHERE  fornecedor.for_codigo = contas_receber.Ctr_codigo_vinculo) ELSE CASE WHEN ctr_vinculo = 'PESSOAL' THEN
(SELECT FUN_nome FROM funcionario WHERE funcionario.fun_cpf = contas_receber.Ctr_codigo_vinculo) ELSE CASE WHEN ctr_vinculo = 'INDICAÇÃO' THEN
(SELECT IND_nome FROM Indicacoes  WHERE  Indicacoes.ind_codigo = contas_receber.Ctr_codigo_vinculo)
 ELSE CASE WHEN ctr_vinculo = 'OUTROS' THEN contas_receber.Ctr_nome END END END END END AS nome,
 contas_Receber_det.ctr_codigo_det, CASE WHEN contas_Receber_det.Ctr_reciboImp IS NULL
 THEN 0 ELSE contas_Receber_det.Ctr_reciboImp END AS Impressao, dbo.contas_receber.Ctr_cod_documento, dbo.contas_receber.Ctr_vinculo,
  contas_receber.Ctr_codigo_vinculo, contas_receber.Ctr_codigo, Tipo_documento.Tpd_descricao, dbo.contas_receber.Emp_codigo,
   contas_receber.Tpd_codigo, contas_Receber_det.Ctr_parcela as parcela,
   CAST(Contas_receber_det.Ctr_valor_vencimento  as money) AS valor, Contas_receber_det.Ctr_dt_vencimento AS data,
   Contas_receber_det.Ctr_recibo AS numero, Contas_receber_det.Ctr_reciboImpData AS ImpData
  ,contas_Receber_pag.Crp_recibotemplate as recibotemplate,  contas_receber_det.ctr_situacao
 FROM contas_receber INNER JOIN contas_Receber_det ON contas_receber.Ctr_codigo = dbo.contas_Receber_det.Ctr_codigo INNER JOIN
 Tipo_documento ON contas_receber.Tpd_codigo = Tipo_documento.Tpd_codigo LEFT OUTER JOIN
  Contas_receber_pag ON contas_receber.Ctr_codigo = Contas_receber_pag.Ctr_codigo AND
   contas_Receber_det.ctr_codigo_det = Contas_receber_pag.ctr_codigo_det

-- [QryReciboPag : TADOQuery]
SELECT CASE WHEN ctp_vinculo = 'CLIENTE' THEN
 (SELECT     cli_nome 
  FROM          clientes
   WHERE  clientes.cli_codigo = contas_apagar.Ctp_codigo_vinculo) ELSE CASE WHEN ctp_vinculo = 'FORNECEDOR' THEN
   (SELECT for_nome
   FROM  fornecedor
  WHERE  fornecedor.for_codigo = contas_apagar.Ctp_codigo_vinculo) ELSE CASE WHEN ctp_vinculo = 'PESSOAL' THEN
   (SELECT     FUN_nome
   FROM  funcionario
   WHERE  funcionario.fun_cpf = contas_apagar.Ctp_codigo_vinculo) ELSE CASE WHEN ctp_vinculo = 'INDICAÇÃO' THEN
   (SELECT IND_nome
   FROM  Indicacoes
   WHERE  Indicacoes.ind_codigo = contas_apagar.Ctp_codigo_vinculo)
   ELSE CASE WHEN ctp_vinculo = 'OUTROS' THEN contas_apagar.Ctp_nome END END END END END AS nome,
   contas_apagar_det.ctp_codigo_det, CASE WHEN contas_apagar_det.ctp_reciboImp IS NULL
   THEN 0 ELSE contas_apagar_det.ctp_reciboImp END AS Impressao, contas_apagar.Ctp_cod_documento, contas_apagar.Ctp_vinculo,
   contas_apagar.Ctp_codigo_vinculo, contas_apagar.Ctp_codigo, Tipo_documento.Tpd_descricao, contas_apagar.Emp_codigo,
   contas_apagar.Tpd_codigo, contas_apagar_det.Ctp_parcela AS parcela, 
  CAST(Contas_apagar_det.Ctp_valor_vencimento AS money) AS valor, Contas_apagar_det.Ctp_dt_vencimento AS data,
 Contas_apagar_det.Ctp_recibo AS numero, Contas_apagar_det.Ctp_reciboImpData AS ImpData,
 Contas_apagar_det.Ctp_recibotemplate AS recibotemplate
  FROM contas_apagar INNER JOIN
  contas_apagar_det ON contas_apagar.Ctp_codigo = contas_apagar_det.Ctp_codigo INNER JOIN
   Tipo_documento ON contas_apagar.Tpd_codigo = Tipo_documento.Tpd_codigo LEFT OUTER JOIN
  Contas_apagar_pag ON contas_apagar.Ctp_codigo = Contas_apagar_pag.Ctp_codigo AND
   contas_apagar_det.ctp_codigo_det = Contas_apagar_pag.ctp_codigo_det

-- [QryRecTotal : TADOQuery]
SELECT     CASE WHEN ctr_vinculo = 'CLIENTE' THEN
                          (SELECT     cli_nome
                            FROM          clientes
                            WHERE      clientes.cli_codigo = contas_receber.Ctr_codigo_vinculo) ELSE CASE WHEN ctr_vinculo = 'FORNECEDOR' THEN
                          (SELECT     for_nome
                            FROM          fornecedor
                            WHERE      fornecedor.for_codigo = contas_receber.Ctr_codigo_vinculo) ELSE CASE WHEN ctr_vinculo = 'PESSOAL' THEN
                          (SELECT     FUN_nome
                            FROM          funcionario
                            WHERE      funcionario.fun_cpf = contas_receber.Ctr_codigo_vinculo) ELSE CASE WHEN ctr_vinculo = 'INDICAÇÃO' THEN
                          (SELECT     IND_nome
                            FROM          Indicacoes
                            WHERE      Indicacoes.ind_codigo = contas_receber.Ctr_codigo_vinculo) 
                      ELSE CASE WHEN ctr_vinculo = 'OUTROS' THEN contas_receber.Ctr_nome END END END END END AS nome, CASE WHEN contas_Receber.Ctr_reciboImp IS NULL 
                      THEN 0 ELSE contas_Receber.Ctr_reciboImp END AS Impressao, dbo.contas_receber.Ctr_cod_documento, dbo.contas_receber.Ctr_vinculo, 
                      dbo.contas_receber.Ctr_codigo_vinculo, dbo.contas_receber.Ctr_codigo, dbo.Tipo_documento.Tpd_descricao, dbo.contas_receber.Emp_codigo, 
                      dbo.contas_receber.Tpd_codigo, CAST(dbo.contas_receber.Ctr_valor_total_original AS money) AS valor,
                          (SELECT     COUNT(Ctr_codigo) AS Expr1
                            FROM          dbo.contas_Receber_det
                            WHERE      (Ctr_codigo = dbo.contas_receber.Ctr_codigo)) AS parcela, dbo.contas_receber.Ctr_status
, contas_receber.Ctr_recibo as numero, contas_Receber.Ctr_recibotemplate as recibotemplate
FROM         dbo.contas_receber INNER JOIN
                      dbo.Tipo_documento ON dbo.contas_receber.Tpd_codigo = dbo.Tipo_documento.Tpd_codigo


