-- [QryConferir : TADOQuery]
SELECT dbo.controle_entrega_data.Pro_codnosso, dbo.controle_entrega_data.cep_acabamento, SUM(dbo.controle_entrega_data.ced_quantidade) AS ced_quantidade2, dbo.controle_entrega_data.cep_tipo, dbo.produtos.Pro_descricao, 
                  dbo.Acabamento.DescAcabamento, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, 
                  dbo.controle_entrega_data.cen_codigo_pre, produtos.Pro_CodReduzido

			
, case when SUM(dbo.controle_entrega_data.ced_quantidade) > (select top 1  (cep_quantidade - cep_quantidade_entregue) as resultado from controle_entrega_prod where cen_codigo_pre =controle_entrega_data.cen_codigo_pre 
and controle_entrega_prod.Pro_codnosso = controle_entrega_data.Pro_codnosso and controle_entrega_prod.cep_acabamento = controle_entrega_data.cep_acabamento ) then
(select top 1  (cep_quantidade - cep_quantidade_entregue) as resultado from controle_entrega_prod where cen_codigo_pre =controle_entrega_data.cen_codigo_pre 
and controle_entrega_prod.Pro_codnosso = controle_entrega_data.Pro_codnosso and controle_entrega_prod.cep_acabamento = controle_entrega_data.cep_acabamento ) else SUM(dbo.controle_entrega_data.ced_quantidade) end as ced_quantidade
			
			
			
			, (select top 1  (cep_quantidade - cep_quantidade_entregue) as resultado from controle_entrega_prod where cen_codigo_pre =controle_entrega_data.cen_codigo_pre 
and controle_entrega_prod.Pro_codnosso = controle_entrega_data.Pro_codnosso and controle_entrega_prod.cep_acabamento = controle_entrega_data.cep_acabamento ) as QuantEntregar







FROM     dbo.controle_entrega_data INNER JOIN
                  dbo.produtos ON dbo.controle_entrega_data.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                  dbo.Acabamento ON dbo.controle_entrega_data.cep_acabamento = dbo.Acabamento.CodAcabamento INNER JOIN
                  dbo.ProdutosFornecedores ON dbo.controle_entrega_data.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso LEFT OUTER JOIN
                  dbo.ProdutosLocEstoque ON dbo.controle_entrega_data.Pro_codnosso = dbo.ProdutosLocEstoque.Pro_codnosso AND dbo.controle_entrega_data.cep_acabamento = dbo.ProdutosLocEstoque.CodAcabamento
WHERE  (dbo.controle_entrega_data.cep_tipo = 'S') and controle_entrega_data.cen_codigo_pre =:pcen_codigo_pre  and controle_entrega_data.Ced_ordemSeparacao =:pCed_ordemSeparacao

and (select top 1  (cep_quantidade - cep_quantidade_entregue) as resultado from controle_entrega_prod where cen_codigo_pre =controle_entrega_data.cen_codigo_pre 
and controle_entrega_prod.Pro_codnosso = controle_entrega_data.Pro_codnosso and controle_entrega_prod.cep_acabamento = controle_entrega_data.cep_acabamento ) > 0


GROUP BY dbo.controle_entrega_data.Pro_codnosso, dbo.controle_entrega_data.cep_acabamento, dbo.controle_entrega_data.cep_tipo, dbo.produtos.Pro_descricao, dbo.Acabamento.DescAcabamento, 
                  dbo.ProdutosFornecedores.ProdFor_CodigoProduto, 
                  dbo.controle_entrega_data.cen_codigo_pre,produtos.Pro_CodReduzido

