   FORM: FrmEscolhaSubProd   Escolha o produto relacionado
   ============================================================ */

-- [QryDescAcabamento : TADOQuery]
SELECT     
CodAcabamento +' -  '+ 
case when acab_tipo =  'E' then 'Ext.:' else
case when acab_tipo =  'T' then 'Ext. e Inter.:' else
''
end
end   + DescAcabamento + '  ' + case when acab_tipo2 =  'I' then 'Inter.:' else '' end + case when DescAcabamento2 is null then '' else DescAcabamento2 end

as descricao

,CodAcabamento

FROM           dbo.Acabamento

-- [QryBuscaProduto : TADOQuery]
SELECT dbo.ProdutosRelacionados.ProdRel_Descricao, dbo.ProdutosRelacionados.ProdRel_Situacao, dbo.ProdutosRelacionadosDet.Pro_codnosso, dbo.ProdutosRelacionadosDet.CodAcabamento, 
                  dbo.ProdutosRelacionadosDet.ProdRelDet_Quantidade, dbo.ProdutosRelacionadosDet.Tam_codigo, dbo.ProdutosRelacionados.ProdRel_codigo, dbo.produtos.Pro_descricao, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, 
                  dbo.ProdutosFornecedores.ProdFor_DescricaoProduto, dbo.Preco_Produto.Pre_CodForTamanho, dbo.tamanho.Tam_descricao,dbo.Preco_Produto.Pre_Venda

FROM     dbo.ProdutosRelacionados INNER JOIN
                  dbo.ProdutosRelacionadosDet ON dbo.ProdutosRelacionados.ProdRel_codigo = dbo.ProdutosRelacionadosDet.ProdRel_codigo INNER JOIN
                  dbo.ProdutosRelacionadosCadProdutos ON dbo.ProdutosRelacionados.ProdRel_codigo = dbo.ProdutosRelacionadosCadProdutos.ProdRel_codigo INNER JOIN
                  dbo.produtos ON dbo.ProdutosRelacionadosCadProdutos.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                  dbo.ProdutosFornecedores ON dbo.produtos.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso LEFT OUTER JOIN
                  dbo.tamanho ON dbo.ProdutosRelacionadosDet.Tam_codigo = dbo.tamanho.Tam_codigo LEFT OUTER JOIN
                  dbo.Preco_Produto ON dbo.ProdutosRelacionadosDet.Pro_codnosso = dbo.Preco_Produto.Pre_Codnosso AND dbo.ProdutosRelacionadosDet.CodAcabamento = dbo.Preco_Produto.Pre_Acabamento AND 
                  dbo.ProdutosRelacionadosDet.Tam_codigo = dbo.Preco_Produto.Tam_codigo

WHERE  (dbo.ProdutosRelacionados.ProdRel_Situacao = 1) and ProdutosRelacionadosCadProdutos.Pro_codnosso =:pPro_codnosso


