-- [qryprecos : TADOQuery]
SELECT     dbo.Preco_Produto.Pre_Codnosso, dbo.Preco_Produto.Pre_Acabamento, dbo.Preco_Produto.Pre_Codindice, dbo.Preco_Produto.Pre_EstMinCalcular, 
                      dbo.Preco_Produto.pre_codigo, dbo.Preco_Produto.Pre_Ativo, dbo.produtos.Pro_descricao, dbo.produtos.Pro_descricao_for, 
                      dbo.produtos.Pro_Codbase, dbo.produtos.For_codigo, dbo.TipoPeca.TpPeca_Codigo, dbo.GrupoProduto.GrupoProduto_Descricao, 
                      dbo.Preco_Produto.Pre_est_min, dbo.Estoque_produto.Epr_estoque,
produtos.Pro_CodEspecial
FROM         dbo.TipoPeca RIGHT OUTER JOIN
                      dbo.Estoque_produto INNER JOIN
                      dbo.Preco_Produto INNER JOIN
                      dbo.produtos ON dbo.Preco_Produto.Pre_Codnosso = dbo.produtos.Pro_codnosso ON 
                      dbo.Estoque_produto.Epr_Codnosso = dbo.Preco_Produto.Pre_Codnosso AND 
                      dbo.Estoque_produto.Epr_Acabamento = dbo.Preco_Produto.Pre_Acabamento ON 
                      dbo.TipoPeca.TpPeca_Codigo = dbo.produtos.Pro_tp_peca LEFT OUTER JOIN
                      dbo.GrupoProduto ON dbo.TipoPeca.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo

