/* ============================================================
   FORM: FrmEtiqVendAmbMod4   FrmEtiqVendAmbMod4
   ============================================================ */

-- [Qryetiqueta : TADOQuery]
SELECT     dbo.pedido.ped_codigo, dbo.Clientes.Cli_Nome, dbo.produtos.Pro_Codbase, dbo.produtos.Pro_codnosso, dbo.produtos.Pro_descricao, 
                      dbo.produtos.Pro_descricao_for, dbo.produtos.Pro_CodEspecial, SUM(dbo.pedido_luminaria_det.pld_quantidade) AS quantidade, dbo.Acabamento.DescAcabamento, 
                      dbo.produtos.Pro_unidade, dbo.pedido.ped_dt_fechamento, dbo.GrupoProduto.GrupoProduto_Descricao, dbo.produtos.Pro_tp_peca
FROM         dbo.pedido INNER JOIN
                      dbo.pedido_luminaria_det ON dbo.pedido.ped_codigo_pre = dbo.pedido_luminaria_det.ped_codigo_pre INNER JOIN
                      dbo.Clientes ON dbo.pedido.cli_codigo = dbo.Clientes.Cli_Codigo INNER JOIN
                      dbo.produtos ON dbo.pedido_luminaria_det.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                      dbo.Acabamento ON dbo.pedido_luminaria_det.pld_acabamento = dbo.Acabamento.CodAcabamento INNER JOIN
                      dbo.GrupoProduto ON dbo.produtos.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo
where pedido_luminaria_det.Pro_codnosso in (:produtos1) and pedido.ped_codigo =:pcodigo1

GROUP BY dbo.pedido.ped_codigo, dbo.Clientes.Cli_Nome, dbo.produtos.Pro_Codbase, dbo.produtos.Pro_codnosso, dbo.produtos.Pro_descricao, 
                      dbo.produtos.Pro_descricao_for, dbo.produtos.Pro_CodEspecial, dbo.Acabamento.DescAcabamento, dbo.produtos.Pro_unidade, dbo.pedido.ped_dt_fechamento, 
                      dbo.GrupoProduto.GrupoProduto_Descricao, dbo.produtos.Pro_tp_peca


/* ============================================================
   FORM: FrmExcluirRelacionado   Exclusão de produtos relacionados (desativados e com estoque zero)
   ============================================================ */

-- [QryProdutos : TADOQuery]
SELECT     TOP (100) PERCENT dbo.produtos.Pro_codnosso, dbo.produtos.Pro_Codbase, dbo.produtos.Pro_descricao, dbo.produtos.Pro_descricao_for, 
                      dbo.fornecedor.For_Nome, dbo.TipoPeca.TpPeca_Codigo, dbo.GrupoProduto.GrupoProduto_Descricao
FROM         dbo.produtos INNER JOIN
                      dbo.Produto_Relacionados ON dbo.produtos.Pro_codnosso = dbo.Produto_Relacionados.Pre_Cod_Prod_filho AND 
                      dbo.produtos.For_codigo = dbo.Produto_Relacionados.pre_codigofor_filho INNER JOIN
                      dbo.Preco_Produto ON dbo.produtos.Pro_codnosso = dbo.Preco_Produto.Pre_Codnosso INNER JOIN
                      dbo.Estoque_produto ON dbo.Preco_Produto.Pre_Codnosso = dbo.Estoque_produto.Epr_Codnosso AND 
                      dbo.Preco_Produto.Pre_Acabamento = dbo.Estoque_produto.Epr_Acabamento INNER JOIN
                      dbo.fornecedor ON dbo.produtos.For_codigo = dbo.fornecedor.For_codigo LEFT OUTER JOIN
                      dbo.GrupoProduto ON dbo.produtos.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo LEFT OUTER JOIN
                      dbo.TipoPeca ON dbo.produtos.Pro_tp_peca = dbo.TipoPeca.TpPeca_Codigo
WHERE     (dbo.produtos.Pro_ativo = 'N') AND (dbo.Estoque_produto.Epr_estoque <= 0) OR
                      (dbo.Preco_Produto.Pre_Ativo = 'N') AND (dbo.Estoque_produto.Epr_estoque <= 0)
GROUP BY dbo.produtos.Pro_codnosso, dbo.produtos.Pro_Codbase, dbo.produtos.Pro_descricao, dbo.produtos.Pro_descricao_for, dbo.fornecedor.For_Nome, 
                      dbo.TipoPeca.TpPeca_Codigo, dbo.GrupoProduto.GrupoProduto_Descricao
ORDER BY dbo.fornecedor.For_Nome, dbo.produtos.Pro_codnosso, dbo.produtos.Pro_Codbase


