/* ============================================================
   FORM: FrmExportarFinanceiro   Exportar Financeiro
   ============================================================ */

-- [QryCONTA : TADOQuery]
SELECT TOP (100) PERCENT dbo.contas_apagar.Ctp_vinculo AS VINCULO, dbo.contas_apagar.Ctp_codigo_vinculo AS CODIGO_VINCULO, dbo.contas_apagar.Ctp_nome AS NOME, 
                  CASE WHEN contas_apagar.Ctp_vinculo = 'FORNECEDOR' THEN
                      (SELECT For_Razao
                       FROM      fornecedor
                       WHERE   for_codigo = contas_apagar.Ctp_codigo_vinculo) 
                  ELSE CASE WHEN contas_apagar.Ctp_vinculo = 'OUTROS' THEN contas_apagar.Ctp_nome ELSE CASE WHEN contas_apagar.Ctp_vinculo = 'PROFISSIONAL EXTERNO' THEN
                      (SELECT Ind_Nome
                       FROM      Indicacoes
                       WHERE   Ind_codigo = contas_apagar.Ctp_codigo_vinculo) 
                  ELSE CASE WHEN contas_apagar.Ctp_vinculo = 'CLIENTE' THEN contas_apagar.Ctp_nome ELSE CASE WHEN contas_apagar.Ctp_vinculo = 'PESSOAL' THEN contas_apagar.Ctp_nome ELSE CASE WHEN contas_apagar.Ctp_vinculo = 'TRANSPORTADORA'
                   THEN contas_apagar.Ctp_nome ELSE contas_apagar.Ctp_nome END END END END END END AS razao, dbo.contas_apagar_det.Ctp_parcela AS PARCELA, dbo.contas_apagar.Ctp_cod_documento AS DOCUMENTO, 
                  dbo.Contas_apagar_pag.Cpp_valor_pago AS VALOR, 


dbo.Contas_apagar_pag.Cpp_data_pagamento  AS DATA, 



dbo.Tipo_documento.Tpd_descricao, dbo.contas_apagar.Ctp_codigo AS CONTA, 
                  dbo.contas_apagar_det.Ctp_dt_vencimento AS data_vencimento, dbo.Bancos_Caixas.Bcx_agencia, dbo.Contas_Bancarias.Cba_numero, dbo.Bancos_Caixas.Bcx_Nome, dbo.contas_apagar.Ctp_historico AS historico
,dbo.contas_apagar_det.Ctp_valor_vencimento AS valor_vencimento
, contas_apagar_det.Ctp_CodigoBarra as Codigo_Barra
FROM     dbo.Bancos_Caixas INNER JOIN
                  dbo.Contas_Bancarias ON dbo.Bancos_Caixas.Bcx_codigo = dbo.Contas_Bancarias.Bcx_codigo AND dbo.Bancos_Caixas.Bcx_codigo = dbo.Contas_Bancarias.Bcx_codigo AND 
                  dbo.Bancos_Caixas.Bcx_codigo = dbo.Contas_Bancarias.Bcx_codigo AND dbo.Bancos_Caixas.Bcx_codigo = dbo.Contas_Bancarias.Bcx_codigo AND dbo.Bancos_Caixas.Emp_codigo = dbo.Contas_Bancarias.Emp_codigo INNER JOIN
                  dbo.contas_apagar INNER JOIN
                  dbo.contas_apagar_det ON dbo.contas_apagar.Ctp_codigo = dbo.contas_apagar_det.Ctp_codigo INNER JOIN
                  dbo.Contas_apagar_pag ON dbo.Contas_apagar_pag.ctp_codigo_det = dbo.contas_apagar_det.ctp_codigo_det INNER JOIN
                  dbo.Tipo_documento ON dbo.Tipo_documento.Tpd_codigo = dbo.contas_apagar.Tpd_codigo ON dbo.Contas_Bancarias.Cba_codigo = dbo.Contas_apagar_pag.cba_codigo

-- [QryParcela : TADOQuery]
SELECT dbo.contas_apagar.Ctp_vinculo AS VINCULO, dbo.contas_apagar.Ctp_codigo_vinculo AS CODIGO_VINCULO, dbo.contas_apagar.Ctp_nome AS NOME, CASE WHEN contas_apagar.Ctp_vinculo = 'FORNECEDOR' THEN
                      (SELECT For_Razao
                       FROM      fornecedor
                       WHERE   for_codigo = contas_apagar.Ctp_codigo_vinculo) 
                  ELSE CASE WHEN contas_apagar.Ctp_vinculo = 'OUTROS' THEN contas_apagar.Ctp_nome ELSE CASE WHEN contas_apagar.Ctp_vinculo = 'PROFISSIONAL EXTERNO' THEN
                      (SELECT Ind_Nome
                       FROM      Indicacoes
                       WHERE   Ind_codigo = contas_apagar.Ctp_codigo_vinculo) 
                  ELSE CASE WHEN contas_apagar.Ctp_vinculo = 'CLIENTE' THEN contas_apagar.Ctp_nome ELSE CASE WHEN contas_apagar.Ctp_vinculo = 'PESSOAL' THEN contas_apagar.Ctp_nome ELSE CASE WHEN contas_apagar.Ctp_vinculo = 'TRANSPORTADORA'
                   THEN contas_apagar.Ctp_nome ELSE contas_apagar.Ctp_nome END END END END END END AS razao, dbo.contas_apagar_det.Ctp_parcela AS PARCELA, dbo.contas_apagar.Ctp_cod_documento AS DOCUMENTO, 
                  dbo.Contas_apagar_pag.Cpp_valor_pago AS VALOR, dbo.Contas_apagar_pag.Cpp_data_pagamento AS DATA, dbo.Tipo_documento.Tpd_descricao, dbo.contas_apagar.Ctp_codigo AS CONTA
FROM     dbo.contas_apagar INNER JOIN
                  dbo.contas_apagar_det ON dbo.contas_apagar.Ctp_codigo = dbo.contas_apagar_det.Ctp_codigo INNER JOIN
                  dbo.Contas_apagar_pag ON dbo.contas_apagar_det.ctp_codigo_det = dbo.Contas_apagar_pag.ctp_codigo_det INNER JOIN
                  dbo.Tipo_documento ON dbo.contas_apagar.Tpd_codigo = dbo.Tipo_documento.Tpd_codigo

-- [ADOQuery1 : TADOQuery]
SELECT TOP (100) PERCENT dbo.contas_apagar.Ctp_vinculo AS VINCULO, dbo.contas_apagar.Ctp_codigo_vinculo AS CODIGO_VINCULO, dbo.contas_apagar.Ctp_nome AS NOME, 
                  CASE WHEN contas_apagar.Ctp_vinculo = 'FORNECEDOR' THEN
                      (SELECT For_Razao
                       FROM      fornecedor
                       WHERE   for_codigo = contas_apagar.Ctp_codigo_vinculo) 
                  ELSE CASE WHEN contas_apagar.Ctp_vinculo = 'OUTROS' THEN contas_apagar.Ctp_nome ELSE CASE WHEN contas_apagar.Ctp_vinculo = 'PROFISSIONAL EXTERNO' THEN
                      (SELECT Ind_Nome
                       FROM      Indicacoes
                       WHERE   Ind_codigo = contas_apagar.Ctp_codigo_vinculo) 
                  ELSE CASE WHEN contas_apagar.Ctp_vinculo = 'CLIENTE' THEN contas_apagar.Ctp_nome ELSE CASE WHEN contas_apagar.Ctp_vinculo = 'PESSOAL' THEN contas_apagar.Ctp_nome ELSE CASE WHEN contas_apagar.Ctp_vinculo = 'TRANSPORTADORA'
                   THEN contas_apagar.Ctp_nome ELSE contas_apagar.Ctp_nome END END END END END END AS razao, dbo.contas_apagar_det.Ctp_parcela AS PARCELA, dbo.contas_apagar.Ctp_cod_documento AS DOCUMENTO, 
                  dbo.Contas_apagar_pag.Cpp_valor_pago AS VALOR, 


dbo.Contas_apagar_pag.Cpp_data_pagamento  AS DATA, 



dbo.Tipo_documento.Tpd_descricao, dbo.contas_apagar.Ctp_codigo AS CONTA, 
                  dbo.contas_apagar_det.Ctp_dt_vencimento AS data_vencimento, dbo.Bancos_Caixas.Bcx_agencia, dbo.Contas_Bancarias.Cba_numero, dbo.Bancos_Caixas.Bcx_Nome, dbo.contas_apagar.Ctp_historico AS historico
,dbo.contas_apagar_det.Ctp_valor_vencimento AS valor_vencimento
, contas_apagar_det.Ctp_CodigoBarra as Codigo_Barra
FROM     dbo.Bancos_Caixas INNER JOIN
                  dbo.Contas_Bancarias ON dbo.Bancos_Caixas.Bcx_codigo = dbo.Contas_Bancarias.Bcx_codigo AND dbo.Bancos_Caixas.Bcx_codigo = dbo.Contas_Bancarias.Bcx_codigo AND 
                  dbo.Bancos_Caixas.Bcx_codigo = dbo.Contas_Bancarias.Bcx_codigo AND dbo.Bancos_Caixas.Bcx_codigo = dbo.Contas_Bancarias.Bcx_codigo AND dbo.Bancos_Caixas.Emp_codigo = dbo.Contas_Bancarias.Emp_codigo INNER JOIN
                  dbo.contas_apagar INNER JOIN
                  dbo.contas_apagar_det ON dbo.contas_apagar.Ctp_codigo = dbo.contas_apagar_det.Ctp_codigo INNER JOIN
                  dbo.Contas_apagar_pag ON dbo.Contas_apagar_pag.ctp_codigo_det = dbo.contas_apagar_det.ctp_codigo_det INNER JOIN
                  dbo.Tipo_documento ON dbo.Tipo_documento.Tpd_codigo = dbo.contas_apagar.Tpd_codigo ON dbo.Contas_Bancarias.Cba_codigo = dbo.Contas_apagar_pag.cba_codigo


/* ============================================================
   FORM: FrmExportarVenda   Exportar Pedido de Venda
   ============================================================ */

-- [Qryvendas : TADOQuery]
SELECT 
(
SELECT TOP 1 dbo.Funcionario.Fun_Nome
FROM     dbo.VendaAtendente INNER JOIN
                  dbo.Funcionario ON dbo.VendaAtendente.Fun_Codigo = dbo.Funcionario.Fun_CPF
				  where VendaAtendente.VenAten_NDocPre = venda.Ven_CodigoPre 
) as atendente
,
(

SELECT TOP 1 dbo.Indicacoes.Ind_Nome
FROM     dbo.VendaIndicacao INNER JOIN
                  dbo.Indicacoes ON dbo.VendaIndicacao.Ind_Codigo = dbo.Indicacoes.Ind_codigo
				  WHERE VendaIndicacao.VenInd_NDocPre = venda.Ven_CodigoPre

) AS PROFISSIONAL

,
max(venda.Ven_SubTotal ) as subtotal
,
max(venda.Ven_DescontoPorc) as desconto_porcentagem
,
max(venda.Ven_Desconto) as desconto
,
max(venda.Ven_Total ) as total
, 
max(venda.Ven_TotalServ) as serviços
,
(
SELECT SUM(dbo.VendaProduto.VenPro_VlItem) AS luminariais
FROM     dbo.VendaProduto INNER JOIN
                  dbo.produtos ON dbo.VendaProduto.Pro_codnosso = dbo.produtos.Pro_codnosso
WHERE  (dbo.produtos.GrupoProduto_codigo = 1) and venda.Ven_CodigoPre = VendaProduto.Ven_CodigoPre 
) as Valor_luminaria
,

(
SELECT SUM(dbo.VendaProduto.VenPro_VlItem) AS luminariais
FROM     dbo.VendaProduto INNER JOIN
                  dbo.produtos ON dbo.VendaProduto.Pro_codnosso = dbo.produtos.Pro_codnosso
WHERE  (dbo.produtos.GrupoProduto_codigo <> 1) and venda.Ven_CodigoPre = VendaProduto.Ven_CodigoPre 
) as Valor_outros
, 
Cli_Nome 
,
venda.Ven_DataEmissao , venda.ven_codigo


FROM     dbo.Venda inner join Clientes on venda.Ven_CodVinculo = Clientes.Cli_Codigo   
WHERE  (dbo.Venda.Ven_Situacao = 'A') AND (dbo.Venda.Ven_Tipo = 'P')
and venda.Ven_DataEmissao >=:data1 and venda.Ven_DataEmissao <=:data2
GROUP BY dbo.Venda.Ven_CodigoPre, Cli_Nome, venda.Ven_DataEmissao,VENDA.VEN_CODIGO
  
order by atendente,venda.Ven_DataEmissao


