  dbo.Clientes.Cli_Endereco as endereco,
  dbo.Clientes.Cli_numero as num,
  dbo.Clientes.Cli_complemento as comp,
  dbo.Clientes.Cli_Bairro as bairro,
Clientes.Cli_CEP as cep,
