   FORM: FrmFact_ImpressaoMod2   FrmFact_ImpressaoMod2
   ============================================================ */

-- [QryFactura : TADOQuery]
SELECT    dbo.Factura.*, TipoExpedicao.TpExp_Descricao  
FROM         dbo.Factura LEFT OUTER JOIN
                      dbo.TipoExpedicao ON dbo.Factura.TpExp_Codigo = dbo.TipoExpedicao.TpExp_Codigo
WHERE
  (dbo.Factura.Fact_Tipo = :PFact_tipo) AND 
