-- [Qryprodutos : TADOQuery]
SELECT  dbo.FacturaProduto.*,
  dbo.produtos.Pro_descricao,
  dbo.produtos.Pro_unidade
FROM
  dbo.FacturaProduto
  INNER JOIN dbo.produtos ON (dbo.FacturaProduto.Pro_codnosso = dbo.produtos.Pro_codnosso)
