-- [QryRelacionado : TADOQuery]
SELECT     TOP (100) PERCENT dbo.Preco_Produto.Pre_Codindice, dbo.Produto_Relacionados.pre_nao_relacionado, 
                      dbo.Produto_Relacionados.Pre_Cod_Prod_Pai, dbo.Produto_Relacionados.pre_quantidade, dbo.produtos.Pro_codnosso,dbo. produtos.Pro_AliqICMS, dbo.produtos.Pro_Codbase, 
                      dbo.produtos.For_codigo, dbo.produtos.GrupoProduto_codigo, dbo.produtos.Pro_lamp_reator, dbo.produtos.Pro_tp_peca, dbo.produtos.Pro_descricao, 
                      dbo.produtos.Pro_quant_minima, dbo.produtos.Pro_unidade, MAX(dbo.Preco_Produto.Pre_Acabamento) AS Pre_Acabamento, 
                      MAX(dbo.Preco_Produto.Pre_Venda) AS Pre_Venda, dbo.Produto_Relacionados.pre_padrao, 
                      dbo.Produto_Relacionados.pre_nao_relacionado AS Expr1
FROM         dbo.Produto_Relacionados INNER JOIN
                      dbo.produtos ON dbo.Produto_Relacionados.Pre_Cod_Prod_filho = dbo.produtos.Pro_codnosso INNER JOIN
                      dbo.Preco_Produto ON dbo.produtos.Pro_codnosso = dbo.Preco_Produto.Pre_Codnosso
GROUP BY dbo.Produto_Relacionados.Pre_Cod_Prod_Pai, dbo.Produto_Relacionados.pre_quantidade, dbo.produtos.Pro_codnosso, dbo.produtos.Pro_Codbase, 
                      dbo.produtos.For_codigo, dbo.produtos.GrupoProduto_codigo, dbo.produtos.Pro_tp_peca, dbo.produtos.Pro_descricao,dbo. produtos.Pro_AliqICMS, 
                      dbo.produtos.Pro_quant_minima, dbo.produtos.Pro_lamp_reator, dbo.produtos.Pro_unidade, dbo.Produto_Relacionados.pre_padrao, 
                      dbo.Produto_Relacionados.pre_nao_relacionado, dbo.Preco_Produto.Pre_Codindice
HAVING      (dbo.Produto_Relacionados.Pre_Cod_Prod_Pai =:produto) AND (dbo.Produto_Relacionados.pre_padrao = 'S')
ORDER BY dbo.produtos.GrupoProduto_codigo

