-- [QryBalanco : TADOQuery]
SELECT     BalEst_Codigo, BalEst_Descricao + ' DATA: ' + CONVERT(varchar(10), BalEst_Data, 103) AS DESCRICAO
FROM            dbo.BalancoEstoque
ORDER BY BalEst_Data DESC

-- [QryBuscaBalanco : TADOQuery]
SELECT        TOP (100) PERCENT dbo.BalancoEstoqueProdutos.BalEst_Codigo, Produtos.Pro_Codnosso, dbo.Preco_Produto.Pre_Acabamento, 
                         ProdutosFornecedores.For_codigo, dbo.Estoque_produto.Epr_estoque,
(

SELECT        SUM(dbo.Pedido_compra_det.Pcd_quantidade_solicit) AS total
FROM            dbo.Pedido_compra_det LEFT OUTER JOIN
                         dbo.ordem_compra_det ON dbo.Pedido_compra_det.Pcp_codigo = dbo.ordem_compra_det.Ocd_cod_pedido AND 
                         dbo.Pedido_compra_det.Pcd_item = dbo.ordem_compra_det.Ocd_item AND dbo.Pedido_compra_det.Pro_codnosso = dbo.ordem_compra_det.Pro_codnosso AND 
                         dbo.Pedido_compra_det.Pcd_acabamento = dbo.ordem_compra_det.Ocd_acabamento
WHERE        (YEAR(dbo.Pedido_compra_det.usr_dt_hr_criacao) > 2013) AND (dbo.Pedido_compra_det.Pcd_recebimento IS NULL) AND 
                         (dbo.ordem_compra_det.Ocp_codigo IS NULL) AND (dbo.Pedido_compra_det.Pcd_destino IS NULL)
and Preco_Produto.Pre_Codnosso = Pedido_compra_det.Pro_codnosso   and Preco_Produto.Pre_Acabamento = Pedido_compra_det.Pcd_acabamento 


) as totalpedido
,
(

SELECT        SUM(dbo.ordem_compra_det.Ocd_quantidade_pedido - CASE WHEN nota_entrada_det.Ned_quantidade_recebida > 0 THEN nota_entrada_det.Ned_quantidade_recebida
                          ELSE 0 END) AS total
FROM            dbo.ordem_compra_det LEFT OUTER JOIN
                         dbo.nota_entrada_det ON dbo.ordem_compra_det.Pro_codnosso = dbo.nota_entrada_det.Pro_codnosso AND 
                         dbo.ordem_compra_det.Ocd_acabamento = dbo.nota_entrada_det.Ned_acabamento AND 
                         dbo.ordem_compra_det.Ocd_item = dbo.nota_entrada_det.Ned_item_ordem AND 
                         dbo.ordem_compra_det.Ocp_codigo = dbo.nota_entrada_det.Ned_cod_ordem
WHERE       ( (dbo.ordem_compra_det.Ocd_recebimento IS NULL) OR
                         (dbo.ordem_compra_det.Ocd_recebimento = 'PARCIAL'))
and Preco_Produto.Pre_Codnosso = ordem_compra_det.Pro_codnosso   and Preco_Produto.Pre_Acabamento = ordem_compra_det.Ocd_acabamento  



) as totalordem


FROM            dbo.Preco_Produto INNER JOIN
                         dbo.produtos ON dbo.Preco_Produto.Pre_Codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                         dbo.Estoque_produto ON dbo.Preco_Produto.Pre_Codnosso = dbo.Estoque_produto.Epr_Codnosso AND dbo.Preco_Produto.Pre_Acabamento = dbo.Estoque_produto.Epr_Acabamento INNER JOIN
                         dbo.ProdutosFornecedores ON dbo.produtos.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso LEFT OUTER JOIN
                         dbo.BalancoEstoqueProdutos ON dbo.Preco_Produto.Pre_Codnosso = dbo.BalancoEstoqueProdutos.Pro_Codnosso AND dbo.Preco_Produto.Pre_Acabamento = dbo.BalancoEstoqueProdutos.CodAcabamento AND 
                         dbo.BalancoEstoqueProdutos.BalEst_Codigo =:pBalEst_Codigo




WHERE        (ProdutosFornecedores.For_codigo =:pFor_codigo) AND (dbo.Estoque_produto.Epr_estoque <> 0) AND (dbo.BalancoEstoqueProdutos.BalEstProd_Codigo IS NULL)


ORDER BY Produtos.Pro_Codnosso

-- [QryProdutosCalc : TADOQuery]
SELECT        dbo.unidades.uni_descricao, dbo.GrupoProduto.GrupoProduto_Descricao, dbo.ProdutosFornecedores.ProdFor_CodigoProduto AS Pro_Codbase, dbo.produtos.Pro_descricao, 
                         dbo.ProdutosFornecedores.ProdFor_DescricaoProduto, dbo.produtos.Pro_CodEspecial, dbo.fornecedor.For_Nome, dbo.TipoPeca.TpPeca_Codigo, dbo.produtos.Pro_unidade, dbo.produtos.Pro_codnosso, 
                         dbo.Preco_Produto.Pre_Acabamento
FROM            dbo.ProdutosFornecedores INNER JOIN
                         dbo.fornecedor ON dbo.ProdutosFornecedores.For_codigo = dbo.fornecedor.For_codigo INNER JOIN
                         dbo.produtos INNER JOIN
                         dbo.TipoPeca ON dbo.produtos.GrupoProduto_codigo = dbo.TipoPeca.GrupoProduto_codigo INNER JOIN
                         dbo.unidades ON dbo.produtos.Pro_unidade = dbo.unidades.uni_codigo INNER JOIN
                         dbo.GrupoProduto ON dbo.produtos.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo INNER JOIN
                         dbo.Preco_Produto ON dbo.produtos.Pro_codnosso = dbo.Preco_Produto.Pre_Codnosso ON dbo.ProdutosFornecedores.Pro_codnosso = dbo.produtos.Pro_codnosso
where produtos.Pro_codnosso =:pPro_codnosso


