SELECT        dbo.Preco_Produto.Pre_Codnosso, dbo.Preco_Produto.Pre_Acabamento, dbo.produtos.Pro_descricao, dbo.Preco_Produto.Tam_codigo
FROM            dbo.Preco_Produto INNER JOIN
                         dbo.produtos ON dbo.Preco_Produto.Pre_Codnosso = dbo.produtos.Pro_codnosso LEFT OUTER JOIN
                         dbo.Estoque_produto ON dbo.Preco_Produto.Tam_codigo = dbo.Estoque_produto.Tam_codigo AND dbo.Preco_Produto.Pre_Acabamento = dbo.Estoque_produto.Epr_Acabamento AND 
                         dbo.Preco_Produto.Pre_Codnosso = dbo.Estoque_produto.Epr_Codnosso
WHERE        (dbo.Estoque_produto.Epr_Acabamento IS NULL)
GROUP BY dbo.Preco_Produto.Pre_Codnosso, dbo.Preco_Produto.Pre_Acabamento, dbo.produtos.Pro_descricao, dbo.Preco_Produto.Tam_codigo

