SELECT     Bancos_Caixas.Bcx_situacao  ,dbo.Bancos_Caixas.Bcx_codigo, dbo.Bancos_Caixas.Emp_codigo, dbo.Bancos_Caixas.Bcx_tipo, dbo.Bancos_Caixas.Bcx_Nome, 
