-- [qrycaixa : TADOQuery]
SELECT    Movimentos.*, Contas_Bancarias.Cba_Saldo_inicial AS Cba_Saldo_inicial, Bancos_Caixas.Bcx_tipo AS Bcx_tipo, Bancos_Caixas.Bcx_Nome AS Bcx_Nome
FROM     Movimentos INNER JOIN Contas_Bancarias ON Movimentos.Cba_codigo = Contas_Bancarias.Cba_codigo AND Movimentos.Cba_codigo = Contas_Bancarias.Cba_codigo AND Movimentos.Cba_codigo = Contas_Bancarias.Cba_codigo AND 
Movimentos.Cba_codigo = Contas_Bancarias.Cba_codigo AND Movimentos.Bcx_codigo = Contas_Bancarias.Bcx_codigo AND Movimentos.Bcx_codigo = dbo.Contas_Bancarias.Bcx_codigo AND dbo.Movimentos.Bcx_codigo = dbo.Contas_Bancarias.Bcx_codigo AND 
Movimentos.Bcx_codigo = dbo.Contas_Bancarias.Bcx_codigo AND dbo.Movimentos.Emp_codigo = dbo.Contas_Bancarias.Emp_codigo AND Movimentos.Emp_codigo = dbo.Contas_Bancarias.Emp_codigo AND dbo.Movimentos.Emp_codigo = dbo.Contas_Bancarias.Emp_codigo AND 
Movimentos.Emp_codigo = dbo.Contas_Bancarias.Emp_codigo INNER JOIN Bancos_Caixas ON dbo.Contas_Bancarias.Bcx_codigo = dbo.Bancos_Caixas.Bcx_codigo AND Contas_Bancarias.Bcx_codigo = dbo.Bancos_Caixas.Bcx_codigo AND dbo.Contas_Bancarias.Bcx_codigo = dbo.Bancos_Caixas.Bcx_codigo AND 
Contas_Bancarias.Bcx_codigo = dbo.Bancos_Caixas.Bcx_codigo AND dbo.Contas_Bancarias.Emp_codigo = dbo.Bancos_Caixas.Emp_codigo AND Contas_Bancarias.Emp_codigo = dbo.Bancos_Caixas.Emp_codigo AND Contas_Bancarias.Emp_codigo = Bancos_Caixas.Emp_codigo AND Contas_Bancarias.Emp_codigo = Bancos_Caixas.Emp_codigo

