                      dbo.Contas_Bancarias.Cba_codigo
FROM         dbo.Contas_Bancarias INNER JOIN
                      dbo.Bancos_Caixas ON dbo.Contas_Bancarias.Bcx_codigo = dbo.Bancos_Caixas.Bcx_codigo AND 
