-- [QryInserirDif : TADOQuery]
INSERT INTO Nota_Entrada_Dif  (Nen_codigo, NenDf_DifFinc, NenDf_DifProd,NenDf_Data) 

(


SELECT     dbo.Nota_entrada.Nen_codigo, dbo.Nota_entrada.Nen_vl_diferenca_fin, dbo.Nota_entrada.Nen_vl_diferenca, getdate()
FROM         dbo.Nota_entrada LEFT OUTER JOIN
                      dbo.Nota_Entrada_Dif ON dbo.Nota_entrada.Nen_codigo = dbo.Nota_Entrada_Dif.Nen_codigo
WHERE    ((dbo.Nota_entrada.Nen_vl_diferenca_fin <> dbo.Nota_Entrada_Dif.NenDf_DifFinc) OR
                      (dbo.Nota_entrada.Nen_vl_diferenca <> dbo.Nota_Entrada_Dif.NenDf_DifProd) OR
                      (dbo.Nota_Entrada_Dif.NenDf_DifProd IS NULL) OR
                      (dbo.Nota_Entrada_Dif.NenDf_DifFinc IS NULL))
and (Nota_Entrada.Nen_vl_diferenca_fin <> 0 or Nota_Entrada.Nen_vl_diferenca <> 0)and NenDf_codigo is null


)


