-- [QryContasRec_Parcelas : TADOQuery]
SELECT      contas_receber.*, Tipo_documento.Tpd_descricao AS desc_doc,  
			TipoContaFinanceira.Tcf_descricao, contas_Receber_det.*, 
			Modo.Mdo_nome AS desc_modo, plano_contas.pco_descricao AS plano_contas

FROM		contas_receber, Tipo_documento, TipoContaFinanceira , contas_Receber_det, Modo, plano_contas

WHERE		contas_receber.Tpd_codigo = Tipo_documento.Tpd_codigo AND
			contas_receber.Tcf_codigo = TipoContaFinanceira.Tcf_codigo AND
			contas_receber.pco_codigo = plano_contas.pco_codigo AND
			contas_receber.ctr_codigo = Contas_Receber_det.ctr_codigo AND
			Contas_Receber_det.Mdo_codigo = Modo.Mdo_codigo

-- [Qryplano : TADOQuery]
SELECT      Pco_codigo, Pco_descricao, Pco_tipo, Pco_CreditoDebito
FROM         dbo.Plano_Contas
WHERE     (Pco_tipo = 'A') AND ((Pco_CreditoDebito = 'C') OR (Pco_CreditoDebito = 'A')) and Pco_descricao is not null
ORDER BY Pco_descricao

-- [Qrydoc : TADOQuery]
SELECT * from  Tipo_documento  where tpd_descricao is not null order by tpd_descricao

-- [Qrytrabalho : TADOQuery]
select * from fornecedor order by For_Razao

-- [Qrypagamento : TADOQuery]
SELECT  Contas_receber_pag.*, Modo.Mdo_nome AS desc_modo
FROM  Contas_receber_pag INNER JOIN
             Modo ON dbo.Contas_receber_pag.Mdo_codigo = Modo.Mdo_codigo
WHERE   (Contas_receber_pag.Ctr_codigo =:codigo) AND (Contas_receber_pag.Ctr_codigo_det =:cod_det )

-- [QrySomaTotal : TADOQuery]
SELECT      SUM(Ctr_valor_vencimento) AS Valor_Total
			
FROM		contas_receber, Tipo_documento, TipoContaFinanceira , contas_Receber_det, Modo, plano_contas

WHERE		contas_receber.Tpd_codigo = Tipo_documento.Tpd_codigo AND
			contas_receber.Tcf_codigo = TipoContaFinanceira.Tcf_codigo AND
			contas_receber.pco_codigo = plano_contas.pco_codigo AND
			contas_receber.ctr_codigo = Contas_Receber_det.ctr_codigo AND
			Contas_Receber_det.Mdo_codigo = Modo.Mdo_codigo

-- [QryValorRecebido : TADOQuery]
SELECT      SUM(Ctr_valor_vencimento) AS Valor_Recebido
			
FROM		contas_receber, Tipo_documento, TipoContaFinanceira , contas_Receber_det, Modo, plano_contas

WHERE		contas_receber.Tpd_codigo = Tipo_documento.Tpd_codigo AND
			contas_receber.Tcf_codigo = TipoContaFinanceira.Tcf_codigo AND
			contas_receber.pco_codigo = plano_contas.pco_codigo AND
			contas_receber.ctr_codigo = Contas_Receber_det.ctr_codigo AND
			Contas_Receber_det.Mdo_codigo = Modo.Mdo_codigo AND ctr_situacao='S'

-- [QryValorNaoRecebido : TADOQuery]
SELECT      SUM(Ctr_valor_vencimento) AS Valor_NaoRecebido
			
FROM		contas_receber, Tipo_documento, TipoContaFinanceira , contas_Receber_det, Modo, plano_contas

WHERE		contas_receber.Tpd_codigo = Tipo_documento.Tpd_codigo AND
			contas_receber.Tcf_codigo = TipoContaFinanceira.Tcf_codigo AND
			contas_receber.pco_codigo = plano_contas.pco_codigo AND
			contas_receber.ctr_codigo = Contas_Receber_det.ctr_codigo AND
			Contas_Receber_det.Mdo_codigo = Modo.Mdo_codigo  and (ctr_situacao='N' OR ctr_situacao is null)


