-- [QryVersaoUsuario : TADOQuery]
SELECT        dbo.HistoricoVersoesLancamento.HistVerLanc_Descricao, 
dbo.HistoricoVersoesSistema.HistVerSis_Descricao, 
dbo.HistoricoVersoes.HistVer_Versao, 
dbo.HistoricoVersoesCategoria.HistVerCat_Descricao, 
dbo.HistoricoVersoesSistema.HistVerSis_Codigo, 
dbo.HistoricoVersoes.HistVer_Codigo,
HistoricoVersoesUsuario.SisUsu_Codigo
FROM            dbo.HistoricoVersoes INNER JOIN
                         dbo.HistoricoVersoesLancamento ON dbo.HistoricoVersoes.HistVer_Codigo = dbo.HistoricoVersoesLancamento.HistVer_Codigo INNER JOIN
                         dbo.HistoricoVersoesSistema ON dbo.HistoricoVersoes.HistVerSis_Codigo = dbo.HistoricoVersoesSistema.HistVerSis_Codigo INNER JOIN
                         dbo.HistoricoVersoesCategoria ON dbo.HistoricoVersoesLancamento.HistVerCat_Codigo = dbo.HistoricoVersoesCategoria.HistVerCat_Codigo INNER JOIN
                         dbo.HistoricoVersoesUsuario ON dbo.HistoricoVersoes.HistVer_Codigo = dbo.HistoricoVersoesUsuario.HistVer_Codigo
WHERE        (dbo.HistoricoVersoes.HistVer_Situacao = 1) AND (dbo.HistoricoVersoesLancamento.HistVerLanc_situacao = 1)
and HistoricoVersoesUsuario.SisUsu_Codigo =:pSisUsu_Codigo and HistVerUsu_Lido = 0


