-- [QryBuscaProdutos : TADOQuery]
SELECT 
  MAX(dbo.pedido_luminaria_det.ped_codigo_pre) AS CODIGOPRE,
  MAX(dbo.pedido_luminaria_det.Pro_codnosso) AS CODIGOPRO,
  MAX(dbo.pedido_luminaria_det.pld_acabamento) AS ACAB,
  SUM(dbo.pedido_luminaria_det.pld_quantidade) AS QUANT,
  MAX(dbo.pedido_luminaria_det.pld_vl_unitario) AS VLUNIT,
  MAX(dbo.produtos.Pro_AliqICMS) AS IVA
FROM
  dbo.produtos
  INNER JOIN dbo.pedido_luminaria_det ON (dbo.produtos.Pro_codnosso = dbo.pedido_luminaria_det.Pro_codnosso)
WHERE
  (dbo.pedido_luminaria_det.ped_codigo_pre IN (12,14,15,56))
GROUP BY
  dbo.produtos.Pro_codnosso,
  dbo.pedido_luminaria_det.pld_acabamento

UNION ALL

SELECT 
  MAX(dbo.pedido_materiais_det.ped_codigo_pre) AS CODIGOPRE,
  MAX(dbo.pedido_materiais_det.Pro_codnosso) AS CODIGOPRO,
  MAX(dbo.pedido_materiais_det.pma_acabamento) AS ACAB,
  SUM(dbo.pedido_materiais_det.pma_quantidade) AS QUANT,
  MAX(dbo.pedido_materiais_det.pma_vl_unitario) AS VLUNIT,
  MAX(produtos_1.Pro_AliqICMS) AS IVA
FROM
  dbo.produtos produtos_1
  INNER JOIN dbo.pedido_materiais_det ON (produtos_1.Pro_codnosso = dbo.pedido_materiais_det.Pro_codnosso)
WHERE
  (dbo.pedido_materiais_det.ped_codigo_pre IN (12,14,15,56))
GROUP BY
  produtos_1.Pro_codnosso,
  dbo.pedido_materiais_det.pma_acabamento


