orc_desc_por_produto as desc_porc_produtos
 from orcamento where orc_codigo=:porc_codigo

-- [Qryprodutos : TADOQuery]
SELECT     dbo.produtos.Pro_descricao AS descricao, orcamento_materiais_det.Pro_codnosso AS codigo, 
                      orcamento_materiais_det.oma_acabamento AS acabamento, orcamento_materiais_det.oma_unidade AS unidade, 
                      sum(orcamento_materiais_det.oma_quantidade) AS quantidade, max(orcamento_materiais_det.oma_vl_unitario) AS vl_unitario, 
                      max(orcamento_materiais_det.oma_vl_item) AS vl_item, max(orcamento_materiais_det.oma_VlImposto) AS vlimposto
,(  sum(orcamento_materiais_det.oma_quantidade) * max(orcamento_materiais_det.oma_vl_unitario)) as vl_item_sem_iva

FROM         orcamento_materiais_det INNER JOIN
                      dbo.produtos ON orcamento_materiais_det.Pro_codnosso = dbo.produtos.Pro_codnosso
GROUP BY dbo.produtos.Pro_descricao, orcamento_materiais_det.Pro_codnosso, orcamento_materiais_det.oma_acabamento, 
                      orcamento_materiais_det.oma_unidade, orcamento_materiais_det.oma_quantidade, orcamento_materiais_det.oma_vl_unitario, 
                      orcamento_materiais_det.oma_vl_item, orcamento_materiais_det.oma_VlImposto

union all

SELECT     dbo.produtos.Pro_descricao AS descricao, dbo.Orcamento_luminaria_det.Pro_codnosso AS codigo, 
                      dbo.Orcamento_luminaria_det.old_acabamento AS acabamento, dbo.Orcamento_luminaria_det.old_unidade AS unidade, 
                      sum(dbo.Orcamento_luminaria_det.old_quantidade) AS quantidade, max(dbo.Orcamento_luminaria_det.old_vl_unitario) AS vl_unitario, 
                      max(dbo.Orcamento_luminaria_det.old_vl_item) AS vl_item, max(dbo.Orcamento_luminaria_det.old_VlImposto) AS vlimposto
,(  sum(orcamento_luminaria_det.old_quantidade) * max(orcamento_luminaria_det.old_vl_unitario)) as vl_item_sem_iva
FROM         dbo.Orcamento_luminaria_det INNER JOIN
                      dbo.produtos ON dbo.Orcamento_luminaria_det.Pro_codnosso = dbo.produtos.Pro_codnosso
GROUP BY dbo.produtos.Pro_descricao, dbo.Orcamento_luminaria_det.Pro_codnosso, dbo.Orcamento_luminaria_det.old_acabamento, 
                      dbo.Orcamento_luminaria_det.old_unidade, dbo.Orcamento_luminaria_det.old_quantidade, dbo.Orcamento_luminaria_det.old_vl_unitario, 
                      dbo.Orcamento_luminaria_det.old_vl_item, dbo.Orcamento_luminaria_det.old_VlImposto

order by codigo

-- [QryIVA : TADOQuery]
SELECT  SUM((dbo.produtos.Pro_AliqICMS / 100) * orcamento_materiais_det.oma_vl_item) AS valor_iva,
produtos.Pro_AliqICMS AS aliq_iva,  SUM(orcamento_materiais_det.oma_vl_item) as base_iva 
FROM  orcamento_materiais_det INNER JOIN
produtos ON orcamento_materiais_det.Pro_codnosso = produtos.Pro_codnosso
 where orcamento_materiais_det.orc_codigo_pre =6
 GROUP BY dbo.produtos.Pro_AliqICMS
union all
SELECT  SUM((produtos.Pro_AliqICMS / 100) * Orcamento_luminaria_det.old_vl_item) AS valor_iva,
 produtos.Pro_AliqICMS AS aliq_iva, SUM(Orcamento_luminaria_det.old_vl_item) as base_iva
 FROM Orcamento_luminaria_det INNER JOIN
 produtos ON Orcamento_luminaria_det.Pro_codnosso = produtos.Pro_codnosso
 where Orcamento_luminaria_det.orc_codigo_pre =6
 GROUP BY produtos.Pro_AliqICMS
 order by aliq_iva

