-- [QrySomaEcoreee : TADOQuery]
select  
(case when  (SELECT SUM(dbo.Orcamento_luminaria_det.old_quantidade * dbo.produtos.Pro_Ecoreee) AS Expr1
FROM         dbo.Orcamento_luminaria_det INNER JOIN
dbo.produtos ON dbo.Orcamento_luminaria_det.Pro_codnosso = dbo.produtos.Pro_codnosso
WHERE  (dbo.Orcamento_luminaria_det.orc_codigo_pre =orcamento.orc_codigo_pre) AND (dbo.produtos.Pro_Ecoreee IS NOT NULL))
> 0 then (SELECT SUM(dbo.Orcamento_luminaria_det.old_quantidade * dbo.produtos.Pro_Ecoreee) AS Expr1
FROM         dbo.Orcamento_luminaria_det INNER JOIN
dbo.produtos ON dbo.Orcamento_luminaria_det.Pro_codnosso = dbo.produtos.Pro_codnosso
WHERE     (dbo.Orcamento_luminaria_det.orc_codigo_pre =orcamento.orc_codigo_pre) AND (dbo.produtos.Pro_Ecoreee IS NOT NULL))
else 0 end)
+
(case when (SELECT SUM(dbo.Orcamento_materiais_det.oma_quantidade * dbo.produtos.Pro_Ecoreee) AS Expr1
FROM dbo.Orcamento_materiais_det INNER JOIN
dbo.produtos ON dbo.Orcamento_materiais_det.Pro_codnosso = dbo.produtos.Pro_codnosso
WHERE     (dbo.Orcamento_materiais_det.orc_codigo_pre =orcamento.orc_codigo_pre) AND (dbo.produtos.Pro_Ecoreee IS NOT NULL)) > 0
then (SELECT     SUM(dbo.Orcamento_materiais_det.oma_quantidade * dbo.produtos.Pro_Ecoreee) AS Expr1
FROM dbo.Orcamento_materiais_det INNER JOIN
dbo.produtos ON dbo.Orcamento_materiais_det.Pro_codnosso = dbo.produtos.Pro_codnosso
WHERE (dbo.Orcamento_materiais_det.orc_codigo_pre =orcamento.orc_codigo_pre) AND (dbo.produtos.Pro_Ecoreee IS NOT NULL)) else 0 end)
as valor
from orcamento
where orcamento.orc_codigo =:porc_codigo


