-- [Qryprodutosarq : TADOQuery]
SELECT    dbo.unidades.uni_descricao, dbo.GrupoProduto.GrupoProduto_Descricao, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, dbo.produtos.Pro_descricao, 
                         dbo.ProdutosFornecedores.ProdFor_DescricaoProduto, dbo.produtos.Pro_CodEspecial, dbo.fornecedor.For_Nome, dbo.TipoPeca.TpPeca_Codigo, dbo.produtos.Pro_unidade, dbo.produtos.Pro_codnosso, 
                          dbo.produtos.pro_NCM, dbo.produtos.Pro_CodReduzido
, ProdutosFornecedores.for_codigo

FROM                                dbo.produtos INNER JOIN
                         dbo.TipoPeca ON dbo.produtos.Pro_tp_peca = dbo.TipoPeca.TpPeca_Codigo INNER JOIN
                         dbo.unidades ON dbo.produtos.Pro_unidade = dbo.unidades.uni_codigo INNER JOIN
                         dbo.GrupoProduto ON dbo.produtos.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo INNER JOIN
                         dbo.ProdutosFornecedores INNER JOIN
                         dbo.fornecedor ON dbo.ProdutosFornecedores.For_codigo = dbo.fornecedor.For_codigo ON dbo.produtos.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso
WHERE        (dbo.ProdutosFornecedores.For_codigo =:pFor_codigo)
GROUP BY dbo.unidades.uni_descricao, dbo.GrupoProduto.GrupoProduto_Descricao, dbo.produtos.Pro_Codbase, dbo.produtos.Pro_descricao, dbo.produtos.Pro_descricao_for, dbo.produtos.Pro_CodEspecial, dbo.fornecedor.For_Nome, 
                         dbo.TipoPeca.TpPeca_Codigo, dbo.produtos.Pro_unidade, dbo.produtos.Pro_codnosso,  dbo.ProdutosFornecedores.ProdFor_CodigoProduto, 
                         dbo.ProdutosFornecedores.ProdFor_DescricaoProduto, dbo.produtos.pro_NCM, dbo.produtos.Pro_CodReduzido, ProdutosFornecedores.for_codigo
ORDER BY dbo.produtos.Pro_codnosso

