-- [Qryvenda : TADOQuery]
SELECT dbo.Venda.Ven_codigo, dbo.Venda.Ven_Tipo, dbo.Venda.usr_dt_hr_criacao, dbo.Funcionario.Fun_Nome, CONVERT(CHAR, dbo.Venda.usr_dt_hr_criacao, 103) AS DATA, FORMAT(dbo.Venda.usr_dt_hr_criacao, N'HH:mm:ss ') AS HORA, 
                  dbo.ProdutosFornecedores.ProdFor_CodigoProduto, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto, dbo.VendaProduto.CodAcabamento, SUM(dbo.VendaProduto.VenPro_Quantidade) AS VenPro_Quantidade, 
                  dbo.VendaProduto.VenPro_VlUnitario, dbo.Venda.Ven_Total, dbo.Venda.Ven_DescontoProd, dbo.Venda.Ven_TotalProd, dbo.Venda.Ven_DescontoPorcProd, dbo.Preco_Produto.Pre_CodBarra
FROM     dbo.Venda INNER JOIN
                  dbo.VendaAtendente ON dbo.Venda.Ven_CodigoPre = dbo.VendaAtendente.VenAten_NDocPre INNER JOIN
                  dbo.Funcionario ON dbo.VendaAtendente.Fun_Codigo = dbo.Funcionario.Fun_CPF INNER JOIN
                  dbo.VendaProduto ON dbo.Venda.Ven_CodigoPre = dbo.VendaProduto.Ven_CodigoPre INNER JOIN
                  dbo.ProdutosFornecedores ON dbo.VendaProduto.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso INNER JOIN
                  dbo.Preco_Produto ON dbo.VendaProduto.Pro_codnosso = dbo.Preco_Produto.Pre_Codnosso AND dbo.VendaProduto.CodAcabamento = dbo.Preco_Produto.Pre_Acabamento
WHERE  (dbo.VendaAtendente.VenAten_Principal = 1) AND (dbo.Venda.Ven_CodigoPre =:pVen_CodigoPre ) AND (dbo.Preco_Produto.Pre_Ativo = 'S')
AND (dbo.ProdutosFornecedores.ProdFor_Padrao = 1)
GROUP BY dbo.Venda.Ven_codigo, dbo.Venda.Ven_Tipo, dbo.Venda.usr_dt_hr_criacao, dbo.Funcionario.Fun_Nome, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto, 
                  dbo.VendaProduto.CodAcabamento, dbo.VendaProduto.VenPro_VlUnitario, dbo.Venda.Ven_Total, dbo.Venda.Ven_DescontoProd, dbo.Venda.Ven_TotalProd, dbo.Venda.Ven_DescontoPorcProd, dbo.Preco_Produto.Pre_CodBarra


