   ============================================================ */

-- [Qrydados : TADOQuery]
SELECT    produtos.Pro_tp_produto AS Grupo,  dbo.produtos.Pro_tp_peca AS Peca, tabela.old_seq AS Seq, SUM(tabela.old_quantidade) as qtde ,SUM(tabela.old_vl_item) 
                      AS Total, dbo.Ambiente.DescAmbiente as Ambiente,
CASE produtos.Pro_tp_produto
      WHEN 'LUMINÁRIAS' THEN 1
      WHEN 'LÂMPADAS' THEN 2
      WHEN 'MATERIAIS ELÉTRICOS' THEN 3
      WHEN 'OUTROS' THEN 4
      END AS OrdemGrupo

FROM         dbo.Orcamento_luminaria_det tabela INNER JOIN
                      dbo.produtos ON tabela.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                      dbo.Ambiente ON tabela.old_ambiente = dbo.Ambiente.CodAmbiente
WHERE     (tabela.orc_codigo_pre =:porc_codigo_preld)
GROUP BY produtos.Pro_tp_produto,dbo.produtos.Pro_tp_peca, tabela.old_seq, dbo.Ambiente.DescAmbiente

UNION ALL

SELECT   produtos.Pro_tp_produto AS Grupo ,dbo.produtos.Pro_tp_peca AS Peca, tabelaMA.oma_seq AS Seq,  SUM(tabelaMA.oma_quantidade) as qtde,  
                      SUM(tabelaMA.oma_vl_item) AS Total, dbo.Ambiente.DescAmbiente AS Ambiente,
CASE produtos.Pro_tp_produto
      WHEN 'LUMINÁRIAS' THEN 1
      WHEN 'LÂMPADAS' THEN 2
      WHEN 'MATERIAIS ELÉTRICOS' THEN 3
      WHEN 'OUTROS' THEN 4
      END AS OrdemGrupo

FROM         dbo.orcamento_materiais_det tabelaMA INNER JOIN
                      dbo.produtos ON tabelaMA.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                      dbo.Ambiente ON tabelaMA.oma_ambiente = dbo.Ambiente.CodAmbiente
WHERE     (tabelaMA.orc_codigo_pre =:porc_codigo_prema)
GROUP BY produtos.Pro_tp_produto , dbo.produtos.Pro_tp_peca, tabelaMA.oma_seq,  dbo.Ambiente.DescAmbiente
order by seq,OrdemGrupo

