  dbo.NotaFiscal.NTF_NatOperacao,
  dbo.NotaFiscal.NTF_IESubsTrib,
  dbo.NotaFiscal.NTF_DtEmissao,
  dbo.NotaFiscal.NTF_DtSaidaEntrada,
  dbo.NotaFiscal.NTF_HoraSaida,
  dbo.NotaFiscal.Cli_Codigo,
  dbo.NotaFiscal.NTF_Nome,
  dbo.NotaFiscal.NTF_InscEst,
  dbo.NotaFiscal.NTF_CNPJCPF,
  dbo.NotaFiscal.NTF_Endereco,
  dbo.NotaFiscal.NTF_EndNumero,
  dbo.NotaFiscal.NTF_Bairro,
  dbo.NotaFiscal.NTF_CEP,
  dbo.NotaFiscal.NTF_Municipio,
  dbo.NotaFiscal.NTF_UF,
  dbo.NotaFiscal.NTF_FoneFax,
  dbo.NotaFiscal.NTF_BaseICMS,
  dbo.NotaFiscal.NTF_VlICMS,
  dbo.NotaFiscal.NTF_BaseSubstICMS,
  dbo.NotaFiscal.NTF_VlSubstICMS,
  dbo.NotaFiscal.NTF_VLProdutos,
  dbo.NotaFiscal.NTF_VlFrete,
  dbo.NotaFiscal.NTF_VlSeguro,
  dbo.NotaFiscal.NTF_DespAcessoria,
  dbo.NotaFiscal.NTF_VlIPI,
  dbo.NotaFiscal.NTF_VlNota,
  dbo.NotaFiscal.Tra_codigo,
  dbo.NotaFiscal.NTF_TraNome,
  dbo.NotaFiscal.NTF_TpFrete,
  dbo.NotaFiscal.NTF_Placa,
  dbo.NotaFiscal.NTF_PlacaUF,
  dbo.NotaFiscal.NTF_TraCNPJCPF,
  dbo.NotaFiscal.NTF_TraEndereco,
  dbo.NotaFiscal.NTF_TraMunicipio,
  dbo.NotaFiscal.NTF_TraUF,
  dbo.NotaFiscal.NTF_TraIE,
  dbo.NotaFiscal.NTF_TraQuant,
  dbo.NotaFiscal.NTF_TraEspecie,
  dbo.NotaFiscal.NTF_TraMarca,
  dbo.NotaFiscal.NTF_TraNumero,
  dbo.NotaFiscal.NTF_TraPesoLiq,
  dbo.NotaFiscal.NTF_TraPesoBruto,
  dbo.NotaFiscal.NTF_Dados1,
  dbo.NotaFiscal.NTF_Dados2,
  dbo.NotaFiscal.Emp_Codigo,
  dbo.NotaFiscal.CatVen_Codigo,
  dbo.NotaFiscal.Par_ComissaoVincParc,
  dbo.NotaFiscal.NTF_FormaPagamento,
  dbo.NotaFiscal.NTF_Impresso,
  dbo.NotaFiscal.Mod_codigo,
  dbo.NotaFiscal.usr_cod_criacao,
  dbo.NotaFiscal.usr_dt_hr_criacao,
  dbo.NotaFiscal.usr_cod_alteracao,
  dbo.NotaFiscal.usr_dt_hr_alteracao,
  dbo.NotaFiscal.NTF_Situacao,
  dbo.NotaFiscal.NTF_ImportTipo,
  dbo.NotaFiscal.NTF_ImportNumero,
  dbo.NotaFiscal.NTF_ImpCodFor,
NotaFiscal.NTF_CriarConta,
case when NotaFiscal.NTF_Tipo = 'S' Then 'X' ELSE '' END AS MarcaSaida,
case when NotaFiscal.NTF_Tipo = 'E' Then 'X' ELSE '' END AS MarcaEntrada,

     (SELECT     Ctr_dt_vencimento
                            FROM          dbo.contas_Receber_det
                            WHERE      (Ctr_codigo = dbo.contas_receber.Ctr_codigo) AND (Ctr_parcela = 1)) AS FaturaData1,
                          (SELECT     Ctr_valor_vencimento
                            FROM          dbo.contas_Receber_det AS contas_Receber_det_1
                            WHERE      (Ctr_codigo = dbo.contas_receber.Ctr_codigo) AND (Ctr_parcela = 1)) AS FaturaValor1, 
                      dbo.contas_receber.Ctr_cod_documento + '-A' AS FaturaNumero1,
                          (SELECT     Ctr_dt_vencimento
                            FROM          dbo.contas_Receber_det AS contas_Receber_det_2
                            WHERE      (Ctr_codigo = dbo.contas_receber.Ctr_codigo) AND (Ctr_parcela = 2)) AS FaturaData2,
                          (SELECT     Ctr_valor_vencimento
                            FROM          dbo.contas_Receber_det AS contas_Receber_det_1
                            WHERE      (Ctr_codigo = dbo.contas_receber.Ctr_codigo) AND (Ctr_parcela = 2)) AS FaturaValor2, 
                      dbo.contas_receber.Ctr_cod_documento + '-B' AS FaturaNumero2,
                          (SELECT     Ctr_dt_vencimento
                            FROM          dbo.contas_Receber_det AS contas_Receber_det_2
                            WHERE      (Ctr_codigo = dbo.contas_receber.Ctr_codigo) AND (Ctr_parcela = 3)) AS FaturaData3,
                          (SELECT     Ctr_valor_vencimento
                            FROM          dbo.contas_Receber_det AS contas_Receber_det_1
                            WHERE      (Ctr_codigo = dbo.contas_receber.Ctr_codigo) AND (Ctr_parcela = 3)) AS FaturaValor3, 
                      dbo.contas_receber.Ctr_cod_documento + '-C' AS FaturaNumero3,
                          (SELECT     Ctr_dt_vencimento
                            FROM          dbo.contas_Receber_det AS contas_Receber_det_2
                            WHERE      (Ctr_codigo = dbo.contas_receber.Ctr_codigo) AND (Ctr_parcela = 4)) AS FaturaData4,
                          (SELECT     Ctr_valor_vencimento
                            FROM          dbo.contas_Receber_det AS contas_Receber_det_1
                            WHERE      (Ctr_codigo = dbo.contas_receber.Ctr_codigo) AND (Ctr_parcela = 4)) AS FaturaValor4, 
                      dbo.contas_receber.Ctr_cod_documento + '-D' AS FaturaNumero4,
                          (SELECT     Ctr_dt_vencimento
                            FROM          dbo.contas_Receber_det AS contas_Receber_det_2
                            WHERE      (Ctr_codigo = dbo.contas_receber.Ctr_codigo) AND (Ctr_parcela = 5)) AS FaturaData5,
                          (SELECT     Ctr_valor_vencimento
                            FROM          dbo.contas_Receber_det AS contas_Receber_det_1
                            WHERE      (Ctr_codigo = dbo.contas_receber.Ctr_codigo) AND (Ctr_parcela = 5)) AS FaturaValor5, 
                      dbo.contas_receber.Ctr_cod_documento + '-E' AS FaturaNumero5,
                          (SELECT     Ctr_dt_vencimento
                            FROM          dbo.contas_Receber_det AS contas_Receber_det_2
                            WHERE      (Ctr_codigo = dbo.contas_receber.Ctr_codigo) AND (Ctr_parcela = 6)) AS FaturaData6,
                          (SELECT     Ctr_valor_vencimento
                            FROM          dbo.contas_Receber_det AS contas_Receber_det_1
                            WHERE      (Ctr_codigo = dbo.contas_receber.Ctr_codigo) AND (Ctr_parcela = 6)) AS FaturaValor6, 
                      dbo.contas_receber.Ctr_cod_documento + '-F' AS FaturaNumero6
FROM         dbo.NotaFiscal LEFT OUTER JOIN
                      dbo.contas_receber ON dbo.NotaFiscal.NTF_Codigo = dbo.contas_receber.Ctr_cod_documento AND dbo.contas_receber.Tpd_codigo = 1022
WHERE
  (dbo.NotaFiscal.NTF_Codigo = :CodNTF)

