SELECT * FROM BalancoEstoqueProdutos
where BalEst_Codigo =:pBalEst_Codigo

-- [QryProdutosCalc : TADOQuery]
SELECT        dbo.unidades.uni_descricao, dbo.GrupoProduto.GrupoProduto_Descricao, dbo.produtos.Pro_Codbase, dbo.produtos.Pro_descricao, dbo.produtos.Pro_descricao_for, 
                         dbo.produtos.Pro_CodEspecial, dbo.fornecedor.For_Nome, dbo.TipoPeca.TpPeca_Codigo, dbo.produtos.Pro_unidade, dbo.produtos.Pro_codnosso
FROM            dbo.produtos INNER JOIN
                         dbo.fornecedor ON dbo.produtos.For_codigo = dbo.fornecedor.For_codigo INNER JOIN
                         dbo.unidades ON dbo.produtos.Pro_unidade = dbo.unidades.uni_codigo INNER JOIN
                         dbo.GrupoProduto ON dbo.produtos.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo INNER JOIN
                         dbo.Preco_Produto ON dbo.produtos.Pro_codnosso = dbo.Preco_Produto.Pre_Codnosso LEFT OUTER JOIN
                         dbo.TipoPeca ON dbo.produtos.Pro_tp_peca = dbo.TipoPeca.TpPeca_Codigo

where Pro_codnosso =:pPro_codnosso

-- [Qryprodutos : TADOQuery]
SELECT        dbo.unidades.uni_descricao, dbo.GrupoProduto.GrupoProduto_Descricao, dbo.ProdutosFornecedores.ProdFor_CodigoProduto AS Pro_Codbase, dbo.produtos.Pro_descricao, 
                         dbo.ProdutosFornecedores.ProdFor_DescricaoProduto AS Pro_descricao_for, dbo.produtos.Pro_CodEspecial, dbo.fornecedor.For_Nome, dbo.TipoPeca.TpPeca_Codigo, dbo.produtos.Pro_unidade, dbo.produtos.Pro_codnosso, 
                         dbo.Preco_Produto.Pre_Acabamento, dbo.Acabamento.DescAcabamento
, 


Preco_Produto.Pre_Acabamento,+ '  '+   CASE WHEN acab_tipo = 'E' THEN 'Ext.:' ELSE CASE WHEN acab_tipo = 'T' THEN 'Ext. e Inter.:' ELSE '' END END + dbo.Acabamento.DescAcabamento + '  ' + CASE WHEN acab_tipo2 = 'I' THEN 'Inter.:' ELSE '' END + CASE WHEN
                          DescAcabamento2 IS NULL THEN '' ELSE DescAcabamento2 END AS descricaoacabamento

, dbo.tamanho.Tam_codigo, dbo.tamanho.Tam_descricao


FROM     dbo.ProdutosFornecedores INNER JOIN
                  dbo.fornecedor ON dbo.ProdutosFornecedores.For_codigo = dbo.fornecedor.For_codigo INNER JOIN
                  dbo.produtos INNER JOIN
                  dbo.TipoPeca ON dbo.produtos.Pro_tp_peca = dbo.TipoPeca.TpPeca_Codigo INNER JOIN
                  dbo.unidades ON dbo.produtos.Pro_unidade = dbo.unidades.uni_codigo INNER JOIN
                  dbo.GrupoProduto ON dbo.produtos.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo INNER JOIN
                  dbo.Preco_Produto ON dbo.produtos.Pro_codnosso = dbo.Preco_Produto.Pre_Codnosso INNER JOIN
                  dbo.Acabamento ON dbo.Preco_Produto.Pre_Acabamento = dbo.Acabamento.CodAcabamento ON dbo.ProdutosFornecedores.Pro_codnosso = dbo.produtos.Pro_codnosso LEFT OUTER JOIN
                  dbo.tamanho ON dbo.Preco_Produto.Tam_codigo = dbo.tamanho.Tam_codigo




where ProdutosFornecedores.For_codigo  =:pfor_codigo and ProdutosFornecedores.ProdFor_CodigoProduto =:pPro_Codbase and produtos.Pro_ativo='S' AND Preco_Produto.Pre_Ativo='S'

 
GROUP BY dbo.unidades.uni_descricao, dbo.GrupoProduto.GrupoProduto_Descricao, dbo.produtos.Pro_Codbase, dbo.produtos.Pro_descricao, dbo.produtos.Pro_descricao_for, dbo.produtos.Pro_CodEspecial, dbo.fornecedor.For_Nome, 
                         dbo.TipoPeca.TpPeca_Codigo, dbo.produtos.Pro_unidade, dbo.produtos.Pro_codnosso, dbo.Preco_Produto.Pre_Acabamento, dbo.Acabamento.DescAcabamento, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, 
                         dbo.ProdutosFornecedores.ProdFor_DescricaoProduto, acab_tipo, acab_tipo2, DescAcabamento2 , dbo.tamanho.Tam_codigo, dbo.tamanho.Tam_descricao

-- [QryOrdem : TADOQuery]
SELECT        dbo.unidades.uni_descricao, dbo.GrupoProduto.GrupoProduto_Descricao, dbo.produtos.Pro_Codbase, dbo.produtos.Pro_descricao, dbo.produtos.Pro_descricao_for, 
                         dbo.produtos.Pro_CodEspecial, dbo.fornecedor.For_Nome, dbo.TipoPeca.TpPeca_Codigo, dbo.produtos.Pro_unidade, dbo.produtos.Pro_codnosso
,Preco_Produto.Pre_Acabamento

FROM            dbo.produtos INNER JOIN
