                         dbo.TipoPeca ON dbo.produtos.GrupoProduto_codigo = dbo.TipoPeca.GrupoProduto_codigo INNER JOIN
                         dbo.unidades ON dbo.produtos.Pro_unidade = dbo.unidades.uni_codigo INNER JOIN
                         dbo.GrupoProduto ON dbo.produtos.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo INNER JOIN
                         dbo.Preco_Produto ON dbo.produtos.Pro_codnosso = dbo.Preco_Produto.Pre_Codnosso

where Pre_CodBarra =:pPre_CodBarra

