SELECT  dbo.produtos.Pro_tp_produto, dbo.produtos.Pro_descricao, dbo.Estoque_produto.Epr_estoque, dbo.VendaProduto.Pro_codnosso, dbo.produtos.Pro_unidade, dbo.VendaProduto.CodAcabamento, 
                  SUM(dbo.VendaProduto.VenPro_Quantidade) AS quantidade, SUM(dbo.VendaProduto.VenPro_VlUnitario) AS vl_unitario, SUM(dbo.VendaProduto.VenPro_VlItem) AS vl_item, dbo.VendaProduto.Ven_CodigoPre, 
                  dbo.ProdutosFornecedores.ProdFor_CodigoProduto AS Pro_Codbase, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto AS Pro_descricao_for, dbo.produtos.Pro_CodEspecial, 
                  dbo.GrupoProduto.GrupoProduto_Descricao, fornecedor.For_Nome
FROM     dbo.produtos INNER JOIN
                  dbo.VendaProduto ON dbo.produtos.Pro_codnosso = dbo.VendaProduto.Pro_codnosso INNER JOIN
                  dbo.GrupoProduto ON dbo.produtos.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo INNER JOIN
                  dbo.Venda ON dbo.VendaProduto.Ven_CodigoPre = dbo.Venda.Ven_CodigoPre INNER JOIN
                  dbo.ProdutosFornecedores ON dbo.produtos.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso INNER JOIN
                  dbo.fornecedor ON dbo.ProdutosFornecedores.For_codigo = dbo.fornecedor.For_codigo LEFT OUTER JOIN
                  dbo.Estoque_produto ON dbo.VendaProduto.CodAcabamento = dbo.Estoque_produto.Epr_Acabamento AND dbo.VendaProduto.Pro_codnosso = dbo.Estoque_produto.Epr_Codnosso
WHERE  (dbo.VendaProduto.Ven_CodigoPre =:codigo) AND (dbo.Venda.Ven_Tipo = 'O') AND (dbo.Estoque_produto.EstTp_Codigo = 1) AND (dbo.Venda.Ven_Situacao = 'A')
GROUP BY dbo.fornecedor.For_Nome, dbo.produtos.GrupoProduto_codigo, dbo.produtos.Pro_tp_produto, dbo.produtos.Pro_descricao, dbo.Estoque_produto.Epr_estoque, dbo.VendaProduto.Pro_codnosso, 
                  dbo.produtos.Pro_unidade, dbo.VendaProduto.CodAcabamento, dbo.VendaProduto.Ven_CodigoPre, dbo.produtos.Pro_Codbase, dbo.produtos.Pro_descricao_for, dbo.produtos.Pro_CodEspecial, 
                  dbo.GrupoProduto.GrupoProduto_Descricao, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto
ORDER BY fornecedor.For_Nome,dbo.produtos.GrupoProduto_codigo, dbo.VendaProduto.Pro_codnosso

-- [Qryquantit_materiais : TADOQuery]
SELECT      dbo.produtos.Pro_tp_produto, dbo.produtos.Pro_descricao, dbo.orcamento_materiais_det.oma_unidade, 
                      dbo.orcamento_materiais_det.oma_acabamento, SUM(dbo.orcamento_materiais_det.oma_quantidade) AS quantidade, 
                      SUM(dbo.orcamento_materiais_det.oma_vl_unitario) AS vl_unitario, SUM(dbo.orcamento_materiais_det.oma_vl_item) AS vl_item, 
                      dbo.orcamento_materiais_det.Pro_codnosso, dbo.Estoque_produto.Epr_estoque, dbo.orcamento_materiais_det.orc_codigo_pre
, produtos.Pro_Codbase, produtos.Pro_descricao_for, produtos.Pro_CodEspecial
FROM         dbo.produtos INNER JOIN
                      dbo.orcamento_materiais_det ON dbo.produtos.Pro_codnosso = dbo.orcamento_materiais_det.Pro_codnosso LEFT OUTER JOIN
                      dbo.Estoque_produto ON dbo.orcamento_materiais_det.oma_acabamento = dbo.Estoque_produto.Epr_Acabamento AND 
                      dbo.orcamento_materiais_det.Pro_codnosso = dbo.Estoque_produto.Epr_Codnosso
GROUP BY dbo.produtos.Pro_tp_produto, dbo.produtos.Pro_descricao, dbo.orcamento_materiais_det.oma_unidade, 
                      dbo.orcamento_materiais_det.oma_acabamento, dbo.orcamento_materiais_det.Pro_codnosso, dbo.Estoque_produto.Epr_estoque, 
                      dbo.orcamento_materiais_det.orc_codigo_pre
, produtos.Pro_Codbase, produtos.Pro_descricao_for, produtos.Pro_CodEspecial
HAVING      (dbo.orcamento_materiais_det.orc_codigo_pre =:codigo)
ORDER BY dbo.orcamento_materiais_det.Pro_codnosso

