WHERE  (dbo.Indicacoes.Ind_Nome IS NOT NULL) AND (dbo.VendaIndicacao.VenInd_TpDoc = 'PRO') AND (dbo.Venda.Ven_Tipo = 'P') AND (dbo.Venda.Ven_Situacao = 'A') AND (dbo.Venda.Emp_codigo =:pemp_codigo)
GROUP BY dbo.Indicacoes.Ind_codigo, dbo.Indicacoes.Ind_Nome, dbo.VendaIndicacao.VenInd_TpDoc, dbo.Venda.Ven_Tipo, dbo.Venda.Ven_Situacao
ORDER BY dbo.Indicacoes.Ind_Nome

