-- [Qryindicacoes_dados : TADOQuery]
SELECT dbo.Indicacoes.Ind_codigo, dbo.Indicacoes.Ind_Nome, dbo.Indicacoes_Detalhe.IndDet_profissao AS ind_profissao, dbo.Indicacoes_Detalhe.IndDet_comercial AS Ind_comercial, 
                  dbo.Indicacoes_Detalhe.IndDet_residencial AS Ind_residencial, dbo.Indicacoes_Detalhe.IndDet_celular AS Ind_celular
FROM     dbo.Indicacoes INNER JOIN
                  dbo.Indicacoes_Detalhe ON dbo.Indicacoes.Ind_codigo = dbo.Indicacoes_Detalhe.Ind_codigo

where dbo.Indicacoes.Ind_codigo=:codigo

-- [Qrycriterios : TADOQuery]
select 
(SELECT     
case when 
SUM(CASE WHEN (vend1.Ven_TipoDesc = 'G' AND Ven_DescontoPorcProd > 0) THEN venpro_vlitem - (venpro_vlitem * (Ven_DescontoPorcProd / 100)) 
                      ELSE venpro_vlitem END) > 0 then
SUM(CASE WHEN (vend1.Ven_TipoDesc = 'G' AND Ven_DescontoPorcProd > 0) THEN venpro_vlitem - (venpro_vlitem * (Ven_DescontoPorcProd / 100)) 
                      ELSE venpro_vlitem END)
else 0
end

FROM         dbo.VendaProduto INNER JOIN
                      dbo.Venda  as vend1 ON dbo.VendaProduto.Ven_CodigoPre = vend1.Ven_CodigoPre INNER JOIN
                      dbo.produtos ON dbo.VendaProduto.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                      dbo.VendaIndicacao ON vend1.Pasta_codigo = dbo.VendaIndicacao.VenInd_NDocPre
WHERE     (vend1.Ven_Situacao = 'A') AND (vend1.Ven_Tipo = 'P') AND (vend1.ParSV_serie <> '3') AND (dbo.VendaIndicacao.VenInd_TpDoc = 'PRO')
and vend1.ven_codigopre = venda.ven_codigopre) and VendaIndicacao.Ind_Codigo = :Ind_Codigo1
-

(
SELECT     CASE WHEN SUM(CASE WHEN VenInd_Porcentagem > 0 THEN CASE WHEN (vdev.Ven_TipoDesc = 'G' AND Ven_DescontoPorcProd > 0) 
                      THEN devpro_vlitem - (devpro_vlitem * (Ven_DescontoPorcProd / 100)) ELSE devpro_vlitem END * (VenInd_Porcentagem / 100) 
                      ELSE CASE WHEN (vdev.Ven_TipoDesc = 'G' AND Ven_DescontoPorcProd > 0) THEN devpro_vlitem - (devpro_vlitem * (Ven_DescontoPorcProd / 100)) 
                      ELSE devpro_vlitem END END) > 0 THEN SUM(CASE WHEN VenInd_Porcentagem > 0 THEN CASE WHEN (vdev.Ven_TipoDesc = 'G' AND Ven_DescontoPorcProd > 0) 
                      THEN devpro_vlitem - (devpro_vlitem * (Ven_DescontoPorcProd / 100)) ELSE devpro_vlitem END * (VenInd_Porcentagem / 100) 
                      ELSE CASE WHEN (vdev.Ven_TipoDesc = 'G' AND Ven_DescontoPorcProd > 0) THEN devpro_vlitem - (devpro_vlitem * (Ven_DescontoPorcProd / 100)) 
                      ELSE devpro_vlitem END END) ELSE 0 END AS ValorComDesc
FROM         dbo.Devolucao INNER JOIN
                      dbo.DevolucaoProduto ON dbo.Devolucao.Dev_CodigoPre = dbo.DevolucaoProduto.Dev_CodigoPre INNER JOIN
                      dbo.produtos ON dbo.DevolucaoProduto.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                      dbo.Venda as vdev ON dbo.Devolucao.ven_codigopre = vdev.Ven_CodigoPre INNER JOIN
                      dbo.VendaIndicacao ON vdev.Ven_CodigoPre = dbo.VendaIndicacao.VenInd_NDocPre
WHERE     (dbo.produtos.GrupoProduto_codigo = 1) AND  (dbo.VendaIndicacao.VenInd_TpDoc = 'PRO') and ((dbo.Devolucao.Dev_migrado = 0) or 
                      (dbo.Devolucao.Dev_migrado IS NULL)) and Devolucao.Dev_situacao = 1
and vdev.ven_codigopre = venda.ven_codigopre and and VendaIndicacao.Ind_Codigo = :Ind_Codigo2  
and Devolucao.Dev_Dtemissao >= :data1 and  Devolucao.Dev_Dtemissao <= :data2

)
 AS vl_luminaria
,


(SELECT     
case when 
SUM(CASE WHEN vend2.Ven_Total > 0 THEN vend2.Ven_Total ELSE 0 END * (VenInd_Porcentagem / 100)) > 0 then
SUM(CASE WHEN vend2.Ven_Total > 0 THEN vend2.Ven_Total ELSE 0 END * (VenInd_Porcentagem / 100)) 
else 0
end

FROM dbo.Venda AS vend2 INNER JOIN
                      dbo.VendaIndicacao ON vend2.Pasta_codigo = dbo.VendaIndicacao.VenInd_NDocPre
WHERE (vend2.Ven_Situacao = 'A') AND (vend2.Ven_Tipo = 'P') AND (vend2.ParSV_serie <> '3') AND (dbo.VendaIndicacao.VenInd_TpDoc = 'PRO')
and vend2.ven_codigopre = venda.ven_codigopre) and VendaIndicacao.Ind_Codigo = :Ind_Codigo3
-
(
SELECT     
case when 
sum(
case when Dev_TotalProd > 0 then Dev_TotalProd else 0 end
+
case when Dev_TotalServ > 0 then Dev_TotalServ else 0 end
* (VenInd_Porcentagem / 100)) > 0 then 

sum(
case when Dev_TotalProd > 0 then Dev_TotalProd else 0 end
+
case when Dev_TotalServ > 0 then Dev_TotalServ else 0 end
* (VenInd_Porcentagem / 100))
else
0
end

FROM         dbo.Devolucao INNER JOIN
                      dbo.Venda AS vdev ON dbo.Devolucao.ven_codigopre = vdev.Ven_CodigoPre INNER JOIN
                      dbo.VendaIndicacao ON vdev.Ven_CodigoPre = dbo.VendaIndicacao.VenInd_NDocPre
WHERE     (dbo.VendaIndicacao.VenInd_TpDoc = 'PRO') and ((dbo.Devolucao.Dev_migrado = 0) or 
                      (dbo.Devolucao.Dev_migrado IS NULL)) and Devolucao.Dev_situacao = 1
and vdev.ven_codigopre = venda.ven_codigopre and VendaIndicacao.Ind_Codigo = :Ind_Codigo4
and Devolucao.Dev_Dtemissao >= :data3 and  Devolucao.Dev_Dtemissao <= :data4

)
 AS vl_total
,
(SELECT     
case when 
SUM(CASE WHEN (VenPro_Quantidade > 0) THEN VenPro_Quantidade ELSE 0 END * (Ven_DescontoPorcProd / 100)) > 0 
then
SUM(CASE WHEN (VenPro_Quantidade > 0) THEN VenPro_Quantidade ELSE 0 END * (Ven_DescontoPorcProd / 100))

else 0
end

FROM         dbo.VendaProduto INNER JOIN
                      dbo.Venda  as vend1 ON dbo.VendaProduto.Ven_CodigoPre = vend1.Ven_CodigoPre INNER JOIN
                      dbo.produtos ON dbo.VendaProduto.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                      dbo.VendaIndicacao ON vend1.Pasta_codigo = dbo.VendaIndicacao.VenInd_NDocPre
WHERE     (vend1.Ven_Situacao = 'A') AND (vend1.Ven_Tipo = 'P') AND (vend1.ParSV_serie <> '3') AND (dbo.VendaIndicacao.VenInd_TpDoc = 'PRO')
and vend1.ven_codigopre = venda.ven_codigopre) and VendaIndicacao.Ind_Codigo = :Ind_Codigo5
-

(
SELECT     
case when 
SUM(CASE WHEN (DevPro_Quantidade > 0) THEN devPro_Quantidade ELSE 0 END * (Ven_DescontoPorcProd / 100)) > 0 
then
SUM(CASE WHEN (devPro_Quantidade > 0) THEN devPro_Quantidade ELSE 0 END * (Ven_DescontoPorcProd / 100))
else 0
end


FROM         dbo.Devolucao INNER JOIN
                      dbo.DevolucaoProduto ON dbo.Devolucao.Dev_CodigoPre = dbo.DevolucaoProduto.Dev_CodigoPre INNER JOIN
                      dbo.produtos ON dbo.DevolucaoProduto.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                      dbo.Venda as vdev ON dbo.Devolucao.ven_codigopre = vdev.Ven_CodigoPre INNER JOIN
                      dbo.VendaIndicacao ON vdev.Ven_CodigoPre = dbo.VendaIndicacao.VenInd_NDocPre
WHERE     (dbo.produtos.GrupoProduto_codigo = 1) AND  (dbo.VendaIndicacao.VenInd_TpDoc = 'PRO') and ((dbo.Devolucao.Dev_migrado = 0) or 
                      (dbo.Devolucao.Dev_migrado IS NULL)) and Devolucao.Dev_situacao = 1
and vdev.ven_codigopre = venda.ven_codigopre and VendaIndicacao.Ind_Codigo = :Ind_Codigo6
and Devolucao.Dev_Dtemissao >= :data5 and  Devolucao.Dev_Dtemissao <= :data6

)
 AS quant_luminaria

from venda where (dbo.Venda.Ven_Situacao = 'A') AND (dbo.Venda.Ven_Tipo = 'P') AND (dbo.Venda.ParSV_serie <> '3')
and venda.Ven_DataEmissao >= :data7 and  venda.Ven_DataEmissao <= :data8

