SELECT     dbo.Orcamento_luminaria_det.Pro_codnosso AS CODIGO, dbo.Orcamento_luminaria_det.old_seq AS SEQ, 
                      dbo.Orcamento_luminaria_det.old_seq_item AS SEQ_ITEM, dbo.Orcamento_luminaria_det.old_acabamento AS ACABAMENTO, 
                      dbo.Orcamento_luminaria_det.old_quantidade AS QUANT, dbo.Orcamento_luminaria_det.old_produto AS PRODUTO, 
                      dbo.Preco_Produto.Pre_Custo AS CUSTO, dbo.Orcamento_luminaria_det.old_quantidade * dbo.Preco_Produto.Pre_Custo AS vl_item, 
                      dbo.Orcamento_luminaria_det.orc_codigo_pre, dbo.produtos.Pro_tp_peca as tipo_peca, dbo.produtos.Pro_tp_produto as tipo_produto
FROM         dbo.Orcamento_luminaria_det INNER JOIN
                      dbo.Preco_Produto ON dbo.Orcamento_luminaria_det.Pro_codnosso = dbo.Preco_Produto.Pre_Codnosso AND 
                      dbo.Orcamento_luminaria_det.old_acabamento = dbo.Preco_Produto.Pre_Acabamento INNER JOIN
                      dbo.produtos ON dbo.Orcamento_luminaria_det.Pro_codnosso = dbo.produtos.Pro_codnosso


