-- [Qryquantit_luminaria : TADOQuery]
SELECT    dbo.pedido_luminaria_det.pld_acabamento, dbo.pedido_luminaria_det.Pro_codnosso, dbo.produtos.Pro_descricao, 
                      dbo.pedido_luminaria_det.pld_unidade, SUM(dbo.pedido_luminaria_det.pld_vl_item) AS tl_vl_item, SUM(dbo.pedido_luminaria_det.pld_quantidade) AS tl_quantidade, 
                      AVG(dbo.pedido_luminaria_det.pld_vl_unitario) AS vl_unitario, dbo.produtos.Pro_tp_peca, dbo.pedido_luminaria_det.ped_codigo_pre, dbo.produtos.Pro_Codbase, 
                      dbo.produtos.Pro_descricao_for, dbo.produtos.Pro_CodEspecial, dbo.Estoque_produto.Epr_estoque, 
                       SUM(dbo.pedido_luminaria_det.pld_quantidade) - dbo.Estoque_produto.Epr_estoque AS quant_pedir
FROM         dbo.pedido_luminaria_det INNER JOIN
                      dbo.produtos ON dbo.pedido_luminaria_det.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                      dbo.Estoque_produto ON dbo.pedido_luminaria_det.Pro_codnosso = dbo.Estoque_produto.Epr_Codnosso AND 
                      dbo.pedido_luminaria_det.pld_acabamento = dbo.Estoque_produto.Epr_Acabamento
WHERE     (dbo.pedido_luminaria_det.pld_quantidade > 0) and (pedido_luminaria_det.ped_codigo_pre =:codigo) 
GROUP BY dbo.pedido_luminaria_det.pld_acabamento, dbo.pedido_luminaria_det.Pro_codnosso, dbo.produtos.Pro_descricao, dbo.pedido_luminaria_det.pld_unidade, 
                      dbo.produtos.Pro_tp_peca, dbo.pedido_luminaria_det.ped_codigo_pre, dbo.produtos.Pro_Codbase, dbo.produtos.Pro_descricao_for, dbo.produtos.Pro_CodEspecial, 
                      dbo.Estoque_produto.Epr_estoque
ORDER BY dbo.pedido_luminaria_det.Pro_codnosso

-- [Qryquantit_materiais : TADOQuery]
SELECT       produtos.Pro_descricao, dbo.pedido_materiais_det.pma_acabamento, dbo.pedido_materiais_det.Pro_codnosso, 
                      dbo.pedido_materiais_det.pma_unidade, dbo.produtos.Pro_tp_produto, dbo.pedido_materiais_det.ped_codigo_pre, SUM(dbo.pedido_materiais_det.pma_quantidade) 
                      AS tl_quantidade, AVG(dbo.pedido_materiais_det.pma_vl_unitario) AS vl_unitario, SUM(dbo.pedido_materiais_det.pma_vl_item) AS tl_vl_item, 
                      dbo.produtos.Pro_Codbase, dbo.produtos.Pro_descricao_for, dbo.produtos.Pro_CodEspecial, dbo.Estoque_produto.Epr_estoque, 
                       SUM(dbo.pedido_materiais_det.pma_quantidade) - dbo.Estoque_produto.Epr_estoque AS quant_pedir
FROM         dbo.pedido_materiais_det INNER JOIN
                      dbo.produtos ON dbo.pedido_materiais_det.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                      dbo.Estoque_produto ON dbo.pedido_materiais_det.Pro_codnosso = dbo.Estoque_produto.Epr_Codnosso AND 
                      dbo.pedido_materiais_det.pma_acabamento = dbo.Estoque_produto.Epr_Acabamento
WHERE     (dbo.pedido_materiais_det.pma_quantidade > 0) and (dbo.pedido_materiais_det.ped_codigo_pre = :codigo) 
GROUP BY dbo.pedido_materiais_det.pma_acabamento, dbo.pedido_materiais_det.Pro_codnosso, dbo.pedido_materiais_det.pma_unidade, dbo.produtos.Pro_tp_produto, 
                      dbo.pedido_materiais_det.ped_codigo_pre, dbo.produtos.Pro_descricao, dbo.produtos.Pro_Codbase, dbo.produtos.Pro_descricao_for, dbo.produtos.Pro_CodEspecial, 
                      dbo.Estoque_produto.Epr_estoque
ORDER BY dbo.pedido_materiais_det.Pro_codnosso

