-- [Qrydata : TADOQuery]
SELECT  dbo.Reserva_tecnica.Ret_codigo, dbo.Reserva_tecnica.Ret_tipo, dbo.Reserva_tecnica.Ret_projeto_avulsa, dbo.pedido.ped_dt_fechamento, 
                      dbo.Avulso.avu_dt_emissao, dbo.pedido.ped_tl_geral_luminaria, dbo.pedido.ped_tl_geral_materiais, dbo.pedido.ped_tl_geral_servico, 
                      dbo.Avulso.avu_tl_geral_luminaria, dbo.Avulso.avu_tl_geral_materiais
FROM         dbo.Reserva_tecnica LEFT OUTER JOIN
                      dbo.pedido ON dbo.Reserva_tecnica.Ret_projeto_avulsa = dbo.pedido.ped_codigo LEFT OUTER JOIN
                      dbo.Avulso ON dbo.Reserva_tecnica.Ret_projeto_avulsa = dbo.Avulso.avu_codigo
WHERE     (dbo.Reserva_tecnica.Ret_situacao = 'ATIVO') and Reserva_tecnica.Ret_codigo=:codigo
ORDER BY dbo.Reserva_tecnica.Ret_data

-- [Qrycalculo : TADOQuery]
SELECT      dbo.Reserva_tecnica.Ret_codigo, dbo.Reserva_tecnica.Ret_tipo, dbo.Reserva_tecnica.Ret_projeto_avulsa, 
                      dbo.pedido.ped_tl_geral_luminaria * dbo.Reserva_tecnica.Ret_tec_luminaria / 100 AS lum_projeto, 
                      dbo.pedido.ped_tl_geral_materiais * dbo.Reserva_tecnica.Ret_tec_materiais / 100 AS mat_projeto, 
                      dbo.pedido.ped_tl_geral_servico * dbo.Reserva_tecnica.Ret_tec_servico / 100 AS ser_projeto, 
                      dbo.Avulso.avu_tl_geral_luminaria * dbo.Reserva_tecnica.Ret_tec_luminaria / 100 AS lum_avulsa, 
                      dbo.Avulso.avu_tl_geral_materiais * dbo.Reserva_tecnica.Ret_tec_materiais / 100 AS mat_avulsa, dbo.contas_apagar.Tpd_codigo, 
                      dbo.contas_apagar.Ctp_valor_total_original
FROM         dbo.Reserva_tecnica INNER JOIN
                      dbo.contas_apagar ON dbo.Reserva_tecnica.Ret_codigo = dbo.contas_apagar.Ctp_cod_documento LEFT OUTER JOIN
                      dbo.pedido ON dbo.Reserva_tecnica.Ret_projeto_avulsa = dbo.pedido.ped_codigo LEFT OUTER JOIN
                      dbo.Avulso ON dbo.Reserva_tecnica.Ret_projeto_avulsa = dbo.Avulso.avu_codigo
WHERE     (dbo.Reserva_tecnica.Ret_situacao = 'ATIVO') AND (dbo.contas_apagar.Tpd_codigo = 1004) and Reserva_tecnica.Ret_codigo=:codigo
ORDER BY dbo.Reserva_tecnica.Ret_data

