-- [Qryprojeto : TADOQuery]
SELECT     dbo.pedido.ped_codigo, dbo.pedido.ped_codigo_pre, dbo.pedido.cli_codigo, dbo.pedido.ped_arquiteta, dbo.pedido.ped_dt_emissao, 
                      dbo.pedido.ped_dt_fechamento, dbo.pedido.ped_cliente, 
                      dbo.pedido.ped_tl_geral_luminaria + dbo.pedido.ped_tl_geral_materiais + dbo.pedido.ped_tl_geral_servico AS total, 
                      dbo.pedido.ped_tl_geral_orcamento, dbo.Clientes.Cli_Nome, dbo.Funcionario.Fun_Nome
FROM         dbo.pedido INNER JOIN
                      dbo.Clientes ON dbo.pedido.cli_codigo = dbo.Clientes.Cli_Codigo INNER JOIN
                      dbo.Funcionario ON dbo.pedido.ped_arquiteta = dbo.Funcionario.Fun_CPF
where pedido.ped_dt_fechamento>=:data1 and pedido.ped_dt_fechamento<=:data2

-- [Qryconta : TADOQuery]
SELECT    dbo.contas_receber.Ctr_cod_documento, dbo.contas_receber.Ctr_valor_total_original, contas_receber.Ctr_codigo,
                      SUM(dbo.contas_Receber_det.Ctr_valor_vencimento) AS total, dbo.contas_receber.Tpd_codigo
FROM         dbo.contas_receber INNER JOIN
                      dbo.contas_Receber_det ON dbo.contas_receber.Ctr_codigo = dbo.contas_Receber_det.Ctr_codigo
GROUP BY dbo.contas_receber.Ctr_cod_documento, dbo.contas_receber.Ctr_valor_total_original, dbo.contas_receber.Tpd_codigo,contas_receber.Ctr_codigo
HAVING      (dbo.contas_receber.Tpd_codigo = 1001) AND (dbo.contas_receber.Ctr_cod_documento =:codigo) AND 
                      (SUM(dbo.contas_Receber_det.Ctr_valor_vencimento) <>:valor)
ORDER BY dbo.contas_receber.Ctr_cod_documento

