-- [QryFactura : TADOQuery]
SELECT     dbo.orcamento.orc_tl_produto AS tl_produto, dbo.orcamento.orc_desc_produto AS desc_produto, dbo.orcamento.orc_tl_geral_produto AS tl_geral_produto, 
                      dbo.orcamento.orc_codigo AS codigo, dbo.orcamento.orc_codigo_pre AS codigo_pre, dbo.orcamento.cli_codigo, dbo.orcamento.orc_dt_emissao AS data, 
                      dbo.orcamento.orc_dt_validade AS DataValidade, dbo.orcamento.orc_desc_por_produto AS desc_porc_produtos, CASE WHEN dbo.Funcionario.Fun_Nome IS NOT NULL
                       THEN dbo.Funcionario.Fun_Nome ELSE 'Mediante Solicitação' END AS eletricista, CASE WHEN Obras.Obr_Endereco IS NOT NULL 
                      THEN Obras.Obr_Endereco ELSE '' END AS Obr_Endereco, CASE WHEN Obras.Obr_numero IS NOT NULL THEN Obras.Obr_numero ELSE '' END AS Obr_numero, 
                      CASE WHEN Obras.Obr_CEP IS NOT NULL THEN Obras.Obr_CEP ELSE '' END AS Obr_CEP, CASE WHEN Municipio.mun_nome IS NOT NULL 
                      THEN Municipio.mun_nome ELSE '' END AS mun_nome, orcamento.orc_forma_pag_extra as forma_pag_extra, orcamento.Orc_TipoDesc as tipodesc, orcamento.Orc_exportacao as exportacao
FROM         dbo.orcamento INNER JOIN
                      dbo.Obras ON dbo.orcamento.Obr_Codigo = dbo.Obras.Obr_Codigo AND dbo.orcamento.cli_codigo = dbo.Obras.Cli_codigo LEFT OUTER JOIN
                      dbo.Municipio ON dbo.Obras.mun_codigo = dbo.Municipio.mun_codigo LEFT OUTER JOIN
                      dbo.Funcionario ON dbo.orcamento.orc_eletricista = dbo.Funcionario.Fun_CPF

where orcamento.orc_codigo=:pcodigo

-- [Qryprodutos : TADOQuery]
SELECT     dbo.produtos.Pro_descricao AS descricao, dbo.Orcamento_luminaria_det.Pro_codnosso AS codigo, dbo.Orcamento_luminaria_det.old_acabamento AS acabamento, 
                      dbo.Orcamento_luminaria_det.old_unidade AS unidade, SUM(dbo.Orcamento_luminaria_det.old_quantidade) AS quantidade, 
                      MAX(dbo.Orcamento_luminaria_det.old_vl_unitario) AS vl_unitario, MAX(dbo.Orcamento_luminaria_det.old_vl_item) AS vl_item, 
                      MAX(dbo.Orcamento_luminaria_det.old_VlImposto) AS vlimposto, SUM(dbo.Orcamento_luminaria_det.old_quantidade) 
                      * MAX(dbo.Orcamento_luminaria_det.old_vl_unitario) AS vl_item_sem_iva, dbo.produtos.Pro_AliqICMS AS aliq, 
                      CASE WHEN dbo.orcamento.orc_desc_por_luminaria > 0 THEN MAX(Orcamento_luminaria_det.old_vl_item) - (MAX(Orcamento_luminaria_det.old_vl_item) 
                      * (orcamento.orc_desc_por_luminaria / 100)) ELSE MAX(Orcamento_luminaria_det.old_vl_item) END AS vl_item_desc, 
                      dbo.orcamento.orc_desc_por_luminaria AS desconto, dbo.VendaAmbiente.VenAmb_Descricao, dbo.Orcamento_luminaria_det.old_seq AS sequencia, 
                      dbo.Orcamento_luminaria_det.old_seq_item AS sequenciaItem
FROM         dbo.Orcamento_luminaria_det INNER JOIN
                      dbo.produtos ON dbo.Orcamento_luminaria_det.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                      dbo.orcamento ON dbo.Orcamento_luminaria_det.orc_codigo_pre = dbo.orcamento.orc_codigo_pre INNER JOIN
                      dbo.VendaAmbiente ON dbo.orcamento.orc_codigo_pre = dbo.VendaAmbiente.VenAmb_NDocPre
WHERE     (dbo.VendaAmbiente.VenAmb_TpDoc = 'ORC') AND (dbo.orcamento.orc_codigo = 6)
GROUP BY dbo.Orcamento_luminaria_det.old_seq, dbo.Orcamento_luminaria_det.old_seq_item, dbo.VendaAmbiente.VenAmb_Descricao, dbo.produtos.Pro_descricao, 
                      dbo.Orcamento_luminaria_det.Pro_codnosso, dbo.Orcamento_luminaria_det.old_acabamento, dbo.Orcamento_luminaria_det.old_unidade, 
                      dbo.Orcamento_luminaria_det.old_quantidade, dbo.Orcamento_luminaria_det.old_vl_unitario, dbo.Orcamento_luminaria_det.old_vl_item, 
                      dbo.Orcamento_luminaria_det.old_VlImposto, dbo.produtos.Pro_AliqICMS, dbo.orcamento.orc_desc_por_luminaria
union all

SELECT     dbo.produtos.Pro_descricao AS descricao, dbo.orcamento_materiais_det.Pro_codnosso AS codigo, dbo.orcamento_materiais_det.oma_acabamento AS acabamento, 
                      dbo.orcamento_materiais_det.oma_unidade AS unidade, SUM(dbo.orcamento_materiais_det.oma_quantidade) AS quantidade, 
                      MAX(dbo.orcamento_materiais_det.oma_vl_unitario) AS vl_unitario, MAX(dbo.orcamento_materiais_det.oma_vl_item) AS vl_item, 
                      MAX(dbo.orcamento_materiais_det.oma_VlImposto) AS vlimposto, SUM(dbo.orcamento_materiais_det.oma_quantidade) 
                      * MAX(dbo.orcamento_materiais_det.oma_vl_unitario) AS vl_item_sem_iva, dbo.produtos.Pro_AliqICMS AS aliq, 
                      CASE WHEN orcamento.orc_desc_por_materiais > 0 THEN MAX(orcamento_materiais_det.oma_vl_item) - (MAX(orcamento_materiais_det.oma_vl_item) 
                      * (orcamento.orc_desc_por_materiais / 100)) ELSE MAX(orcamento_materiais_det.oma_vl_item) END AS vl_item_desc, 
                      dbo.orcamento.orc_desc_por_materiais AS desconto, dbo.VendaAmbiente.VenAmb_Descricao, dbo.orcamento_materiais_det.oma_seq AS sequencia, 
                      dbo.orcamento_materiais_det.oma_seq_item AS sequenciaItem
FROM         dbo.orcamento_materiais_det INNER JOIN
                      dbo.produtos ON dbo.orcamento_materiais_det.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                      dbo.orcamento ON dbo.orcamento_materiais_det.orc_codigo_pre = dbo.orcamento.orc_codigo_pre INNER JOIN
                      dbo.VendaAmbiente ON dbo.orcamento.orc_codigo_pre = dbo.VendaAmbiente.VenAmb_NDocPre
WHERE     (dbo.VendaAmbiente.VenAmb_TpDoc = 'ORC') AND (dbo.orcamento.orc_codigo = 6)
GROUP BY dbo.orcamento_materiais_det.oma_seq, dbo.orcamento_materiais_det.oma_seq_item, dbo.VendaAmbiente.VenAmb_Descricao, dbo.produtos.Pro_descricao, 
                      dbo.orcamento_materiais_det.Pro_codnosso, dbo.orcamento_materiais_det.oma_acabamento, dbo.orcamento_materiais_det.oma_unidade, 
                      dbo.orcamento_materiais_det.oma_quantidade, dbo.orcamento_materiais_det.oma_vl_unitario, dbo.orcamento_materiais_det.oma_vl_item, 
                      dbo.orcamento_materiais_det.oma_VlImposto, dbo.produtos.Pro_AliqICMS, dbo.orcamento.orc_desc_por_materiais, dbo.orcamento_materiais_det.oma_seq_item

-- [QryIVA : TADOQuery]
SELECT  SUM((dbo.produtos.Pro_AliqICMS / 100) * orcamento_materiais_det.oma_vl_item) AS valor_iva,
produtos.Pro_AliqICMS AS aliq_iva,  SUM(orcamento_materiais_det.oma_vl_item) as base_iva 
FROM  orcamento_materiais_det INNER JOIN
produtos ON orcamento_materiais_det.Pro_codnosso = produtos.Pro_codnosso
 where orcamento_materiais_det.orc_codigo_pre =6
 GROUP BY dbo.produtos.Pro_AliqICMS
union all
SELECT  SUM((produtos.Pro_AliqICMS / 100) * Orcamento_luminaria_det.old_vl_item) AS valor_iva,
 produtos.Pro_AliqICMS AS aliq_iva, SUM(Orcamento_luminaria_det.old_vl_item) as base_iva
 FROM Orcamento_luminaria_det INNER JOIN
 produtos ON Orcamento_luminaria_det.Pro_codnosso = produtos.Pro_codnosso
 where Orcamento_luminaria_det.orc_codigo_pre =6
 GROUP BY produtos.Pro_AliqICMS
 order by aliq_iva

