-- [QryEndCliente : TADOQuery]
SELECT     dbo.Clientes.Cli_cnpj_cpf AS cpf, dbo.Clientes.Cli_Nome AS nome, dbo.Clientes.Cli_Endereco AS endereco, dbo.Clientes.Cli_numero AS num, 
                      dbo.Clientes.Cli_complemento AS comp, dbo.Clientes.Cli_Bairro AS bairro, dbo.Clientes.Cli_CEP AS cep, dbo.Municipio.mun_nome AS cidade, 
                      dbo.Municipio.mun_uf AS uf, dbo.Paises.Paises_Descricao, CASE WHEN cli_fcomercial IS NOT NULL THEN cli_fcomercial ELSE '' END AS FoneCom, 
                      CASE WHEN Clientes.Cli_celular IS NOT NULL THEN Clientes.Cli_celular ELSE '' END AS Fonecelular, CASE WHEN Clientes.Cli_Fresidencial IS NOT NULL 
                      THEN Clientes.Cli_Fresidencial ELSE '' END AS FoneRes
FROM         dbo.Clientes INNER JOIN
                      dbo.Municipio ON dbo.Clientes.Cli_codcidade = dbo.Municipio.mun_codigo INNER JOIN
                      dbo.Paises ON dbo.Municipio.Paises_codigo = dbo.Paises.Paises_Codigo

