-- [Qryvenda : TADOQuery]
SELECT     
case when  Ven_Tipo ='O' then 'ORÇAMENTO' else 'PEDIDO DE VENDA' END as tipo,
dbo.Clientes.Cli_Nome, dbo.Venda.Ven_codigo, dbo.Venda.Ven_Situacao, dbo.Venda.ParSV_serie, dbo.Venda.Ven_Orcamento, dbo.Venda.Ven_DataEmissao, 
                      dbo.Venda.Ven_DataValidade, dbo.Venda.Ven_DataFechaVenda, dbo.Venda.Ven_DataConclusao, dbo.Venda.Ven_Total, dbo.Venda.Pasta_codigo, 
                      dbo.Venda.Ven_CodigoPre, dbo.Venda.Ven_AcrescimoProd, dbo.Venda.Ven_AcrescimoPorcProd, dbo.Venda.Ven_DescontoPorcProd, dbo.Venda.Ven_DescontoProd, 
                      dbo.Venda.Ven_TotalProd, dbo.Venda.Ven_SubTotalProd, dbo.Venda.Ven_SubTotal, dbo.Venda.Ven_Acrescimo, dbo.Venda.Ven_AcrescimoPorc, 
                      dbo.Venda.Ven_DescontoPorc, dbo.Venda.Ven_Desconto, Venda.Ven_CodVinculo, venda.Ven_DescricaoVenda
FROM         dbo.Clientes INNER JOIN
                      dbo.Venda ON dbo.Clientes.Cli_Codigo = dbo.Venda.Ven_CodVinculo

where venda.Pasta_codigo =:pPasta_codigo and venda.ven_tipo='P'

-- [QryDevolucao : TADOQuery]
SELECT     dbo.Devolucao.Dev_codigo, dbo.Devolucao.Dev_Dtemissao, dbo.Devolucao.Dev_Total, dbo.Clientes.Cli_Nome, dbo.Venda.Ven_codigo, dbo.Venda.ParSV_serie
,Devolucao.Dev_codigopre
FROM         dbo.Devolucao INNER JOIN
                      dbo.Venda ON dbo.Devolucao.ven_codigopre = dbo.Venda.Ven_CodigoPre INNER JOIN
                      dbo.Clientes ON dbo.Venda.Ven_CodVinculo = dbo.Clientes.Cli_Codigo
where venda.Pasta_codigo =:pPasta_codigo and devolucao.Dev_migrado is null and devolucao.Dev_situacao = 1

-- [QryVendapai : TADOQuery]
SELECT  CAST(venda.ven_codigo as varchar(12) )+    '   Série ' + Venda.ParSV_serie   + ' - Data Emissão: ' + CONVERT(VARCHAR(10), Venda.Ven_DataEmissao, 103)

as venda, Venda.Ven_CodigoPre

FROM         dbo.Clientes INNER JOIN
                      dbo.Venda ON dbo.Clientes.Cli_Codigo = dbo.Venda.Ven_CodVinculo
where venda.Pasta_codigo  =:pPasta_codigo and venda.ven_tipo='P' and venda.ven_situacao = 'A'
ORDER by Venda.Ven_DataEmissao

-- [Qryorcamento : TADOQuery]
SELECT     
case when  Ven_Tipo ='O' then 'ORÇAMENTO' else 'PEDIDO DE VENDA' END as tipo,
dbo.Clientes.Cli_Nome, dbo.Venda.Ven_codigo, dbo.Venda.Ven_Situacao, dbo.Venda.ParSV_serie, dbo.Venda.Ven_Orcamento, dbo.Venda.Ven_DataEmissao, 
                      dbo.Venda.Ven_DataValidade, dbo.Venda.Ven_DataFechaVenda, dbo.Venda.Ven_DataConclusao, dbo.Venda.Ven_Total, dbo.Venda.Pasta_codigo, 
                      dbo.Venda.Ven_CodigoPre, dbo.Venda.Ven_AcrescimoProd, dbo.Venda.Ven_AcrescimoPorcProd, dbo.Venda.Ven_DescontoPorcProd, dbo.Venda.Ven_DescontoProd, 
                      dbo.Venda.Ven_TotalProd, dbo.Venda.Ven_SubTotalProd, dbo.Venda.Ven_SubTotal, dbo.Venda.Ven_Acrescimo, dbo.Venda.Ven_AcrescimoPorc, 
                      dbo.Venda.Ven_DescontoPorc, dbo.Venda.Ven_Desconto, Venda.Ven_CodVinculo, venda.Ven_DescricaoVenda
FROM         dbo.Clientes INNER JOIN
                      dbo.Venda ON dbo.Clientes.Cli_Codigo = dbo.Venda.Ven_CodVinculo

where venda.Pasta_codigo =:pPasta_codigo and venda.ven_tipo='O' and Venda.Ven_DataFechaVenda is null


