-- [Qryestoque_ma : TADOQuery]
SELECT max(pedido_materiais_det.pma_codindice) as pma_codindice,pedido_materiais_det.Pro_codnosso, pedido_materiais_det.pma_acabamento, (Sum([pedido_materiais_det].[pma_quantidade]))AS total, pedido_materiais_det.ped_codigo_pre,[Estoque_produto].[Epr_estoque] 
FROM pedido_materiais_det INNER JOIN Estoque_produto ON (pedido_materiais_det.pma_acabamento = Estoque_produto.Epr_Acabamento) AND (pedido_materiais_det.Pro_codnosso = Estoque_produto.Epr_Codnosso)
where pedido_materiais_det.ped_codigo_pre=:codigo and Estoque_produto.EstTp_Codigo=1
GROUP BY pedido_materiais_det.Pro_codnosso, pedido_materiais_det.pma_acabamento, pedido_materiais_det.ped_codigo_pre, Estoque_produto.Epr_estoque, pedido_materiais_det.ped_codigo_pre

-- [Qryestoque_lu : TADOQuery]
SELECT max(pedido_luminaria_det.pld_codindice) as pld_codindice  , pedido_luminaria_det.ped_codigo_pre, pedido_luminaria_det.Pro_codnosso, pedido_luminaria_det.pld_acabamento, ((Sum(pedido_luminaria_det.pld_quantidade))) AS total,Estoque_produto.Epr_estoque
FROM pedido_luminaria_det INNER JOIN Estoque_produto ON (pedido_luminaria_det.Pro_codnosso = Estoque_produto.Epr_Codnosso) AND (pedido_luminaria_det.pld_acabamento = Estoque_produto.Epr_Acabamento)
where pedido_luminaria_det.ped_codigo_pre=:codigo and Estoque_produto.EstTp_Codigo=1
GROUP BY pedido_luminaria_det.ped_codigo_pre, pedido_luminaria_det.Pro_codnosso, pedido_luminaria_det.pld_acabamento, Estoque_produto.Epr_estoque

