-- [Qryproduto : TADOQuery]
SELECT dbo.Preco_Produto.Pre_Acabamento, dbo.produtos.Pro_codnosso, dbo.produtos.Pro_descricao, dbo.produtos.Pro_unidade, dbo.Preco_Produto.Pre_compra, dbo.Preco_Produto.Pre_Tabela, dbo.Preco_Produto.Pre_Custo, 
                  dbo.unidades.uni_descricao, dbo.produtos.Pro_CodEspecial, dbo.Preco_Produto.Pre_VlNFor, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto, 
                  CASE WHEN acab_tipo = 'E' THEN 'Ext.:' ELSE CASE WHEN acab_tipo = 'T' THEN 'Ext. e Inter.:' ELSE '' END END + dbo.Acabamento.DescAcabamento + '  ' + CASE WHEN acab_tipo2 = 'I' THEN 'Inter.:' ELSE '' END + CASE WHEN DescAcabamento2
                   IS NULL THEN '' ELSE DescAcabamento2 END AS descricaoacabamento, dbo.Preco_Produto.Tam_codigo, dbo.tamanho.Tam_descricao
,fornecedor.For_Nome
FROM     dbo.produtos INNER JOIN
                  dbo.Preco_Produto ON dbo.produtos.Pro_codnosso = dbo.Preco_Produto.Pre_Codnosso INNER JOIN
                  dbo.unidades ON dbo.produtos.Pro_unidade = dbo.unidades.uni_codigo INNER JOIN
                  dbo.ProdutosFornecedores ON dbo.produtos.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso INNER JOIN
                  dbo.Acabamento ON dbo.Preco_Produto.Pre_Acabamento = dbo.Acabamento.CodAcabamento INNER JOIN
                  dbo.fornecedor ON dbo.ProdutosFornecedores.For_codigo = dbo.fornecedor.For_codigo LEFT OUTER JOIN
                  dbo.tamanho ON dbo.Preco_Produto.Tam_codigo = dbo.tamanho.Tam_codigo

WHERE (((produtos.Pro_codnosso)=:codigo) AND ((Preco_Produto.Pre_Acabamento)=:acabamento))
and (dbo.ProdutosFornecedores.ProdFor_Situacao = 1) AND (dbo.ProdutosFornecedores.ProdFor_Padrao = 1)

