SELECT  *              
FROM  pos_venda where Pve_codigo=:codigo

-- [Qryprojetos : TADOQuery]
SELECT     TOP (100) PERCENT dbo.Venda.Ven_codigo, dbo.Venda.ParSV_serie, dbo.Pasta.Pasta_codigo, dbo.Pasta.Pasta_Descricao, dbo.Obras.Obr_Descricao, 
                      dbo.Venda.Ven_DataEmissao, dbo.Venda.Ven_DataValidade, dbo.Venda.Ven_DataFechaVenda, dbo.Venda.Ven_Tipo, dbo.Venda.Ven_Situacao, 
                      dbo.Venda.Ven_CodVinculo, dbo.Motivo_devolucao.Mod_descricao
FROM         dbo.Venda INNER JOIN
                      dbo.Obras ON dbo.Venda.Obr_codigo = dbo.Obras.Obr_Codigo LEFT OUTER JOIN
                      dbo.Motivo_devolucao ON dbo.Venda.Mod_codigo = dbo.Motivo_devolucao.Mod_codigo LEFT OUTER JOIN
                      dbo.Pasta ON dbo.Venda.Pasta_codigo = dbo.Pasta.Pasta_codigo

WHERE     (dbo.Venda.Ven_DataFechaVenda IS NULL) AND (dbo.Venda.Ven_Tipo = 'O') and Venda.Ven_CodVinculo =:codigo
ORDER BY dbo.Venda.Ven_codigo

-- [Qryavulsa : TADOQuery]
SELECT     TOP (100) PERCENT dbo.Venda.Ven_codigo, dbo.Venda.ParSV_serie, dbo.Pasta.Pasta_codigo, dbo.Pasta.Pasta_Descricao, dbo.Obras.Obr_Descricao, 
                      dbo.Venda.Ven_DataEmissao, dbo.Venda.Ven_DataValidade, dbo.Venda.Ven_DataFechaVenda, dbo.Venda.Ven_Tipo, dbo.Venda.Ven_Situacao, 
                      dbo.Venda.Ven_CodVinculo, dbo.Motivo_devolucao.Mod_descricao, dbo.Venda.Ven_Orcamento
FROM         dbo.Venda INNER JOIN
                      dbo.Obras ON dbo.Venda.Obr_codigo = dbo.Obras.Obr_Codigo LEFT OUTER JOIN
                      dbo.Motivo_devolucao ON dbo.Venda.Mod_codigo = dbo.Motivo_devolucao.Mod_codigo LEFT OUTER JOIN
                      dbo.Pasta ON dbo.Venda.Pasta_codigo = dbo.Pasta.Pasta_codigo
WHERE     (dbo.Venda.Ven_Tipo = 'P')  and Venda.Ven_CodVinculo =:codigo
