-- [Qryprodutos : TADOQuery]
SELECT     dbo.produtos.Pro_codnosso, dbo.Preco_Produto.Pre_Acabamento, dbo.Preco_Produto.Pre_Venda, dbo.produtos.Pro_unidade, dbo.fornecedor.For_Nome, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, 
                  dbo.Estoque_produto.EstTp_Codigo, dbo.Estoque_produto.Epr_estoque,Preco_Produto.Pre_CodBarra
FROM        dbo.produtos INNER JOIN
                  dbo.ProdutosFornecedores ON dbo.produtos.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso INNER JOIN
                  dbo.Preco_Produto ON dbo.produtos.Pro_codnosso = dbo.Preco_Produto.Pre_Codnosso INNER JOIN
                  dbo.fornecedor ON dbo.ProdutosFornecedores.For_codigo = dbo.fornecedor.For_codigo INNER JOIN
                  dbo.Estoque_produto ON dbo.Preco_Produto.Pre_Codnosso = dbo.Estoque_produto.Epr_Codnosso AND dbo.Preco_Produto.Pre_Acabamento = dbo.Estoque_produto.Epr_Acabamento
WHERE     (dbo.Estoque_produto.EstTp_Codigo = 1)


