   FORM: FrmPreVendaEscolher   Pré-Venda
   ============================================================ */

-- [QryPre : TADOQuery]
SELECT      dbo.Venda.Ven_codigo, dbo.Venda.ParSV_serie, dbo.Venda.Ven_CodigoPre, dbo.Venda.Ven_DataEmissao, dbo.Venda.Ven_Total, dbo.Clientes.Cli_Nome, dbo.Venda.Ven_Tipo, dbo.VendaAtendente.VenAten_TpDoc, dbo.Funcionario.Fun_Nome
 , (SELECT TOP (1) dbo.NotaFiscal.NTF_Numero FROM NotaFiscal INNER JOIN
     NotaFiscalImportaDoc ON NotaFiscal.NTF_Codigo = NotaFiscalImportaDoc.NTF_Codigo
        WHERE (NotaFiscalImportaDoc.NTFImp_DocCodigo = venda.ven_codigo) AND
           (NotaFiscalImportaDoc.NTFImp_DocTipo = 'VEN')) AS nota

FROM        dbo.Clientes INNER JOIN
                  dbo.Venda ON dbo.Clientes.Cli_Codigo = dbo.Venda.Ven_CodVinculo INNER JOIN
                  dbo.VendaAtendente ON dbo.Venda.Ven_CodigoPre = dbo.VendaAtendente.VenAten_NDocPre INNER JOIN
                  dbo.Funcionario ON dbo.VendaAtendente.Fun_Codigo = dbo.Funcionario.Fun_CPF
WHERE     (dbo.Venda.Ven_Tipo = 'V') AND (dbo.VendaAtendente.VenAten_TpDoc = 'VEN')

AND (SELECT TOP (1) dbo.NotaFiscal.NTF_Numero FROM NotaFiscal INNER JOIN
     NotaFiscalImportaDoc ON NotaFiscal.NTF_Codigo = NotaFiscalImportaDoc.NTF_Codigo
        WHERE (NotaFiscalImportaDoc.NTFImp_DocCodigo = venda.ven_codigo) AND
           (NotaFiscalImportaDoc.NTFImp_DocTipo = 'VEN'))  IS NULL



ORDER BY dbo.Venda.Ven_codigo, dbo.Venda.Ven_DataEmissao


