-- [Qryrelatorio2 : TADOQuery]
SELECT        TOP (100) PERCENT MAX(dbo.VendaProduto.VenPro_Vlimposto) AS cod_vlimposto, dbo.VendaProduto.Pro_codnosso, dbo.VendaProduto.Ven_CodigoPre, dbo.VendaProduto.CodAcabamento, 
                         SUM(dbo.VendaProduto.VenPro_Quantidade) AS tl_quantidade, MAX(dbo.VendaProduto.VenPro_VlUnitario) AS vl_unitario, SUM(dbo.VendaProduto.VenPro_VlItem) AS tl_vl_item, dbo.produtos.Pro_tp_peca, 
                         dbo.produtos.Pro_tp_produto, dbo.ProdutosFornecedores.ProdFor_CodigoProduto AS Pro_Codbase, dbo.produtos.Pro_CodEspecial, MAX(dbo.VendaProduto.VenPro_Vldesconto) AS desconto, 
                         CASE WHEN substring(vendaproduto.Pro_codnosso, 1, 18) = '999999999999999999' THEN vendaproduto.VenPro_PreProduto ELSE dbo.ProdutosFornecedores.ProdFor_DescricaoProduto END AS Pro_descricao_for, 
                         CASE WHEN substring(vendaproduto.Pro_codnosso, 1, 18) = '999999999999999999' THEN vendaproduto.VenPro_PreProduto ELSE produtos.Pro_descricao END AS Pro_descricao, 
                         dbo.ProdutosFornecedores.ProdFor_Padrao
FROM            dbo.VendaProduto WITH (NOLOCK) INNER JOIN
                         dbo.produtos WITH (NOLOCK) ON dbo.VendaProduto.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                         dbo.ProdutosFornecedores ON dbo.produtos.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso
WHERE        (dbo.VendaProduto.Ven_CodigoPre =:pVen_codigopre) AND (dbo.VendaProduto.VenPro_Quantidade > 0) AND (dbo.produtos.GrupoProduto_codigo > 1) AND (dbo.ProdutosFornecedores.ProdFor_Padrao = 1)
GROUP BY dbo.VendaProduto.Pro_codnosso, dbo.produtos.Pro_descricao, dbo.VendaProduto.Ven_CodigoPre, dbo.VendaProduto.CodAcabamento, dbo.produtos.Pro_tp_peca, dbo.produtos.Pro_tp_produto, dbo.produtos.Pro_descricao_for, 
                         dbo.produtos.Pro_Codbase, dbo.produtos.Pro_CodEspecial, dbo.VendaProduto.VenPro_Vlimposto, dbo.VendaProduto.VenPro_Vldesconto, dbo.VendaProduto.VenPro_PreProduto, 
                         dbo.ProdutosFornecedores.ProdFor_CodigoProduto, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto, dbo.ProdutosFornecedores.ProdFor_Padrao
ORDER BY dbo.VendaProduto.Pro_codnosso

