SELECT pedido_materiais_det.Pro_codnosso, pedido_materiais_det.pma_produto, pedido_materiais_det.pma_unidade, Sum(pedido_materiais_det.pma_vl_item) AS tl_vl_item, 
Sum(pedido_materiais_det.pma_quantidade) AS tl_quantidade, Max(pedido_materiais_det.pma_vl_unitario) AS vl_unitario, produtos.Pro_tp_produto, pedido_materiais_det.ped_codigo_pre 
,produtos.Pro_descricao_for, produtos.Pro_Codbase, produtos.Pro_CodEspecial , pedido_materiais_det.pma_vlimposto
,Max(pedido_materiais_det.pma_desconto) AS desconto, produtos.Pro_tp_peca
FROM pedido_materiais_det WITH (NOLOCK) INNER JOIN produtos WITH (NOLOCK) ON pedido_materiais_det.Pro_codnosso = produtos.Pro_codnosso 
GROUP BY pedido_materiais_det.Pro_codnosso, pedido_materiais_det.pma_produto, pedido_materiais_det.pma_unidade, produtos.Pro_tp_produto, pedido_materiais_det.ped_codigo_pre 
,produtos.Pro_descricao_for, produtos.Pro_Codbase, produtos.Pro_CodEspecial ,pedido_materiais_det.pma_vlimposto,pedido_materiais_det.pma_desconto, produtos.Pro_tp_peca
HAVING (((pedido_materiais_det.ped_codigo_pre)=:codigo) )

-- [Qrypedido_com_amb : TADOQuery]
SELECT pedido_luminaria_det.Pro_codnosso, pedido_luminaria_det.pld_seq, pedido_luminaria_det.pld_produto, pedido_luminaria_det.ped_codigo_pre, pedido_luminaria_det.pld_ambiente, VendaAmbiente.VenAmb_Descricao, pedido_luminaria_det.pld_acabamento, Sum(pedido_luminaria_det.pld_quantidade) AS tl_quantidade, Max(pedido_luminaria_det.pld_vl_unitario) AS vl_unitario, Sum(pedido_luminaria_det.pld_vl_item) AS tl_vl_item, produtos.Pro_tp_peca, produtos.Pro_tp_produto, pedido_luminaria_det.pld_seq_item
,max(pedido_luminaria_det.pld_desconto) as desconto

FROM (pedido_luminaria_det WITH (NOLOCK) INNER JOIN VendaAmbiente WITH (NOLOCK) ON pedido_luminaria_det.pld_ambiente = VendaAmbiente.CodAmbiente) INNER JOIN produtos WITH (NOLOCK) ON pedido_luminaria_det.Pro_codnosso = produtos.Pro_codnosso
WHERE (((pedido_luminaria_det.ped_codigo_pre)=:codigo and pedido_luminaria_det.pld_seq =:seq and pedido_luminaria_det.pld_quantidade > 0)) and pedido_luminaria_det.pld_seq_item=:item
and VendaAmbiente.VenAmb_TpDoc='PRO' and VendaAmbiente.VenAmb_NDocPre = pedido_luminaria_det.ped_codigo_pre
GROUP BY pedido_luminaria_det.Pro_codnosso, pedido_luminaria_det.pld_seq, pedido_luminaria_det.pld_produto, pedido_luminaria_det.ped_codigo_pre, pedido_luminaria_det.pld_ambiente, VendaAmbiente.VenAmb_Descricao, pedido_luminaria_det.pld_acabamento, produtos.Pro_tp_peca, produtos.Pro_tp_produto, pedido_luminaria_det.pld_seq, pedido_luminaria_det.pld_seq_item,pedido_luminaria_det.pld_desconto
ORDER BY  pedido_luminaria_det.pld_seq, pedido_luminaria_det.pld_seq_item;

-- [Qryquantit_materiais : TADOQuery]
SELECT pedido_materiais_det.pma_acabamento,pedido_materiais_det.Pro_codnosso, pedido_materiais_det.pma_produto, pedido_materiais_det.pma_unidade, Sum(pedido_materiais_det.pma_vl_item) AS tl_vl_item, Sum(pedido_materiais_det.pma_quantidade) AS tl_quantidade, Max(pedido_materiais_det.pma_vl_unitario) AS vl_unitario, produtos.Pro_tp_produto, pedido_materiais_det.ped_codigo_pre
