HAVING (((pedido_luminaria_det.ped_codigo_pre)=:codigo))

-- [Qryped_lum : TADOQuery]
SELECT pedido_luminaria_det.Pro_codnosso, pedido_luminaria_det.pld_seq, pedido_luminaria_det.pld_produto, 
pedido_luminaria_det.ped_codigo_pre, pedido_luminaria_det.pld_ambiente, VendaAmbiente.VenAmb_Descricao, 
pedido_luminaria_det.pld_acabamento, Sum(pedido_luminaria_det.pld_quantidade) AS tl_quantidade, 
Max(pedido_luminaria_det.pld_vl_unitario) AS vl_unitario, Sum(pedido_luminaria_det.pld_vl_item) AS tl_vl_item,
produtos.Pro_tp_peca, produtos.Pro_tp_produto, pedido_luminaria_det.pld_seq_item 
,produtos.Pro_descricao_for, produtos.Pro_Codbase, produtos.Pro_CodEspecial, pedido_luminaria_det.pld_vlimposto 
, Max(pedido_luminaria_det.pld_desconto) as desconto
FROM (pedido_luminaria_det WITH (NOLOCK) INNER JOIN VendaAmbiente WITH (NOLOCK) ON pedido_luminaria_det.pld_ambiente = 
VendaAmbiente.CodAmbiente) INNER JOIN produtos WITH (NOLOCK) ON pedido_luminaria_det.Pro_codnosso = produtos.Pro_codnosso 
WHERE (((pedido_luminaria_det.ped_codigo_pre)=:codigo) and pedido_luminaria_det.pld_quantidade > 0) 
and VendaAmbiente.VenAmb_TpDoc = 'PRO' and VendaAmbiente.VenAmb_NDocPre = pedido_luminaria_det.ped_codigo_pre
GROUP BY pedido_luminaria_det.Pro_codnosso, pedido_luminaria_det.pld_seq,pedido_luminaria_det.pld_seq_item ,pedido_luminaria_det.pld_produto, 
pedido_luminaria_det.ped_codigo_pre, pedido_luminaria_det.pld_ambiente, VendaAmbiente.VenAmb_Descricao, pedido_luminaria_det.pld_acabamento, 
produtos.Pro_tp_peca, produtos.Pro_tp_produto
,produtos.Pro_descricao_for, produtos.Pro_Codbase, produtos.Pro_CodEspecial , pedido_luminaria_det.pld_vlimposto,pedido_luminaria_det.pld_desconto 
ORDER BY pedido_luminaria_det.pld_seq,pedido_luminaria_det.pld_seq_item

-- [Qryorcamento_lum : TADOQuery]
SELECT        TOP (100) PERCENT dbo.VendaProduto.VenPro_Vlimposto AS cod_vlimposto, dbo.VendaProduto.Pro_codnosso, dbo.VendaProduto.VenPro_Seq, dbo.VendaProduto.Ven_CodigoPre, dbo.VendaProduto.CodAmbiente, 
                         dbo.VendaAmbiente.VenAmb_Descricao, dbo.VendaProduto.CodAcabamento, SUM(dbo.VendaProduto.VenPro_Quantidade) AS tl_quantidade, MAX(dbo.VendaProduto.VenPro_VlUnitario) AS vl_unitario, 
                         SUM(dbo.VendaProduto.VenPro_VlItem) AS tl_vl_item, dbo.produtos.Pro_tp_peca, dbo.produtos.Pro_tp_produto, dbo.VendaProduto.VenPro_SeqItem, dbo.ProdutosFornecedores.ProdFor_CodigoProduto AS Pro_Codbase, 
                         dbo.produtos.Pro_CodEspecial, MAX(dbo.VendaProduto.VenPro_Vldesconto) AS desconto, CASE WHEN substring(vendaproduto.Pro_codnosso, 1, 18) 
                         = '999999999999999999' THEN vendaproduto.VenPro_PreProduto ELSE dbo.ProdutosFornecedores.ProdFor_DescricaoProduto END AS Pro_descricao_for, CASE WHEN substring(vendaproduto.Pro_codnosso, 1, 18) 
                         = '999999999999999999' THEN vendaproduto.VenPro_PreProduto ELSE produtos.Pro_descricao END AS Pro_descricao, dbo.ProdutosFornecedores.ProdFor_Padrao
FROM            dbo.VendaProduto WITH (NOLOCK) INNER JOIN
                         dbo.VendaAmbiente WITH (NOLOCK) ON dbo.VendaProduto.CodAmbiente = dbo.VendaAmbiente.CodAmbiente AND dbo.VendaProduto.Ven_CodigoPre = dbo.VendaAmbiente.VenAmb_NDocPre INNER JOIN
                         dbo.produtos WITH (NOLOCK) ON dbo.VendaProduto.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                         dbo.ProdutosFornecedores ON dbo.produtos.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso
WHERE        (dbo.VendaAmbiente.VenAmb_TpDoc =:pVenAmb_TpDoc ) 
AND (dbo.VendaProduto.Ven_CodigoPre =:pVen_codigopre) 
AND (dbo.VendaProduto.VenPro_Quantidade > 0) AND (dbo.produtos.GrupoProduto_codigo = 1) AND 
                         (dbo.ProdutosFornecedores.ProdFor_Padrao = 1)
GROUP BY dbo.VendaProduto.Pro_codnosso, dbo.VendaProduto.VenPro_Seq, dbo.produtos.Pro_descricao, dbo.VendaProduto.Ven_CodigoPre, dbo.VendaProduto.CodAmbiente, dbo.VendaAmbiente.VenAmb_Descricao, 
                         dbo.VendaProduto.CodAcabamento, dbo.produtos.Pro_tp_peca, dbo.produtos.Pro_tp_produto, dbo.VendaProduto.VenPro_Seq, dbo.VendaProduto.VenPro_SeqItem, dbo.produtos.Pro_descricao_for, dbo.produtos.Pro_Codbase, 
                         dbo.produtos.Pro_CodEspecial, dbo.VendaProduto.VenPro_Vlimposto, dbo.VendaProduto.VenPro_Vldesconto, dbo.VendaProduto.VenPro_PreProduto, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, 
                         dbo.ProdutosFornecedores.ProdFor_DescricaoProduto, dbo.ProdutosFornecedores.ProdFor_Padrao
ORDER BY dbo.VendaProduto.VenPro_Seq, dbo.VendaProduto.VenPro_SeqItem

-- [Qryordem_total : TADOQuery]
SELECT        dbo.ProdutosFornecedores.ProdFor_CodigoProduto AS Pro_Codbase, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto AS Pro_descricao_for, dbo.produtos.Pro_codnosso, dbo.produtos.Pro_descricao, 
                         dbo.Acabamento.DescAcabamento, dbo.ordem_compra_det.Ocd_acabamento, SUM(dbo.ordem_compra_det.Ocd_quantidade_solicit) AS quantidade, max(dbo.ordem_compra_det.Ocd_vl_compra) AS vl_compra, 
                         sum(dbo.ordem_compra_det.Ocd_vl_item) AS vl_item, dbo.ordem_compra_det.Ocp_codigo
FROM            dbo.ordem_compra_det WITH (NOLOCK) INNER JOIN
                         dbo.produtos WITH (NOLOCK) ON dbo.ordem_compra_det.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                         dbo.Acabamento WITH (NOLOCK) ON dbo.ordem_compra_det.Ocd_acabamento = dbo.Acabamento.CodAcabamento INNER JOIN
                         dbo.ProdutosFornecedores WITH (NOLOCK) ON dbo.produtos.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso
GROUP BY dbo.produtos.Pro_Codbase, dbo.produtos.Pro_descricao_for, dbo.produtos.Pro_codnosso, dbo.produtos.Pro_descricao, dbo.Acabamento.DescAcabamento, dbo.ordem_compra_det.Ocp_codigo, 
                         dbo.ordem_compra_det.Ocd_acabamento, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto,ProdutosFornecedores.ProdFor_Padrao

HAVING (((ordem_compra_det.Ocp_codigo)=:codigo))
AND (dbo.ProdutosFornecedores.ProdFor_Padrao = 1)

-- [Qryordem_det : TADOQuery]
SELECT * from ordem_compra_det WITH (NOLOCK) where Ocp_codigo=:codigo and pro_codnosso=:produto and ocd_acabamento=:acabamento

-- [QryOrc_Mat_Amb : TADOQuery]
SELECT produtos.Pro_tp_produto, orcamento_materiais_det.orc_codigo_pre, orcamento_materiais_det.Pro_codnosso, orcamento_materiais_det.oma_seq_item, orcamento_materiais_det.oma_seq, orcamento_materiais_det.oma_produto, orcamento_materiais_det.oma_ambiente, Sum(orcamento_materiais_det.oma_quantidade) AS tl_quantidade, orcamento_materiais_det.oma_vl_unitario AS vl_unitario, Sum(orcamento_materiais_det.oma_vl_item) AS tl_vl_item, orcamento_materiais_det.oma_acabamento
FROM produtos WITH (NOLOCK) INNER JOIN orcamento_materiais_det WITH (NOLOCK) ON produtos.Pro_codnosso = orcamento_materiais_det.Pro_codnosso
GROUP BY produtos.Pro_tp_produto, orcamento_materiais_det.orc_codigo_pre, orcamento_materiais_det.Pro_codnosso, orcamento_materiais_det.oma_seq_item, orcamento_materiais_det.oma_seq, orcamento_materiais_det.oma_produto, orcamento_materiais_det.oma_ambiente, orcamento_materiais_det.oma_acabamento,orcamento_materiais_det.oma_vl_unitario
HAVING (((orcamento_materiais_det.orc_codigo_pre)=:codigo) AND ((orcamento_materiais_det.oma_seq_item)=:item) AND ((orcamento_materiais_det.oma_seq)=:sequencia))
ORDER BY orcamento_materiais_det.oma_seq, orcamento_materiais_det.oma_seq_item

-- [Qryluminaria_com_amb : TADOQuery]
SELECT orcamento_luminaria_det.Pro_codnosso, orcamento_luminaria_det.old_seq, orcamento_luminaria_det.old_produto, orcamento_luminaria_det.orc_codigo_pre, orcamento_luminaria_det.old_ambiente, VendaAmbiente.VenAmb_Descricao, orcamento_luminaria_det.old_acabamento, Sum(orcamento_luminaria_det.old_quantidade) AS tl_quantidade, Max(orcamento_luminaria_det.old_vl_unitario) AS vl_unitario, Sum(orcamento_luminaria_det.old_vl_item) AS tl_vl_item, produtos.Pro_tp_peca, produtos.Pro_tp_produto, orcamento_luminaria_det.old_seq_item
FROM (orcamento_luminaria_det WITH (NOLOCK) INNER JOIN VendaAmbiente WITH (NOLOCK) ON orcamento_luminaria_det.old_ambiente = VendaAmbiente.CodAmbiente) INNER JOIN produtos WITH (NOLOCK) ON orcamento_luminaria_det.Pro_codnosso = produtos.Pro_codnosso
WHERE orcamento_luminaria_det.orc_codigo_pre=:codigo and orcamento_luminaria_det.old_seq =:seq and orcamento_luminaria_det.old_seq_item=:item
and VendaAmbiente.VenAmb_TpDoc = 'PRO' and VendaAmbiente.VenAmb_NDocPre = orcamento_luminaria_det.orc_codigo_pre
GROUP BY orcamento_luminaria_det.Pro_codnosso, orcamento_luminaria_det.old_seq, orcamento_luminaria_det.old_produto, orcamento_luminaria_det.orc_codigo_pre, orcamento_luminaria_det.old_ambiente, VendaAmbiente.VenAmb_Descricao, orcamento_luminaria_det.old_acabamento, produtos.Pro_tp_peca, produtos.Pro_tp_produto, orcamento_luminaria_det.old_seq, orcamento_luminaria_det.old_seq_item
ORDER BY  orcamento_luminaria_det.old_seq, orcamento_luminaria_det.old_seq_item;

-- [Qryorc_mat_amb_Slum : TADOQuery]
SELECT produtos.Pro_tp_produto, orcamento_materiais_det.orc_codigo_pre, orcamento_materiais_det.Pro_codnosso, orcamento_materiais_det.oma_seq_item, orcamento_materiais_det.oma_seq, orcamento_materiais_det.oma_produto, orcamento_materiais_det.oma_ambiente, Sum(orcamento_materiais_det.oma_quantidade) AS tl_quantidade, Sum(orcamento_materiais_det.oma_vl_unitario) AS vl_unitario, Sum(orcamento_materiais_det.oma_vl_item) AS tl_vl_item, orcamento_materiais_det.oma_acabamento, Ambiente.DescAmbiente
FROM (produtos WITH (NOLOCK) INNER JOIN orcamento_materiais_det WITH (NOLOCK) ON produtos.Pro_codnosso = orcamento_materiais_det.Pro_codnosso) INNER JOIN Ambiente WITH (NOLOCK) ON orcamento_materiais_det.oma_ambiente = Ambiente.CodAmbiente
GROUP BY produtos.Pro_tp_produto, orcamento_materiais_det.orc_codigo_pre, orcamento_materiais_det.Pro_codnosso, orcamento_materiais_det.oma_seq_item, orcamento_materiais_det.oma_seq, orcamento_materiais_det.oma_produto, orcamento_materiais_det.oma_ambiente, orcamento_materiais_det.oma_acabamento, Ambiente.DescAmbiente
having  orcamento_materiais_det.orc_codigo_pre=:codigo and   orcamento_materiais_det.oma_seq=:sequencia and  orcamento_materiais_det.oma_seq_item=:item  order by  orcamento_materiais_det.oma_seq,  orcamento_materiais_det.oma_seq_item

-- [QryOrc_Mat_seq : TADOQuery]
SELECT produtos.Pro_tp_produto, orcamento_materiais_det.orc_codigo_pre, orcamento_materiais_det.Pro_codnosso, orcamento_materiais_det.oma_seq_item, orcamento_materiais_det.oma_seq, orcamento_materiais_det.oma_produto, orcamento_materiais_det.oma_ambiente, Sum(orcamento_materiais_det.oma_quantidade) AS tl_quantidade, Sum(orcamento_materiais_det.oma_vl_unitario) AS vl_unitario, Sum(orcamento_materiais_det.oma_vl_item) AS tl_vl_item, orcamento_materiais_det.oma_acabamento, Orcamento_luminaria_det.old_item
FROM (produtos WITH (NOLOCK) INNER JOIN orcamento_materiais_det WITH (NOLOCK) ON produtos.Pro_codnosso = orcamento_materiais_det.Pro_codnosso) LEFT JOIN Orcamento_luminaria_det WITH (NOLOCK) ON (orcamento_materiais_det.oma_seq_item = Orcamento_luminaria_det.old_seq_item) AND (orcamento_materiais_det.oma_seq = Orcamento_luminaria_det.old_seq) AND (orcamento_materiais_det.orc_codigo_pre = Orcamento_luminaria_det.orc_codigo_pre)
GROUP BY produtos.Pro_tp_produto, orcamento_materiais_det.orc_codigo_pre, orcamento_materiais_det.Pro_codnosso, orcamento_materiais_det.oma_seq_item, orcamento_materiais_det.oma_seq, orcamento_materiais_det.oma_produto, orcamento_materiais_det.oma_ambiente, orcamento_materiais_det.oma_acabamento, Orcamento_luminaria_det.old_item
HAVING (((orcamento_materiais_det.orc_codigo_pre)=:codigo) AND ((orcamento_materiais_det.oma_seq_item)=:item) AND ((orcamento_materiais_det.oma_seq)=:sequencia) AND ((Orcamento_luminaria_det.old_item) Is Null))
ORDER BY orcamento_materiais_det.oma_seq, orcamento_materiais_det.oma_seq_item

-- [Qryped_mat_amb_Slum : TADOQuery]
SELECT produtos.Pro_tp_produto, pedido_materiais_det.ped_codigo_pre, pedido_materiais_det.Pro_codnosso, pedido_materiais_det.pma_seq_item, pedido_materiais_det.pma_seq, pedido_materiais_det.pma_produto, pedido_materiais_det.pma_ambiente, Sum(pedido_materiais_det.pma_quantidade) AS tl_quantidade, Sum(pedido_materiais_det.pma_vl_unitario) AS vl_unitario, Sum(pedido_materiais_det.pma_vl_item) AS tl_vl_item, pedido_materiais_det.pma_acabamento, Ambiente.DescAmbiente
FROM (produtos WITH (NOLOCK) INNER JOIN pedido_materiais_det WITH (NOLOCK) ON produtos.Pro_codnosso = pedido_materiais_det.Pro_codnosso) INNER JOIN Ambiente WITH (NOLOCK) ON pedido_materiais_det.pma_ambiente = Ambiente.CodAmbiente
GROUP BY produtos.Pro_tp_produto, pedido_materiais_det.ped_codigo_pre, pedido_materiais_det.Pro_codnosso, pedido_materiais_det.pma_seq_item, pedido_materiais_det.pma_seq, pedido_materiais_det.pma_produto, pedido_materiais_det.pma_ambiente, pedido_materiais_det.pma_acabamento, Ambiente.DescAmbiente
having    pedido_materiais_det.ped_codigo_pre=:codigo and   pedido_materiais_det.pma_seq=:sequencia  and pedido_materiais_det.pma_seq_item=:item order by  pedido_materiais_det.pma_seq,  pedido_materiais_det.pma_seq_item

-- [Qryped_Mat_Amb : TADOQuery]
SELECT produtos.Pro_tp_produto, pedido_materiais_det.ped_codigo_pre, pedido_materiais_det.Pro_codnosso, pedido_materiais_det.pma_seq_item, pedido_materiais_det.pma_seq, pedido_materiais_det.pma_produto, pedido_materiais_det.pma_ambiente, Sum(pedido_materiais_det.pma_quantidade) AS tl_quantidade, pedido_materiais_det.pma_vl_unitario AS vl_unitario, Sum(pedido_materiais_det.pma_vl_item) AS tl_vl_item, pedido_materiais_det.pma_acabamento
FROM produtos WITH (NOLOCK) INNER JOIN pedido_materiais_det WITH (NOLOCK) ON produtos.Pro_codnosso = pedido_materiais_det.Pro_codnosso
GROUP BY produtos.Pro_tp_produto, pedido_materiais_det.ped_codigo_pre, pedido_materiais_det.Pro_codnosso, pedido_materiais_det.pma_seq_item, pedido_materiais_det.pma_seq, pedido_materiais_det.pma_produto, pedido_materiais_det.pma_ambiente, pedido_materiais_det.pma_acabamento,pedido_materiais_det.pma_vl_unitario
HAVING (((pedido_materiais_det.ped_codigo_pre)=:codigo) AND ((pedido_materiais_det.pma_seq_item)=:item) AND ((pedido_materiais_det.pma_seq)=:sequencia))
ORDER BY pedido_materiais_det.pma_seq, pedido_materiais_det.pma_seq_item

-- [QryPed_Mat_seq : TADOQuery]
SELECT produtos.Pro_tp_produto, pedido_materiais_det.ped_codigo_pre, pedido_materiais_det.Pro_codnosso, pedido_materiais_det.pma_seq_item, pedido_materiais_det.pma_seq, pedido_materiais_det.pma_produto, pedido_materiais_det.pma_ambiente, Sum(pedido_materiais_det.pma_quantidade) AS tl_quantidade, Sum(pedido_materiais_det.pma_vl_unitario) AS vl_unitario, Sum(pedido_materiais_det.pma_vl_item) AS tl_vl_item, pedido_materiais_det.pma_acabamento, pedido_luminaria_det.pld_item
FROM (produtos WITH (NOLOCK) INNER JOIN pedido_materiais_det WITH (NOLOCK) ON produtos.Pro_codnosso = pedido_materiais_det.Pro_codnosso) LEFT JOIN pedido_luminaria_det WITH (NOLOCK) ON (pedido_materiais_det.pma_seq_item = pedido_luminaria_det.pld_seq_item) AND (pedido_materiais_det.pma_seq = pedido_luminaria_det.pld_seq) AND (pedido_materiais_det.ped_codigo_pre = pedido_luminaria_det.ped_codigo_pre)
GROUP BY produtos.Pro_tp_produto, pedido_materiais_det.ped_codigo_pre, pedido_materiais_det.Pro_codnosso, pedido_materiais_det.pma_seq_item, pedido_materiais_det.pma_seq, pedido_materiais_det.pma_produto, pedido_materiais_det.pma_ambiente, pedido_materiais_det.pma_acabamento, pedido_luminaria_det.pld_item
HAVING (((pedido_materiais_det.ped_codigo_pre)=:codigo) AND ((pedido_materiais_det.pma_seq_item)=:item) AND ((pedido_materiais_det.pma_seq)=:sequencia) AND ((pedido_luminaria_det.pld_item) Is Null))
ORDER BY pedido_materiais_det.pma_seq, pedido_materiais_det.pma_seq_item

