-- [QrypromocaoProd : TADOQuery]
SELECT        dbo.PromocaoProdutos.*, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto, dbo.fornecedor.For_Nome, dbo.produtos.Pro_descricao, dbo.produtos.Pro_CodEspecial, 
                         dbo.GrupoProduto.GrupoProduto_Descricao, produtos.Pro_tp_peca, produtos.Pro_unidade
FROM            dbo.PromocaoProdutos INNER JOIN
                         dbo.produtos ON dbo.PromocaoProdutos.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                         dbo.GrupoProduto ON dbo.produtos.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo INNER JOIN
                         dbo.ProdutosFornecedores ON dbo.produtos.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso INNER JOIN
                         dbo.fornecedor ON dbo.ProdutosFornecedores.For_codigo = dbo.fornecedor.For_codigo
where  prom_codigo =:pprom_codigo and ProdutosFornecedores.ProdFor_Padrao =1

