select * from promocao where prom_codigo =:pprom_codigo

-- [QryPromocaoEst : TADOQuery]
SELECT        dbo.PromocaoEstoque.*, dbo.Estoque_produto.Epr_estoque, dbo.EstoqueTipo.EstTp_Descricao
FROM            dbo.PromocaoEstoque INNER JOIN
                         dbo.Estoque_produto ON dbo.PromocaoEstoque.EstTp_Codigo = dbo.Estoque_produto.EstTp_Codigo AND dbo.PromocaoEstoque.Pro_codnosso = dbo.Estoque_produto.Epr_Codnosso AND 
                         dbo.PromocaoEstoque.CodAcabamento = dbo.Estoque_produto.Epr_Acabamento INNER JOIN
                         dbo.EstoqueTipo ON dbo.PromocaoEstoque.EstTp_Codigo = dbo.EstoqueTipo.EstTp_Codigo
where  prom_codigo =:pprom_codigo

-- [QryEstoque : TADOQuery]
SELECT        dbo.EstoqueTipo.EstTp_Descricao, dbo.Estoque_produto.Epr_estoque, EstoqueTipo.EstTp_Codigo

FROM            dbo.Estoque_produto INNER JOIN
                         dbo.EstoqueTipo ON dbo.Estoque_produto.EstTp_Codigo = dbo.EstoqueTipo.EstTp_Codigo
where Estoque_produto.Epr_Codnosso=:pEpr_Codnosso  and Estoque_produto.Epr_Acabamento =:pEpr_Acabamento


