SELECT        dbo.contas_apagar.Ctp_codigo AS CodigoConta, dbo.contas_apagar_det.ctp_codigo_det AS CodigoContaParcela, dbo.contas_apagar.Ctp_nome AS nome, 
                         dbo.contas_apagar.Ctp_cod_documento AS codigodoc, dbo.contas_apagar.Ctp_historico AS historico, dbo.Plano_Contas.Pco_descricao AS PlanoConta, 
                         dbo.Tipo_documento.Tpd_descricao AS TipoConta, dbo.contas_apagar_det.Ctp_parcela AS Parcela, dbo.contas_apagar_det.Ctp_dt_vencimento AS DataVencimento, 
                         dbo.contas_apagar_det.Ctp_valor_vencimento AS Valor, dbo.contas_apagar_det.Ctp_CodigoBarra AS codigobarra, 
                         dbo.forma_pagamento_fin.Fpf_descricao AS formapagamento
, contas_apagar.Pco_codigo, contas_apagar.tpd_codigo, contas_apagar.cdc_codigo
FROM            dbo.contas_apagar INNER JOIN
                         dbo.contas_apagar_det ON dbo.contas_apagar.Ctp_codigo = dbo.contas_apagar_det.Ctp_codigo LEFT OUTER JOIN
                         dbo.forma_pagamento_fin ON dbo.contas_apagar.Ctp_forma_pag = dbo.forma_pagamento_fin.Fpf_codigo LEFT OUTER JOIN
                         dbo.Tipo_documento ON dbo.contas_apagar.Tpd_codigo = dbo.Tipo_documento.Tpd_codigo LEFT OUTER JOIN
                         dbo.Plano_Contas ON dbo.contas_apagar.Pco_codigo = dbo.Plano_Contas.Pco_codigo
WHERE        (dbo.contas_apagar_det.Ctp_situacao = 'N')

