-- [Qrypedido : TADOQuery]
SELECT   pedido.ped_codigo_pre , dbo.pedido.ped_codigo, dbo.Clientes.Cli_Nome, dbo.Funcionario.Fun_Nome, dbo.pedido.ped_Descricao, dbo.pedido.ped_desc_por_luminaria, 
                      dbo.pedido.ped_desc_por_materiais, dbo.pedido.ped_desc_por_servico, dbo.Obras.Obr_Descricao, pedido.Ped_TipoDesc
FROM         dbo.pedido LEFT OUTER JOIN
                      dbo.Obras ON dbo.pedido.Obr_Codigo = dbo.Obras.Obr_Codigo LEFT OUTER JOIN
                      dbo.Clientes ON dbo.pedido.cli_codigo = dbo.Clientes.Cli_Codigo LEFT OUTER JOIN
                      dbo.Funcionario ON dbo.pedido.ped_arquiteta = dbo.Funcionario.Fun_CPF
WHERE     (dbo.pedido.ped_codigo =:codigo)

-- [Qrydesagio : TADOQuery]
SELECT     SUM(dbo.Ent_devolucao_luminaria_det.eld_vl_item) AS valor, dbo.produtos.GrupoProduto_codigo, dbo.GrupoProduto.GrupoProduto_Descricao,
 (SELECT     ParDes_porcentagem
                            FROM          dbo.ParamentrosDesagio
                            WHERE      (ParDes_data >= GETDATE()) AND (GrupoProduto_Codigo = dbo.produtos.GrupoProduto_codigo)) AS porcentagem

FROM         dbo.Ent_devolucao INNER JOIN
                      dbo.Ent_devolucao_luminaria_det ON dbo.Ent_devolucao.edv_codigo_pre = dbo.Ent_devolucao_luminaria_det.edv_codigo_pre INNER JOIN
                      dbo.produtos ON dbo.Ent_devolucao_luminaria_det.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                      dbo.GrupoProduto ON dbo.produtos.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo
WHERE     (dbo.Ent_devolucao.ped_codigo =:codigo1) AND (dbo.Ent_devolucao.edv_status = 'A') and Ent_devolucao.edv_Desagio is null
GROUP BY dbo.produtos.GrupoProduto_codigo, dbo.GrupoProduto.GrupoProduto_Descricao
union all
SELECT     SUM(dbo.Ent_devolucao_materiais_det.ema_vl_item) AS valor, dbo.produtos.GrupoProduto_codigo, dbo.GrupoProduto.GrupoProduto_Descricao,
 (SELECT     ParDes_porcentagem
                            FROM          dbo.ParamentrosDesagio
                            WHERE      (ParDes_data >= GETDATE()) AND (GrupoProduto_Codigo = dbo.produtos.GrupoProduto_codigo)) AS porcentagem

FROM         dbo.Ent_devolucao INNER JOIN
                      dbo.Ent_devolucao_materiais_det ON dbo.Ent_devolucao.edv_codigo_pre = dbo.Ent_devolucao_materiais_det.edv_codigo_pre INNER JOIN
                      dbo.produtos ON dbo.Ent_devolucao_materiais_det.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                      dbo.GrupoProduto ON dbo.produtos.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo
WHERE     (dbo.Ent_devolucao.ped_codigo =:codigo2) AND (dbo.Ent_devolucao.edv_status = 'A') and Ent_devolucao.edv_Desagio is null
GROUP BY dbo.produtos.GrupoProduto_codigo, dbo.GrupoProduto.GrupoProduto_Descricao

-- [QryDesagioTab : TADOQuery]
SELECT     SUM(Ent_devolucaoDesagio.EdvDes_valorComDesc) AS valor, dbo.Ent_devolucaoDesagio.EdvDes_porcentagem, dbo.Ent_devolucaoDesagio.GrupoProduto_Codigo
FROM         dbo.Ent_devolucao INNER JOIN
                      dbo.Ent_devolucaoDesagio ON dbo.Ent_devolucao.edv_codigo = dbo.Ent_devolucaoDesagio.edv_codigo
WHERE     (dbo.Ent_devolucaoDesagio.EdvDes_valor > 0) and Ent_devolucao.ped_codigo =:pcodigo
GROUP BY dbo.Ent_devolucaoDesagio.EdvDes_porcentagem, dbo.Ent_devolucaoDesagio.GrupoProduto_Codigo

union all
SELECT     SUM(dbo.DevolucaoDesagio.DevDes_valorComDesc) AS valor, dbo.DevolucaoDesagio.DevDes_porcentagem AS EdvDes_porcentagem, 
                      dbo.DevolucaoDesagio.GrupoProduto_Codigo
FROM         dbo.Devolucao INNER JOIN
                      dbo.DevolucaoDesagio ON dbo.Devolucao.Dev_CodigoPre = dbo.DevolucaoDesagio.Dev_codigopre INNER JOIN
                      dbo.Venda ON dbo.Devolucao.ven_codigopre = dbo.Venda.Ven_CodigoPre
WHERE     (dbo.Devolucao.Dev_situacao = 1) AND (dbo.Venda.Ven_Situacao = 'A') AND (dbo.Venda.Ven_Tipo = 'P') AND (dbo.Venda.ParSV_serie = '1') AND 
                      (dbo.Devolucao.Dev_migrado IS NULL) and venda.ven_codigo =:pven_codigo
GROUP BY dbo.DevolucaoDesagio.GrupoProduto_Codigo, dbo.DevolucaoDesagio.DevDes_porcentagem

