SELECT     dbo.Clientes.Cli_Fcomercial, dbo.Clientes.Cli_Fresidencial, dbo.Clientes.Cli_fax, dbo.Clientes.Cli_celular, dbo.Indicacoes.Ind_comercial, 
                      dbo.Indicacoes.Ind_residencial, dbo.Indicacoes.Ind_fax, dbo.Indicacoes.Ind_celular, dbo.pedido.ped_codigo, dbo.pedido.ped_codigo_pre, 
                      dbo.Clientes.Cli_Nome, dbo.Funcionario.Fun_Nome, dbo.Indicacoes.Ind_Nome, dbo.pedido.ped_dt_fechamento, dbo.pedido.ped_Descricao, 
                      dbo.pedido.ped_Endereco, dbo.pedido.ped_numero, dbo.pedido.ped_complemento, dbo.pedido.ped_Bairro, dbo.pedido.ped_Cidade, 
                      dbo.pedido.ped_UF, dbo.pedido.ped_CEP
FROM         dbo.pedido LEFT OUTER JOIN
