SELECT     dbo.contas_apagar_det.usr_dt_hr_criacao AS usr_dt_hr_criacao, dbo.contas_apagar.Tpd_codigo AS Tpd_codigo, dbo.Modo.Mdo_nome AS mdo_nome, 
                      dbo.Tipo_documento.Tpd_descricao AS Tpd_descricao, dbo.contas_apagar_det.*, dbo.contas_apagar.Ctp_cod_documento AS Ctp_cod_documento, 
                      dbo.contas_apagar.Ctp_historico AS Ctp_historico, dbo.contas_apagar.Ctp_vinculo AS Ctp_vinculo, 
                      dbo.contas_apagar.Ctp_codigo_vinculo AS Ctp_codigo_vinculo, dbo.contas_apagar.Ctp_nome AS Ctp_nome
, TipoContaFinanceira.Tcf_descricao
,
(SELECT COUNT(Ctp_codigo) AS Expr1 FROM contas_apagar_det AS contar
 WHERE (contar.Ctp_codigo = dbo.contas_apagar.Ctp_codigo)) AS TotalParcela,
 Contas_apagar_det.Ctp_parcela as parcela
 


FROM         dbo.contas_apagar_det INNER JOIN
                      dbo.contas_apagar INNER JOIN
                      dbo.Tipo_documento ON dbo.contas_apagar.Tpd_codigo = dbo.Tipo_documento.Tpd_codigo ON 
                      dbo.contas_apagar_det.Ctp_codigo = dbo.contas_apagar.Ctp_codigo LEFT OUTER JOIN
                      dbo.Modo ON dbo.contas_apagar_det.Mdo_codigo = dbo.Modo.Mdo_codigo
INNER JOIN dbo.TipoContaFinanceira ON dbo.contas_apagar.Tcf_codigo = dbo.TipoContaFinanceira.Tcf_codigo

