   FORM: FrmRel_Custo_Venda   FrmRel_Custo_Venda
   ============================================================ */

-- [QryPRODUTO : TADOQuery]
SELECT     dbo.VendaProduto.Pro_codnosso, dbo.VendaProduto.CodAcabamento, SUM(dbo.VendaProduto.VenPro_Quantidade) AS VenPro_Quantidade, 
                      MAX(dbo.Preco_Produto.Pre_Custo) AS Pre_Custo, SUM(dbo.VendaProduto.VenPro_Quantidade * dbo.Preco_Produto.Pre_Custo) AS VALOR_ITEM, 
                      dbo.produtos.Pro_Codbase, dbo.produtos.Pro_tp_peca, dbo.produtos.Pro_descricao, dbo.produtos.Pro_descricao_for, dbo.GrupoProduto.GrupoProduto_Descricao, 
                      dbo.produtos.Pro_CodEspecial, dbo.Venda.Ven_codigo, dbo.Venda.ParSV_serie, dbo.Clientes.Cli_Nome, dbo.Venda.Ven_DataEmissao,

(SELECT TOP (1) Pre_VENDA  FROM dbo.Preco_Produto
  WHERE   (dbo.VendaProduto.CodAcabamento = Pre_Acabamento) AND (dbo.VendaProduto.Pro_codnosso = Pre_Codnosso) and Pre_Ativo = 'S') AS PRE_VENDA, SUM(dbo.VendaProduto.VenPro_Quantidade) *
  (SELECT TOP (1) Pre_VENDA FROM dbo.Preco_Produto AS Preco_Produto_2
  WHERE   (dbo.VendaProduto.CodAcabamento = Pre_Acabamento) AND (dbo.VendaProduto.Pro_codnosso = Pre_Codnosso) and Pre_Ativo = 'S') AS VALOR_ITEMVENDA

FROM         dbo.Venda INNER JOIN
                      dbo.VendaProduto ON dbo.Venda.Ven_CodigoPre = dbo.VendaProduto.Ven_CodigoPre INNER JOIN
                      dbo.produtos ON dbo.VendaProduto.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                      dbo.Preco_Produto ON dbo.produtos.Pro_codnosso = dbo.Preco_Produto.Pre_Codnosso AND 
                      dbo.VendaProduto.CodAcabamento = dbo.Preco_Produto.Pre_Acabamento AND dbo.VendaProduto.pld_codindice = dbo.Preco_Produto.Pre_Codindice INNER JOIN
                      dbo.GrupoProduto ON dbo.produtos.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo INNER JOIN
                      dbo.Clientes ON dbo.Venda.Ven_CodVinculo = dbo.Clientes.Cli_Codigo
WHERE venda.ven_codigopre =:pven_codigopre and venda.ven_tipo =:pven_tipo



GROUP BY dbo.GrupoProduto.GrupoProduto_ordem, dbo.GrupoProduto.GrupoProduto_Descricao, dbo.produtos.Pro_Codbase, dbo.produtos.Pro_tp_peca, 
                      dbo.produtos.Pro_descricao, dbo.produtos.Pro_descricao_for, dbo.produtos.Pro_CodEspecial, dbo.VendaProduto.Pro_codnosso, dbo.VendaProduto.CodAcabamento, 
                      dbo.Venda.Ven_codigo, dbo.Venda.ParSV_serie, dbo.Clientes.Cli_Nome, dbo.Venda.Ven_DataEmissao
order by GrupoProduto.GrupoProduto_ordem,GrupoProduto.GrupoProduto_Descricao


