SELECT     dbo.Transferencia.Tra_codigo, dbo.Transferencia.Tra_tipo, dbo.Transferencia.Tra_situacao, dbo.Transferencia.Tra_operacao_origem, 
                      dbo.Transferencia.Tra_valor_origem, dbo.Transferencia.Tra_data_origem, dbo.Transferencia.Tra_historico_origem, 
                      dbo.Transferencia.Tra_realizado_origem, Contas_Bancarias_1.Cba_numero AS cba_numero_destino, 
                      Bancos_Caixas_1.Bcx_Nome AS bcx_nome_destino, Contas_Bancarias_1.Cba_codigo AS cba_destino, 
                      Contas_Bancarias_1.Bcx_codigo AS bcx_destino, Contas_Bancarias_2.Cba_codigo AS cba_origem, Contas_Bancarias_2.Bcx_codigo AS bcx_origem, 
                      Contas_Bancarias_2.Cba_numero AS cba_numero_origem, Bancos_Caixas_2.Bcx_Nome AS bcx_nome_origem
FROM         dbo.Bancos_Caixas Bancos_Caixas_1 INNER JOIN
                      dbo.Contas_Bancarias Contas_Bancarias_1 ON Bancos_Caixas_1.Bcx_codigo = Contas_Bancarias_1.Bcx_codigo INNER JOIN
                      dbo.Contas_Bancarias Contas_Bancarias_2 INNER JOIN
                      dbo.Bancos_Caixas Bancos_Caixas_2 ON Contas_Bancarias_2.Bcx_codigo = Bancos_Caixas_2.Bcx_codigo AND 
                      Contas_Bancarias_2.Bcx_codigo = Bancos_Caixas_2.Bcx_codigo INNER JOIN
                      dbo.Transferencia ON Contas_Bancarias_2.Bcx_codigo = dbo.Transferencia.Tra_Bcx_origem AND 
                      Contas_Bancarias_2.Cba_codigo = dbo.Transferencia.Tra_Cba_origem ON Contas_Bancarias_1.Bcx_codigo = dbo.Transferencia.Tra_Bcx_destino AND
                       Contas_Bancarias_1.Cba_codigo = dbo.Transferencia.Tra_Cba_destino


