-- [QryEstoque : TADOQuery]
SELECT     dbo.produtos.Pro_codnosso, dbo.produtos.For_codigo, dbo.produtos.Pro_tp_peca, dbo.produtos.Pro_tp_produto, dbo.produtos.Pro_descricao, 
                      dbo.Estoque_produto.Epr_Acabamento, dbo.Estoque_produto.Epr_estoque, MAX(dbo.Preco_Produto.Pre_est_min) AS Pre_est_min, Preco_Produto.Pre_Venda, produtos.Pro_Codbase, produtos.Pro_CodEspecial
,produtos.Pro_descricao_for , fabrica.fab_descricao ,Preco_Produto.Pre_CodBarra

FROM         dbo.produtos INNER JOIN
                      dbo.Estoque_produto ON dbo.produtos.Pro_codnosso = dbo.Estoque_produto.Epr_Codnosso LEFT OUTER JOIN
                      dbo.Preco_Produto ON dbo.Estoque_produto.Epr_Codnosso = dbo.Preco_Produto.Pre_Codnosso AND 
                      dbo.Estoque_produto.Epr_Acabamento = dbo.Preco_Produto.Pre_Acabamento

LEFT OUTER JOIN  dbo.Fabrica ON dbo.produtos.Fab_Codigo = dbo.Fabrica.Fab_Codigo

where  produtos.For_codigo=:codigo  and Estoque_produto.Epr_estoque  <> 0  
GROUP BY dbo.produtos.Pro_codnosso, dbo.produtos.For_codigo, dbo.produtos.Pro_tp_peca, dbo.produtos.Pro_tp_produto, dbo.produtos.Pro_descricao, 
                      dbo.Estoque_produto.Epr_Acabamento, dbo.Estoque_produto.Epr_estoque,Preco_Produto.Pre_Venda,produtos.Pro_descricao_for,produtos.Pro_Codbase, produtos.Pro_CodEspecial 
,produtos.Pro_descricao_for , fabrica.fab_descricao ,Preco_Produto.Pre_CodBarra

ORDER BY produtos.Pro_codnosso, Estoque_produto.Epr_Acabamento

