-- [QryRelacionado : TADOQuery]
SELECT     dbo.produtos.Pro_codnosso, dbo.produtos.Pro_descricao, dbo.produtos.Pro_CodEspecial, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto, dbo.Preco_Produto.Pre_Tabela, dbo.Preco_Produto.Pre_Custo, 
                  dbo.Preco_Produto.Pre_Venda, dbo.Preco_Produto.Pre_VlNFor, dbo.Preco_Produto.Pre_Acabamento, dbo.Preco_Produto.Pre_Codindice, Preco_Produto.Pre_compra
FROM        dbo.ProdutosRelacionadosDet INNER JOIN
                  dbo.produtos ON dbo.ProdutosRelacionadosDet.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                  dbo.Preco_Produto ON dbo.produtos.Pro_codnosso = dbo.Preco_Produto.Pre_Codnosso INNER JOIN
                  dbo.ProdutosRelacionadosCadProdutos INNER JOIN
                  dbo.ProdutosRelacionados ON dbo.ProdutosRelacionadosCadProdutos.ProdRel_codigo = dbo.ProdutosRelacionados.ProdRel_codigo ON dbo.ProdutosRelacionadosDet.ProdRel_codigo = dbo.ProdutosRelacionados.ProdRel_codigo INNER JOIN
                  dbo.ProdutosFornecedores ON dbo.produtos.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso
WHERE     (dbo.ProdutosFornecedores.ProdFor_Padrao = 1) AND (dbo.ProdutosRelacionadosCadProdutos.ProdRelCadProd_padrao = 1) AND (dbo.ProdutosRelacionadosCadProdutos.ProdRelCadProd_situacao = 1) AND (dbo.Preco_Produto.Pre_Ativo = 'S')
and ProdutosRelacionadosCadProdutos.Pro_codnosso =:pPro_codnosso


