                         dbo.nota_entrada_det.Ned_quantidade_solicit, dbo.nota_entrada_det.Ned_recebido, dbo.produtos.Pro_tp_produto, dbo.produtos.Pro_tp_peca, dbo.Nota_entrada.Nen_codigo, dbo.Nota_entrada.Nen_numero_nota, 
                         dbo.Nota_entrada.Nen_dt_nota, dbo.Nota_entrada.Nen_dt_emissao, dbo.Nota_entrada.Nen_obs, dbo.nota_entrada_det.Ned_item_ordem, dbo.nota_entrada_det.Ned_cod_ordem, 
                         dbo.ProdutosFornecedores.ProdFor_DescricaoProduto AS Pro_descricao_for, dbo.ProdutosFornecedores.ProdFor_CodigoProduto AS Pro_Codbase
FROM            dbo.ProdutosFornecedores INNER JOIN
