                         dbo.Nota_entrada INNER JOIN
                         dbo.nota_entrada_det ON dbo.Nota_entrada.Nen_codigo = dbo.nota_entrada_det.Nen_codigo INNER JOIN
                         dbo.produtos ON dbo.nota_entrada_det.Pro_codnosso = dbo.produtos.Pro_codnosso ON dbo.ProdutosFornecedores.Pro_codnosso = dbo.produtos.Pro_codnosso
