-- [Qryorcamento : TADOQuery]
SELECT     Venda.Ven_CodigoPre,


dbo.Funcionario.Fun_Nome, dbo.Clientes.Cli_Nome, dbo.Clientes.Cli_Fcomercial, dbo.Clientes.Cli_Fresidencial, dbo.Venda.Ven_DataEmissao, dbo.Venda.Ven_codigo, 
                      dbo.Venda.Ven_Total, dbo.Venda.Ven_DataFechaVenda, dbo.Venda.usr_dt_hr_criacao, dbo.VendaAtendente.VenAten_Porcentagem, 
                      ROUND(dbo.VendaIndicacao.VenInd_Porcentagem / 100 * ROUND(dbo.VendaAtendente.VenAten_Porcentagem / 100 * dbo.Venda.Ven_Total, 2), 2) AS total, 
                      dbo.VendaIndicacao.VenInd_TpDoc, dbo.Indicacoes.Ind_Nome, dbo.VendaIndicacao.Ind_Codigo, dbo.Motivo_devolucao.Mod_descricao
,Venda.Ven_situacao, Venda.Ven_DataValidade
FROM         dbo.VendaIndicacao INNER JOIN
                      dbo.Venda INNER JOIN
                      dbo.VendaAtendente INNER JOIN
                      dbo.Funcionario ON dbo.VendaAtendente.Fun_Codigo = dbo.Funcionario.Fun_CPF ON dbo.Venda.Ven_CodigoPre = dbo.VendaAtendente.VenAten_NDocPre ON 
                      dbo.VendaIndicacao.VenInd_NDocPre = dbo.Venda.Ven_CodigoPre INNER JOIN
                      dbo.Indicacoes ON dbo.VendaIndicacao.Ind_Codigo = dbo.Indicacoes.Ind_codigo LEFT OUTER JOIN
                      dbo.Motivo_devolucao ON dbo.Venda.Mod_codigo = dbo.Motivo_devolucao.Mod_codigo LEFT OUTER JOIN
                      dbo.Clientes ON dbo.Venda.Ven_CodVinculo = dbo.Clientes.Cli_Codigo

