                      dbo.contas_Receber_det.Ctr_valor_vencimento, dbo.contas_Receber_det.Ctr_situacao, dbo.contas_Receber_det.Ctr_parcela, dbo.Modo.Mdo_nome
, contas_receber.emp_codigo, contas_receber.Ctr_valor_total_original

FROM         dbo.contas_receber INNER JOIN
