SELECT     Contas_receber_pag.Ctr_codigo, dbo.Modo.Mdo_nome, dbo.Contas_receber_pag.Crp_valor_pago, 
                      dbo.Contas_receber_pag.Crp_data_pagamento, dbo.Contas_receber_pag.ctr_codigo_det, dbo.Contas_receber_pag.Crp_numero_cheque, 
                      dbo.Contas_receber_pag.Crp_nome_banco
FROM         dbo.Contas_receber_pag INNER JOIN  dbo.Modo ON dbo.Contas_receber_pag.Mdo_codigo = dbo.Modo.Mdo_codigo
where  Contas_receber_pag.Ctr_codigo=:PCtr_codigo and Contas_receber_pag.ctr_codigo_det=:Pctr_codigo_det

-- [Qrylucro : TADOQuery]
SELECT SUM(VendaProduto.VenPro_Quantidade * dbo.Valorcusto (VendaProduto.Pro_codnosso,VendaProduto.CodAcabamento, DATEADD(DAY, -30 ,Venda.Ven_DataEmissao) ,Venda.Ven_DataEmissao)) AS Saldo_custo   
 , max(Venda.Ven_TotalProd) as Ven_TotalProd

, max(Venda.Ven_TotalProd) - SUM(VendaProduto.VenPro_Quantidade * dbo.Valorcusto (VendaProduto.Pro_codnosso,VendaProduto.CodAcabamento, DATEADD(DAY, -30 ,Venda.Ven_DataEmissao) ,Venda.Ven_DataEmissao))  
 as lucrobruto
,case when max(Venda.Ven_TotalProd) > 0 then (max(Venda.Ven_TotalProd) - SUM(VendaProduto.VenPro_Quantidade * dbo.Valorcusto (VendaProduto.Pro_codnosso,VendaProduto.CodAcabamento, DATEADD(DAY, -30 ,Venda.Ven_DataEmissao) ,Venda.Ven_DataEmissao))  
)/ max(Venda.Ven_TotalProd) else 0 end AS MC
 FROM Venda INNER JOIN VendaProduto ON Venda.Ven_CodigoPre = VendaProduto.Ven_CodigoPre INNER JOIN
         Preco_Produto ON VendaProduto.Pro_codnosso = Preco_Produto.Pre_Codnosso AND
         VendaProduto.CodAcabamento = Preco_Produto.Pre_Acabamento


         WHERE (Venda.Ven_Tipo = 'P') AND (Venda.Ven_Situacao = 'A') AND Venda.Ven_CodigoPre =:pVen_CodigoPre

-- [QryContasEmpresas : TADOQuery]
SELECT SUM(VendaProduto.VenPro_Quantidade * dbo.Valorcusto (VendaProduto.Pro_codnosso,VendaProduto.CodAcabamento, DATEADD(DAY, -30 ,Venda.Ven_DataEmissao) ,Venda.Ven_DataEmissao)) AS Saldo_custo   
 , max(Venda.Ven_TotalProd) as Ven_TotalProd

, max(Venda.Ven_TotalProd) - SUM(VendaProduto.VenPro_Quantidade * dbo.Valorcusto (VendaProduto.Pro_codnosso,VendaProduto.CodAcabamento, DATEADD(DAY, -30 ,Venda.Ven_DataEmissao) ,Venda.Ven_DataEmissao))  
 as lucrobruto
,case when max(Venda.Ven_TotalProd) > 0 then (max(Venda.Ven_TotalProd) - SUM(VendaProduto.VenPro_Quantidade * dbo.Valorcusto (VendaProduto.Pro_codnosso,VendaProduto.CodAcabamento, DATEADD(DAY, -30 ,Venda.Ven_DataEmissao) ,Venda.Ven_DataEmissao))  
)/ max(Venda.Ven_TotalProd) else 0 end AS MC
 FROM Venda INNER JOIN VendaProduto ON Venda.Ven_CodigoPre = VendaProduto.Ven_CodigoPre INNER JOIN
         Preco_Produto ON VendaProduto.Pro_codnosso = Preco_Produto.Pre_Codnosso AND
         VendaProduto.CodAcabamento = Preco_Produto.Pre_Acabamento


         WHERE (Venda.Ven_Tipo = 'P') AND (Venda.Ven_Situacao = 'A') AND Venda.Ven_CodigoPre =:pVen_CodigoPre

