   FORM: FrmRel_pedido_compra   FrmRel_pedido_compra
   ============================================================ */

-- [QryPed_compra : TADOQuery]
SELECT produtos.Pro_unidade,produtos.Pro_descricao, dbo.produtos.Pro_tp_peca, dbo.produtos.Pro_tp_produto, dbo.Pedido_compra_det.Pro_codnosso, dbo.Pedido_compra_det.Pcd_acabamento, dbo.Pedido_compra_det.Pcd_quantidade_solicit, 
                  dbo.Pedido_compra_det.Pcd_destino, dbo.Pedido_compra_det.Pcp_codigo, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto, dbo.fornecedor.For_Nome,
                      (SELECT TOP (1) Pre_VlNFor
                       FROM      dbo.Preco_Produto
                       WHERE   (Pre_Codnosso = dbo.produtos.Pro_codnosso) AND (Pre_Acabamento = dbo.Pedido_compra_det.Pcd_acabamento)) AS vl_unitario,
                      (SELECT TOP (1) Pre_VlNFor
                       FROM      dbo.Preco_Produto AS Preco_Produto_1
                       WHERE   (Pre_Codnosso = dbo.produtos.Pro_codnosso) AND (Pre_Acabamento = dbo.Pedido_compra_det.Pcd_acabamento)) * dbo.Pedido_compra_det.Pcd_quantidade_solicit AS vl_item, 
 dbo.Acabamento.DescAcabamento + ' - ' + dbo.Pedido_compra_det.Pcd_acabamento AS DescAcabamento
FROM     dbo.Acabamento INNER JOIN
                  dbo.Pedido_compra_det ON dbo.Acabamento.CodAcabamento = dbo.Pedido_compra_det.Pcd_acabamento LEFT OUTER JOIN
                  dbo.ProdutosFornecedores INNER JOIN
                  dbo.produtos ON dbo.ProdutosFornecedores.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                  dbo.fornecedor ON dbo.ProdutosFornecedores.For_codigo = dbo.fornecedor.For_codigo ON dbo.Pedido_compra_det.Pro_codnosso = dbo.produtos.Pro_codnosso

where Pedido_compra_det.Pcp_codigo=:codigo
and (dbo.ProdutosFornecedores.ProdFor_Situacao = 1) AND (dbo.ProdutosFornecedores.ProdFor_Padrao = 1)

