FROM        ProdutosRelacionados

-- [QryProdRelDet : TADOQuery]
select ProdRelDet_Codigo, ProdRel_codigo, ProdutosRelacionadosDet.Pro_codnosso, CodAcabamento, ProdRelDet_Quantidade, ProdutosFornecedores.ProdFor_CodigoProduto,
ProdutosFornecedores.ProdFor_DescricaoProduto, produtos.Pro_CodEspecial, produtos.Pro_descricao, CASE WHEN ProdRelDet_padrao = '1' THEN 'SIM' ELSE 'NÃO' END as ProdRelDet_padrao, 
CASE WHEN ProdRelDet_NaoRelacionado = '1' THEN 'SIM' ELSE 'NÃO' END as ProdRelDet_NaoRelacionado  
from ProdutosRelacionadosDet 
	INNER JOIN ProdutosFornecedores ON ProdutosRelacionadosDet.Pro_codnosso = ProdutosFornecedores.Pro_codnosso
	INNER JOIN produtos ON ProdutosRelacionadosDet.Pro_codnosso = produtos.Pro_codnosso
where ProdRel_codigo =:pcod


/* ============================================================
   FORM: FrmRel_Projetos_Fechados   FrmRel_Projetos_Fechados
   ============================================================ */

-- [Qryfechados : TADOQuery]
SELECT  Venda.Ven_ValorCredito,  dbo.Venda.Ven_codigopre   ,  dbo.VendaIndicacao.VenInd_TpDoc, dbo.Indicacoes.Ind_Nome, dbo.Venda.Ven_codigo, dbo.Venda.ParSV_serie, dbo.Venda.Ven_DataEmissao, 
                      dbo.Venda.Ven_Orcamento, dbo.Venda.Ven_TotalServ, dbo.Venda.Ven_TotalProd, dbo.Venda.Ven_Total, Indicacoes.ind_codigo,
                   
case when venda.Ven_TipoDesc ='G' THEN
    (   (SELECT     SUM(dbo.VendaProduto.VenPro_VlItem - CASE WHEN Vendal.Ven_DescontoPorc > 0 THEN (VendaProduto.VenPro_VlItem * (Vendal.Ven_DescontoPorc / 100))
                                                    ELSE 0 END) AS Expr1
                            FROM          dbo.VendaProduto INNER JOIN
                                                   dbo.produtos ON dbo.VendaProduto.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                                                   dbo.Venda AS vendal ON dbo.VendaProduto.Ven_CodigoPre = vendal.Ven_CodigoPre
                            WHERE      (dbo.VendaProduto.Ven_CodigoPre = venda.Ven_CodigoPre) AND (dbo.produtos.GrupoProduto_codigo = 1)))
else 

(SELECT     SUM(dbo.VendaProduto.VenPro_VlItem) AS Expr1
                            FROM          dbo.VendaProduto INNER JOIN
                                                   dbo.produtos ON dbo.VendaProduto.Pro_codnosso = dbo.produtos.Pro_codnosso 
                            WHERE      (dbo.VendaProduto.Ven_CodigoPre = venda.Ven_CodigoPre) AND (dbo.produtos.GrupoProduto_codigo = 1))
end
 AS valorluminarias,

case when venda.Ven_TipoDesc ='G' THEN

                          (SELECT     SUM(VendaProduto_1.VenPro_VlItem - CASE WHEN Vendam.Ven_DescontoPorc > 0 THEN (VendaProduto_1.VenPro_VlItem * (Vendam.Ven_DescontoPorc /
                                                    100)) ELSE 0 END) AS Expr1
                            FROM          dbo.VendaProduto AS VendaProduto_1 INNER JOIN
                                                   dbo.produtos AS produtos_1 ON VendaProduto_1.Pro_codnosso = produtos_1.Pro_codnosso INNER JOIN
                                                   dbo.Venda AS vendam ON VendaProduto_1.Ven_CodigoPre = vendam.Ven_CodigoPre
                            WHERE      (VendaProduto_1.Ven_CodigoPre = venda.Ven_CodigoPre) AND (produtos_1.GrupoProduto_codigo > 1)) 

else

                       (SELECT     SUM(VendaProduto_1.VenPro_VlItem) AS Expr1
                            FROM          dbo.VendaProduto AS VendaProduto_1 INNER JOIN
                                                   dbo.produtos AS produtos_1 ON VendaProduto_1.Pro_codnosso = produtos_1.Pro_codnosso 
                            WHERE      (VendaProduto_1.Ven_CodigoPre = venda.Ven_CodigoPre) AND (produtos_1.GrupoProduto_codigo > 1)) 


end
AS valormateriais, dbo.Clientes.Cli_Nome


FROM         dbo.Indicacoes INNER JOIN
                      dbo.VendaIndicacao ON dbo.Indicacoes.Ind_codigo = dbo.VendaIndicacao.Ind_Codigo INNER JOIN
                      dbo.Venda ON dbo.VendaIndicacao.VenInd_NDocPre = dbo.Venda.Ven_CodigoPre INNER JOIN
                      dbo.Clientes ON dbo.Venda.Ven_CodVinculo = dbo.Clientes.Cli_Codigo
WHERE     (dbo.VendaIndicacao.VenInd_TpDoc = 'PRO') AND (dbo.Venda.Ven_Situacao = 'A') AND (dbo.Venda.Ven_Tipo = 'P')


