   FORM: FrmRel_Quantitativo   FrmRel_Quantitativo
   ============================================================ */

-- [QryVENDA : TADOQuery]
SELECT dbo.Venda.Ven_codigo, dbo.Venda.ParSV_serie, dbo.Venda.Ven_DataEmissao, dbo.Clientes.Cli_Nome, dbo.clientes.cli_cnpj_cpf, dbo.clientes.cli_tp_pessoa, dbo.Municipio.mun_nome, 
                      dbo.clientes.cli_ie_rg, dbo.Municipio.mun_uf, dbo.Obras.Obr_Descricao, dbo.Obras.Obr_Endereco, dbo.Obras.Obr_numero, dbo.Obras.Obr_complemento, dbo.Obras.Obr_Bairro, 
                      dbo.Obras.Obr_UF, dbo.Obras.Obr_CEP, Venda.Ven_codigopre, venda.emp_codigo
,Clientes.Cli_celular, Clientes.Cli_Fcomercial, dbo.Clientes.Cli_Fresidencial
, Venda.ven_tipo, Venda.Ven_DataConclusao, venda.Ven_DataPrevEntrega, venda.Ven_TipoEntrega

FROM     dbo.Venda INNER JOIN
                  dbo.Obras ON dbo.Venda.Obr_codigo = dbo.Obras.Obr_Codigo INNER JOIN
                  dbo.Clientes ON dbo.Obras.Cli_codigo = dbo.Clientes.Cli_Codigo LEFT OUTER JOIN
                  dbo.Municipio ON dbo.Obras.mun_codigo = dbo.Municipio.mun_codigo


WHERE     (Venda.Ven_codigopre =:pven_codigopre)

-- [Qryprodutos : TADOQuery]
SELECT dbo.produtos.Pro_descricao,  dbo.VendaProduto.Pro_codnosso, dbo.produtos.Pro_unidade, dbo.produtos.Pro_PesoBruto, 
                  CASE WHEN dbo.vendaproduto.VenPro_Vldesconto IS NULL THEN 0 ELSE dbo.vendaproduto.VenPro_Vldesconto END AS VenPro_Vldesconto, dbo.produtos.Pro_tp_produto, dbo.VendaProduto.Ven_CodigoPre, 
                  SUM(dbo.VendaProduto.VenPro_Quantidade) AS tl_quantidade, AVG(dbo.VendaProduto.VenPro_VlUnitario) AS vl_unitario, SUM(dbo.VendaProduto.VenPro_VlItem) AS tl_vl_item, 
                  dbo.ProdutosFornecedores.ProdFor_CodigoProduto AS Pro_Codbase, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto AS Pro_descricao_for, dbo.produtos.Pro_CodEspecial, 
                  dbo.Estoque_produto.Epr_estoque, SUM(dbo.VendaProduto.VenPro_Quantidade) - dbo.Estoque_produto.Epr_estoque AS quant_pedir, dbo.produtos.GrupoProduto_codigo, 
                  dbo.GrupoProduto.GrupoProduto_Descricao, dbo.produtos.Pro_tp_peca, dbo.fornecedor.For_Nome + ' - ' + fornecedor.For_Sigla as For_Nome
, dbo.Acabamento.DescAcabamento + ' - ' + dbo.Acabamento.CodAcabamento AS Acabamento,
Acabamento.CodAcabamento 

, dbo.ValorCusto(dbo.VendaProduto.Pro_codnosso, dbo.Acabamento.CodAcabamento, DATEADD(day, - 30, dbo.Venda.Ven_DataEmissao), 
                  dbo.Venda.Ven_DataEmissao) AS valor_custo, SUM(dbo.VendaProduto.VenPro_Quantidade) * dbo.ValorCusto(dbo.VendaProduto.Pro_codnosso, dbo.Acabamento.CodAcabamento, DATEADD(day, - 30, dbo.Venda.Ven_DataEmissao), 
                  dbo.Venda.Ven_DataEmissao) AS valor_item_custo

FROM     dbo.ProdutosFornecedores INNER JOIN
                  dbo.fornecedor ON dbo.ProdutosFornecedores.For_codigo = dbo.fornecedor.For_codigo INNER JOIN
                  dbo.VendaProduto INNER JOIN
                  dbo.produtos ON dbo.VendaProduto.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                  dbo.Estoque_produto ON dbo.VendaProduto.Pro_codnosso = dbo.Estoque_produto.Epr_Codnosso AND dbo.VendaProduto.CodAcabamento = dbo.Estoque_produto.Epr_Acabamento INNER JOIN
                  dbo.GrupoProduto ON dbo.produtos.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo ON dbo.ProdutosFornecedores.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                  dbo.Acabamento ON dbo.VendaProduto.CodAcabamento = dbo.Acabamento.CodAcabamento INNER JOIN
                  dbo.Venda ON dbo.VendaProduto.Ven_CodigoPre = dbo.Venda.Ven_CodigoPre



WHERE    (dbo.VendaProduto.VenPro_Quantidade > 0) AND (dbo.VendaProduto.Ven_CodigoPre =:pVen_CodigoPre) AND (dbo.Estoque_produto.EstTp_Codigo = 1)  and ProdutosFornecedores.ProdFor_Padrao= 1
and (dbo.Estoque_produto.Emp_codigo =:pEmp_codigo)

GROUP BY dbo.VendaProduto.CodAcabamento, dbo.VendaProduto.Pro_codnosso, dbo.produtos.Pro_unidade, dbo.produtos.Pro_PesoBruto, CASE WHEN dbo.vendaproduto.VenPro_Vldesconto IS NULL 
                  THEN 0 ELSE dbo.vendaproduto.VenPro_Vldesconto END, dbo.produtos.Pro_tp_produto, dbo.VendaProduto.Ven_CodigoPre, dbo.produtos.Pro_descricao, dbo.produtos.Pro_Codbase, dbo.produtos.Pro_descricao_for, 
                  dbo.produtos.Pro_CodEspecial, dbo.Estoque_produto.Epr_estoque, dbo.produtos.GrupoProduto_codigo, dbo.GrupoProduto.GrupoProduto_Descricao, dbo.produtos.Pro_tp_peca, dbo.fornecedor.For_Nome, 
                  dbo.ProdutosFornecedores.ProdFor_CodigoProduto, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto,Acabamento.DescAcabamento,Acabamento.CodAcabamento,Venda.Ven_DataEmissao,fornecedor.For_Sigla
ORDER BY dbo.produtos.GrupoProduto_codigo, dbo.VendaProduto.Pro_codnosso

