SELECT TOP (100) PERCENT dbo.VendaAmbiente.VenAmb_Descricao, dbo.produtos.Pro_descricao, dbo.VendaProduto.CodAcabamento, dbo.VendaProduto.Pro_codnosso, dbo.Marca.Marca_Descricao, 
                  dbo.produtos.Pro_unidade, dbo.produtos.Pro_PesoBruto, dbo.VendaProduto.VenPro_Vldesconto, dbo.produtos.Pro_tp_produto, dbo.VendaProduto.Ven_CodigoPre, SUM(dbo.VendaProduto.VenPro_Quantidade) 
                  AS tl_quantidade, AVG(dbo.VendaProduto.VenPro_VlUnitario) AS vl_unitario, SUM(dbo.VendaProduto.VenPro_VlItem) AS tl_vl_item, dbo.ProdutosFornecedores.ProdFor_CodigoProduto AS Pro_Codbase, 
                  dbo.ProdutosFornecedores.ProdFor_DescricaoProduto AS Pro_descricao_for, dbo.produtos.Pro_CodEspecial, dbo.Estoque_produto.Epr_estoque, SUM(dbo.VendaProduto.VenPro_Quantidade) 
                  - dbo.Estoque_produto.Epr_estoque AS quant_pedir, dbo.produtos.GrupoProduto_codigo, dbo.GrupoProduto.GrupoProduto_Descricao, dbo.produtos.Pro_tp_peca, VendaProduto.CodAmbiente
FROM     dbo.VendaProduto INNER JOIN
                  dbo.VendaAmbiente ON dbo.VendaProduto.Ven_CodigoPre = dbo.VendaAmbiente.VenAmb_NDocPre AND dbo.VendaProduto.CodAmbiente = dbo.VendaAmbiente.CodAmbiente INNER JOIN
                  dbo.produtos ON dbo.VendaProduto.Pro_codnosso = dbo.produtos.Pro_codnosso LEFT OUTER JOIN
                  dbo.Marca ON dbo.produtos.Marca_Codigo = dbo.Marca.Marca_Codigo INNER JOIN
                  dbo.Estoque_produto ON dbo.VendaProduto.Pro_codnosso = dbo.Estoque_produto.Epr_Codnosso AND dbo.VendaProduto.CodAcabamento = dbo.Estoque_produto.Epr_Acabamento INNER JOIN
                  dbo.GrupoProduto ON dbo.produtos.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo INNER JOIN
                  dbo.ProdutosFornecedores ON dbo.produtos.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso
WHERE Estoque_produto.emp_codigo =:pemp_codigo and   (dbo.VendaProduto.VenPro_Quantidade > 0) AND (dbo.VendaProduto.Ven_CodigoPre =:pVen_CodigoPre) AND (dbo.Estoque_produto.EstTp_Codigo = 1) and ProdutosFornecedores.ProdFor_Padrao= 1
GROUP BY dbo.VendaAmbiente.VenAmb_Descricao, dbo.VendaProduto.CodAcabamento, dbo.VendaProduto.Pro_codnosso, dbo.Marca.Marca_Descricao, dbo.produtos.Pro_unidade, dbo.produtos.Pro_PesoBruto, 
                  dbo.VendaProduto.VenPro_Vldesconto, dbo.produtos.Pro_tp_produto, dbo.VendaProduto.Ven_CodigoPre, dbo.produtos.Pro_descricao, dbo.produtos.Pro_Codbase, dbo.produtos.Pro_descricao_for, 
                  dbo.produtos.Pro_CodEspecial, dbo.Estoque_produto.Epr_estoque, dbo.produtos.GrupoProduto_codigo, dbo.GrupoProduto.GrupoProduto_Descricao, dbo.produtos.Pro_tp_peca, 
                  dbo.ProdutosFornecedores.ProdFor_CodigoProduto, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto,VendaProduto.CodAmbiente
ORDER BY dbo.produtos.GrupoProduto_codigo, dbo.VendaAmbiente.VenAmb_Descricao, dbo.VendaProduto.Pro_codnosso

