                      dbo.Transferencia_filiais_produtos.Pro_codnosso, dbo.Transferencia_filiais_produtos.Tfp_acabamento, 
                      dbo.Transferencia_filiais_produtos.Tfp_quantidade, dbo.Transferencia_filiais_produtos.Tfp_vl_unitario, 
                      dbo.Transferencia_filiais_produtos.Tfp_vl_item, dbo.Transferencia_filiais_produtos.Tfp_tipo, dbo.produtos.Pro_descricao,.produtos.Pro_tp_peca
