-- [Qryestoque : TADOQuery]
SELECT     TOP (100) PERCENT dbo.fornecedor.For_Nome, dbo.produtos.Pro_codnosso, dbo.produtos.Pro_tp_produto, dbo.produtos.Pro_tp_peca, dbo.produtos.Pro_descricao, 
                      dbo.Preco_Produto.Pre_Acabamento, MAX(dbo.Preco_Produto.Pre_Tabela) AS Pre_Tabela, MAX(dbo.Preco_Produto.Pre_compra) AS Pre_compra, 
                      MAX(dbo.Preco_Produto.Pre_Venda) AS Pre_Venda, MAX(dbo.Preco_Produto.Pre_Custo) AS Pre_Custo, SUM(dbo.Estoque_produto.Epr_estoque) AS estoque, 
                      dbo.produtos.For_codigo, dbo.Fabrica.Fab_Descricao
,produtos.Pro_Codbase, dbo.produtos.Pro_descricao_for, dbo.produtos.Pro_CodEspecial

FROM         dbo.produtos INNER JOIN
                      dbo.fornecedor ON dbo.produtos.For_codigo = dbo.fornecedor.For_codigo INNER JOIN
                      dbo.Preco_Produto ON dbo.produtos.Pro_codnosso = dbo.Preco_Produto.Pre_Codnosso INNER JOIN
                      dbo.Estoque_produto ON dbo.Preco_Produto.Pre_Codnosso = dbo.Estoque_produto.Epr_Codnosso AND 
                      dbo.Preco_Produto.Pre_Acabamento = dbo.Estoque_produto.Epr_Acabamento LEFT OUTER JOIN
                      dbo.Fabrica ON dbo.produtos.Fab_Codigo = dbo.Fabrica.Fab_Codigo
WHERE     (dbo.produtos.For_codigo = 1)
GROUP BY dbo.fornecedor.For_Nome, dbo.produtos.Pro_codnosso, dbo.Preco_Produto.Pre_Acabamento, dbo.produtos.Pro_tp_produto, dbo.produtos.Pro_tp_peca, 
                      dbo.produtos.Pro_descricao, dbo.produtos.For_codigo, dbo.Fabrica.Fab_Descricao
,produtos.Pro_Codbase, dbo.produtos.Pro_descricao_for, dbo.produtos.Pro_CodEspecial
ORDER BY dbo.fornecedor.For_Nome, dbo.produtos.Pro_codnosso, dbo.Preco_Produto.Pre_Acabamento


