-- [badoRelAcerto : TBetterADODataSet]
SELECT     acerto_eletrecistas_servicos.aes_codigo, acerto_eletrecistas_servicos.pse_quantidade, acerto_eletrecistas_servicos.pse_descricao, acerto_eletrecistas_servicos.aes_vl_unitario, 
                      acerto_eletrecistas_servicos.pse_vl_eletrecista, acerto_eletrecistas_det.aed_data_acerto, case when acerto_eletrecistas_det.aed_qtde > 0 then acerto_eletrecistas_det.aed_qtde else 0 end  aed_qtde, 
                     case when acerto_eletrecistas_det.aed_valor_acerto > 0 then  acerto_eletrecistas_det.aed_valor_acerto else 0 end aed_valor_acerto, acerto_eletrecistas.ped_desc_por_servico,case when acerto_eletrecistas.ael_total_servicos  > 0 then acerto_eletrecistas.ael_total_servicos else 0 end ael_total_servicos, 
case when ael_vlr_adto1 >0 then ael_vlr_adto1 else 0 end ael_vlr_adto1, 
case when ael_vlr_adto2 >0 then ael_vlr_adto2 else 0 end ael_vlr_adto2,
case when ael_vlr_adto3 >0 then ael_vlr_adto3 else 0 end ael_vlr_adto3, 
acerto_eletrecistas_det.aed_operacao, case when acerto_eletrecistas.ael_total_recebido > 0 then acerto_eletrecistas.ael_total_recebido else 0 end ael_total_recebido, case when acerto_eletrecistas.ael_total_pago > 0 then acerto_eletrecistas.ael_total_pago else 0 end ael_total_pago
, acerto_eletrecistas.ael_codigo

FROM         acerto_eletrecistas_servicos LEFT JOIN
                      acerto_eletrecistas_det ON acerto_eletrecistas_servicos.aes_codigo = acerto_eletrecistas_det.aes_codigo INNER JOIN
                      acerto_eletrecistas ON acerto_eletrecistas_servicos.ael_codigo = acerto_eletrecistas.ael_codigo

WHERE     (acerto_eletrecistas_servicos.ael_codigo = :CodAcerto)
AND  (acerto_eletrecistas_servicos.aes_serv_alterado is null)


/* ============================================================
   FORM: FrmRelDataEntregaPrevista   FrmRelDataEntregaPrevista
   ============================================================ */

-- [QryDtEntPrev : TADOQuery]
SELECT        dbo.Venda.Ven_codigo, dbo.Venda.ParSV_serie, dbo.Venda.Ven_DataEmissao, dbo.Clientes.Cli_Nome, dbo.VendaProduto.Pro_codnosso, dbo.VendaProduto.CodAcabamento, dbo.produtos.Pro_Codbase, 
                         dbo.produtos.Pro_descricao, dbo.produtos.Pro_descricao_for, SUM(dbo.VendaProduto.VenPro_Quantidade) AS VenPro_Quantidade, dbo.produtos.Pro_unidade, dbo.produtos.Pro_CodEspecial, 
                         dbo.fornecedor.For_Nome, dbo.Venda.Ven_Situacao, dbo.Venda.Ven_Tipo, dbo.Venda.Ven_DataEmissao + dbo.Paramentros.par_entrega AS DataPrevista, venda.ven_codigopre
FROM            dbo.Venda INNER JOIN
                         dbo.VendaProduto ON dbo.Venda.Ven_CodigoPre = dbo.VendaProduto.Ven_CodigoPre INNER JOIN
                         dbo.produtos ON dbo.VendaProduto.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                         dbo.fornecedor ON dbo.produtos.For_codigo = dbo.fornecedor.For_codigo INNER JOIN
                         dbo.Clientes ON dbo.Venda.Ven_CodVinculo = dbo.Clientes.Cli_Codigo CROSS JOIN
                         dbo.Paramentros
WHERE        (dbo.Venda.Ven_Situacao = 'A') AND (dbo.Venda.Ven_Tipo = 'P') AND (dbo.Venda.Ven_DataEmissao + dbo.Paramentros.par_entrega >= '25/08/2016')
GROUP BY dbo.Clientes.Cli_Nome, dbo.VendaProduto.Pro_codnosso, dbo.VendaProduto.CodAcabamento, dbo.produtos.Pro_Codbase, dbo.produtos.Pro_descricao, dbo.produtos.Pro_descricao_for, 
                         dbo.Venda.Ven_DataEmissao, dbo.Venda.ParSV_serie, dbo.Venda.Ven_codigo, dbo.produtos.Pro_unidade, dbo.produtos.Pro_CodEspecial, dbo.fornecedor.For_Nome, dbo.Venda.Ven_Situacao, 
                         dbo.Venda.Ven_Tipo, dbo.Paramentros.par_entrega,  venda.ven_codigopre

-- [QryOrdem : TADOQuery]
SELECT        dbo.ordem_compra_det.Pro_codnosso, dbo.ordem_compra_det.Ocd_acabamento, dbo.ordem_compra_det.Ocd_quantidade_pedido, dbo.ordem_compra_det.Ocd_quantidade_solicit, 
                         dbo.ordem_compra_det.Ocd_cod_pedido, dbo.ordem_compra_det.Ocd_cod_venda, dbo.ordem_compra.Ocp_codigo, dbo.ordem_compra_det.ocd_ped_av_fan, dbo.ordem_compra_det.Ocd_ped_modo, 
                        case when dbo.ordem_compra_det.Ocd_recebimento IS NULL then 'NÃO RECEBIDO' ELSE dbo.ordem_compra_det.Ocd_recebimento END AS Ocd_recebimento , 
dbo.ordemNotas(ordem_compra_det.Ocp_codigo,ordem_compra_det.ocd_item) as notas
FROM            dbo.ordem_compra INNER JOIN
                         dbo.ordem_compra_det ON dbo.ordem_compra.Ocp_codigo = dbo.ordem_compra_det.Ocp_codigo

WHERE        (dbo.ordem_compra_det.Ocd_ped_modo = 'P')     
AND ordem_compra_det.Pro_codnosso =:PPro_codnosso 
AND ordem_compra_det.Ocd_acabamento =:POcd_acabamento
AND  ordem_compra_det.Ocd_cod_venda =:POcd_cod_venda


