-- [qRel : TADOQuery]
SELECT DEV.ven_codigopre, PE.Ven_DataEmissao, DET.Pro_codnosso, P.Pro_descricao AS CodProduto, F.For_codigo, F.For_Razao, DET.CodAcabamento, P.Pro_descricao,
DET.DevPro_Quantidade AS QuantDEV, dbo.Clientes.Cli_Nome, A.DescAcabamento, PE.Ven_codigo, PE.ParSV_serie
, P.Pro_Codbase,P.Pro_descricao_for, P.Pro_CodEspecial


FROM  Devolucao AS DEV INNER JOIN Venda AS PE ON DEV.ven_codigopre = PE.Ven_CodigoPre INNER JOIN
 DevolucaoProduto AS DET ON DEV.Dev_CodigoPre = DET.Dev_CodigoPre INNER JOIN
  produtos AS P ON DET.Pro_codnosso = P.Pro_codnosso INNER JOIN
   fornecedor AS F ON P.For_codigo = F.For_codigo INNER JOIN
                 Acabamento AS A ON DET.CodAcabamento = A.CodAcabamento INNER JOIN
                 Clientes ON PE.Ven_CodVinculo = Clientes.Cli_Codigo
                 WHERE  (DET.DevPro_usuarioestoque IS NULL)


/* ============================================================
   FORM: FrmRelForInd   
   ============================================================ */

-- [QryForInd : TADOQuery]
SELECT     TOP (100) PERCENT dbo.GrupoProduto.GrupoProduto_Descricao, dbo.TipoPeca.TpPeca_Codigo, dbo.produtos.Pro_codnosso, 
                      dbo.produtos.Pro_Codbase, dbo.produtos.Pro_descricao, dbo.produtos.Pro_descricao_for, dbo.fornecedor.For_Nome, 
                      dbo.pedido_luminaria_det.pld_acabamento AS acabamento, SUM(dbo.pedido_luminaria_det.pld_vl_unitario) AS vl_unitario, dbo.Indicacoes.Ind_Nome, 
                      SUM(dbo.pedido_luminaria_det.pld_vl_item * CASE WHEN VendaIndicacao.venind_porcentagem IS NULL 
                      THEN 0 ELSE (VendaIndicacao.venind_porcentagem / 100) END) AS vl_item, 
                      SUM(dbo.pedido_luminaria_det.pld_quantidade * CASE WHEN VendaIndicacao.venind_porcentagem IS NULL 
                      THEN 0 ELSE (VendaIndicacao.venind_porcentagem / 100) END) AS quantidade
FROM         dbo.pedido INNER JOIN
                      dbo.pedido_luminaria_det ON dbo.pedido.ped_codigo_pre = dbo.pedido_luminaria_det.ped_codigo_pre INNER JOIN
                      dbo.produtos ON dbo.pedido_luminaria_det.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                      dbo.GrupoProduto ON dbo.produtos.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo INNER JOIN
                      dbo.TipoPeca ON dbo.produtos.Pro_tp_peca = dbo.TipoPeca.TpPeca_Codigo INNER JOIN
                      dbo.fornecedor ON dbo.produtos.For_codigo = dbo.fornecedor.For_codigo INNER JOIN
                      dbo.VendaIndicacao ON dbo.pedido.ped_codigo_pre = dbo.VendaIndicacao.VenInd_NDocPre INNER JOIN
                      dbo.Indicacoes ON dbo.VendaIndicacao.Ind_Codigo = dbo.Indicacoes.Ind_codigo
WHERE     (dbo.VendaIndicacao.VenInd_TpDoc = 'PRO')
GROUP BY dbo.fornecedor.For_Nome, dbo.Indicacoes.Ind_Nome, dbo.GrupoProduto.GrupoProduto_Descricao, dbo.TipoPeca.TpPeca_Codigo, 
                      dbo.produtos.Pro_codnosso, dbo.produtos.Pro_Codbase, dbo.produtos.Pro_descricao, dbo.produtos.Pro_descricao_for, 
                      dbo.pedido_luminaria_det.pld_acabamento
ORDER BY dbo.fornecedor.For_Nome, dbo.Indicacoes.Ind_Nome, dbo.GrupoProduto.GrupoProduto_Descricao, dbo.TipoPeca.TpPeca_Codigo, 
                      dbo.produtos.Pro_codnosso, dbo.produtos.Pro_Codbase, dbo.produtos.Pro_descricao, dbo.produtos.Pro_descricao_for, acabamento


