   ============================================================ */

-- [Qryimagem : TADOQuery]
select * from empresa

-- [QryDados : TADOQuery]
SELECT  VendaProduto.VenPro_Seq AS sequencia, VendaProduto.VenPro_SeqItem AS item, VendaProduto.Pro_codnosso AS codigo,
 produtos.Pro_descricao AS produto, produtos.Pro_unidade AS unidade, VendaAmbiente.VenAmb_Descricao AS ambiente,
  VendaProduto.CodAcabamento AS acabamento, VendaProduto.VenPro_Quantidade AS quantidade, 
   VendaProduto.VenPro_VlItem AS vlitem, produtos.Pro_tp_peca AS Peca, produtos.Pro_descricao_for, produtos.Pro_Codbase,
    produtos.Pro_CodEspecial, VendaProduto.VenPro_Vlimposto AS VlImposto, GrupoProduto.GrupoProduto_ordem AS ordem, VenPro_VldescontoProc AS Desconto,
 
case WHEN VendaProduto.VenPro_VLdescontoPROC > 0 then (VendaProduto.VenPro_vlunitario - (VendaProduto.VenPro_vlunitario * (VendaProduto.VenPro_VLdescontoPROC/100)))
  else VendaProduto.VenPro_vlunitario end AS vlunitario

   FROM VendaProduto WITH (NOLOCK) INNER JOIN VendaAmbiente WITH (NOLOCK) ON VendaProduto.CodAmbiente = VendaAmbiente.CodAmbiente AND
    VendaProduto.Ven_CodigoPre = vendaAmbiente.VenAmb_NDocPre INNER JOIN
     produtos WITH (NOLOCK) ON VendaProduto.Pro_codnosso = produtos.Pro_codnosso INNER JOIN
      GrupoProduto ON produtos.GrupoProduto_codigo = GrupoProduto.GrupoProduto_Codigo
       WHERE (VendaAmbiente.VenAmb_TpDoc ='PRO') and VendaProduto.Ven_CodigoPre =1755
       order by sequencia,item, ordem

