-- [QryPlano : TADOQuery]
SELECT     TOP 100 PERCENT 'Débito' AS TipoPlano, Plano_Contas_3.Pco_descricao AS Nivel1, Plano_Contas_3.Pco_codigo AS CodNivel1, 
                      Plano_Contas_2.Pco_descricao AS Nivel2, Plano_Contas_2.Pco_codigo AS CodNivel2, Plano_Contas_1.Pco_descricao AS Nivel3, 
                      Plano_Contas_1.Pco_codigo AS CodNivel3, dbo.contas_apagar.Pco_codigo AS CodNivel4, Plano_Contas_5.Pco_descricao AS Nivel4
FROM         dbo.Plano_Contas Plano_Contas_2 LEFT OUTER JOIN
                      dbo.Plano_Contas Plano_Contas_3 ON Plano_Contas_2.Pco_pai = Plano_Contas_3.Pco_codigo RIGHT OUTER JOIN
                      dbo.Plano_Contas Plano_Contas_5 INNER JOIN
                      dbo.contas_apagar ON Plano_Contas_5.Pco_codigo = dbo.contas_apagar.Pco_codigo INNER JOIN
                      dbo.contas_apagar_det ON dbo.contas_apagar.Ctp_codigo = dbo.contas_apagar_det.Ctp_codigo INNER JOIN
                      dbo.Tipo_documento ON dbo.contas_apagar.Tpd_codigo = dbo.Tipo_documento.Tpd_codigo LEFT OUTER JOIN
                      dbo.Plano_Contas Plano_Contas_1 ON Plano_Contas_5.Pco_pai = Plano_Contas_1.Pco_codigo ON 
                      Plano_Contas_2.Pco_codigo = Plano_Contas_1.Pco_pai
GROUP BY Plano_Contas_3.Pco_descricao, Plano_Contas_3.Pco_codigo, Plano_Contas_1.Pco_descricao, Plano_Contas_1.Pco_codigo, 
                      Plano_Contas_2.Pco_descricao, Plano_Contas_2.Pco_codigo, dbo.contas_apagar.Pco_codigo, Plano_Contas_5.Pco_descricao

