/* ============================================================
   FORM: FrmRelVendaFor   
   ============================================================ */

-- [QryForInd : TADOQuery]
SELECT     CASE WHEN
                          (SELECT     TOP (1) PreLog_compra
                            FROM          Preco_Produto_Log
                            WHERE      (PreLog_Codnosso = produtos.Pro_codnosso) AND (PreLog_Acabamento = pedido_luminaria_det.pld_acabamento) AND 
                                                   (usr_dt_hr_criacao >= MAX(pedido.ped_dt_fechamento))
                            ORDER BY usr_dt_hr_criacao) > 0 THEN
                          (SELECT     TOP (1) PreLog_compra
                            FROM          Preco_Produto_Log
                            WHERE      (PreLog_Codnosso = produtos.Pro_codnosso) AND (PreLog_Acabamento = pedido_luminaria_det.pld_acabamento) AND 
                                                   (usr_dt_hr_criacao >= MAX(pedido.ped_dt_fechamento))
                            ORDER BY usr_dt_hr_criacao) ELSE
                          (SELECT     TOP (1) Pre_compra
                            FROM          Preco_Produto
                            WHERE      pre_Codnosso = produtos.Pro_codnosso AND Pre_Acabamento = pedido_luminaria_det.pld_acabamento) 
                      END * SUM(dbo.pedido_luminaria_det.pld_quantidade) AS ValorCompra, dbo.GrupoProduto.GrupoProduto_Descricao, dbo.TipoPeca.TpPeca_Codigo, 
                      dbo.produtos.Pro_codnosso, dbo.produtos.Pro_Codbase, dbo.produtos.Pro_descricao, dbo.produtos.Pro_descricao_for, dbo.fornecedor.For_Nome, 
                      dbo.pedido_luminaria_det.pld_acabamento AS acabamento, SUM(dbo.pedido_luminaria_det.pld_vl_unitario) AS vl_unitario, 
                      SUM(dbo.pedido_luminaria_det.pld_vl_item - CASE WHEN pedido.ped_desc_por_luminaria IS NULL 
                      THEN 0 ELSE round((pedido_luminaria_det.pld_vl_item * pedido.ped_desc_por_luminaria) / 100, 4) END) AS vl_item, 
                      SUM(dbo.pedido_luminaria_det.pld_quantidade) AS quantidade
FROM         dbo.pedido INNER JOIN
                      dbo.pedido_luminaria_det ON dbo.pedido.ped_codigo_pre = dbo.pedido_luminaria_det.ped_codigo_pre INNER JOIN
                      dbo.produtos ON dbo.pedido_luminaria_det.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                      dbo.GrupoProduto ON dbo.produtos.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo INNER JOIN
                      dbo.TipoPeca ON dbo.produtos.Pro_tp_peca = dbo.TipoPeca.TpPeca_Codigo INNER JOIN
                      dbo.fornecedor ON dbo.produtos.For_codigo = dbo.fornecedor.For_codigo
 GROUP BY fornecedor.For_Nome, GrupoProduto.GrupoProduto_Descricao, TipoPeca.TpPeca_Codigo,
produtos.Pro_codnosso, produtos.Pro_Codbase, produtos.Pro_descricao, produtos.Pro_descricao_for,
 pedido_luminaria_det.pld_acabamento


/* ============================================================
   FORM: FrmRequisicaoEstoq   Requisição de Produtos
   ============================================================ */

-- [QryReqProduto : TADOQuery]
