-- [Qryestoque : TADOQuery]
SELECT  dbo.produtos.Pro_codnosso, dbo.estoque_produto_dia.Epd_Acabamento, dbo.ProdutosFornecedores.ProdFor_CodigoProduto AS Pro_Codbase, dbo.produtos.Pro_descricao, 
                  dbo.ProdutosFornecedores.ProdFor_DescricaoProduto AS Pro_descricao_for, dbo.estoquefisicoDataEmp(dbo.produtos.Pro_codnosso, dbo.estoque_produto_dia.Epd_Acabamento, dbo.estoque_produto_dia.Epd_data, 
                  dbo.estoque_produto_dia.Emp_codigo) AS estoquefisico, CASE WHEN dbo.estoque_produto_dia.Epd_estoque < 0 THEN 0 ELSE dbo.estoque_produto_dia.Epd_estoque END AS estoquevenda, dbo.estoque_produto_dia.Epd_data, 
                  dbo.produtos.Pro_unidade, 
CASE WHEN dbo.estoque_produto_dia.Epd_estoque < 0 THEN 0 ELSE dbo.estoque_produto_dia.Epd_estoque END * dbo.Preco_Produto.Pre_Custo AS totalvenda, 
                  dbo.Preco_Produto.Pre_Custo
FROM     dbo.produtos INNER JOIN
                  dbo.estoque_produto_dia ON dbo.produtos.Pro_codnosso = dbo.estoque_produto_dia.Epd_Codnosso INNER JOIN
                  dbo.Preco_Produto ON dbo.estoque_produto_dia.Epd_Codnosso = dbo.Preco_Produto.Pre_Codnosso AND dbo.estoque_produto_dia.Epd_Acabamento = dbo.Preco_Produto.Pre_Acabamento INNER JOIN
                  dbo.ProdutosFornecedores ON dbo.produtos.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso
WHERE (dbo.estoque_produto_dia.Epd_data =:pdata)


/* ============================================================
   FORM: FrmRltEstoqueDia   FrmRltEstoqueDia
   ============================================================ */

-- [Qryestoque : TADOQuery]
SELECT     dbo.estoque_produto_dia.EstTp_Codigo, dbo.produtos.Pro_codnosso, dbo.estoque_produto_dia.Epd_Acabamento, dbo.produtos.Pro_Codbase, 
                      dbo.produtos.Pro_descricao, dbo.produtos.Pro_descricao_for, dbo.estoquefisicoData(dbo.produtos.Pro_codnosso, dbo.estoque_produto_dia.Epd_Acabamento, 
                      dbo.estoque_produto_dia.Epd_data) AS estoque, dbo.estoque_produto_dia.Epd_data, dbo.produtos.Pro_unidade, dbo.estoquefisicoData(dbo.produtos.Pro_codnosso, 
                      dbo.estoque_produto_dia.Epd_Acabamento, dbo.estoque_produto_dia.Epd_data) * dbo.Preco_Produto.Pre_Custo AS totalItem, dbo.Preco_Produto.Pre_Custo
FROM         dbo.produtos INNER JOIN
                      dbo.estoque_produto_dia ON dbo.produtos.Pro_codnosso = dbo.estoque_produto_dia.Epd_Codnosso INNER JOIN
                      dbo.Preco_Produto ON dbo.estoque_produto_dia.Epd_Codnosso = dbo.Preco_Produto.Pre_Codnosso AND 
                      dbo.estoque_produto_dia.Epd_Acabamento = dbo.Preco_Produto.Pre_Acabamento
where estoque_produto_dia.Epd_data =:pdata


