SELECT     dbo.pedido.ped_codigo, dbo.Clientes.Cli_Nome, dbo.produtos.Pro_Codbase, dbo.produtos.Pro_codnosso, dbo.produtos.Pro_descricao, 
                      dbo.produtos.Pro_descricao_for, dbo.produtos.Pro_CodEspecial, SUM(dbo.pedido_luminaria_det.pld_quantidade) AS quantidade, dbo.Acabamento.DescAcabamento, 
                      dbo.produtos.Pro_unidade, dbo.pedido.ped_dt_fechamento, dbo.GrupoProduto.GrupoProduto_Descricao, dbo.produtos.Pro_tp_peca
FROM         dbo.pedido INNER JOIN
