-- [QryNotas : TADOQuery]
select 
case when  NTF_Modelo = '55' then 'NFe' else 'NFCe' end as modelo,

NTF_numero, NTF_DtEmissao, NTF_situacao, clientes.cli_codigo, clientes.cli_nome, NTF_cnpjcpf, NTF_ProtocoloNFE, NTF_VlNota, NTF_chaveNFE
, NotaFiscal.CFOP_codigo + '  ' +NotaFiscal.NTF_NatOperacao as NatOperacao

from Notafiscal INNER JOIN clientes ON notafiscal.cli_codigo = clientes.cli_codigo
where NTF_DtEmissao>= :Dataini and NTF_DtEmissao<= :Datafim
order by NTF_numero

