SELECT  mdo_nome, mdo_codigo
FROM modo where mdo_tipo='T'  order by mdo_nome

-- [Qryapagar : TADOQuery]
SELECT     dbo.Reserva_tecnica.*, dbo.Clientes.Cli_Nome AS Cli_Nome, dbo.Indicacoes.Ind_Nome AS Ind_Nome
FROM         dbo.Reserva_tecnica INNER JOIN
                      dbo.Indicacoes ON dbo.Reserva_tecnica.Ind_codigo = dbo.Indicacoes.Ind_codigo INNER JOIN
                      dbo.Clientes ON dbo.Reserva_tecnica.Cli_codigo = dbo.Clientes.Cli_Codigo

