-- [ADOQuery1 : TADOQuery]
SELECT * FROM Reserva_tecnica_GrupoProd where ret_codigo=:codigo

-- [qryCreditoInd : TADOQuery]
SELECT * FROM CreditoIndicacao WHERE Ret_codigo =:codigo

-- [QryProcInd : TADOQuery]
SELECT     VenInd_Porcentagem
FROM         dbo.VendaIndicacao
WHERE     (VenInd_TpDoc = 'PRO')
and  VenInd_NDocPre =:pVenInd_NDocPre  and Ind_Codigo =:pInd_Codigo

-- [QryRTFornecedor : TADOQuery]
SELECT        SUM(dbo.VendaProduto.VenPro_Quantidade * dbo.VendaProduto.VenPro_VlUnitario) AS totalitem, dbo.FornecedorRTGrupProd.GrupoProduto_Codigo, 
                         SUM((dbo.VendaProduto.VenPro_Quantidade * dbo.VendaProduto.VenPro_VlUnitario) * (dbo.FornecedorRTGrupProd.ForRTGruProd_Porc / 100)) AS totalitemRT, 
                         SUM((dbo.VendaProduto.VenPro_Quantidade * dbo.VendaProduto.VenPro_VlUnitario) * (dbo.FornecedorRTGrupProd.ForRTGruProd_Porc / 100)) 
                         * 100 / SUM(dbo.VendaProduto.VenPro_Quantidade * dbo.VendaProduto.VenPro_VlUnitario) AS PORCRT
FROM            dbo.Venda INNER JOIN
                         dbo.VendaProduto ON dbo.Venda.Ven_CodigoPre = dbo.VendaProduto.Ven_CodigoPre INNER JOIN
                         dbo.produtos ON dbo.VendaProduto.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                         dbo.FornecedorRTGrupProd ON dbo.produtos.GrupoProduto_codigo = dbo.FornecedorRTGrupProd.GrupoProduto_Codigo INNER JOIN
                         dbo.ProdutosFornecedores ON dbo.produtos.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso AND dbo.FornecedorRTGrupProd.for_codigo = dbo.ProdutosFornecedores.For_codigo
WHERE        (dbo.Venda.Ven_Tipo = 'P') AND (dbo.Venda.Ven_Situacao = 'A') AND (dbo.Venda.Ven_CodigoPre =:pVen_CodigoPre )
GROUP BY dbo.FornecedorRTGrupProd.GrupoProduto_Codigo

-- [Qrydevolucao : TADOQuery]
SELECT        dbo.DevolucaoProduto.DevPro_Quantidade * (dbo.DevolucaoProduto.DevPro_VlUnitario - CASE WHEN (dbo.Devolucao.Dev_DescontoPorcProd) 
                         > 0 THEN DevolucaoProduto.DevPro_VlUnitario * (Devolucao.Dev_DescontoPorcProd / 100) ELSE 0 END) AS total, dbo.produtos.GrupoProduto_codigo
FROM            dbo.Devolucao INNER JOIN
                         dbo.DevolucaoProduto ON dbo.Devolucao.Dev_CodigoPre = dbo.DevolucaoProduto.Dev_CodigoPre INNER JOIN
                         dbo.produtos ON dbo.DevolucaoProduto.Pro_codnosso = dbo.produtos.Pro_codnosso
WHERE        (dbo.Devolucao.ven_codigopre =:pven_codigopre) and  produtos.GrupoProduto_codigo =:pGrupoProduto_codigo
GROUP BY dbo.DevolucaoProduto.DevPro_Quantidade * (dbo.DevolucaoProduto.DevPro_VlUnitario - CASE WHEN (dbo.Devolucao.Dev_DescontoPorcProd) 
                         > 0 THEN DevolucaoProduto.DevPro_VlUnitario * (Devolucao.Dev_DescontoPorcProd / 100) ELSE 0 END), dbo.produtos.GrupoProduto_codigo


