SELECT pedido_materiais_det.Pro_codnosso, pedido_materiais_det.pma_acabamento, Sum([pedido_materiais_det].[pma_quantidade])-Estoque_produto.Epr_estoque AS total, pedido_materiais_det.ped_codigo_pre, pedido_materiais_det.pma_saida_comp
FROM pedido_materiais_det INNER JOIN Estoque_produto ON (pedido_materiais_det.Pro_codnosso = Estoque_produto.Epr_Codnosso) AND (pedido_materiais_det.pma_acabamento = Estoque_produto.Epr_Acabamento)
where pedido_materiais_det.ped_codigo_pre=:codigo and pedido_materiais_det.pma_saida_comp=:saida
and Estoque_produto.EstTp_Codigo=1
GROUP BY pedido_materiais_det.Pro_codnosso, pedido_materiais_det.pma_acabamento, pedido_materiais_det.ped_codigo_pre, pedido_materiais_det.pma_saida_comp, Estoque_produto.Epr_esto

