where pedido_luminaria_det.ped_codigo_pre=:codigo and pedido_luminaria_det.pld_saida_comp=:saida
and Estoque_produto.EstTp_Codigo=1

GROUP BY pedido_luminaria_det.ped_codigo_pre, pedido_luminaria_det.Pro_codnosso, pedido_luminaria_det.pld_acabamento, pedido_luminaria_det.pld_saida_comp, Estoque_produto.Epr_estoque

