/* ============================================================
   FORM: FrmSel_Acabamento   Acabamento
   ============================================================ */

-- [QryConsultaAcab : TADOQuery]
SELECT * FROM Acabamento

-- [qryAcabamento : TADOQuery]
SELECT  produtos.Pro_codnosso, produtos.Pro_Codbase, produtos.For_codigo, produtos.GrupoProduto_codigo, produtos.Pro_tp_peca, 
                produtos.Pro_descricao, produtos.Pro_quant_minima, produtos.Pro_unidade, Preco_Produto.Pre_Venda, 
                Preco_Produto.Pre_Acabamento, Estoque_produto.Epr_estoque, fornecedor.For_prazo_entrega, Preco_Produto.Pre_Codindice
FROM      produtos WITH (NOLOCK) INNER JOIN
                Preco_Produto ON produtos.Pro_codnosso = Preco_Produto.Pre_Codnosso INNER JOIN
                Estoque_produto WITH (NOLOCK) ON Preco_Produto.Pre_Acabamento = Estoque_produto.Epr_Acabamento AND 
                Preco_Produto.Pre_Codnosso = Estoque_produto.Epr_Codnosso INNER JOIN
                fornecedor WITH (NOLOCK) ON produtos.For_codigo = fornecedor.For_codigo
WHERE (((produtos.Pro_codbase)=:PRODUTO))  AND Preco_Produto.pre_ativo='S'
and Estoque_produto.EstTp_Codigo=1


