-- [qrypreco : TADOQuery]
SELECT DISTINCT
  produtos.Pro_codnosso,
  produtos.Pro_Codbase,
  produtos.For_codigo,
  produtos.GrupoProduto_codigo,
  produtos.Pro_tp_peca,
  produtos.Pro_descricao,
  produtos.Pro_quant_minima,
  produtos.Pro_unidade,
  produtos.Pro_AliqICMS,
  Preco_Produto.Pre_Venda,
  Preco_Produto.Pre_Acabamento,
  Estoque_produto.Epr_estoque,
  fornecedor.For_prazo_entrega,
  Preco_Produto.Pre_Codindice
FROM
  produtos
  INNER JOIN Preco_Produto ON (produtos.Pro_codnosso = Preco_Produto.Pre_Codnosso)
  INNER JOIN Estoque_produto ON (Preco_Produto.Pre_Acabamento = Estoque_produto.Epr_Acabamento)
  AND (Preco_Produto.Pre_Codnosso = Estoque_produto.Epr_Codnosso)
  LEFT OUTER JOIN fornecedor ON (produtos.For_codigo = fornecedor.For_codigo)
WHERE
  (((produtos.Pro_codnosso)=:PRODUTO))  AND Preco_Produto.pre_ativo='S'

