and ProdutosFornecedores.for_codigo =:pfor_codigo
GROUP BY dbo.VendaProduto.Pro_codnosso, dbo.VendaProduto.CodAcabamento, dbo.produtos.Pro_descricao, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto, 
