/* ============================================================
   FORM: FrmSelEstoqueUltimaVenda   Relatório quantidade de venda, quantidade de dias sem venda e última data de venda
   ============================================================ */

-- [QryFornecedor : TADOQuery]
SELECT  For_codigo, For_Nome, for_classificacao
FROM            dbo.fornecedor
WHERE        (for_classificacao = 'F')
ORDER BY For_codigo

-- [QryVenda : TADOQuery]
SELECT   dbo.Estoque_produto.Epr_Codnosso, '' AS epr_acabamento,
(SELECT   TOP (1) Pre_Venda FROM dbo.Preco_Produto
WHERE (Pre_Codnosso = dbo.Estoque_produto.Epr_Codnosso)) *
(SELECT   SUM(Epr_estoque) AS Expr1
 FROM dbo.Estoque_produto AS estoque
  WHERE (Epr_estoque > 0) AND (Epr_Codnosso = dbo.Estoque_produto.Epr_Codnosso)) AS valor_estoque,
  (SELECT   TOP (1) dbo.Nota_entrada.usr_dt_hr_criacao
   FROM dbo.Nota_entrada INNER JOIN
   nota_entrada_det ON dbo.Nota_entrada.Nen_codigo = dbo.nota_entrada_det.Nen_codigo
   WHERE (dbo.nota_entrada_det.Pro_codnosso = dbo.Estoque_produto.Epr_Codnosso) AND (dbo.Nota_entrada.Nen_status = 'A')
    ORDER BY dbo.Nota_entrada.usr_dt_hr_criacao DESC) AS data_entrada,
    (SELECT TOP (1) DATEDIFF(day, dbo.Venda.Ven_DataEmissao, GETDATE()) AS DIAS
    FROM dbo.VendaProduto INNER JOIN
    Venda ON dbo.VendaProduto.Ven_CodigoPre = dbo.Venda.Ven_CodigoPre
    WHERE (dbo.Venda.Ven_Tipo = 'P') AND (dbo.Venda.Ven_Situacao = 'A') AND (dbo.VendaProduto.Pro_codnosso = dbo.Estoque_produto.Epr_Codnosso)
    ORDER BY DIAS) AS DIAS,
    (SELECT   SUM(VendaProduto_2.VenPro_Quantidade) AS Expr1
    FROM VendaProduto AS VendaProduto_2 INNER JOIN
    Venda AS Venda_2 ON VendaProduto_2.Ven_CodigoPre = Venda_2.Ven_CodigoPre
    WHERE (Venda_2.Ven_Tipo = 'P') AND (Venda_2.Ven_Situacao = 'A') AND (VendaProduto_2.Pro_codnosso = dbo.Estoque_produto.Epr_Codnosso) AND
    (Venda_2.Ven_DataEmissao >=:data1 ) AND  (Venda_2.Ven_DataEmissao <=:data2)) AS quantidade,
    (SELECT   TOP (1) Venda_1.Ven_DataEmissao FROM VendaProduto AS VendaProduto_1 INNER JOIN
    Venda AS Venda_1 ON VendaProduto_1.Ven_CodigoPre = Venda_1.Ven_CodigoPre
    WHERE (Venda_1.Ven_Tipo = 'P') AND (Venda_1.Ven_Situacao = 'A') AND (VendaProduto_1.Pro_codnosso = dbo.Estoque_produto.Epr_Codnosso)
    ORDER BY Venda_1.Ven_DataEmissao DESC) AS data,
    (SELECT SUM(Epr_estoque) AS Expr1 FROM dbo.Estoque_produto AS estoque
    WHERE (Epr_estoque > 0) AND (Epr_Codnosso = dbo.Estoque_produto.Epr_Codnosso)) AS epr_estoque, dbo.produtos.Pro_descricao, dbo.produtos.Pro_tp_peca,
    ProdutosFornecedores.ProdFor_CodigoProduto, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto, dbo.fornecedor.For_Nome
    FROM Estoque_produto INNER JOIN produtos ON Estoque_produto.Epr_Codnosso = produtos.Pro_codnosso INNER JOIN
    ProdutosFornecedores ON Estoque_produto.Epr_Codnosso = ProdutosFornecedores.Pro_codnosso INNER JOIN
    fornecedor ON ProdutosFornecedores.For_codigo = fornecedor.For_codigo
WHERE     (dbo.Estoque_produto.Epr_estoque > 0)

	GROUP BY dbo.Estoque_produto.Epr_Codnosso, dbo.produtos.Pro_descricao, dbo.produtos.Pro_tp_peca, dbo.ProdutosFornecedores.ProdFor_CodigoProduto,
   dbo.ProdutosFornecedores.ProdFor_DescricaoProduto, dbo.fornecedor.For_Nome


ORDER BY DIAS DESC


