SELECT     dbo.produtos.Pro_codnosso, produtos.pro_descricao, ProdFor_CodigoProduto, ProdFor_DescricaoProduto, ProdutosFornecedores.For_codigo, 
                      dbo.produtos.Pro_tp_peca, dbo.produtos.Pro_unidade, dbo.produtos.GrupoProduto_codigo, dbo.produtos.Pro_CodEspecial, 
                      dbo.GrupoProduto.GrupoProduto_Descricao, dbo.fornecedor.For_Nome, dbo.Fabrica.Fab_Descricao, dbo.Preco_Produto.Pre_Acabamento, 
