/* ============================================================
   FORM: FrmSelEtiqProdSep   Etiqueta de Produtos Separados
   ============================================================ */

-- [Qryconsulta : TADOQuery]
SELECT dbo.controle_entrega_data.cep_tipo, dbo.controle_entrega_data.cep_operacao, SUM(dbo.controle_entrega_data.ced_quantidade) AS ced_quantidade, dbo.controle_entrega_data.cep_acabamento, 
                  dbo.controle_entrega_data.Pro_codnosso, dbo.Venda.Ven_Tipo, dbo.Venda.Ven_Situacao, dbo.Venda.Ven_codigo, dbo.Clientes.Cli_Nome, dbo.produtos.Pro_descricao, dbo.produtos.Pro_CodEspecial, 
                  dbo.controle_entrega_data.ced_data, dbo.Venda.ParSV_serie, dbo.Acabamento.DescAcabamento, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto
FROM     dbo.Controle_entrega INNER JOIN
                  dbo.controle_entrega_prod ON dbo.Controle_entrega.cen_codigo_pre = dbo.controle_entrega_prod.cen_codigo_pre INNER JOIN
                  dbo.controle_entrega_data ON dbo.controle_entrega_prod.cen_codigo_pre = dbo.controle_entrega_data.cen_codigo_pre AND dbo.controle_entrega_prod.Pro_codnosso = dbo.controle_entrega_data.Pro_codnosso AND 
                  dbo.controle_entrega_prod.cep_acabamento = dbo.controle_entrega_data.cep_acabamento INNER JOIN
                  dbo.Venda ON dbo.Controle_entrega.cen_pedido_avulso = dbo.Venda.Ven_codigo AND dbo.Controle_entrega.ParSV_serie = dbo.Venda.ParSV_serie INNER JOIN
                  dbo.Clientes ON dbo.Venda.Ven_CodVinculo = dbo.Clientes.Cli_Codigo INNER JOIN
                  dbo.produtos ON dbo.controle_entrega_prod.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                  dbo.Acabamento ON dbo.controle_entrega_data.cep_acabamento = dbo.Acabamento.CodAcabamento INNER JOIN
                  dbo.ProdutosFornecedores ON dbo.produtos.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso
where (dbo.controle_entrega_data.cep_tipo = 'S') AND (dbo.controle_entrega_data.cep_operacao = 'E') AND (dbo.Venda.Ven_Tipo = 'P') AND (dbo.Venda.Ven_Situacao = 'A')
and dbo.controle_entrega_data.ced_data >=:ced_data1 and dbo.controle_entrega_data.ced_data <=:ced_data2
and  (dbo.ProdutosFornecedores.ProdFor_Situacao = 1) AND (dbo.ProdutosFornecedores.ProdFor_Padrao = 1)

GROUP BY dbo.Venda.Ven_codigo, dbo.controle_entrega_data.cep_tipo, dbo.controle_entrega_data.cep_operacao, dbo.controle_entrega_data.cep_acabamento, dbo.controle_entrega_data.Pro_codnosso, dbo.Venda.Ven_Tipo, dbo.Venda.Ven_Situacao, 
                   dbo.Clientes.Cli_Nome, dbo.produtos.Pro_descricao, dbo.produtos.Pro_CodEspecial, dbo.controle_entrega_data.ced_data, dbo.Venda.ParSV_serie, dbo.Acabamento.DescAcabamento, 
                  dbo.ProdutosFornecedores.ProdFor_CodigoProduto, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto
ORDER BY dbo.Venda.Ven_codigo

-- [QryLocEstoque : TADOQuery]
SELECT 'P'+ProdLocEst_Predio + ' R' + ProdLocEst_Rua + ' N' + ProdLocEst_Numero + ' A' + ProdLocEst_Apto AS endereco
FROM     dbo.ProdutosLocEstoque
WHERE  (EstTp_Codigo = 1) AND (Pro_codnosso =:pPro_codnosso) AND (CodAcabamento =:pCodAcabamento)


