SELECT    venda.ven_codigo, dbo.Clientes.Cli_Nome, dbo.produtos.Pro_Codbase, dbo.produtos.Pro_codnosso, dbo.produtos.Pro_descricao, 
                      dbo.produtos.Pro_descricao_for, dbo.produtos.Pro_CodEspecial, SUM(VendaProduto.VenPro_Quantidade) AS quantidade, dbo.Acabamento.DescAcabamento, 
                      dbo.produtos.Pro_unidade, venda.Ven_DataEmissao, dbo.GrupoProduto.GrupoProduto_Descricao, dbo.produtos.Pro_tp_peca, venda.ParSV_serie
,VendaAmbiente.VenAmb_Descricao
