                      VendaProduto ON venda.ven_codigopre = VendaProduto.ven_codigopre INNER JOIN
                      dbo.Clientes ON venda.Ven_CodVinculo = dbo.Clientes.Cli_Codigo INNER JOIN
                      dbo.produtos ON VendaProduto.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                      dbo.Acabamento ON VendaProduto.CodAcabamento = dbo.Acabamento.CodAcabamento INNER JOIN
                      dbo.GrupoProduto ON dbo.produtos.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo
 INNER JOIN dbo.VendaAmbiente ON dbo.VendaProduto.Ven_CodigoPre = dbo.VendaAmbiente.VenAmb_NDocPre AND
dbo.VendaProduto.CodAmbiente = dbo.VendaAmbiente.CodAmbiente

where venda.ven_codigopre  =:pcodigo1 and VendaProduto.VenPro_Quantidade > 0

GROUP BY venda.ven_codigo, dbo.Clientes.Cli_Nome, dbo.produtos.Pro_Codbase, dbo.produtos.Pro_codnosso, dbo.produtos.Pro_descricao, 
                      dbo.produtos.Pro_descricao_for, dbo.produtos.Pro_CodEspecial, dbo.Acabamento.DescAcabamento, dbo.produtos.Pro_unidade, venda.Ven_DataEmissao, 
                      dbo.GrupoProduto.GrupoProduto_Descricao, dbo.produtos.Pro_tp_peca,venda.ParSV_serie,VendaAmbiente.VenAmb_Descricao


