-- [Qryprodutos : TADOQuery]
SELECT dbo.VendaProduto.Pro_codnosso, dbo.produtos.Pro_descricao, dbo.produtos.Pro_tp_peca, dbo.produtos.Pro_tp_produto, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto, 
                  dbo.fornecedor.For_Nome, SUM(dbo.VendaProduto.VenPro_Quantidade) AS VenPro_Quantidade, AVG(dbo.VendaProduto.VenPro_VlUnitario) AS VenPro_VlUnitario, 
                  SUM(dbo.VendaProduto.VenPro_Quantidade * dbo.VendaProduto.VenPro_VlUnitario) AS total, dbo.produtos.Pro_CodEspecial
FROM     dbo.Venda INNER JOIN
                  dbo.VendaProduto ON dbo.Venda.Ven_CodigoPre = dbo.VendaProduto.Ven_CodigoPre INNER JOIN
                  dbo.produtos ON dbo.VendaProduto.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                  dbo.ProdutosFornecedores ON dbo.produtos.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso INNER JOIN
                  dbo.fornecedor ON dbo.ProdutosFornecedores.For_codigo = dbo.fornecedor.For_codigo
WHERE  (dbo.ProdutosFornecedores.ProdFor_Padrao = 1)
GROUP BY dbo.VendaProduto.Pro_codnosso, dbo.produtos.Pro_descricao, dbo.produtos.Pro_tp_peca, dbo.produtos.Pro_tp_produto, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto, 
                  dbo.fornecedor.For_Nome, dbo.produtos.Pro_CodEspecial

-- [Qrytotal : TADOQuery]
SELECT SUM(dbo.VendaProduto.VenPro_Quantidade * dbo.VendaProduto.VenPro_VlUnitario) AS total
FROM     dbo.Venda INNER JOIN
                  dbo.VendaProduto ON dbo.Venda.Ven_CodigoPre = dbo.VendaProduto.Ven_CodigoPre INNER JOIN
                  dbo.produtos ON dbo.VendaProduto.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                  dbo.ProdutosFornecedores ON dbo.produtos.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso INNER JOIN
                  dbo.fornecedor ON dbo.ProdutosFornecedores.For_codigo = dbo.fornecedor.For_codigo
WHERE  (dbo.ProdutosFornecedores.ProdFor_Padrao = 1)


