                      dbo.Venda.Ven_TipoDesc, dbo.Venda.Ven_FormaPagExtra, dbo.Venda.Ven_Eletricista, dbo.Venda.Ven_TotalServ, dbo.Venda.Ven_PagReduzido, 
                      dbo.Venda.Ven_LimiteDesconto, dbo.Venda.par_ParcelarVlAcima, dbo.Venda.par_VlMinParcela, dbo.Venda.par_QuantMaxParcela, dbo.Obras.Obr_Descricao

