/* ============================================================
   FORM: frmSelRelEntDevolucao   Relatório de entrada por devolução
   ============================================================ */

-- [QryLuminarias : TADOQuery]
SELECT     dbo.Devolucao.Dev_codigo, dbo.Devolucao.Dev_CodigoPre, dbo.Devolucao.ven_codigopre, dbo.Devolucao.Dev_Dtemissao, dbo.VendaAmbiente.VenAmb_Descricao, 
                      dbo.DevolucaoProduto.DevPro_Seq, dbo.DevolucaoProduto.DevPro_SeqItem, dbo.DevolucaoProduto.CodAmbiente, dbo.DevolucaoProduto.CodAcabamento, 
                      dbo.DevolucaoProduto.Pro_codnosso, dbo.DevolucaoProduto.DevPro_VlUnitario, dbo.DevolucaoProduto.DevPro_VlItem, dbo.DevolucaoProduto.DevPro_Quantidade, 
                      dbo.DevolucaoProduto.DevPro_QuantidadeOriginal, DevolucaoProduto.DevPro_motivodev, Motivo_devolucao.Mod_descricao,DevolucaoProduto.DevPro_usuarioestoque, 
                      dbo.produtos.Pro_descricao, dbo.produtos.Pro_descricao_for, dbo.produtos.Pro_tp_peca, 
                      dbo.produtos.Pro_Codbase, dbo.produtos.Pro_CodEspecial, dbo.GrupoProduto.GrupoProduto_Descricao, dbo.GrupoProduto.GrupoProduto_ordem, 
                      dbo.Venda.Ven_codigo, dbo.Venda.Ven_Situacao, dbo.Venda.Ven_CodigoPre AS Expr1, dbo.Devolucao.Dev_situacao, dbo.Clientes.Cli_Nome, 
                      dbo.Venda.Ven_DataEmissao, CASE WHEN Devolucao.Dev_TipoDesc = 'P' THEN DevolucaoProduto.DevPro_VlItem ELSE CASE WHEN Dev_DescontoPorcProd IS NULL
                       THEN DevolucaoProduto.DevPro_VlItem ELSE DevolucaoProduto.DevPro_VlItem - DevolucaoProduto.DevPro_VlItem * (Dev_DescontoPorcProd / 100) 
                      END END AS valoritemdesc,  
                      CASE WHEN DevolucaoDesagio.DevDes_porcentagem > 0 THEN CASE WHEN Devolucao.Dev_TipoDesc = 'P' THEN DevolucaoProduto.DevPro_VlItem ELSE CASE WHEN
                       Dev_DescontoPorcProd IS NULL 
                      THEN DevolucaoProduto.DevPro_VlItem ELSE DevolucaoProduto.DevPro_VlItem - DevolucaoProduto.DevPro_VlItem * (Dev_DescontoPorcProd / 100) 
                      END END * (DevolucaoDesagio.DevDes_porcentagem / 100) ELSE 0 END AS ValorDesagio
FROM         dbo.Devolucao INNER JOIN
                      dbo.DevolucaoProduto ON dbo.Devolucao.Dev_CodigoPre = dbo.DevolucaoProduto.Dev_CodigoPre INNER JOIN
                      dbo.VendaAmbiente ON dbo.Devolucao.ven_codigopre = dbo.VendaAmbiente.VenAmb_NDocPre AND 
                      dbo.DevolucaoProduto.CodAmbiente = dbo.VendaAmbiente.CodAmbiente INNER JOIN
                      Motivo_devolucao ON dbo.DevolucaoProduto.DevPro_motivodev = Motivo_devolucao.mod_codigo INNER JOIN
                      dbo.produtos ON dbo.DevolucaoProduto.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                      dbo.GrupoProduto ON dbo.produtos.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo INNER JOIN
                      dbo.Venda ON dbo.Devolucao.ven_codigopre = dbo.Venda.Ven_CodigoPre INNER JOIN
                      dbo.Clientes ON dbo.Venda.Ven_CodVinculo = dbo.Clientes.Cli_Codigo LEFT OUTER JOIN
                      dbo.DevolucaoDesagio ON dbo.produtos.GrupoProduto_codigo = dbo.DevolucaoDesagio.GrupoProduto_Codigo AND 
                      dbo.Devolucao.Dev_CodigoPre = dbo.DevolucaoDesagio.Dev_codigopre

-- [QryServicos : TADOQuery]
SELECT DevolucaoServico.DevSer_item, DevolucaoServico.Dev_codigopre, DevolucaoServico.Sev_cod, Servicos.Serv_Desc,
 DevolucaoServico.DevSer_quantidade, DevolucaoServico.DevSer_vlunitario, DevolucaoServico.DevSer_vlitem,
DevolucaoServico.DevSer_VlEletricista, Devolucao.Dev_codigo, Clientes.Cli_Nome,
 Venda.Ven_codigo, Venda.Ven_CodigoPre, Venda.Ven_Situacao,Venda.Ven_DataEmissao, Devolucao.dev_situacao
 FROM Devolucao INNER JOIN DevolucaoServico ON Devolucao.Dev_CodigoPre = DevolucaoServico.Dev_codigopre INNER JOIN
 Servicos ON DevolucaoServico.Sev_cod = Servicos.sev_cod INNER JOIN
 Venda ON Devolucao.ven_codigopre = Venda.Ven_CodigoPre INNER JOIN Clientes ON Venda.Ven_CodVinculo = Clientes.Cli_Codigo

