-- [QryProjetos : TADOQuery]
SELECT Venda.Ven_codigo, Venda.ParSV_serie, Venda.Ven_DataEmissao, Venda.Ven_DataFechaVenda, Venda.Ven_Situacao, Clientes.Cli_Nome, Venda.Ven_CodigoPre
FROM     Venda INNER JOIN
                  Devolucao ON Venda.Ven_CodigoPre = Devolucao.ven_codigopre INNER JOIN
                  Clientes ON Venda.Ven_CodVinculo = Clientes.Cli_Codigo
WHERE     (dbo.Venda.Ven_Situacao = 'A') and Devolucao.Dev_Dtemissao >=:DATAINI and Devolucao.Dev_Dtemissao <=:DataFim
GROUP BY Venda.Ven_codigo, Venda.ParSV_serie, Venda.Ven_DataEmissao, Venda.Ven_DataFechaVenda, Venda.Ven_Situacao, Clientes.Cli_Nome, Venda.Ven_CodigoPre

