-- [QryServicos : TADOQuery]
SELECT     pedido.ped_codigo, pedido.ped_dt_fechamento, Saida_complementacao.scp_cliente, Funcionario.Fun_Nome, 
                      Indicacoes.Ind_Nome, Saida_comp_servico_det.sse_descricao, Saida_comp_servico_det.sse_quantidade, Saida_comp_servico_det.sse_vl_unitario, 
                      Saida_comp_servico_det.sse_vl_item,saida_complementacao.scp_status
FROM         pedido INNER JOIN
                      Saida_complementacao ON pedido.ped_codigo = Saida_complementacao.ped_codigo INNER JOIN
                      Funcionario ON pedido.ped_arquiteta = Funcionario.Fun_CPF INNER JOIN
                      Indicacoes ON pedido.ped_indicacao = Indicacoes.Ind_codigo INNER JOIN
                      Saida_comp_servico_det ON Saida_complementacao.Scp_codigo_pre = Saida_comp_servico_det.Scp_codigo_pre

-- [QryLuminarias : TADOQuery]
SELECT     pedido.ped_codigo, pedido.ped_dt_fechamento, Saida_complementacao.scp_cliente, Ambiente.DescAmbiente, Funcionario.Fun_Nome, 
                      Indicacoes.Ind_Nome, Saida_comp_luminaria_det.sld_seq, Saida_comp_luminaria_det.sld_seq_item, Saida_comp_luminaria_det.Pro_codnosso, 
                      Saida_comp_luminaria_det.sld_produto, Saida_comp_luminaria_det.sld_quantidade, Saida_comp_luminaria_det.sld_vl_unitario, 
                      Saida_comp_luminaria_det.sld_vl_item, Saida_comp_luminaria_det.sld_acabamento,saida_complementacao.scp_status
FROM         pedido INNER JOIN
                      Saida_complementacao ON pedido.ped_codigo = Saida_complementacao.ped_codigo INNER JOIN
                      Saida_comp_luminaria_det ON Saida_complementacao.Scp_codigo = Saida_comp_luminaria_det.scp_codigo_pre INNER JOIN
                      Ambiente ON Saida_comp_luminaria_det.sld_ambiente = Ambiente.CodAmbiente INNER JOIN
                      Funcionario ON pedido.ped_arquiteta = Funcionario.Fun_CPF INNER JOIN
                      Indicacoes ON pedido.ped_indicacao = Indicacoes.Ind_codigo

-- [QryMateriais : TADOQuery]
SELECT     pedido.ped_codigo, pedido.ped_dt_fechamento, Saida_complementacao.scp_cliente, Ambiente.DescAmbiente, Funcionario.Fun_Nome, 
                      Indicacoes.Ind_Nome, Saida_comp_servico_det.sse_descricao, Saida_comp_servico_det.sse_quantidade, Saida_comp_servico_det.sse_vl_unitario, 
                      Saida_comp_servico_det.sse_vl_item,saida_complementacao.scp_status
FROM         pedido INNER JOIN
                      Saida_complementacao ON pedido.ped_codigo = Saida_complementacao.ped_codigo INNER JOIN
                      Funcionario ON pedido.ped_arquiteta = Funcionario.Fun_CPF INNER JOIN
                      Indicacoes ON pedido.ped_indicacao = Indicacoes.Ind_codigo INNER JOIN
                      Saida_comp_servico_det ON Saida_complementacao.Scp_codigo_pre = Saida_comp_servico_det.Scp_codigo_pre CROSS JOIN
                      Ambiente

-- [QryProjetos : TADOQuery]
SELECT     DISTINCT Saida_complementacao.ped_codigo, Saida_complementacao.scp_cliente, pedido.ped_dt_fechamento
FROM         Saida_complementacao INNER JOIN
                      pedido ON Saida_complementacao.ped_codigo = pedido.ped_codigo
WHERE scp_data >= :DataIni AND scp_data <= :DataFim
AND ped_status = 'A'

