   ============================================================ */

-- [QryCliente : TADOQuery]
SELECT DISTINCT 
  dbo.Clientes.Cli_Codigo,
  dbo.Clientes.Cli_Nome
FROM
  dbo.Clientes WITH (NOLOCK)
  INNER JOIN dbo.Controle_entrega WITH (NOLOCK) ON (dbo.Clientes.Cli_Codigo = dbo.Controle_entrega.cli_codigo)
order by Clientes.Cli_Nome

-- [QryProjetos : TADOQuery]
SELECT
  dbo.Controle_entrega.cen_pedido_avulso
FROM
  dbo.Controle_entrega WITH (NOLOCK)
WHERE
  (dbo.Controle_entrega.cli_codigo = :Pcli_codigo) and Controle_entrega.ParSV_serie=:PParSV_serie
order by Controle_entrega.cen_pedido_avulso

-- [QryData : TADOQuery]
SELECT DISTINCT 
  dbo.controle_entrega_data.ced_data,
  dbo.controle_entrega_data.cen_codigo_pre,
  Controle_entrega.cen_modo,
  dbo.controle_entrega_data.ced_ordem
FROM
  dbo.controle_entrega_data WITH (NOLOCK)
  INNER JOIN dbo.Controle_entrega WITH (NOLOCK) ON (dbo.controle_entrega_data.cen_codigo_pre = dbo.Controle_entrega.cen_codigo_pre)
WHERE
  (dbo.controle_entrega_data.cep_tipo = 'E' or dbo.controle_entrega_data.cep_tipo  is  null) AND
dbo.controle_entrega_data.cep_operacao = 'E'  and
  (dbo.Controle_entrega.cen_pedido_avulso = :Pcen_pedido_avulso)
and Controle_entrega.ParSV_serie=:PParSV_serie
order by   dbo.controle_entrega_data.ced_data,  dbo.controle_entrega_data.ced_ordem


