-- [QryContasBancarias : TADOQuery]
SELECT     dbo.Bancos_Caixas.Bcx_situacao, dbo.Contas_Bancarias.Cba_codigo, dbo.Contas_Bancarias.Bcx_codigo, 
                      dbo.Contas_Bancarias.Emp_codigo, dbo.Bancos_Caixas.Bcx_Nome, dbo.Contas_Bancarias.Cba_numero, 
                      CASE WHEN Bancos_Caixas.Bcx_tipo = 'B' THEN 'Banco: ' + dbo.Bancos_Caixas.Bcx_Nome + ' - AG: ' + dbo.Bancos_Caixas.Bcx_agencia + ' CT: ' + dbo.Contas_Bancarias.Cba_numero
                       ELSE 'Caixa: ' + Contas_Bancarias.Cba_numero + ' - ' + dbo.Bancos_Caixas.Bcx_Nome END AS nome, dbo.Contas_Bancarias.Cba_Saldo_inicial, 
                      dbo.Bancos_Caixas.Bcx_tipo, dbo.Bancos_Caixas.Bcx_agencia
FROM         dbo.Bancos_Caixas LEFT OUTER JOIN
                      dbo.Contas_Bancarias ON dbo.Bancos_Caixas.Bcx_codigo = dbo.Contas_Bancarias.Bcx_codigo AND 
                      dbo.Bancos_Caixas.Bcx_codigo = dbo.Contas_Bancarias.Bcx_codigo AND dbo.Bancos_Caixas.Bcx_codigo = dbo.Contas_Bancarias.Bcx_codigo AND 
                      dbo.Bancos_Caixas.Bcx_codigo = dbo.Contas_Bancarias.Bcx_codigo AND dbo.Bancos_Caixas.Emp_codigo = dbo.Contas_Bancarias.Emp_codigo AND
                       dbo.Bancos_Caixas.Emp_codigo = dbo.Contas_Bancarias.Emp_codigo AND 
                      dbo.Bancos_Caixas.Emp_codigo = dbo.Contas_Bancarias.Emp_codigo AND 
                      dbo.Bancos_Caixas.Emp_codigo = dbo.Contas_Bancarias.Emp_codigo
where Contas_Bancarias.Cba_situacao ='A'
ORDER BY dbo.Bancos_Caixas.Bcx_Nome


/* ============================================================
   FORM: FrmVendasNfeNfce   Consulta de valores Nfe, NFCe de pré-venda
   ============================================================ */

-- [Qryvenda : TADOQuery]
SELECT dbo.VendaAtendente.Fun_Codigo, SUM(dbo.NotaFiscal.NTF_VLProdutos) AS NTF_VLProdutos, SUM(dbo.NotaFiscal.NTF_VlNota) AS NTF_VlNota, SUM(dbo.NotaFiscal.NTF_Desconto) AS NTF_Desconto, dbo.Funcionario.Fun_Nome
FROM     dbo.Venda INNER JOIN
                  dbo.NotaFiscal INNER JOIN
                  dbo.NotaFiscalImportaDoc ON dbo.NotaFiscal.NTF_Codigo = dbo.NotaFiscalImportaDoc.NTF_Codigo ON dbo.Venda.Ven_codigo = dbo.NotaFiscalImportaDoc.NTFImp_DocCodigo INNER JOIN
                  dbo.VendaAtendente ON dbo.Venda.Ven_CodigoPre = dbo.VendaAtendente.VenAten_NDocPre INNER JOIN
                  dbo.Funcionario ON dbo.VendaAtendente.Emp_Codigo = dbo.Funcionario.Emp_codigo AND dbo.VendaAtendente.Fun_Codigo = dbo.Funcionario.Fun_CPF
WHERE  (dbo.Venda.Ven_Tipo = 'V') AND (dbo.NotaFiscal.NTF_DtEmissao >= :data1) AND (dbo.NotaFiscal.NTF_DtEmissao <= :data2)
GROUP BY dbo.VendaAtendente.Fun_Codigo, dbo.Funcionario.Fun_Nome

-- [QryTroca : TADOQuery]
SELECT dbo.VendaAtendente.Fun_Codigo, SUM(dbo.NotaFiscal.NTF_VLProdutos) AS NTF_VLProdutos, SUM(dbo.NotaFiscal.NTF_VlNota) AS NTF_VlNota, SUM(dbo.NotaFiscal.NTF_Desconto) AS NTF_Desconto, dbo.Funcionario.Fun_Nome
FROM     dbo.Venda INNER JOIN
                  dbo.NotaFiscal INNER JOIN
                  dbo.NotaFiscalImportaDoc ON dbo.NotaFiscal.NTF_Codigo = dbo.NotaFiscalImportaDoc.NTF_Codigo ON dbo.Venda.Ven_codigo = dbo.NotaFiscalImportaDoc.NTFImp_DocCodigo INNER JOIN
                  dbo.VendaAtendente ON dbo.Venda.Ven_CodigoPre = dbo.VendaAtendente.VenAten_NDocPre INNER JOIN
                  dbo.Funcionario ON dbo.VendaAtendente.Emp_Codigo = dbo.Funcionario.Emp_codigo AND dbo.VendaAtendente.Fun_Codigo = dbo.Funcionario.Fun_CPF
WHERE  (dbo.Venda.Ven_Tipo = 'V') AND (dbo.NotaFiscal.NTF_DtEmissao >= :data1) AND (dbo.NotaFiscal.NTF_DtEmissao <= :data2)
GROUP BY dbo.VendaAtendente.Fun_Codigo, dbo.Funcionario.Fun_Nome


/* ============================================================
   FORM: FrmVincularContaPagar   FrmVincularContaPagar
   ============================================================ */

-- [Qryparcela : TADOQuery]
SELECT        dbo.contas_apagar.Ctp_codigo AS CodigoConta, dbo.contas_apagar_det.ctp_codigo_det AS CodigoContaParcela, dbo.contas_apagar.Ctp_nome AS nome, 
                         dbo.contas_apagar.Ctp_cod_documento AS codigodoc, dbo.contas_apagar.Ctp_historico AS historico, dbo.Plano_Contas.Pco_descricao AS PlanoConta, 
                         dbo.Tipo_documento.Tpd_descricao AS TipoConta, dbo.contas_apagar_det.Ctp_parcela AS Parcela, dbo.contas_apagar_det.Ctp_dt_vencimento AS DataVencimento, 
                         dbo.contas_apagar_det.Ctp_valor_vencimento AS Valor, dbo.contas_apagar_det.Ctp_CodigoBarra AS codigobarra, 
                         dbo.forma_pagamento_fin.Fpf_descricao AS formapagamento
, contas_apagar.Pco_codigo, contas_apagar.tpd_codigo, contas_apagar.cdc_codigo
FROM            dbo.contas_apagar INNER JOIN
                         dbo.contas_apagar_det ON dbo.contas_apagar.Ctp_codigo = dbo.contas_apagar_det.Ctp_codigo LEFT OUTER JOIN
                         dbo.forma_pagamento_fin ON dbo.contas_apagar.Ctp_forma_pag = dbo.forma_pagamento_fin.Fpf_codigo LEFT OUTER JOIN
                         dbo.Tipo_documento ON dbo.contas_apagar.Tpd_codigo = dbo.Tipo_documento.Tpd_codigo LEFT OUTER JOIN
                         dbo.Plano_Contas ON dbo.contas_apagar.Pco_codigo = dbo.Plano_Contas.Pco_codigo
WHERE        (dbo.contas_apagar_det.Ctp_situacao = 'N')

-- [Qryagrupado : TADOQuery]
SELECT contas_apagar.Ctp_codigo AS CodigoConta, contas_apagar_det.ctp_codigo_det AS CodigoContaParcela, contas_apagar.Ctp_nome AS nome,
 contas_apagar.Ctp_cod_documento AS codigodoc, contas_apagar.Ctp_historico AS historico, Plano_Contas.Pco_descricao AS PlanoConta,
 Tipo_documento.Tpd_descricao AS TipoConta, contas_apagar_det.Ctp_parcela AS Parcela, contas_apagar_det.Ctp_dt_vencimento AS DataVencimento,
 contas_apagar_det.Ctp_valor_vencimento AS Valor, contas_apagar_det.Ctp_CodigoBarra AS codigobarra,
 forma_pagamento_fin.Fpf_descricao AS formapagamento , contas_apagar.Pco_codigo, contas_apagar.tpd_codigo, contas_apagar.cdc_codigo,Modo.Mdo_nome
, 0 as selecionado 
 FROM contas_apagar INNER JOIN 
 contas_apagar_det ON contas_apagar.Ctp_codigo = contas_apagar_det.Ctp_codigo LEFT OUTER JOIN
 Modo ON contas_apagar_det.Mdo_codigo = Modo.Mdo_codigo LEFT OUTER JOIN
 forma_pagamento_fin ON dbo.contas_apagar.Ctp_forma_pag = forma_pagamento_fin.Fpf_codigo LEFT OUTER JOIN
 Tipo_documento ON contas_apagar.Tpd_codigo = Tipo_documento.Tpd_codigo LEFT OUTER JOIN
 Plano_Contas ON contas_apagar.Pco_codigo = Plano_Contas.Pco_codigo


