/* ============================================================
   FORM: Rel_ConsultaComissao   
   ============================================================ */

-- [Qry_ConsultaComissao : TADOQuery]
SELECT  CASE WHEN FechamentoComissao.FechComis_Situacao = 'A' THEN 'ABERTO' ELSE 'FECHADO' END AS situacao,
 CASE WHEN ControleRH.CtrlRH_TpDocOri = 1002 THEN (SELECT avu_dt_emissao FROM Avulso
 wHERE avu_codigo = ControleRH.CtrlRH_codDocOri) ELSE CASE 
WHEN ControleRH.CtrlRH_TpDocOri = 1001 THEN 
(SELECT ped_dt_fechamento FROM pedido WHERE ped_codigo = ControleRH.CtrlRH_codDocOri) 
ELSE CASE WHEN ControleRH.CtrlRH_TpDocOri = 1017 THEN 
(SELECT edv_data FROM Ent_devolucao WHERE edv_codigo = ControleRH.CtrlRH_codDocOri)
 ELSE CASE WHEN ControleRH.CtrlRH_TpDocOri = 1018 THEN
 (SELECT Scp_data FROM Saida_complementacao WHERE Scp_codigo = ControleRH.CtrlRH_codDocOri)
 ELSE CASE WHEN ControleRH.CtrlRH_TpDocOri = 1009 THEN 
(SELECT Fact_DtEmissao FROM Factura WHERE Fact_Codigo = ControleRH.CtrlRH_codDocOri AND Fact_Tipo = 'FCT')
 ELSE CASE WHEN ControleRH.CtrlRH_TpDocOri = 1012 THEN 
(SELECT Fact_DtEmissao FROM Factura WHERE Fact_Codigo = ControleRH.CtrlRH_codDocOri AND Fact_Tipo = 'VDI')
 END END END END END END AS datavend, 
Funcionario.Fun_Nome, ControleRH.CtrlRH_Valor, dbo.ControleRH.CtrlRH_Operacao, 
CASE WHEN ControleRH.Tpd_codigo = 1014 THEN 'COMISSÃO' ELSE CASE WHEN ControleRH.Tpd_codigo = 1015 
THEN 'PREMIAÇÃO' ELSE CASE WHEN ControleRH.Tpd_codigo = 1019 THEN 'PARTICIPAÇÃO' ELSE 'RATEIO' END END END
 AS tipo, dbo.contas_apagar_det.Ctp_dt_vencimento, ControleRH.CtrlRH_CodDocOri,  (SELECT SUM(CtrlRH_Valor) AS Expr1 FROM ControleRH AS ControleRHC WHERE (CtrlRH_Operacao = 'C') 
AND (FechComis_Codigo = dbo.ControleRH.FechComis_Codigo)) AS TotalCredito, 
(SELECT SUM(CtrlRH_Valor) AS Expr1 FROM ControleRH AS ControleRHD WHERE (CtrlRH_Operacao = 'D') AND
 (FechComis_Codigo = dbo.ControleRH.FechComis_Codigo)) AS TotalDebito 
,CASE WHEN ControleRH.CtrlRH_TpDocOri = 1002 THEN 'VENDA AVULSA' ELSE CASE 
WHEN ControleRH.CtrlRH_TpDocOri = 1001 THEN 
'PROJETO'
ELSE CASE WHEN ControleRH.CtrlRH_TpDocOri = 1017 THEN 
'ENTRADA POR DEVOLUÇÃO'
 ELSE CASE WHEN ControleRH.CtrlRH_TpDocOri = 1018 THEN
 'SAÍDA POR COMPLEMENTAÇÃO'	
 ELSE CASE WHEN ControleRH.CtrlRH_TpDocOri = 1009 THEN 
'FACTURA'
 ELSE CASE WHEN ControleRH.CtrlRH_TpDocOri = 1012 THEN 
'VENDA A DINHEIRO'
 END END END END END END AS TIPOVENDA, 0.00  AS TotalCreditoBloq, 0.00  AS TotalDEBITOBloq
 ,case when ControleRH.CtrlRH_ContaRefVincDet is not null and ControleRH.CtrlRH_Pendente is null then 'B' else ' ' end as sitlanc 
, ControleRH.CtrlRH_ComPreCondTP, ControleRH.ComPre_codigo, ComissaoPremiacao.ComPre_Descricao,
ControleRH.CtrlRH_TpDocOri

FROM ControleRH INNER JOIN
    FechamentoComissao ON ControleRH.FechComis_Codigo = FechamentoComissao.FechComis_Codigo INNER JOIN
    Funcionario ON ControleRH.Fun_Codigo = Funcionario.Fun_CPF INNER JOIN
    contas_apagar_det ON FechamentoComissao.FechComis_ContaUnica = contas_apagar_det.Ctp_codigo LEFT OUTER JOIN
    ComissaoPremiacao ON ControleRH.ComPre_codigo = ComissaoPremiacao.ComPre_codigo


 WHERE (ControleRH.CtrlRH_VendaExcluida IS NULL OR ControleRH.CtrlRH_VendaExcluida = 'N')


