/* ============================================================
   FORM: RelExtBancario   
   ============================================================ */

-- [QryExtrato : TADOQuery]
SELECT     Mba_operacao, Mba_historico, Mba_valor, Mba_din_che_tra, Mba_data_emissao, Mba_data_efetivacao, Mba_efetivado, Cba_codigo, 
                      CASE WHEN Cpp_cod_pag IS NOT NULL THEN 'CP' ELSE CASE WHEN Crp_cod_pag IS NOT NULL THEN 'CR' ELSE 'DI' END END AS via, 
                      Mba_numero_cheque, Mba_conta_corrente, Mba_agencia, Mba_emitente, Mba_nome_banco, Mba_cpf_cnpj_emitente
FROM         dbo.Movimento_bancario

-- [QrySaldo : TADOQuery]
SELECT     (SELECT     CASE WHEN SUM(CASE WHEN credito.mba_operacao = 'CRÉDITO' THEN credito.mba_valor ELSE 0 END) IS NOT NULL 
                                              THEN SUM(CASE WHEN credito.mba_operacao = 'CRÉDITO' THEN credito.mba_valor ELSE 0 END) ELSE 0 END AS Expr1
                       FROM          dbo.Movimento_bancario AS credito
                       WHERE      (Mba_efetivado = 'S')) -
                          (SELECT     CASE WHEN SUM(CASE WHEN credito.mba_operacao = 'DÉBITO' THEN credito.mba_valor ELSE 0 END) IS NOT NULL 
                                                   THEN SUM(CASE WHEN credito.mba_operacao = 'DÉBITO' THEN credito.mba_valor ELSE 0 END) ELSE 0 END AS Expr1
                            FROM          dbo.Movimento_bancario AS credito
                            WHERE      (Mba_efetivado = 'S')) AS Saldo


