SELECT dbo.controle_entrega_data.Pro_codnosso, dbo.controle_entrega_data.cep_acabamento, SUM(dbo.controle_entrega_data.ced_quantidade) AS ced_quantidade, dbo.controle_entrega_data.cep_tipo, dbo.produtos.Pro_descricao, 
                  dbo.Acabamento.DescAcabamento, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, 
                  dbo.ProdutosLocEstoque.ProdLocEst_Predio + ' - ' + dbo.ProdutosLocEstoque.ProdLocEst_Rua + ' - ' + dbo.ProdutosLocEstoque.ProdLocEst_Numero + ' - ' + dbo.ProdutosLocEstoque.ProdLocEst_Apto AS LOCALIZACAO, 
                  dbo.controle_entrega_data.cen_codigo_pre, produtos.Pro_PesoBruto, produtos.Pro_CodEspecial
FROM     dbo.controle_entrega_data INNER JOIN
                  dbo.produtos ON dbo.controle_entrega_data.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                  dbo.Acabamento ON dbo.controle_entrega_data.cep_acabamento = dbo.Acabamento.CodAcabamento INNER JOIN
                  dbo.ProdutosFornecedores ON dbo.controle_entrega_data.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso LEFT OUTER JOIN
                  dbo.ProdutosLocEstoque ON dbo.controle_entrega_data.Pro_codnosso = dbo.ProdutosLocEstoque.Pro_codnosso AND dbo.controle_entrega_data.cep_acabamento = dbo.ProdutosLocEstoque.CodAcabamento
WHERE  (dbo.controle_entrega_data.cep_tipo = 'S') and controle_entrega_data.cen_codigo_pre =:pcen_codigo_pre  and controle_entrega_data.Ced_ordemSeparacao =:pCed_ordemSeparacao
GROUP BY dbo.controle_entrega_data.Pro_codnosso, dbo.controle_entrega_data.cep_acabamento, dbo.controle_entrega_data.cep_tipo, dbo.produtos.Pro_descricao, dbo.Acabamento.DescAcabamento, 
                  dbo.ProdutosFornecedores.ProdFor_CodigoProduto, 
                  dbo.ProdutosLocEstoque.ProdLocEst_Predio + ' - ' + dbo.ProdutosLocEstoque.ProdLocEst_Rua + ' - ' + dbo.ProdutosLocEstoque.ProdLocEst_Numero + ' - ' + dbo.ProdutosLocEstoque.ProdLocEst_Apto, 
                  dbo.controle_entrega_data.cen_codigo_pre,produtos.Pro_PesoBruto,produtos.Pro_CodEspecial


