-- [QryAssistProduto : TADOQuery]
SELECT dbo.produtos.Pro_descricao, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto, dbo.GrupoProduto.GrupoProduto_Descricao, dbo.produtos.Pro_tp_peca, 
                  dbo.Assistencia_TecnicaProdutos.ASTECProd_Codigo, dbo.Assistencia_TecnicaProdutos.ASTEC_Codigo, dbo.Assistencia_TecnicaProdutos.Pro_codnosso, dbo.Assistencia_TecnicaProdutos.CodAcabamento, 
                  dbo.Assistencia_TecnicaProdutos.ASTECProd_quantidade, dbo.Assistencia_TecnicaProdutos.ASTECProd_Motivo, dbo.Assistencia_TecnicaProdutos.usr_cod_criacao, dbo.Assistencia_TecnicaProdutos.usr_dt_hr_criacao, 
                  dbo.Assistencia_TecnicaProdutos.usr_cod_alteracao, dbo.Assistencia_TecnicaProdutos.usr_dt_hr_alteracao, dbo.Assistencia_TecnicaProdutos.Emp_codigo
FROM     dbo.ProdutosFornecedores INNER JOIN
                  dbo.produtos ON dbo.ProdutosFornecedores.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
