   FORM: RltBalancoEstoque   
   ============================================================ */

-- [Qrybalanco : TADOQuery]
SELECT dbo.BalancoEstoque.BalEst_Codigo, dbo.BalancoEstoque.BalEst_Descricao, dbo.BalancoEstoque.BalEst_DataProc, dbo.BalancoEstoqueProdutos.Pro_Codnosso, dbo.BalancoEstoqueProdutos.CodAcabamento, 
                  dbo.BalancoEstoqueProdutos.BalEstProd_Quantidade, dbo.fornecedor.For_Nome, dbo.produtos.Pro_tp_peca, dbo.GrupoProduto.GrupoProduto_Descricao, dbo.produtos.Pro_unidade, 
                  CASE WHEN dbo.BalancoEstoque.BalEst_Processado = 1 THEN 'SIM' ELSE 'NÃO' END AS BalEst_Processado, CASE WHEN dbo.SisUsuarios.Nome IS NOT NULL THEN dbo.SisUsuarios.Nome ELSE '' END AS SisUsuarios, 
                  dbo.BalancoEstoque.BalEst_Data, dbo.produtos.Pro_descricao, dbo.produtos.Pro_CodEspecial, dbo.Estoque_produto.Epr_estoque, dbo.ProdutosFornecedores.ProdFor_CodigoProduto AS Pro_Codbase, 
                  dbo.ProdutosFornecedores.ProdFor_DescricaoProduto AS Pro_descricao_for
FROM     dbo.ProdutosFornecedores INNER JOIN
                  dbo.fornecedor ON dbo.ProdutosFornecedores.For_codigo = dbo.fornecedor.For_codigo INNER JOIN
                  dbo.Estoque_produto INNER JOIN
                  dbo.BalancoEstoque INNER JOIN
                  dbo.BalancoEstoqueProdutos ON dbo.BalancoEstoque.BalEst_Codigo = dbo.BalancoEstoqueProdutos.BalEst_Codigo ON dbo.Estoque_produto.Epr_Codnosso = dbo.BalancoEstoqueProdutos.Pro_Codnosso AND 
                  dbo.Estoque_produto.Epr_Acabamento = dbo.BalancoEstoqueProdutos.CodAcabamento INNER JOIN
                  dbo.GrupoProduto INNER JOIN
                  dbo.produtos ON dbo.GrupoProduto.GrupoProduto_Codigo = dbo.produtos.GrupoProduto_codigo ON dbo.BalancoEstoqueProdutos.Pro_Codnosso = dbo.produtos.Pro_codnosso ON 
                  dbo.ProdutosFornecedores.Pro_codnosso = dbo.produtos.Pro_codnosso LEFT OUTER JOIN
                  dbo.SisUsuarios ON dbo.BalancoEstoque.BalEst_UsuarioProc = dbo.SisUsuarios.Id

WHERE        (dbo.Estoque_produto.EstTp_Codigo = 1) and   BalancoEstoque.BalEst_Codigo =:pBalEst_Codigo


