   FORM: RltCadControleCheque   
   ============================================================ */

-- [QryControleDet : TADOQuery]
SELECT  'A RECEBER' AS tipoconta,  CASE WHEN ControleChequeDet.ControlChequeDet_Vinculo = 'OUTROS ' THEN ControleChequeDet.ControlChequeDet_emitente WHEN ControleChequeDet.ControlChequeDet_Vinculo
                       = 'CLIENTE' THEN
                          (SELECT     cli_nome
                            FROM          clientes
                            WHERE      clientes.cli_codigo = ControleChequeDet.ControlChequeDet_vinculocodigo) 
                      WHEN ControleChequeDet.ControlChequeDet_Vinculo = 'INDICAÇÃO' THEN
                          (SELECT     ind_nome
                            FROM          indicacoes
                            WHERE      indicacoes.ind_codigo = ControleChequeDet.ControlChequeDet_vinculocodigo) 
                      WHEN ControleChequeDet.ControlChequeDet_Vinculo = 'FORNECEDOR' THEN
                          (SELECT     for_nome
                            FROM          fornecedor
                            WHERE      fornecedor.for_codigo = ControleChequeDet.ControlChequeDet_vinculocodigo) 
                      WHEN ControleChequeDet.ControlChequeDet_Vinculo = 'PESSOAL' THEN
                          (SELECT     fun_nome
                            FROM          funcionario
                            WHERE      funcionario.fun_cpf = ControleChequeDet.ControlChequeDet_vinculocodigo) 
                      WHEN ControleChequeDet.ControlChequeDet_Vinculo = 'MATRIZ/FILIAL' THEN
                          (SELECT     fil_fantasia
                            FROM          filiais
                            WHERE      filiais.fil_codigo = ControleChequeDet.ControlChequeDet_vinculocodigo) END AS nome, 
                      dbo.ControleChequeDet.ControlChequeDet_Tipo AS tipo, dbo.contas_receber.Ctr_cod_documento AS numdoc, 
                      dbo.Tipo_documento.Tpd_descricao AS documento, dbo.ControleChequeDet.ControlChequeDet_Vinculo AS vinculo, 
                      dbo.ControleChequeDet.ControlChequeDet_NumCheque AS numcheque, dbo.ControleChequeDet.ControlChequeDet_Conta AS Conta, 
                      dbo.ControleChequeDet.ControlChequeDet_Agencia AS agencia, dbo.Bancos.Ban_Nome AS banco, dbo.ControleChequeDet.ControlChequeDet_Codigo, 
                      dbo.Contas_receber_pag.Crp_data_pagamento AS data, dbo.ControleChequeDet.ControlChequeDet_Situacao AS situacao, 
                      dbo.contas_receber.Ctr_codigo AS codigoconta, dbo.Contas_receber_pag.Crp_cod_pag AS CodigoContaPag, 
                      dbo.ControleCheque.ControlCheque_codigo, dbo.Contas_receber_pag.Crp_valor_pago AS valor, dbo.ControleChequeDet.ControlChequeDet_Emitente, 
                      dbo.ControleChequeDet.ControlChequeDet_EmitCNPJCPF, dbo.EmpresaFactoring.EmpFact_Nome, 
                      dbo.ControleChequeDet.ControlChequeDet_FactDesc, dbo.ControleChequeDet.ControlChequeDet_FactDtEnvio, 
                      dbo.ControleChequeDet.ControlChequeDet_FactDtComp, dbo.ControleChequeDet.ControlChequeDet_Compensado, 
                      dbo.ControleChequeDet.Ban_Codigo, 
                      CASE WHEN contas_receber.ctr_vinculo = 'OUTROS ' THEN contas_receber.ctr_nome WHEN contas_receber.ctr_vinculo = 'CLIENTE' THEN
                          (SELECT     cli_nome
                            FROM          clientes
                            WHERE      clientes.cli_codigo = contas_receber.ctr_codigo_vinculo) WHEN contas_receber.ctr_vinculo = 'INDICAÇÃO' THEN
                          (SELECT     ind_nome
                            FROM          indicacoes
                            WHERE      indicacoes.ind_codigo = contas_receber.ctr_codigo_vinculo) WHEN contas_receber.ctr_vinculo = 'FORNECEDOR' THEN
                          (SELECT     for_nome
                            FROM          fornecedor
                            WHERE      fornecedor.for_codigo = contas_receber.ctr_codigo_vinculo) WHEN contas_receber.ctr_vinculo = 'PESSOAL' THEN
                          (SELECT     fun_nome
                            FROM          funcionario
                            WHERE      funcionario.fun_cpf = contas_receber.ctr_codigo_vinculo) WHEN contas_receber.ctr_vinculo = 'MATRIZ/FILIAL' THEN
                          (SELECT     fil_fantasia
                            FROM          filiais
                            WHERE      filiais.fil_codigo = contas_receber.ctr_codigo_vinculo) END AS titularconta, dbo.Contas_receber_pag.Ctr_parcelas AS parcela
FROM         dbo.Contas_receber_pag INNER JOIN
                      dbo.contas_receber ON dbo.Contas_receber_pag.Ctr_codigo = dbo.contas_receber.Ctr_codigo INNER JOIN
                      dbo.ControleCheque ON dbo.Contas_receber_pag.Crp_cod_pag = dbo.ControleCheque.ControlCheque_CodPagamento INNER JOIN
                      dbo.ControleChequeDet ON dbo.ControleCheque.ControlCheque_codigo = dbo.ControleChequeDet.ControlCheque_Codigo LEFT OUTER JOIN
                      dbo.EmpresaFactoring ON dbo.ControleChequeDet.EmpFact_Codigo = dbo.EmpresaFactoring.EmpFact_Codigo LEFT OUTER JOIN
                      dbo.Bancos ON dbo.ControleChequeDet.Ban_Codigo = dbo.Bancos.Ban_Codigo LEFT OUTER JOIN
                      dbo.Tipo_documento ON dbo.contas_receber.Tpd_codigo = dbo.Tipo_documento.Tpd_codigo
WHERE     (dbo.ControleCheque.ControlCheque_tipo = 'R')

