/* ============================================================
   FORM: RltComissaoPremiacao   RltComissaoPremiacao
   ============================================================ */

-- [QryComissao : TADOQuery]
SELECT 
  dbo.MetaVenda.MetaVenda_descricao,
  dbo.Rateio.Rateio_descricao,
  dbo.CategoriaRemuneracao.CatRem_Descricao,
  dbo.ComissaoPremiacao.ComPre_codigo,
  dbo.ComissaoPremiacao.ComPre_Descricao,
  dbo.ComissaoPremiacao.ComPre_Tipo,
  dbo.ComissaoPremiacao.ComPre_TipoMeta,
  dbo.ComissaoPremiacao.ComPre_Modo,
  dbo.ComissaoPremiacao.CatRem_Codigo,
  dbo.ComissaoPremiacao.ComPre_RecVlCalc,
  dbo.ComissaoPremiacao.ComPre_RecValor,
  dbo.ComissaoPremiacao.ComPre_CondMontante,
  dbo.ComissaoPremiacao.ComPre_CondPorcent,
  dbo.ComissaoPremiacao.MetaVenda_Codigo,
  dbo.ComissaoPremiacao.Rateio_Codigo,
  dbo.ComissaoPremiacao.ComPre_CondPagProporc,
  dbo.ComissaoPremiacao.ComPre_CondModo,
  dbo.ComissaoPremiacao.ComPre_Situacao,
  dbo.ComissaoPremiacao.usr_cod_criacao,
  dbo.ComissaoPremiacao.usr_dt_hr_criacao,
  dbo.ComissaoPremiacao.usr_cod_alteracao,
  dbo.ComissaoPremiacao.usr_dt_hr_alteracao,
  dbo.ComissaoPremiacao.Emp_codigo,
  dbo.ComissaoPremiacao.ComPre_DtVigInicial,
  dbo.ComissaoPremiacao.ComPre_DtVigFinal

FROM
  dbo.ComissaoPremiacao  WITH (NOLOCK)
  LEFT OUTER JOIN dbo.MetaVenda ON (dbo.ComissaoPremiacao.MetaVenda_Codigo = dbo.MetaVenda.MetaVenda_Codigo)
  LEFT OUTER JOIN dbo.Rateio ON (dbo.ComissaoPremiacao.Rateio_Codigo = dbo.Rateio.Rateio_Codigo)
  LEFT OUTER JOIN dbo.CategoriaRemuneracao ON (dbo.ComissaoPremiacao.CatRem_Codigo = dbo.CategoriaRemuneracao.CatRem_Codigo)
WHERE
  (dbo.ComissaoPremiacao.ComPre_codigo = :PComPre_codigo)

-- [QryGrupoProd : TADOQuery]
SELECT 
  dbo.ComissaoPremiacaoGrup.ComPre_codigo,
  dbo.ComissaoPremiacaoGrup.GrupoProduto_Codigo,
  dbo.ComissaoPremiacaoGrup.ComPreGrup_Porcentegem,
