FROM
  dbo.ComissaoPremiacaoGrup  WITH (nolock)
  LEFT OUTER JOIN dbo.GrupoProduto ON (dbo.ComissaoPremiacaoGrup.GrupoProduto_Codigo = dbo.GrupoProduto.GrupoProduto_Codigo)
WHERE
  (dbo.ComissaoPremiacaoGrup.ComPre_codigo = :PCompre_codigo)

-- [QryCondicoes : TADOQuery]
SELECT 
  dbo.ComissaoPremiacaoCond.ComPreCond_codigo,
  dbo.ComissaoPremiacaoCond.ComPre_codigo,
  dbo.ComissaoPremiacaoCond.ComPreCond_PorcCom,
  dbo.ComissaoPremiacaoCond.ComPreCond_PorcRat,
  dbo.ComissaoPremiacaoCond.Rateio_Codigo,
  dbo.ComissaoPremiacaoCond.MetaVenda_Codigo,
  dbo.ComissaoPremiacaoCond.ComPreCond_FormaPag,
  dbo.ComissaoPremiacaoCond.ComPreCond_Desconto,
  dbo.ComissaoPremiacaoCond.ComPreCond_SimbDesc,
  dbo.ComissaoPremiacaoCond.usr_cod_criacao,
  dbo.ComissaoPremiacaoCond.usr_dt_hr_criacao,
  dbo.ComissaoPremiacaoCond.usr_cod_alteracao,
  dbo.ComissaoPremiacaoCond.usr_dt_hr_alteracao,
  dbo.ComissaoPremiacaoCond.Emp_Codigo,
  dbo.MetaVenda.MetaVenda_descricao,
  dbo.Forma_Pagamento.Fpg_descricao,
  dbo.Rateio.Rateio_descricao
FROM
  dbo.ComissaoPremiacaoCond  WITH (nolock)
  LEFT OUTER JOIN dbo.MetaVenda ON (dbo.ComissaoPremiacaoCond.MetaVenda_Codigo = dbo.MetaVenda.MetaVenda_Codigo)
  LEFT OUTER JOIN dbo.Forma_Pagamento ON (dbo.ComissaoPremiacaoCond.ComPreCond_FormaPag = dbo.Forma_Pagamento.Fpg_codigo)
  LEFT OUTER JOIN dbo.Rateio ON (dbo.ComissaoPremiacaoCond.Rateio_Codigo = dbo.Rateio.Rateio_Codigo)
WHERE
  (dbo.ComissaoPremiacaoCond.ComPre_codigo = :PComPre_codigo)

