   FORM: RltContasSintetica   RltContasSintetica
   ============================================================ */

-- [Qrycontas : TADOQuery]
SELECT Ctp_vinculo, Ctp_nome,
sum(contas_apagar_det.Ctp_valor_vencimento) as valor FROM contas_apagar INNER JOIN 
contas_apagar_det ON contas_apagar.Ctp_codigo = contas_apagar_det.Ctp_codigo LEFT OUTER JOIN 
Contas_apagar_pag ON contas_apagar_det.Ctp_codigo = Contas_apagar_pag.Ctp_codigo AND 
contas_apagar_det.ctp_codigo_det = Contas_apagar_pag.ctp_codigo_det LEFT OUTER JOIN 
Plano_Contas ON contas_apagar.Pco_codigo = Plano_Contas.Pco_codigo 
group by Ctp_vinculo, Ctp_nome
order  by Ctp_vinculo, Ctp_nome


/* ============================================================
   FORM: RltControleCheque   
   ============================================================ */

-- [QryDados : TADOQuery]
SELECT     CASE WHEN ControleChequeDet.ControlChequeDet_Vinculo = 'OUTROS ' THEN ControleChequeDet.ControlChequeDet_emitente WHEN ControleChequeDet.ControlChequeDet_Vinculo
                       = 'CLIENTE' THEN
                          (SELECT     cli_nome
                            FROM          clientes
                            WHERE      clientes.cli_codigo = ControleChequeDet.ControlChequeDet_vinculocodigo) 
                      WHEN ControleChequeDet.ControlChequeDet_Vinculo = 'INDICAÇÃO' THEN
                          (SELECT     ind_nome
                            FROM          indicacoes
                            WHERE      indicacoes.ind_codigo = ControleChequeDet.ControlChequeDet_vinculocodigo) 
                      WHEN ControleChequeDet.ControlChequeDet_Vinculo = 'FORNECEDOR' THEN
                          (SELECT     for_nome
                            FROM          fornecedor
                            WHERE      fornecedor.for_codigo = ControleChequeDet.ControlChequeDet_vinculocodigo) 
                      WHEN ControleChequeDet.ControlChequeDet_Vinculo = 'PESSOAL' THEN
                          (SELECT     fun_nome
                            FROM          funcionario
                            WHERE      funcionario.fun_cpf = ControleChequeDet.ControlChequeDet_vinculocodigo) 
                      WHEN ControleChequeDet.ControlChequeDet_Vinculo = 'MATRIZ/FILIAL' THEN
                          (SELECT     fil_fantasia
                            FROM          filiais
                            WHERE      filiais.fil_codigo = ControleChequeDet.ControlChequeDet_vinculocodigo) END AS nome, 
                      ControleChequedet.ControlChequedet_tipo AS tipo, dbo.contas_receber.Ctr_cod_documento AS numdoc, dbo.Tipo_documento.Tpd_descricao AS documento, 
                      dbo.ControleChequeDet.ControlChequeDet_Vinculo AS vinculo, dbo.ControleChequeDet.ControlChequeDet_NumCheque AS numcheque, 
                      dbo.ControleChequeDet.ControlChequeDet_Conta AS Conta, dbo.ControleChequeDet.ControlChequeDet_Agencia AS agencia, 
                      dbo.Bancos.Ban_Nome AS banco, dbo.ControleChequeDet.ControlChequeDet_Codigo, dbo.Contas_receber_pag.Crp_data_pagamento AS data, 
                      dbo.ControleChequeDet.ControlChequeDet_Situacao AS situacao, contas_receber.Ctr_codigo as codigoconta, Contas_receber_pag.Crp_cod_pag AS CodigoContaPag
,ControleCheque.ControlCheque_Codigo,Contas_receber_pag.Crp_valor_pago AS valor, Contas_receber_pag.ctr_parcelas as parcela FROM   dbo.Contas_receber_pag INNER JOIN
                      dbo.contas_receber ON dbo.Contas_receber_pag.Ctr_codigo = dbo.contas_receber.Ctr_codigo INNER JOIN
                      dbo.ControleCheque ON dbo.Contas_receber_pag.Crp_cod_pag = dbo.ControleCheque.ControlCheque_CodPagamento INNER JOIN
                      dbo.ControleChequeDet ON dbo.ControleCheque.ControlCheque_codigo = dbo.ControleChequeDet.ControlCheque_Codigo LEFT OUTER JOIN
                      dbo.Bancos ON dbo.ControleChequeDet.Ban_Codigo = dbo.Bancos.Ban_Codigo LEFT OUTER JOIN
                      dbo.Tipo_documento ON dbo.contas_receber.Tpd_codigo = dbo.Tipo_documento.Tpd_codigo
WHERE     (dbo.ControleCheque.ControlCheque_tipo = 'R')


/* ============================================================
   FORM: RltControleEntrega   RltControleEntrega
   ============================================================ */

-- [QryControle : TADOQuery]
SELECT dbo.Controle_entrega.cen_codigo_pre, dbo.Controle_entrega.cen_codigo, dbo.Controle_entrega.cen_pedido_avulso, dbo.Controle_entrega.cen_tipo, dbo.Controle_entrega.cen_data_conclusao, dbo.Controle_entrega.cen_cliente, 
                  dbo.Controle_entrega.cli_codigo, dbo.Controle_entrega.usr_cod_criacao, dbo.Controle_entrega.usr_dt_hr_criacao, dbo.Controle_entrega.usr_cod_alteracao, dbo.Controle_entrega.usr_dt_hr_alteracao, dbo.Controle_entrega.cen_modo, 
                  dbo.Clientes.Cli_Nome, dbo.Controle_entrega.ParSV_serie, dbo.Obras.Obr_Descricao
FROM     dbo.Venda INNER JOIN
                  dbo.Obras ON dbo.Venda.Obr_codigo = dbo.Obras.Obr_Codigo INNER JOIN
                  dbo.Controle_entrega WITH (NOLOCK) INNER JOIN
                  dbo.Clientes WITH (NOLOCK) ON dbo.Controle_entrega.cli_codigo = dbo.Clientes.Cli_Codigo ON dbo.Venda.Ven_codigo = dbo.Controle_entrega.cen_pedido_avulso AND 
                  dbo.Venda.ParSV_serie = dbo.Controle_entrega.ParSV_serie
WHERE  (dbo.Venda.Ven_Situacao = 'A') AND (dbo.Venda.Ven_Tipo = 'P')
AND
  (dbo.Controle_entrega.cen_codigo = :Pcen_codigo)

-- [QryControleProd : TADOQuery]
SELECT 
  dbo.controle_entrega_prod.CEP_QuantidadeDevolvida,
  dbo.controle_entrega_prod.cen_codigo_pre,
  dbo.controle_entrega_prod.Pro_codnosso,
  dbo.controle_entrega_prod.cep_acabamento,
  dbo.controle_entrega_prod.cep_tipo,
  dbo.controle_entrega_prod.cep_quantidade_entregue,
  dbo.controle_entrega_prod.cep_quantidade,
  dbo.controle_entrega_prod.cep_quantidade_separada,
  dbo.controle_entrega_prod.cep_quantidade_separadaRet,
  dbo.controle_entrega_prod.cep_quantidade_entregueRet,
  dbo.controle_entrega_prod.CodAmbiente,
  dbo.produtos.Pro_descricao,
  ProdutosFornecedores.ProdFor_DescricaoProduto as Pro_descricao_for,
  ProdutosFornecedores.ProdFor_CodigoProduto as Pro_Codbase,
  dbo.controle_entrega_prod.Cep_VendItem


FROM            dbo.controle_entrega_prod WITH (NOLOCK) LEFT OUTER JOIN
                         dbo.Ambiente WITH (NOLOCK) ON dbo.controle_entrega_prod.CodAmbiente = dbo.Ambiente.CodAmbiente INNER JOIN
                         dbo.produtos WITH (NOLOCK) ON dbo.controle_entrega_prod.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                         dbo.ProdutosFornecedores ON dbo.produtos.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso

WHERE
  (dbo.controle_entrega_prod.cen_codigo_pre = :Pcen_codigo_pre) AND 
  (dbo.controle_entrega_prod.cep_quantidade > 0)

 UNION

  SELECT dbo.controle_entrega_prod.CEP_QuantidadeDevolvida, dbo.controle_entrega_prod.cen_codigo_pre, dbo.controle_entrega_prod.Pro_codnosso, dbo.controle_entrega_prod.cep_acabamento, dbo.controle_entrega_prod.cep_tipo, 
                  dbo.controle_entrega_prod.cep_quantidade_entregue, dbo.controle_entrega_prod.cep_quantidade, dbo.controle_entrega_prod.cep_quantidade_separada, dbo.controle_entrega_prod.cep_quantidade_separadaRet, 
                  dbo.controle_entrega_prod.cep_quantidade_entregueRET, dbo.controle_entrega_prod.CodAmbiente, 
				  dbo.Servicos.Serv_Desc as Pro_descricao,
				  dbo.Servicos.Serv_Desc AS Pro_descricao_for, 
				  dbo.controle_entrega_prod.Pro_codnosso AS Pro_Codbase, 
                  dbo.controle_entrega_prod.Cep_VendItem
FROM     dbo.controle_entrega_prod WITH (NOLOCK) INNER JOIN
                  dbo.Servicos ON dbo.controle_entrega_prod.Pro_codnosso = dbo.Servicos.sev_cod LEFT OUTER JOIN
                  dbo.Ambiente WITH (NOLOCK) ON dbo.controle_entrega_prod.CodAmbiente = dbo.Ambiente.CodAmbiente
WHERE  (dbo.controle_entrega_prod.cen_codigo_pre =:Pcen_codigo_pre2) AND (dbo.controle_entrega_prod.cep_quantidade > 0) AND (dbo.controle_entrega_prod.Cep_Servico = 1)

