-- [Qrycontrole : TADOQuery]
SELECT   dbo.Venda.Ven_Tipo, dbo.Clientes.Cli_Nome, dbo.Venda.Ven_codigo, dbo.Venda.ParSV_serie, dbo.controle_entrega_prod.Pro_codnosso, dbo.controle_entrega_prod.cep_acabamento, 
                         SUM(dbo.controle_entrega_data.ced_quantidade * dbo.VendaProduto.VenPro_VlUnitario) AS valortotal, MAX(dbo.VendaProduto.VenPro_VlUnitario) AS vlunitario, SUM(dbo.controle_entrega_data.ced_quantidade) AS quantidade, 
                         dbo.ProdutosFornecedores.ProdFor_CodigoProduto, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto, dbo.fornecedor.For_Nome, dbo.Venda.Ven_Situacao, dbo.controle_entrega_data.ced_data, 
                         dbo.controle_entrega_prod.Cep_TipoEntrega, DATEADD(day,
                             (SELECT        par_entrega
                               FROM            dbo.Paramentros), dbo.Venda.Ven_DataEmissao) AS datamaxima, dbo.VendaProduto.VenPro_DataEntrega, dbo.produtos.Pro_descricao, dbo.produtos.Pro_CodEspecial, 
                         dbo.GrupoProduto.GrupoProduto_Descricao, dbo.produtos.Pro_tp_peca, dbo.produtos.Pro_unidade

, (select CenAs_Entregou from Controle_entrega_Assinaturas where Controle_entrega_Assinaturas.cen_codigo_pre =controle_entrega_prod.cen_codigo_pre and Controle_entrega_Assinaturas.Ced_ordem =controle_entrega_data.Ced_ordem) as entregou
, (select CenAs_recebeu from Controle_entrega_Assinaturas where Controle_entrega_Assinaturas.cen_codigo_pre =controle_entrega_prod.cen_codigo_pre and Controle_entrega_Assinaturas.Ced_ordem =controle_entrega_data.Ced_ordem) as recebeu


FROM            dbo.fornecedor INNER JOIN
                         dbo.ProdutosFornecedores ON dbo.fornecedor.For_codigo = dbo.ProdutosFornecedores.For_codigo INNER JOIN
                         dbo.produtos ON dbo.ProdutosFornecedores.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                         dbo.Controle_entrega INNER JOIN
                         dbo.controle_entrega_prod ON dbo.Controle_entrega.cen_codigo_pre = dbo.controle_entrega_prod.cen_codigo_pre INNER JOIN
                         dbo.Venda ON dbo.Controle_entrega.cen_pedido_avulso = dbo.Venda.Ven_codigo AND dbo.Controle_entrega.ParSV_serie = dbo.Venda.ParSV_serie INNER JOIN
                         dbo.Clientes ON dbo.Venda.Ven_CodVinculo = dbo.Clientes.Cli_Codigo INNER JOIN
                         dbo.VendaProduto ON dbo.Venda.Ven_CodigoPre = dbo.VendaProduto.Ven_CodigoPre AND dbo.controle_entrega_prod.Pro_codnosso = dbo.VendaProduto.Pro_codnosso AND 
                         dbo.controle_entrega_prod.cep_acabamento = dbo.VendaProduto.CodAcabamento INNER JOIN
                         dbo.controle_entrega_data ON dbo.controle_entrega_prod.cen_codigo_pre = dbo.controle_entrega_data.cen_codigo_pre AND dbo.controle_entrega_prod.Pro_codnosso = dbo.controle_entrega_data.Pro_codnosso AND 
                         dbo.controle_entrega_prod.cep_acabamento = dbo.controle_entrega_data.cep_acabamento ON dbo.produtos.Pro_codnosso = dbo.VendaProduto.Pro_codnosso INNER JOIN
                         dbo.GrupoProduto ON dbo.produtos.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo
GROUP BY dbo.Venda.Ven_Tipo, dbo.Clientes.Cli_Nome, dbo.Venda.Ven_codigo, dbo.Venda.ParSV_serie, dbo.controle_entrega_prod.Pro_codnosso, dbo.controle_entrega_prod.cep_acabamento, 
                         dbo.ProdutosFornecedores.ProdFor_CodigoProduto, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto, dbo.fornecedor.For_Nome, dbo.Venda.Ven_Situacao, dbo.controle_entrega_data.ced_data, 
                         dbo.controle_entrega_prod.Cep_TipoEntrega, dbo.Venda.Ven_DataEmissao, dbo.VendaProduto.VenPro_DataEntrega, dbo.produtos.Pro_descricao, dbo.produtos.Pro_CodEspecial, dbo.GrupoProduto.GrupoProduto_Descricao, 
                         dbo.produtos.Pro_tp_peca, dbo.produtos.Pro_unidade, dbo.controle_entrega_data.cep_tipo
,controle_entrega_prod.cen_codigo_pre,controle_entrega_data.Ced_ordem,Venda.Ven_CodVinculo

