-- [QryCredito : TADOQuery]
SELECT     (SELECT     SUM(Credito_Valor) AS C1
                       FROM          dbo.Credito
                       WHERE      (Credito_Operacao = 'C') AND (Credito_Situacao = 'A')) AS TotalCredito,
                          (SELECT     SUM(Credito_Valor) AS C2
                            FROM          dbo.Credito AS Credito_2
                            WHERE      (Credito_Operacao = 'D') AND (Credito_Situacao = 'A')) AS TotalDebito, Credito_1.Credito_Codigo, Credito_1.Credito_TipoVinculo, 
                      Credito_1.Credito_CodigoVinculo, Credito_1.Credito_Operacao, Credito_1.Credito_Valor, Credito_1.Credito_Data, Credito_1.Tpd_Codigo, 
                      Credito_1.Credito_TpdcodigoOrigem, Credito_1.Credito_CodigoDoc, Credito_1.Credito_Obs, Credito_1.Credito_Situacao, dbo.Clientes.Cli_Nome, 
                      dbo.fornecedor.For_Nome, dbo.Tipo_documento.Tpd_descricao
FROM         dbo.Credito AS Credito_1 INNER JOIN
                      dbo.Clientes ON Credito_1.Credito_CodigoVinculo = dbo.Clientes.Cli_Codigo INNER JOIN
                      dbo.fornecedor ON Credito_1.Credito_CodigoVinculo = dbo.fornecedor.For_codigo LEFT OUTER JOIN
                      dbo.Tipo_documento ON Credito_1.Tpd_Codigo = dbo.Tipo_documento.Tpd_codigo

-- [QrySaldoInicial : TADOQuery]
SELECT (SELECT SUM(Credito_Valor) AS totalC FROM dbo.Credito c1 WHERE (Credito_Operacao = 'C') AND
     (Credito_TipoVinculo = dbo.Credito.Credito_TipoVinculo) AND (Credito_CodigoVinculo = dbo.Credito.Credito_CodigoVinculo) AND (Credito_Situacao = 'A')) AS somaCredito,
    (SELECT SUM(Credito_Valor) AS totalD FROM dbo.Credito c2 WHERE (Credito_Operacao = 'D') AND
     (Credito_TipoVinculo = dbo.Credito.Credito_TipoVinculo) AND (Credito_CodigoVinculo = dbo.Credito.Credito_CodigoVinculo) AND (Credito_Situacao = 'A')) AS somaDebito,
    dbo.Credito.Credito_CodigoVinculo  FROM dbo.Credito WHERE (Credito.Credito_Situacao = 'A') AND
     (Credito.Credito_TipoVinculo =:PtpVinculo) AND
     (Credito.Credito_CodigoVinculo =:PCodVinculo) AND 
     (Credito.Credito_Data<:Pdataini)


