-- [QryEntradaPorDevolucao : TADOQuery]
SELECT   
DevolucaoProduto.DevPro_simbolo, DevolucaoProduto.DevPro_aplicacao,
     dbo.DevolucaoProduto.Dev_CodigoPre, dbo.DevolucaoProduto.DevPro_item, dbo.DevolucaoProduto.Pro_codnosso, dbo.DevolucaoProduto.CodAcabamento, dbo.DevolucaoProduto.CodAmbiente, 
                         dbo.DevolucaoProduto.DevPro_Seq, dbo.DevolucaoProduto.DevPro_SeqItem, dbo.DevolucaoProduto.DevPro_Quantidade, dbo.DevolucaoProduto.DevPro_QuantidadeOriginal, dbo.DevolucaoProduto.DevPro_VlUnitario, 
                         dbo.DevolucaoProduto.DevPro_VlItem, dbo.DevolucaoProduto.DevPro_Vldesconto, dbo.DevolucaoProduto.DevPro_VlDescontoProc, dbo.DevolucaoProduto.DevPro_Vlimposto, dbo.DevolucaoProduto.DevPro_ProdutoPai, 
                         dbo.DevolucaoProduto.DevPro_ProdutoSubPai, dbo.DevolucaoProduto.DevPro_ItemPai, dbo.DevolucaoProduto.DevPro_ItemSubPai, dbo.DevolucaoProduto.DevPro_ValorCredito, dbo.DevolucaoProduto.pld_codindice, 
                         dbo.DevolucaoProduto.DevPro_usuarioestoque, dbo.DevolucaoProduto.DevPro_DtHrUsuarioEstoque, dbo.DevolucaoProduto.DevPro_motivodev, dbo.DevolucaoProduto.usr_dt_hr_criacao, 
                         dbo.DevolucaoProduto.usr_cod_alteracao, dbo.DevolucaoProduto.usr_dt_hr_alteracao, dbo.DevolucaoProduto.usr_cod_criacao, dbo.ProdutosFornecedores.ProdFor_CodigoProduto AS Pro_Codbase, dbo.produtos.Pro_tp_peca, 
                         dbo.GrupoProduto.GrupoProduto_Descricao, dbo.produtos.Pro_descricao, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto AS Pro_descricao_for, dbo.produtos.Pro_unidade, dbo.produtos.Pro_CodEspecial, 
                         dbo.fornecedor.For_Nome, dbo.produtos.pro_tempoInstalacao, dbo.produtos.GrupoProduto_codigo, REPLICATE('0', 2 - LEN(dbo.DevolucaoProduto.DevPro_Seq)) + CAST(dbo.DevolucaoProduto.DevPro_Seq AS varchar(2)) 
                         + ' - ' + dbo.VendaAmbiente.VenAmb_Descricao AS Nomeambiente, dbo.Venda.Ven_codigo, dbo.Venda.ParSV_serie, dbo.Clientes.Cli_Nome, dbo.Motivo_devolucao.Mod_descricao, dbo.SisUsuarios.Nome, 
                         dbo.Devolucao.Dev_codigo, dbo.Devolucao.Dev_situacao, venda.Ven_CodigoPre
FROM            dbo.DevolucaoProduto INNER JOIN
                         dbo.produtos ON dbo.DevolucaoProduto.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                         dbo.GrupoProduto ON dbo.produtos.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo INNER JOIN
                         dbo.VendaAmbiente ON dbo.DevolucaoProduto.CodAmbiente = dbo.VendaAmbiente.CodAmbiente INNER JOIN
                         dbo.ProdutosFornecedores INNER JOIN
                         dbo.fornecedor ON dbo.ProdutosFornecedores.For_codigo = dbo.fornecedor.For_codigo ON dbo.produtos.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso LEFT OUTER JOIN
                         dbo.SisUsuarios ON dbo.DevolucaoProduto.DevPro_usuarioestoque = dbo.SisUsuarios.Id LEFT OUTER JOIN
                         dbo.Motivo_devolucao ON dbo.DevolucaoProduto.DevPro_motivodev = dbo.Motivo_devolucao.Mod_codigo RIGHT OUTER JOIN
                         dbo.Venda INNER JOIN
                         dbo.Devolucao ON dbo.Venda.Ven_CodigoPre = dbo.Devolucao.ven_codigopre INNER JOIN
                         dbo.Clientes ON dbo.Venda.Ven_CodVinculo = dbo.Clientes.Cli_Codigo ON dbo.DevolucaoProduto.Dev_CodigoPre = dbo.Devolucao.Dev_CodigoPre AND dbo.VendaAmbiente.VenAmb_NDocPre = dbo.Devolucao.ven_codigopre
where Devolucao.Dev_CodigoPre =:pDev_CodigoPre AND (dbo.ProdutosFornecedores.ProdFor_Padrao = 1)
order by DevolucaoProduto.DevPro_Seq

