SELECT dbo.DevolucaoProduto.Pro_codnosso, dbo.DevolucaoProduto.CodAcabamento, dbo.produtos.Pro_unidade, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto, 
                  dbo.fornecedor.For_Nome, SUM(dbo.DevolucaoProduto.DevPro_Quantidade) AS DevPro_Quantidade, dbo.DevolucaoProduto.DevPro_VlUnitario, SUM(dbo.DevolucaoProduto.DevPro_Quantidade) 
                  * dbo.DevolucaoProduto.DevPro_VlUnitario AS total, dbo.produtos.Pro_CodEspecial
FROM     dbo.DevolucaoProduto INNER JOIN
                  dbo.produtos ON dbo.DevolucaoProduto.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                  dbo.ProdutosFornecedores ON dbo.DevolucaoProduto.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso INNER JOIN
                  dbo.fornecedor ON dbo.ProdutosFornecedores.For_codigo = dbo.fornecedor.For_codigo

where DevolucaoProduto.Dev_CodigoPre =:pDev_CodigoPre AND (dbo.ProdutosFornecedores.ProdFor_Padrao = 1)
GROUP BY dbo.DevolucaoProduto.Pro_codnosso, dbo.DevolucaoProduto.CodAcabamento, dbo.produtos.Pro_unidade, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto, 
                  dbo.fornecedor.For_Nome, dbo.DevolucaoProduto.DevPro_VlUnitario, dbo.produtos.Pro_CodEspecial

order by ProdutosFornecedores.ProdFor_CodigoProduto

