dbo.VendaProduto.Pro_codnosso, dbo.VendaProduto.VenPro_VlUnitario AS vl_unitario, dbo.VendaProduto.VenPro_VlItem AS vl_item, dbo.VendaProduto.VenPro_Vldesconto, dbo.VendaAmbiente.CodAmbiente,
dbo.produtos.GrupoProduto_codigo, dbo.GrupoProduto.GrupoProduto_ordem AS ordem, dbo.produtos.Pro_CodEspecial, dbo.VendaProduto.VenPro_VlDescontoProc AS Desconto,
dbo.ProdutosFornecedores.ProdFor_DescricaoProduto AS Pro_descricao_for, dbo.produtos.Pro_descricao AS descricao, dbo.ProdutosFornecedores.ProdFor_CodigoProduto AS Pro_Codbase, dbo.VendaProduto.prom_codigo,
dbo.VendaProduto.VenPro_VlPromocao, dbo.VendaProduto.VenPro_ProcPromocao, dbo.VendaProduto.VenPro_VlCadastroPromocao, dbo.VendaDataEntrega.VenDtEnt_quantidade AS quantidade
, VendaDataEntrega.VenDtEnt_observacao as observacao

FROM dbo.GrupoProduto INNER JOIN VendaAmbiente INNER JOIN
VendaProduto ON dbo.VendaAmbiente.VenAmb_NDocPre = dbo.VendaProduto.Ven_CodigoPre AND dbo.VendaAmbiente.CodAmbiente = dbo.VendaProduto.CodAmbiente INNER JOIN
produtos ON dbo.VendaProduto.Pro_codnosso = dbo.produtos.Pro_codnosso ON dbo.GrupoProduto.GrupoProduto_Codigo = dbo.produtos.GrupoProduto_codigo INNER JOIN
ProdutosFornecedores ON dbo.produtos.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso INNER JOIN
VendaDataEntrega ON dbo.VendaProduto.Ven_CodigoPre = dbo.VendaDataEntrega.Ven_CodigoPre AND dbo.VendaProduto.Pro_codnosso = dbo.VendaDataEntrega.Pro_codnosso AND
VendaProduto.CodAcabamento = dbo.VendaDataEntrega.CodAcabamento AND dbo.VendaProduto.VenPro_Seq = dbo.VendaDataEntrega.VenPro_Seq AND
VendaProduto.VenPro_SeqItem = dbo.VendaDataEntrega.VenPro_SeqItem

