-- [QryEntrega : TADOQuery]
SELECT  cen_pedido_avulso, ParSV_serie, cen_cliente, usr_dt_hr_criacao
FROM     dbo.Controle_entrega
WHERE  EXISTS
                      (SELECT cen_codigo_pre
                       FROM      dbo.controle_entrega_prod
                       WHERE   (dbo.Controle_entrega.cen_codigo_pre = cen_codigo_pre) AND (cep_quantidade > cep_quantidade_entregue + CEP_QuantidadeDevolvidaEst) AND (dbo.Controle_entrega.cen_codigo_pre = cen_codigo_pre))

and usr_dt_hr_criacao >=:data1 and usr_dt_hr_criacao <=:data2
ORDER BY cen_pedido_avulso


