-- [Qryprodutos : TADOQuery]
SELECT dbo.fornecedor.For_Nome, dbo.produtos.Pro_codnosso, dbo.produtos.Pro_tp_produto, dbo.produtos.Pro_tp_peca, dbo.produtos.Pro_descricao, dbo.Preco_Produto.Pre_Acabamento, 
MAX(dbo.Preco_Produto.Pre_Tabela) AS Pre_Tabela, MAX(dbo.Preco_Produto.Pre_compra) AS Pre_compra, MAX(dbo.Preco_Produto.Pre_Venda) AS Pre_Venda, MAX(dbo.Preco_Produto.Pre_Custo) AS Pre_Custo, 
SUM(dbo.Estoque_produto.Epr_estoque) AS Epr_estoque, dbo.produtos.For_codigo, MAX(dbo.Preco_Produto.Pre_Venda) * SUM(dbo.Estoque_produto.Epr_estoque) AS est_pre_venda, 
MAX(dbo.Preco_Produto.Pre_compra) * SUM(dbo.Estoque_produto.Epr_estoque) AS est_pre_compra, MAX(dbo.Preco_Produto.Pre_Tabela) * SUM(dbo.Estoque_produto.Epr_estoque) AS est_pre_tabela, 
MAX(dbo.Preco_Produto.Pre_Custo) * SUM(dbo.Estoque_produto.Epr_estoque) AS est_pre_custo,dbo.produtos.Pro_Codbase, dbo.produtos.Pro_descricao_for,produtos.Pro_CodEspecial FROM dbo.produtos INNER JOIN dbo.fornecedor ON dbo.produtos.For_codigo = dbo.fornecedor.For_codigo
 INNER JOIN dbo.Preco_Produto ON dbo.produtos.Pro_codnosso = dbo.Preco_Produto.Pre_Codnosso INNER JOIN dbo.Estoque_produto ON dbo.Preco_Produto.Pre_Codnosso = dbo.Estoque_produto.Epr_Codnosso
 AND dbo.Preco_Produto.Pre_Acabamento = dbo.Estoque_produto.Epr_Acabamento WHERE     (dbo.Estoque_produto.Epr_estoque > 0)   GROUP BY fornecedor.For_Nome, 
produtos.Pro_codnosso,Preco_Produto.Pre_Acabamento, produtos.Pro_tp_produto, produtos.Pro_tp_peca, produtos.Pro_descricao, produtos.For_codigo,dbo.produtos.Pro_Codbase, dbo.produtos.Pro_descricao_for,produtos.Pro_CodEspecial 
