-- [Qryprodutos : TADOQuery]
SELECT     TOP (100) PERCENT 
Clientes.Cli_Codigo, dbo.Clientes.Cli_Nome,
dbo.produtos.Pro_codnosso, dbo.produtos.Pro_Codbase, dbo.produtos.Pro_descricao, dbo.produtos.Pro_descricao_for, 
                      dbo.produtos.Pro_tp_peca, dbo.produtos.Pro_CodEspecial, dbo.GrupoProduto.GrupoProduto_Descricao, dbo.produtos.Pro_unidade, 
                      dbo.Preco_Produto.Pre_Acabamento, dbo.produtos.For_codigo, dbo.fornecedor.For_Nome, SUM(dbo.Estoque_produto.Epr_estoque) AS Epr_estoque, 
                      CASE WHEN
                          (SELECT     SUM(CASE WHEN CEP_QuantidadeDevolvidaEst >= controle_entrega_prod.cep_quantidade_separada AND 
                                                   controle_entrega_prod.cep_quantidade_separada > (controle_entrega_prod.cep_quantidade - CEP_QuantidadeDevolvidaEst) 
                                                   THEN CASE WHEN controle_entrega_prod.cep_quantidade_separada - CASE WHEN CEP_QuantidadeDevolvidaEst > 0 THEN CEP_QuantidadeDevolvidaEst
                                                    ELSE 0 END > 0 THEN controle_entrega_prod.cep_quantidade_separada - CASE WHEN CEP_QuantidadeDevolvidaEst > 0 THEN CEP_QuantidadeDevolvidaEst
                                                    ELSE 0 END ELSE 0 END ELSE controle_entrega_prod.cep_quantidade_separada END - CASE WHEN CEP_QuantidadeDevolvidaEst >= controle_entrega_prod.cep_quantidade_entregue
                                                    AND controle_entrega_prod.cep_quantidade_entregue > (controle_entrega_prod.cep_quantidade - CEP_QuantidadeDevolvidaEst) 
                                                   THEN CASE WHEN controle_entrega_prod.cep_quantidade_entregue - CASE WHEN CEP_QuantidadeDevolvidaEst > 0 THEN CEP_QuantidadeDevolvidaEst
                                                    ELSE 0 END > 0 THEN controle_entrega_prod.cep_quantidade_entregue - CASE WHEN CEP_QuantidadeDevolvidaEst > 0 THEN CEP_QuantidadeDevolvidaEst
                                                    ELSE 0 END ELSE 0 END ELSE controle_entrega_prod.cep_quantidade_entregue END)
                            FROM          controle_entrega_prod
                            WHERE      controle_entrega_prod.Pro_codnosso = produtos.Pro_codnosso AND controle_entrega_prod.cep_acabamento = Preco_Produto.Pre_Acabamento) IS NULL
                       THEN '0' ELSE
                          (SELECT     SUM(CASE WHEN CEP_QuantidadeDevolvidaEst >= controle_entrega_prod.cep_quantidade_separada AND 
                                                   controle_entrega_prod.cep_quantidade_separada > (controle_entrega_prod.cep_quantidade - CEP_QuantidadeDevolvidaEst) 
                                                   THEN CASE WHEN controle_entrega_prod.cep_quantidade_separada - CASE WHEN CEP_QuantidadeDevolvidaEst > 0 THEN CEP_QuantidadeDevolvidaEst
                                                    ELSE 0 END > 0 THEN controle_entrega_prod.cep_quantidade_separada - CASE WHEN CEP_QuantidadeDevolvidaEst > 0 THEN CEP_QuantidadeDevolvidaEst
                                                    ELSE 0 END ELSE 0 END ELSE controle_entrega_prod.cep_quantidade_separada END - CASE WHEN CEP_QuantidadeDevolvidaEst >= controle_entrega_prod.cep_quantidade_entregue
                                                    AND controle_entrega_prod.cep_quantidade_entregue > (controle_entrega_prod.cep_quantidade - CEP_QuantidadeDevolvidaEst) 
                                                   THEN CASE WHEN controle_entrega_prod.cep_quantidade_entregue - CASE WHEN CEP_QuantidadeDevolvidaEst > 0 THEN CEP_QuantidadeDevolvidaEst
                                                    ELSE 0 END > 0 THEN controle_entrega_prod.cep_quantidade_entregue - CASE WHEN CEP_QuantidadeDevolvidaEst > 0 THEN CEP_QuantidadeDevolvidaEst
                                                    ELSE 0 END ELSE 0 END ELSE controle_entrega_prod.cep_quantidade_entregue END)
                            FROM          controle_entrega_prod
                            WHERE      controle_entrega_prod.Pro_codnosso = produtos.Pro_codnosso AND controle_entrega_prod.cep_acabamento = Preco_Produto.Pre_Acabamento) 
                      END AS sepnent, CASE WHEN
                          (SELECT     SUM(CASE WHEN controle_entrega_prod.cep_quantidade - CASE WHEN CEP_QuantidadeDevolvidaEst > 0 THEN CEP_QuantidadeDevolvidaEst ELSE 0 END
                                                    > 0 THEN controle_entrega_prod.cep_quantidade - CASE WHEN CEP_QuantidadeDevolvidaEst > 0 THEN CEP_QuantidadeDevolvidaEst ELSE 0 END ELSE
                                                    0 END - CASE WHEN CEP_QuantidadeDevolvidaEst >= controle_entrega_prod.cep_quantidade_separada AND 
                                                   controle_entrega_prod.cep_quantidade_separada > (controle_entrega_prod.cep_quantidade - CEP_QuantidadeDevolvidaEst) 
                                                   THEN CASE WHEN controle_entrega_prod.cep_quantidade_separada - CASE WHEN CEP_QuantidadeDevolvidaEst > 0 THEN CEP_QuantidadeDevolvidaEst
                                                    ELSE 0 END > 0 THEN controle_entrega_prod.cep_quantidade_separada - CASE WHEN CEP_QuantidadeDevolvidaEst > 0 THEN CEP_QuantidadeDevolvidaEst
                                                    ELSE 0 END ELSE 0 END ELSE controle_entrega_prod.cep_quantidade_separada END)
                            FROM          controle_entrega_prod
                            WHERE      controle_entrega_prod.Pro_codnosso = produtos.Pro_codnosso AND controle_entrega_prod.cep_acabamento = Preco_Produto.Pre_Acabamento) IS NULL
                       THEN '0' ELSE
                          (SELECT     SUM(CASE WHEN controle_entrega_prod.cep_quantidade - CASE WHEN CEP_QuantidadeDevolvidaEst > 0 THEN CEP_QuantidadeDevolvidaEst ELSE 0 END
                                                    > 0 THEN controle_entrega_prod.cep_quantidade - CASE WHEN CEP_QuantidadeDevolvidaEst > 0 THEN CEP_QuantidadeDevolvidaEst ELSE 0 END ELSE
                                                    0 END - CASE WHEN CEP_QuantidadeDevolvidaEst >= controle_entrega_prod.cep_quantidade_separada AND 
                                                   controle_entrega_prod.cep_quantidade_separada > (controle_entrega_prod.cep_quantidade - CEP_QuantidadeDevolvidaEst) 
                                                   THEN CASE WHEN controle_entrega_prod.cep_quantidade_separada - CASE WHEN CEP_QuantidadeDevolvidaEst > 0 THEN CEP_QuantidadeDevolvidaEst
                                                    ELSE 0 END > 0 THEN controle_entrega_prod.cep_quantidade_separada - CASE WHEN CEP_QuantidadeDevolvidaEst > 0 THEN CEP_QuantidadeDevolvidaEst
                                                    ELSE 0 END ELSE 0 END ELSE controle_entrega_prod.cep_quantidade_separada END)
                            FROM          controle_entrega_prod
                            WHERE      controle_entrega_prod.Pro_codnosso = produtos.Pro_codnosso AND controle_entrega_prod.cep_acabamento = Preco_Produto.Pre_Acabamento) 
                      END AS naosep, dbo.Venda.Ven_codigo, dbo.Venda.ParSV_serie, CAST(dbo.Venda.Ven_codigo AS VARCHAR(12)) + '-' + dbo.Venda.ParSV_serie AS PEDIDOVENDA
FROM         dbo.Venda INNER JOIN
                      dbo.VendaProduto ON dbo.Venda.Ven_CodigoPre = dbo.VendaProduto.Ven_CodigoPre INNER JOIN
                      dbo.produtos INNER JOIN
                      dbo.Preco_Produto ON dbo.produtos.Pro_codnosso = dbo.Preco_Produto.Pre_Codnosso INNER JOIN
                      dbo.Estoque_produto ON dbo.Preco_Produto.Pre_Codnosso = dbo.Estoque_produto.Epr_Codnosso AND 
                      dbo.Preco_Produto.Pre_Acabamento = dbo.Estoque_produto.Epr_Acabamento INNER JOIN
                      dbo.GrupoProduto ON dbo.produtos.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo INNER JOIN
                      dbo.fornecedor ON dbo.produtos.For_codigo = dbo.fornecedor.For_codigo ON dbo.VendaProduto.Pro_codnosso = dbo.Preco_Produto.Pre_Codnosso AND 
                      dbo.VendaProduto.CodAcabamento = dbo.Preco_Produto.Pre_Acabamento
INNER JOIN
                         dbo.Clientes ON dbo.Venda.Ven_CodVinculo = dbo.Clientes.Cli_Codigo


WHERE     (dbo.Venda.Ven_Situacao = 'A') AND (dbo.Venda.Ven_Tipo = 'P') AND (dbo.Venda.ParSV_serie < 3) 
GROUP BY dbo.produtos.Pro_codnosso, dbo.produtos.Pro_Codbase, dbo.produtos.Pro_descricao, dbo.produtos.Pro_descricao_for, dbo.produtos.Pro_tp_peca, 
                      dbo.produtos.Pro_CodEspecial, dbo.GrupoProduto.GrupoProduto_Descricao, dbo.produtos.Pro_unidade, dbo.Preco_Produto.Pre_Acabamento, 
                      dbo.produtos.For_codigo, dbo.fornecedor.For_Nome, dbo.Venda.Ven_codigo, dbo.Venda.ParSV_serie,Clientes.Cli_Codigo, dbo.Clientes.Cli_Nome
ORDER BY dbo.Venda.Ven_codigo, dbo.Venda.ParSV_serie

