SELECT venda.ven_codigo, dbo.Clientes.Cli_Nome, ProdutosFornecedores.ProdFor_CodigoProduto as Pro_Codbase, dbo.produtos.Pro_codnosso, dbo.produtos.Pro_descricao,  ProdutosFornecedores.ProdFor_DescricaoProduto as Pro_descricao_for, dbo.produtos.Pro_CodEspecial, SUM(VendaProduto.VenPro_Quantidade) AS quantidade, dbo.Acabamento.DescAcabamento,  dbo.produtos.Pro_unidade, venda.Ven_DataEmissao, dbo.GrupoProduto.GrupoProduto_Descricao, dbo.produtos.Pro_tp_peca, venda.ParSV_serie ,VendaAmbiente.VenAmb_Descricao, Preco_Produto.Pre_CodBarra, ProdutosFornecedores.ProdFor_CodigoBarra 
FROM venda INNER JOIN  VendaProduto ON venda.ven_codigopre = VendaProduto.ven_codigopre INNER JOIN  dbo.Clientes ON venda.Ven_CodVinculo = dbo.Clientes.Cli_Codigo INNER JOIN  dbo.produtos ON VendaProduto.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN  dbo.Acabamento ON VendaProduto.CodAcabamento = dbo.Acabamento.CodAcabamento INNER JOIN  dbo.GrupoProduto ON dbo.produtos.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo INNER JOIN dbo.VendaAmbiente ON dbo.VendaProduto.Ven_CodigoPre = dbo.VendaAmbiente.VenAmb_NDocPre AND dbo.VendaProduto.CodAmbiente = dbo.VendaAmbiente.CodAmbiente INNER JOIN  dbo.Preco_Produto ON dbo.VendaProduto.Pro_codnosso = dbo.Preco_Produto.Pre_Codnosso AND dbo.VendaProduto.CodAcabamento = dbo.Preco_Produto.Pre_Acabamento INNER JOIN dbo.ProdutosFornecedores ON dbo.produtos.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso 
where VendaProduto.Pro_codnosso in ('PD783.NL', 'STH6338/24') and venda.ven_tipo ='P' AND venda.ven_situacao ='A' and VendaProduto.VenPro_Quantidade > 0 and venda.ven_codigopre =6021 and VendaProduto.VenPro_Quantidade > 0 GROUP BY venda.ven_codigo, dbo.Clientes.Cli_Nome, ProdutosFornecedores.ProdFor_CodigoProduto, dbo.produtos.Pro_codnosso, dbo.produtos.Pro_descricao, ProdutosFornecedores.ProdFor_DescricaoProduto, dbo.produtos.Pro_CodEspecial, dbo.Acabamento.DescAcabamento, dbo.produtos.Pro_unidade, venda.Ven_DataEmissao, dbo.GrupoProduto.GrupoProduto_Descricao, dbo.produtos.Pro_tp_peca,venda.ParSV_serie,VendaAmbiente.VenAmb_Descricao, Preco_Produto.Pre_CodBarra, ProdutosFornecedores.ProdFor_CodigoBarra

