SELECT     dbo.ControleChequeDet.ControlChequeDet_Agencia, dbo.ControleChequeDet.ControlChequeDet_Conta, 
                      dbo.ControleChequeDet.ControlChequeDet_NumCheque, dbo.ControleChequeDet.ControlChequeDet_Situacao, dbo.Bancos.Ban_Nome, 
                      dbo.ControleCheque.ControlCheque_tipo, dbo.ControleCheque.ControlCheque_CodPagamento, 
                      CASE WHEN ControleChequeDet.ControlChequeDet_Vinculo = 'CLIENTE' THEN
                          (SELECT     cli_nome
                            FROM          clientes
                            WHERE      clientes.cli_codigo = ControleChequeDet.ControlChequeDet_VinculoCodigo) 
                      ELSE CASE WHEN ControleChequeDet.ControlChequeDet_Vinculo = 'FORNECEDOR' THEN
                          (SELECT     for_nome
                            FROM          fornecedor
                            WHERE      fornecedor.for_codigo = ControleChequeDet.ControlChequeDet_VinculoCodigo) 
                      ELSE CASE WHEN ControleChequeDet.ControlChequeDet_Vinculo = 'PESSOAL' THEN
                          (SELECT     FUN_nome
                            FROM          funcionario
                            WHERE      funcionario.fun_cpf = ControleChequeDet.ControlChequeDet_VinculoCodigo) 
                      ELSE CASE WHEN ControleChequeDet.ControlChequeDet_Vinculo = 'INDICAÇÃO' THEN
                          (SELECT     IND_nome
                            FROM          Indicacoes
                            WHERE      Indicacoes.ind_codigo = ControleChequeDet.ControlChequeDet_VinculoCodigo) 
                      ELSE CASE WHEN ControleChequeDet.ControlChequeDet_Vinculo = 'EMPRESA' THEN
                          (SELECT     EMPRESA.EMPRESA
                            FROM          empresa
                            WHERE      EMPRESA.CODLANC = ControleChequeDet.ControlChequeDet_VinculoCodigo) 
                      ELSE CASE WHEN ControleChequeDet.ControlChequeDet_Vinculo = 'OUTROS' THEN dbo.ControleChequeDet.ControlChequeDet_Emitente END END END
                       END END END AS nome, CASE WHEN ControleChequeDet.ControlChequeDet_Vinculo = 'CLIENTE' THEN
                          (SELECT     Cli_cnpj_cpf
                            FROM          clientes
                            WHERE      clientes.cli_codigo = ControleChequeDet.ControlChequeDet_VinculoCodigo) 
                      ELSE CASE WHEN ControleChequeDet.ControlChequeDet_Vinculo = 'FORNECEDOR' THEN
                          (SELECT     For_cnpj_cpf
                            FROM          fornecedor
                            WHERE      fornecedor.for_codigo = ControleChequeDet.ControlChequeDet_VinculoCodigo) 
                      ELSE CASE WHEN ControleChequeDet.ControlChequeDet_Vinculo = 'PESSOAL' THEN
                          (SELECT     CAST(funcionario.fun_cpf AS varCHAR(20))
                            FROM          funcionario
                            WHERE      funcionario.fun_cpf = ControleChequeDet.ControlChequeDet_VinculoCodigo) 
                      ELSE CASE WHEN ControleChequeDet.ControlChequeDet_Vinculo = 'INDICAÇÃO' THEN ' ' ELSE CASE WHEN ControleChequeDet.ControlChequeDet_Vinculo
                       = 'EMPRESA' THEN
                          (SELECT     EMPRESA.CGCCPF
                            FROM          empresa
                            WHERE      EMPRESA.CODLANC = ControleChequeDet.ControlChequeDet_VinculoCodigo) 
                      ELSE CASE WHEN ControleChequeDet.ControlChequeDet_Vinculo = 'OUTROS' THEN ControleChequeDet.ControlChequeDet_EmitCNPJCPF END END END
                       END END END AS CNPJCPF
FROM         dbo.ControleCheque INNER JOIN
                      dbo.ControleChequeDet ON dbo.ControleCheque.ControlCheque_codigo = dbo.ControleChequeDet.ControlCheque_Codigo INNER JOIN
                      dbo.Bancos ON dbo.ControleChequeDet.Ban_Codigo = dbo.Bancos.Ban_Codigo
WHERE ControleCheque.ControlCheque_CodPagamento =:PControlCheque_CodPagamento and ControleCheque.ControlCheque_tipo =:pControlCheque_tipo


