sELECT     dbo.contas_Receber_det.ctr_codigo_det AS codigo, dbo.contas_Receber_det.Ctr_valor_pagamento AS valor, dbo.contas_Receber_det.Ctr_dt_vencimento AS data, 
                      dbo.Modo.Mdo_nome AS modo, dbo.contas_receber.Ctr_cod_documento AS NumeroDoc, dbo.Tipo_documento.Tpd_descricao AS tipodoc, 
                      dbo.contas_receber.Ctr_historico AS historico, CASE WHEN ctr_vinculo = 'CLIENTE' THEN
                          (SELECT     cli_nome
                            FROM          clientes
                            WHERE      clientes.cli_codigo = contas_receber.Ctr_codigo_vinculo) ELSE CASE WHEN ctr_vinculo = 'FORNECEDOR' THEN
                          (SELECT     for_nome
                            FROM          fornecedor
                            WHERE      fornecedor.for_codigo = contas_receber.Ctr_codigo_vinculo) ELSE CASE WHEN ctr_vinculo = 'PESSOAL' THEN
                          (SELECT     FUN_nome
                            FROM          funcionario
                            WHERE      funcionario.fun_cpf = contas_receber.Ctr_codigo_vinculo) ELSE CASE WHEN ctr_vinculo = 'INDICAÇÃO' THEN
                          (SELECT     IND_nome
                            FROM          Indicacoes
                            WHERE      Indicacoes.ind_codigo = contas_receber.Ctr_codigo_vinculo) 
                      ELSE CASE WHEN ctr_vinculo = 'OUTROS' THEN contas_receber.Ctr_nome END END END END END AS nome, 'CR' AS VIA, 'C' AS operacao, 
                      dbo.Contas_receber_pag.Crp_cod_pag as conta_pag
FROM         dbo.Modo INNER JOIN
                      dbo.contas_Receber_det ON dbo.Modo.Mdo_codigo = dbo.contas_Receber_det.Mdo_codigo INNER JOIN
                      dbo.contas_receber ON dbo.contas_Receber_det.Ctr_codigo = dbo.contas_receber.Ctr_codigo LEFT OUTER JOIN
                      dbo.Contas_receber_pag ON dbo.contas_Receber_det.ctr_codigo_det = dbo.Contas_receber_pag.ctr_codigo_det AND 
                      dbo.contas_Receber_det.Ctr_codigo = dbo.Contas_receber_pag.Ctr_codigo LEFT OUTER JOIN
                      dbo.Tipo_documento ON dbo.contas_receber.Tpd_codigo = dbo.Tipo_documento.Tpd_codigo
WHERE     (dbo.contas_Receber_det.Ctr_situacao = 'S')


union all

SELECT     dbo.contas_apagar_det.ctp_codigo_det AS codigo, dbo.contas_apagar_det.Ctp_valor_vencimento AS valor, dbo.contas_apagar_det.Ctp_dt_vencimento AS data, 
                      dbo.Modo.Mdo_nome AS modo, dbo.contas_apagar.Ctp_cod_documento AS NumeroDoc, dbo.Tipo_documento.Tpd_descricao AS tipodoc, 
                      dbo.contas_apagar.Ctp_historico AS historico, CASE WHEN ctp_vinculo = 'CLIENTE' THEN
                          (SELECT     cli_nome
                            FROM          clientes
                            WHERE      clientes.cli_codigo = contas_apagar.Ctp_codigo_vinculo) ELSE CASE WHEN ctp_vinculo = 'FORNECEDOR' THEN
                          (SELECT     for_nome
                            FROM          fornecedor
                            WHERE      fornecedor.for_codigo = contas_apagar.Ctp_codigo_vinculo) ELSE CASE WHEN ctp_vinculo = 'PESSOAL' THEN
                          (SELECT     FUN_nome
                            FROM          funcionario
                            WHERE      funcionario.fun_cpf = contas_apagar.Ctp_codigo_vinculo) ELSE CASE WHEN ctp_vinculo = 'INDICAÇÃO' THEN
                          (SELECT     IND_nome
                            FROM          Indicacoes
                            WHERE      Indicacoes.ind_codigo = contas_apagar.Ctp_codigo_vinculo) 
                      ELSE CASE WHEN ctp_vinculo = 'OUTROS' THEN contas_apagar.Ctp_nome END END END END END AS nome, 'CP' AS VIA, 'D' AS operacao, 
                      dbo.Contas_apagar_pag.Cpp_cod_pag AS codigo_pag
FROM         dbo.Modo INNER JOIN
                      dbo.contas_apagar_det ON dbo.Modo.Mdo_codigo = dbo.contas_apagar_det.Mdo_codigo INNER JOIN
                      dbo.contas_apagar ON dbo.contas_apagar_det.Ctp_codigo = dbo.contas_apagar.Ctp_codigo LEFT OUTER JOIN
                      dbo.Contas_apagar_pag ON dbo.contas_apagar_det.ctp_codigo_det = dbo.Contas_apagar_pag.ctp_codigo_det AND 
                      dbo.contas_apagar_det.Ctp_codigo = dbo.Contas_apagar_pag.Ctp_codigo LEFT OUTER JOIN
                      dbo.Tipo_documento ON dbo.contas_apagar.Tpd_codigo = dbo.Tipo_documento.Tpd_codigo
WHERE     (dbo.contas_apagar_det.Ctp_situacao = 'S')

-- [QrySaldo : TADOQuery]
SELECT     dbo.Contas_apagar_pag.Cpp_cod_pag AS codigo, dbo.Contas_apagar_pag.Cpp_valor_pago AS valor, 
                      dbo.Contas_apagar_pag.Cpp_data_pagamento AS data, dbo.Bancos_Caixas.Bcx_tipo AS TipoCT, dbo.Modo.Mdo_nome AS modo, 
                      dbo.Contas_apagar_pag.Cpp_numero_cheque AS cheque, dbo.contas_apagar.Ctp_cod_documento AS NumeroDoc, 
                      dbo.Tipo_documento.Tpd_descricao AS tipodoc, dbo.contas_apagar.Ctp_historico AS historico, CASE WHEN ctp_vinculo = 'CLIENTE' THEN
                          (SELECT     cli_nome
                            FROM          clientes
                            WHERE      clientes.cli_codigo = contas_apagar.Ctp_codigo_vinculo) ELSE CASE WHEN ctp_vinculo = 'FORNECEDOR' THEN
                          (SELECT     for_nome
                            FROM          fornecedor
                            WHERE      fornecedor.for_codigo = contas_apagar.Ctp_codigo_vinculo) ELSE CASE WHEN ctp_vinculo = 'PESSOAL' THEN
                          (SELECT     FUN_nome
                            FROM          funcionario
                            WHERE      funcionario.fun_cpf = contas_apagar.Ctp_codigo_vinculo) ELSE CASE WHEN ctp_vinculo = 'INDICAÇÃO' THEN
                          (SELECT     IND_nome
                            FROM          Indicacoes
                            WHERE      Indicacoes.ind_codigo = contas_apagar.Ctp_codigo_vinculo) 
                      ELSE CASE WHEN ctp_vinculo = 'OUTROS' THEN contas_apagar.Ctp_nome END END END END END AS nome, 
                      CASE WHEN Bancos_Caixas.Bcx_tipo = 'B' THEN 'Banco: ' + dbo.Bancos_Caixas.Bcx_Nome + ' - AG: ' + dbo.Bancos_Caixas.Bcx_agencia + ' CT: ' + dbo.Contas_Bancarias.Cba_numero
                       ELSE 'Caixa: ' + Contas_Bancarias.Cba_numero + ' - ' + dbo.Bancos_Caixas.Bcx_Nome END AS bancocaixa ,'CP' AS VIA, 'D' AS operacao
,CASE WHEN Bancos_Caixas.Bcx_tipo = 'B' THEN
                          (SELECT  top (1)   Movimento_bancario.Mba_efetivado
                            FROM          Movimento_bancario
                            WHERE      Movimento_bancario.Cpp_cod_pag = Contas_apagar_pag.Cpp_cod_pag order by Movimento_bancario.Cpp_cod_pag) ELSE 'S' END AS efetivado

FROM         dbo.contas_apagar_det INNER JOIN
                      dbo.Contas_apagar_pag ON dbo.contas_apagar_det.Ctp_codigo = dbo.Contas_apagar_pag.Ctp_codigo AND 
                      dbo.contas_apagar_det.ctp_codigo_det = dbo.Contas_apagar_pag.ctp_codigo_det INNER JOIN
                      dbo.Contas_Bancarias ON dbo.Contas_apagar_pag.cba_codigo = dbo.Contas_Bancarias.Cba_codigo AND 
                      dbo.Contas_apagar_pag.Emp_codigo = dbo.Contas_Bancarias.Emp_codigo INNER JOIN
                      dbo.Bancos_Caixas ON dbo.Contas_Bancarias.Bcx_codigo = dbo.Bancos_Caixas.Bcx_codigo AND 
                      dbo.Contas_Bancarias.Bcx_codigo = dbo.Bancos_Caixas.Bcx_codigo AND dbo.Contas_Bancarias.Bcx_codigo = dbo.Bancos_Caixas.Bcx_codigo AND 
                      dbo.Contas_Bancarias.Bcx_codigo = dbo.Bancos_Caixas.Bcx_codigo AND dbo.Contas_Bancarias.Emp_codigo = dbo.Bancos_Caixas.Emp_codigo AND
                       dbo.Contas_Bancarias.Emp_codigo = dbo.Bancos_Caixas.Emp_codigo AND 
                      dbo.Contas_Bancarias.Emp_codigo = dbo.Bancos_Caixas.Emp_codigo AND 
                      dbo.Contas_Bancarias.Emp_codigo = dbo.Bancos_Caixas.Emp_codigo INNER JOIN
                      dbo.Modo ON dbo.Contas_apagar_pag.mdo_codigo = dbo.Modo.Mdo_codigo INNER JOIN
                      dbo.contas_apagar ON dbo.contas_apagar_det.Ctp_codigo = dbo.contas_apagar.Ctp_codigo LEFT OUTER JOIN
                      dbo.Tipo_documento ON dbo.contas_apagar.Tpd_codigo = dbo.Tipo_documento.Tpd_codigo
WHERE     (dbo.contas_apagar_det.Ctp_situacao = 'S')

UNION ALL

SELECT     dbo.Contas_receber_pag.Crp_cod_pag AS codigo, dbo.Contas_receber_pag.Crp_valor_pago AS valor, 
                      dbo.Contas_receber_pag.Crp_data_pagamento AS data, dbo.Bancos_Caixas.Bcx_tipo AS TipoCT, dbo.Modo.Mdo_nome AS modo, 
