                      dbo.Tipo_documento.Tpd_descricao AS tipodoc, dbo.contas_receber.Ctr_historico AS historico, CASE WHEN ctr_vinculo = 'CLIENTE' THEN
                          (SELECT     cli_nome
                            FROM          clientes
                            WHERE      clientes.cli_codigo = contas_receber.Ctr_codigo_vinculo) ELSE CASE WHEN ctr_vinculo = 'FORNECEDOR' THEN
                          (SELECT     for_nome
                            FROM          fornecedor
                            WHERE      fornecedor.for_codigo = contas_receber.Ctr_codigo_vinculo) ELSE CASE WHEN ctr_vinculo = 'PESSOAL' THEN
                          (SELECT     FUN_nome
                            FROM          funcionario
                            WHERE      funcionario.fun_cpf = contas_receber.Ctr_codigo_vinculo) ELSE CASE WHEN ctr_vinculo = 'INDICAÇÃO' THEN
                          (SELECT     IND_nome
                            FROM          Indicacoes
                            WHERE      Indicacoes.ind_codigo = contas_receber.Ctr_codigo_vinculo) 
                      ELSE CASE WHEN ctr_vinculo = 'OUTROS' THEN contas_receber.Ctr_nome END END END END END AS nome, 
                      CASE WHEN Bancos_Caixas.Bcx_tipo = 'B' THEN 'Banco: ' + dbo.Bancos_Caixas.Bcx_Nome + ' - AG: ' + dbo.Bancos_Caixas.Bcx_agencia + ' CT: ' + dbo.Contas_Bancarias.Cba_numero
                       ELSE 'Caixa: ' + Contas_Bancarias.Cba_numero + ' - ' + dbo.Bancos_Caixas.Bcx_Nome END AS bancocaixa, 'CR' AS VIA, 'C' AS operacao
,CASE WHEN Bancos_Caixas.Bcx_tipo = 'B' THEN
                          (SELECT top (1)    Movimento_bancario.Mba_efetivado
                            FROM          Movimento_bancario
                            WHERE      Movimento_bancario.Crp_cod_pag = Contas_receber_pag.Crp_cod_pag order by Movimento_bancario.Crp_cod_pag) ELSE 'S' END AS efetivado


FROM         dbo.contas_Receber_det INNER JOIN
                      dbo.Contas_receber_pag ON dbo.contas_Receber_det.Ctr_codigo = dbo.Contas_receber_pag.Ctr_codigo AND 
                      dbo.contas_Receber_det.ctr_codigo_det = dbo.Contas_receber_pag.ctr_codigo_det INNER JOIN
                      dbo.Contas_Bancarias ON dbo.Contas_receber_pag.cba_codigo = dbo.Contas_Bancarias.Cba_codigo AND 
                      dbo.Contas_receber_pag.Emp_codigo = dbo.Contas_Bancarias.Emp_codigo INNER JOIN
                      dbo.Bancos_Caixas ON dbo.Contas_Bancarias.Bcx_codigo = dbo.Bancos_Caixas.Bcx_codigo AND 
                      dbo.Contas_Bancarias.Bcx_codigo = dbo.Bancos_Caixas.Bcx_codigo AND dbo.Contas_Bancarias.Bcx_codigo = dbo.Bancos_Caixas.Bcx_codigo AND 
                      dbo.Contas_Bancarias.Bcx_codigo = dbo.Bancos_Caixas.Bcx_codigo AND dbo.Contas_Bancarias.Emp_codigo = dbo.Bancos_Caixas.Emp_codigo AND
                       dbo.Contas_Bancarias.Emp_codigo = dbo.Bancos_Caixas.Emp_codigo AND 
                      dbo.Contas_Bancarias.Emp_codigo = dbo.Bancos_Caixas.Emp_codigo AND 
                      dbo.Contas_Bancarias.Emp_codigo = dbo.Bancos_Caixas.Emp_codigo INNER JOIN
                      dbo.Modo ON dbo.Contas_receber_pag.Mdo_codigo = dbo.Modo.Mdo_codigo INNER JOIN
                      dbo.contas_receber ON dbo.contas_Receber_det.Ctr_codigo = dbo.contas_receber.Ctr_codigo LEFT OUTER JOIN
                      dbo.Tipo_documento ON dbo.contas_receber.Tpd_codigo = dbo.Tipo_documento.Tpd_codigo
WHERE     (dbo.contas_Receber_det.Ctr_situacao = 'S')

UNION ALL


SELECT     0 AS codigo, dbo.Movimento_bancario.Mba_valor AS valor, dbo.Movimento_bancario.Mba_data_emissao AS data, 'B' AS tipoct, 
                      dbo.Movimento_bancario.Mba_din_che_tra AS modo, dbo.Movimento_bancario.Mba_numero_cheque AS cheque, '' AS numerodoc, '' AS tipodoc, 
                      dbo.Movimento_bancario.Mba_historico AS historico, '' AS nome, 
                      CASE WHEN Bancos_Caixas.Bcx_tipo = 'B' THEN 'Banco: ' + dbo.Bancos_Caixas.Bcx_Nome + ' - AG: ' + dbo.Bancos_Caixas.Bcx_agencia + ' CT: ' + dbo.Contas_Bancarias.Cba_numero
                       ELSE 'Caixa: ' + Contas_Bancarias.Cba_numero + ' - ' + dbo.Bancos_Caixas.Bcx_Nome END AS bancocaixa, 'DI' AS VIA

,   CASE WHEN Movimento_bancario.Mba_operacao = 'DÉBITO' THEN 'D' ELSE 'C' END AS operacao

,Movimento_bancario.Mba_efetivado AS efetivado
FROM         dbo.Contas_Bancarias INNER JOIN
                      dbo.Bancos_Caixas ON dbo.Contas_Bancarias.Bcx_codigo = dbo.Bancos_Caixas.Bcx_codigo AND 
                      dbo.Contas_Bancarias.Bcx_codigo = dbo.Bancos_Caixas.Bcx_codigo AND dbo.Contas_Bancarias.Bcx_codigo = dbo.Bancos_Caixas.Bcx_codigo AND 
                      dbo.Contas_Bancarias.Bcx_codigo = dbo.Bancos_Caixas.Bcx_codigo AND dbo.Contas_Bancarias.Emp_codigo = dbo.Bancos_Caixas.Emp_codigo AND
                       dbo.Contas_Bancarias.Emp_codigo = dbo.Bancos_Caixas.Emp_codigo AND 
                      dbo.Contas_Bancarias.Emp_codigo = dbo.Bancos_Caixas.Emp_codigo AND 
                      dbo.Contas_Bancarias.Emp_codigo = dbo.Bancos_Caixas.Emp_codigo INNER JOIN
                      dbo.Movimento_bancario ON dbo.Contas_Bancarias.Cba_codigo = dbo.Movimento_bancario.Cba_codigo AND 
                      dbo.Contas_Bancarias.Emp_codigo = dbo.Movimento_bancario.Emp_codigo
WHERE     (dbo.Movimento_bancario.Mba_efetivado = 'S') AND (dbo.Movimento_bancario.Cpp_cod_pag IS NULL) AND 
    (dbo.Movimento_bancario.Crp_cod_pag IS NULL)




union all


SELECT     0 AS codigo, dbo.Movimentos.Mvt_valor AS valor, dbo.Movimentos.Mvt_data AS data, 'B' AS tipoct, dbo.Movimentos.mvt_din_che_tran AS modo, 
                      '' AS cheque, dbo.Movimentos.Mvt_Numero_doc AS numerodoc, '' AS tipodoc, dbo.Movimentos.Mvt_obs AS historico, '' AS nome, 
                      CASE WHEN Bancos_Caixas.Bcx_tipo = 'B' THEN 'Banco: ' + dbo.Bancos_Caixas.Bcx_Nome + ' - AG: ' + dbo.Bancos_Caixas.Bcx_agencia + ' CT: ' + dbo.Contas_Bancarias.Cba_numero
                       ELSE 'Caixa: ' + Contas_Bancarias.Cba_numero + ' - ' + dbo.Bancos_Caixas.Bcx_Nome END AS bancocaixa, 'DI' AS VIA, 
                      CASE WHEN Movimentos.Mvt_credito_debito = 'DÉBITO' THEN 'D' ELSE 'C' END AS operacao
,'S' AS efetivado
FROM         dbo.Movimentos INNER JOIN
                      dbo.Contas_Bancarias ON dbo.Movimentos.Cba_codigo = dbo.Contas_Bancarias.Cba_codigo AND 
                      dbo.Movimentos.Cba_codigo = dbo.Contas_Bancarias.Cba_codigo AND dbo.Movimentos.Cba_codigo = dbo.Contas_Bancarias.Cba_codigo AND 
                      dbo.Movimentos.Cba_codigo = dbo.Contas_Bancarias.Cba_codigo AND dbo.Movimentos.Bcx_codigo = dbo.Contas_Bancarias.Bcx_codigo AND 
                      dbo.Movimentos.Bcx_codigo = dbo.Contas_Bancarias.Bcx_codigo AND dbo.Movimentos.Bcx_codigo = dbo.Contas_Bancarias.Bcx_codigo AND 
                      dbo.Movimentos.Bcx_codigo = dbo.Contas_Bancarias.Bcx_codigo AND dbo.Movimentos.Emp_codigo = dbo.Contas_Bancarias.Emp_codigo AND 
                      dbo.Movimentos.Emp_codigo = dbo.Contas_Bancarias.Emp_codigo AND dbo.Movimentos.Emp_codigo = dbo.Contas_Bancarias.Emp_codigo AND 
                      dbo.Movimentos.Emp_codigo = dbo.Contas_Bancarias.Emp_codigo INNER JOIN
                      dbo.Bancos_Caixas ON dbo.Contas_Bancarias.Bcx_codigo = dbo.Bancos_Caixas.Bcx_codigo AND 
                      dbo.Contas_Bancarias.Bcx_codigo = dbo.Bancos_Caixas.Bcx_codigo AND dbo.Contas_Bancarias.Bcx_codigo = dbo.Bancos_Caixas.Bcx_codigo AND 
                      dbo.Contas_Bancarias.Bcx_codigo = dbo.Bancos_Caixas.Bcx_codigo AND dbo.Contas_Bancarias.Emp_codigo = dbo.Bancos_Caixas.Emp_codigo AND
                       dbo.Contas_Bancarias.Emp_codigo = dbo.Bancos_Caixas.Emp_codigo AND 
                      dbo.Contas_Bancarias.Emp_codigo = dbo.Bancos_Caixas.Emp_codigo AND 
                      dbo.Contas_Bancarias.Emp_codigo = dbo.Bancos_Caixas.Emp_codigo
WHERE     (dbo.Movimentos.Cpp_cod_pag IS NULL) AND (dbo.Movimentos.Crp_cod_pag IS NULL)

-- [QryCheque : TADOQuery]
SELECT     dbo.ControleChequeDet.ControlChequeDet_Agencia, dbo.ControleChequeDet.ControlChequeDet_Conta, 
                      dbo.ControleChequeDet.ControlChequeDet_NumCheque, dbo.ControleChequeDet.ControlChequeDet_Situacao, dbo.Bancos.Ban_Nome, 
                      dbo.ControleCheque.ControlCheque_tipo, dbo.ControleCheque.ControlCheque_CodPagamento, 
                      CASE WHEN ControleChequeDet.ControlChequeDet_Vinculo = 'CLIENTE' THEN
                          (SELECT     cli_nome
                            FROM          clientes
                            WHERE      clientes.cli_codigo = ControleChequeDet.ControlChequeDet_VinculoCodigo) 
                      ELSE CASE WHEN ControleChequeDet.ControlChequeDet_Vinculo = 'FORNECEDOR' THEN
                          (SELECT     for_nome
                            FROM          fornecedor
                            WHERE      fornecedor.for_codigo = ControleChequeDet.ControlChequeDet_VinculoCodigo) 
                      ELSE CASE WHEN ControleChequeDet.ControlChequeDet_Vinculo = 'PESSOAL' THEN
                          (SELECT     FUN_nome
                            FROM          funcionario
                            WHERE      funcionario.fun_cpf = ControleChequeDet.ControlChequeDet_VinculoCodigo) 
                      ELSE CASE WHEN ControleChequeDet.ControlChequeDet_Vinculo = 'INDICAÇÃO' THEN
                          (SELECT     IND_nome
                            FROM          Indicacoes
                            WHERE      Indicacoes.ind_codigo = ControleChequeDet.ControlChequeDet_VinculoCodigo) 
                      ELSE CASE WHEN ControleChequeDet.ControlChequeDet_Vinculo = 'EMPRESA' THEN
                          (SELECT     EMPRESA.EMPRESA
                            FROM          empresa
                            WHERE      EMPRESA.CODLANC = ControleChequeDet.ControlChequeDet_VinculoCodigo) 
                      ELSE CASE WHEN ControleChequeDet.ControlChequeDet_Vinculo = 'OUTROS' THEN dbo.ControleChequeDet.ControlChequeDet_Emitente END END END
                       END END END AS nome, CASE WHEN ControleChequeDet.ControlChequeDet_Vinculo = 'CLIENTE' THEN
                          (SELECT     Cli_cnpj_cpf
                            FROM          clientes
                            WHERE      clientes.cli_codigo = ControleChequeDet.ControlChequeDet_VinculoCodigo) 
                      ELSE CASE WHEN ControleChequeDet.ControlChequeDet_Vinculo = 'FORNECEDOR' THEN
                          (SELECT     For_cnpj_cpf
                            FROM          fornecedor
                            WHERE      fornecedor.for_codigo = ControleChequeDet.ControlChequeDet_VinculoCodigo) 
                      ELSE CASE WHEN ControleChequeDet.ControlChequeDet_Vinculo = 'PESSOAL' THEN
                          (SELECT     CAST(funcionario.fun_cpf AS varCHAR(20))
                            FROM          funcionario
                            WHERE      funcionario.fun_cpf = ControleChequeDet.ControlChequeDet_VinculoCodigo) 
                      ELSE CASE WHEN ControleChequeDet.ControlChequeDet_Vinculo = 'INDICAÇÃO' THEN ' ' ELSE CASE WHEN ControleChequeDet.ControlChequeDet_Vinculo
                       = 'EMPRESA' THEN
                          (SELECT     EMPRESA.CGCCPF
                            FROM          empresa
                            WHERE      EMPRESA.CODLANC = ControleChequeDet.ControlChequeDet_VinculoCodigo) 
                      ELSE CASE WHEN ControleChequeDet.ControlChequeDet_Vinculo = 'OUTROS' THEN ControleChequeDet.ControlChequeDet_EmitCNPJCPF END END END
                       END END END AS CNPJCPF
FROM         dbo.ControleCheque INNER JOIN
                      dbo.ControleChequeDet ON dbo.ControleCheque.ControlCheque_codigo = dbo.ControleChequeDet.ControlCheque_Codigo INNER JOIN
                      dbo.Bancos ON dbo.ControleChequeDet.Ban_Codigo = dbo.Bancos.Ban_Codigo
WHERE ControleCheque.ControlCheque_CodPagamento =:PControlCheque_CodPagamento and ControleCheque.ControlCheque_tipo =:pControlCheque_tipo


/* ============================================================
   FORM: RltExtratoVenda   
   ============================================================ */

-- [Qryextrato : TADOQuery]
SELECT  MONTH(dbo.Venda.Ven_DataEmissao) AS mes, YEAR(dbo.Venda.Ven_DataEmissao) AS ano, SUM(dbo.Venda.Ven_Total) AS total
FROM            dbo.Venda INNER JOIN
                         dbo.VendaAtendente ON dbo.Venda.Ven_CodigoPre = dbo.VendaAtendente.VenAten_NDocPre INNER JOIN
                         dbo.Clientes ON dbo.Venda.Ven_CodVinculo = dbo.Clientes.Cli_Codigo INNER JOIN
                         dbo.CategoriaVenda ON dbo.Venda.CatVen_Codigo = dbo.CategoriaVenda.CatVen_Codigo
WHERE        (dbo.Venda.Ven_DataEmissao >= CONVERT(DATETIME, '2014-01-01 00:00:00', 102)) AND (dbo.Venda.Ven_DataEmissao <= CONVERT(DATETIME, '2018-12-31 00:00:00', 102))
GROUP BY YEAR(dbo.Venda.Ven_DataEmissao), MONTH(dbo.Venda.Ven_DataEmissao)
ORDER BY ano, mes


