   FORM: RltFechamentoMeta   RltFechamentoMeta
   ============================================================ */

-- [QryFechamento : TADOQuery]
SELECT 
  dbo.FechamentoMeta.FechMeta_Codigo,
  dbo.FechamentoMeta.FechMeta_MesAno,
  dbo.FechamentoMeta.FechMeta_data,
  dbo.FechamentoMeta.FechMeta_Obs
FROM
  dbo.FechamentoMeta
WHERE
  (dbo.FechamentoMeta.FechMeta_Codigo = :PFechMeta_Codigo)

-- [QryFechMetaF : TADOQuery]
SELECT 
  dbo.MetaVenda.MetaVenda_descricao,
  dbo.FechamentoMetaFunc.FechMetaFun_VlAlcancado,
  dbo.FechamentoMetaFunc.FechMetaFun_porcentagem,
  dbo.FechamentoMetaFunc.FechMeta_Codigo,
  dbo.Funcionario.Fun_Nome,
  dbo.FechamentoMetaFunc.Fun_codigo,
  dbo.MetaVendaDet.MetaVendaDet_Valor,
  dbo.CategoriaRemuneracao.CatRem_Descricao
FROM
  dbo.FechamentoMetaFunc
  LEFT OUTER JOIN dbo.Funcionario ON (dbo.FechamentoMetaFunc.Fun_codigo = dbo.Funcionario.Fun_CPF)
  LEFT OUTER JOIN dbo.MetaVenda ON (dbo.FechamentoMetaFunc.MetaVenda_Codigo = dbo.MetaVenda.MetaVenda_Codigo)
  LEFT OUTER JOIN dbo.MetaVendaDet ON (dbo.MetaVenda.MetaVenda_Codigo = dbo.MetaVendaDet.MetaVenda_Codigo)
  INNER JOIN dbo.CategoriaRemuneracao ON (dbo.FechamentoMetaFunc.CatRem_Codigo = dbo.CategoriaRemuneracao.CatRem_Codigo)
WHERE
  (dbo.FechamentoMetaFunc.FechMeta_Codigo = :PFechMeta_Codigo)

-- [QryFechMetaE : TADOQuery]
SELECT 
  dbo.FechamentoMetaEmp.Emp_Codigo,
  dbo.FechamentoMetaEmp.MetaVenda_Codigo,
  dbo.FechamentoMetaEmp.FechMetaEmp_VlAlcancado,
  dbo.FechamentoMetaEmp.FechMetaEmp_porcentagem,
  dbo.MetaVenda.MetaVenda_descricao,
dbo.MetaVenda.MetaVenda_valor
FROM
  dbo.FechamentoMetaEmp
  LEFT OUTER JOIN dbo.MetaVenda ON (dbo.FechamentoMetaEmp.MetaVenda_Codigo = dbo.MetaVenda.MetaVenda_Codigo)
WHERE
  (dbo.FechamentoMetaEmp.FechMeta_Codigo = :PFechMeta_Codigo)


