                         dbo.Clientes.Cli_dtnasc_conjuge, dbo.Clientes.Cli_conj_Fcomercial, dbo.Clientes.Cli_conj_Fresidencial, dbo.Clientes.Cli_conj_celular, dbo.Clientes.Cli_email, 
