-- [Qryprodutos : TADOQuery]
SELECT TOP (100) PERCENT dbo.produtos.pro_NCM, dbo.TabelaImposto.PIS_codigo, dbo.TabelaImposto.COFINS_codigo, dbo.produtos.Pro_codnosso, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, 
                  dbo.ProdutosFornecedores.ProdFor_DescricaoProduto, dbo.TabelaImposto.TbImp_icmsst, dbo.TabelaImposto.TbImp_icms, dbo.TabelaImposto.TbImp_descricao,
                      (SELECT TOP (1) dbo.nota_entrada_det.PIS_codigo
                       FROM      dbo.Nota_entrada INNER JOIN
                                         dbo.nota_entrada_det ON dbo.Nota_entrada.Nen_codigo = dbo.nota_entrada_det.Nen_codigo
                       WHERE   (NOT (dbo.nota_entrada_det.PIS_codigo IS NULL)) AND (dbo.nota_entrada_det.Pro_codnosso = dbo.produtos.Pro_codnosso)
                       ORDER BY dbo.Nota_entrada.Nen_dt_emissao DESC) AS pis_entrada,
                      (SELECT TOP (1) nota_entrada_det_1.COFINS_codigo
                       FROM      dbo.Nota_entrada AS Nota_entrada_1 INNER JOIN
                                         dbo.nota_entrada_det AS nota_entrada_det_1 ON Nota_entrada_1.Nen_codigo = nota_entrada_det_1.Nen_codigo
                       WHERE   (NOT (nota_entrada_det_1.COFINS_codigo IS NULL)) AND (nota_entrada_det_1.Pro_codnosso = dbo.produtos.Pro_codnosso)
                       ORDER BY Nota_entrada_1.Nen_dt_emissao DESC) AS confins_entrada, dbo.ProdutosFornecedores.For_codigo
FROM     dbo.produtos INNER JOIN
                  dbo.ProdutosFornecedores ON dbo.produtos.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso INNER JOIN
                  dbo.TabelaImposto ON dbo.produtos.TbImp_codigo = dbo.TabelaImposto.TbImp_codigo
ORDER BY dbo.ProdutosFornecedores.ProdFor_CodigoProduto


