SELECT        dbo.produtos.Pro_codnosso, dbo.produtos.Pro_Codbase, dbo.produtos.For_codigo, dbo.produtos.Pro_tp_produto, dbo.produtos.Pro_tp_peca, dbo.produtos.Pro_descricao, dbo.produtos.Pro_descricao_for, 
                         dbo.produtos.Pro_quant_minima, dbo.produtos.Pro_foto, dbo.produtos.Pro_dt_vigencia, dbo.produtos.Pro_exportado, dbo.produtos.Pro_ativo, dbo.produtos.Pro_unidade, dbo.produtos.Pro_comissao, 
                         dbo.produtos.Pro_lamp_reator, dbo.produtos.usr_cod_criacao, dbo.produtos.usr_dt_hr_criacao, dbo.produtos.usr_cod_alteracao, dbo.produtos.usr_dt_hr_alteracao, dbo.produtos.GrupoProduto_codigo, 
                         dbo.produtos.Pro_CodReduzido, dbo.produtos.Trib_Codigo, dbo.produtos.Pro_AliqICMS, dbo.produtos.Pro_Tensao, dbo.produtos.Pro_Consumo, dbo.produtos.Pro_TensaoBi, dbo.produtos.Pro_VaoLivre, 
                         dbo.produtos.Pro_Angulacao, dbo.produtos.Pro_Temp_Cor, dbo.produtos.pro_tempoInstalacao, dbo.produtos.TpTrib_codigo, dbo.produtos.TpOriPro_codigo, dbo.produtos.Pro_CodEspecial, dbo.produtos.Pro_Ecoreee, 
                         dbo.produtos.pro_NCM, dbo.produtos.Pro_IVA_ST, dbo.produtos.pro_AliqPIS, dbo.produtos.pro_AliqIPI, dbo.produtos.pro_AliqCOFINS, dbo.produtos.COFINS_codigo, dbo.produtos.PIS_codigo, dbo.produtos.IPI_codigo, 
                         dbo.produtos.TbImp_codigo, dbo.produtos.Pro_DescricaoComplementar, dbo.produtos.Pro_TipoProduto, dbo.produtos.Pro_GeneroProdServ, dbo.produtos.Desig_Codigo, dbo.produtos.Marca_Codigo, 
                         dbo.produtos.Prod_DescricaoLivre, dbo.produtos.Prod_ExibirSite, dbo.produtos.Fab_Codigo, dbo.produtos.Pro_CorteNicho, dbo.produtos.Pro_PesoLiq, dbo.produtos.Pro_PesoBruto, 
                         dbo.produtos.Pro_DescricaoComplementarFor, dbo.produtos.Pro_Dimensoes, dbo.produtos.Pro_PrazoEntrega, dbo.produtos.Pro_UnidadeEntrada, dbo.produtos.Pro_QuantEntrada, dbo.produtos.Pro_QuantSaida, 
                         dbo.produtos.Pro_AlturaProduto, dbo.produtos.Pro_LarguraProduto, dbo.produtos.Pro_ComprimentoProduto, dbo.produtos.Pro_RaioProduto, dbo.produtos.Pro_AlturaCaixa, dbo.produtos.Pro_LarguraCaixa, 
                         dbo.produtos.Pro_ComprimentoCaixa, dbo.produtos.Pro_RaioCaixa, dbo.produtos.Pro_CEST, dbo.produtos.ClasProd_codigo, dbo.produtos.Emp_codigo, dbo.produtos.Pro_Lumen, dbo.TipoOrigemProduto.TpOriPro_Descricao, 
                         dbo.GrupoProduto.GrupoProduto_Descricao, dbo.Fabrica.Fab_Descricao, dbo.Marca.Marca_Descricao, dbo.DESIGNER.Desig_Descricao, dbo.ClassificacaoProduto.ClasProd_Descricao, 
                         dbo.TabelaImposto.CFOP_codigo + ' - ' + dbo.TabelaImposto.TbImp_descricao AS descricaoimpostonfe
FROM            dbo.produtos LEFT OUTER JOIN
                         dbo.TabelaImposto ON dbo.produtos.TbImp_codigo = dbo.TabelaImposto.TbImp_codigo LEFT OUTER JOIN
                         dbo.ClassificacaoProduto ON dbo.produtos.ClasProd_codigo = dbo.ClassificacaoProduto.ClasProd_codigo LEFT OUTER JOIN
                         dbo.DESIGNER ON dbo.produtos.Desig_Codigo = dbo.DESIGNER.Desig_Codigo LEFT OUTER JOIN
                         dbo.Marca ON dbo.produtos.Marca_Codigo = dbo.Marca.Marca_Codigo LEFT OUTER JOIN
                         dbo.Fabrica ON dbo.produtos.Fab_Codigo = dbo.Fabrica.Fab_Codigo LEFT OUTER JOIN
                         dbo.TipoOrigemProduto ON dbo.produtos.TpOriPro_codigo = dbo.TipoOrigemProduto.TpOriPro_codigo LEFT OUTER JOIN
dbo.GrupoProduto ON dbo.produtos.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo

WHERE
  (dbo.produtos.Pro_CodReduzido =:CodRed)

-- [QryValores : TADOQuery]
SELECT 
  dbo.Preco_Produto.Pre_Codnosso,
  dbo.Preco_Produto.Pre_Acabamento,
  dbo.Preco_Produto.Pre_Codindice,
  dbo.Preco_Produto.Pre_Tabela,
  dbo.Preco_Produto.Pre_compra,
  dbo.Preco_Produto.Pre_Custo,
  dbo.Preco_Produto.Pre_Venda,
  dbo.Preco_Produto.Pre_Lucro,
  dbo.Preco_Produto.Pre_PorLucro,
  dbo.Preco_Produto.Pre_est_min,
  dbo.Preco_Produto.Pre_tp_vl,
  dbo.Preco_Produto.Pre_Ativo,
  dbo.Acabamento.DescAcabamento,
  dbo.Estoque_produto.Epr_estoque,
  Preco_Produto.Pre_VlNFor
FROM
  dbo.Preco_Produto
  LEFT OUTER JOIN dbo.Acabamento ON (dbo.Preco_Produto.Pre_Acabamento = dbo.Acabamento.CodAcabamento)
  INNER JOIN dbo.Estoque_produto ON (dbo.Preco_Produto.Pre_Codnosso = dbo.Estoque_produto.Epr_Codnosso)
  AND (dbo.Preco_Produto.Pre_Acabamento = dbo.Estoque_produto.Epr_Acabamento)
WHERE
  (dbo.Preco_Produto.Pre_Codnosso =:CodNosso)

-- [QryProRelacionado : TADOQuery]
SELECT        dbo.produtos.Pro_codnosso, dbo.ProdutosRelacionados.ProdRel_Descricao, dbo.ProdutosRelacionadosDet.CodAcabamento, dbo.ProdutosRelacionadosDet.ProdRelDet_Quantidade, 
                         CASE WHEN dbo.ProdutosRelacionadosDet.ProdRelDet_NaoRelacionado = 1 THEN 'SIM' ELSE 'NÃO' END AS ProdRelDet_NaoRelacionado, 
                         CASE WHEN dbo.ProdutosRelacionadosDet.ProdRelDet_padrao = 1 THEN 'SIM' ELSE 'NÃO' END AS ProdRelDet_padrao, dbo.ProdutosRelacionadosDet.Pro_codnosso AS Pro_codnossoRel
FROM            dbo.produtos INNER JOIN
                         dbo.ProdutosRelacionadosCadProdutos ON dbo.produtos.Pro_codnosso = dbo.ProdutosRelacionadosCadProdutos.Pro_codnosso INNER JOIN
                         dbo.ProdutosRelacionados ON dbo.ProdutosRelacionadosCadProdutos.ProdRel_codigo = dbo.ProdutosRelacionados.ProdRel_codigo INNER JOIN
                         dbo.ProdutosRelacionadosDet ON dbo.ProdutosRelacionados.ProdRel_codigo = dbo.ProdutosRelacionadosDet.ProdRel_codigo

WHERE
produtos.Pro_codnosso =:PPro_codnosso

-- [Qryfornecedores : TADOQuery]
SELECT        dbo.fornecedor.For_Nome, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto, dbo.ProdutosFornecedores.ProdFor_CodigoBarra, 
                         CASE WHEN dbo.ProdutosFornecedores.ProdFor_Padrao = 1 THEN 'SIM' ELSE 'NÃO' END AS ProdFor_Padrao, CASE WHEN dbo.ProdutosFornecedores.ProdFor_Situacao = 1 THEN 'SIM' ELSE 'NÃO' END AS ProdFor_Situacao, 
                         dbo.ProdutosFornecedores.ProdFor_DescricaoCompl, dbo.ProdutosFornecedores.ProdFor_Codigo, dbo.ProdutosFornecedores.ProdFor_prazo_entrega, dbo.ProdutosFornecedores.ProdFor_QtdeMinEmb, 
                         CASE WHEN dbo.ProdutosFornecedores.ProdFor_EmbFechada = 1 THEN 'SIM' ELSE 'NÃO' END AS ProdFor_EmbFechada
FROM            dbo.produtos INNER JOIN
                         dbo.ProdutosFornecedores ON dbo.produtos.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso INNER JOIN
                         dbo.fornecedor ON dbo.ProdutosFornecedores.For_codigo = dbo.fornecedor.For_codigo

where produtos.Pro_codnosso =:PPro_codnosso

-- [QryGed : TADOQuery]
SELECT        GED.dbo.GED.GED_Arquivo
FROM            dbo.produtos LEFT OUTER JOIN
                         GED.dbo.GED ON dbo.produtos.Pro_CodReduzido = GED.dbo.GED.GED_CadastroCodigo
WHERE        (SUBSTRING(dbo.produtos.Pro_codnosso, 1, 18) <> '999999999999999999') AND (GED.dbo.GED.GED_Arquivo IS NOT NULL)

and  produtos.Pro_codnosso =:PPro_codnosso


