                      dbo.Forma_Pagamento.Fpg_descricao, dbo.Modo.Mdo_nome, dbo.contas_receber.Ctr_codigo, dbo.contas_Receber_det.ctr_codigo_det
,CASE WHEN contas_Receber_det.Ctr_situacao = 'S' THEN 'SIM' ELSE 'NÃO' END AS situacao



