SELECT     dbo.Modo.Mdo_nome, dbo.Contas_receber_pag.Crp_valor_pago, dbo.Contas_receber_pag.Crp_data_pagamento, dbo.Contas_receber_pag.Crp_numero_banco, 
                      dbo.Contas_receber_pag.Crp_nome_banco, dbo.Contas_receber_pag.Crp_cpf_cnpj_emitente, dbo.Contas_receber_pag.Crp_agencia, 
                      dbo.Contas_receber_pag.Crp_conta_corrente, dbo.Contas_receber_pag.Crp_numero_cheque, dbo.Contas_receber_pag.Crp_emitente, 
                      dbo.Contas_receber_pag.Crp_numero_cartao, dbo.Contas_receber_pag.Crp_liberacao_cartao
FROM         dbo.Contas_receber_pag INNER JOIN
                      dbo.Modo ON dbo.Contas_receber_pag.Mdo_codigo = dbo.Modo.Mdo_codigo
where Contas_receber_pag.ctr_codigo_det =:pctr_codigo_det

