-- [Qrybalanco : TADOQuery]
SELECT  dbo.ForaDoBalanco.ForBal_codigo, dbo.ForaDoBalanco.ForBal_descricao, dbo.ForaDoBalanco.usr_cod_criacao, dbo.fornecedor.For_Nome, 
                         dbo.BalancoEstoque.BalEst_Descricao,  CASE WHEN forbal_Processado = 1 THEN 'SIM' ELSE 'NÃO' END AS forBal_Processado, dbo.ForaDoBalanco.ForBal_DataProc, dbo.SisUsuarios.Nome, 
                         dbo.ForaDoBalanco.ForBal_Data, dbo.produtos.Pro_codnosso, dbo.produtos.Pro_Codbase, dbo.produtos.Pro_tp_peca, dbo.produtos.Pro_descricao, 
                         dbo.produtos.Pro_descricao_for, dbo.produtos.Pro_unidade, dbo.produtos.Pro_CodEspecial, dbo.produtos.Pro_TipoProduto, 
                         dbo.ForaDoBalancoProduto.ForBalProd_Quant, dbo.ForaDoBalancoProduto.ForBalProd_QuantOrdem, dbo.ForaDoBalancoProduto.ForBalProd_QuantPedidoCompra, 
                         dbo.ForaDoBalancoProduto.ForBalProd_QuantEstoque, dbo.ForaDoBalancoProduto.ForBalProd_QuantNaoSeparada, 
                         dbo.ForaDoBalancoProduto.CodAcabamento
FROM            dbo.ForaDoBalanco INNER JOIN
                         dbo.fornecedor ON dbo.ForaDoBalanco.For_codigo = dbo.fornecedor.For_codigo INNER JOIN
                         dbo.ForaDoBalancoProduto ON dbo.ForaDoBalanco.ForBal_codigo = dbo.ForaDoBalancoProduto.ForBal_codigo INNER JOIN
                         dbo.produtos ON dbo.ForaDoBalancoProduto.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                         dbo.BalancoEstoque ON dbo.ForaDoBalanco.BalEst_Codigo = dbo.BalancoEstoque.BalEst_Codigo LEFT OUTER JOIN
                         dbo.SisUsuarios ON dbo.ForaDoBalanco.ForBal_UsuarioProc = dbo.SisUsuarios.Id

