-- [QryGanhos : TADOQuery]
SELECT     dbo.ControleRH.Tpd_codigo, dbo.ControleRH.CtrlRH_CodDocOri, dbo.ControleRH.CtrlRH_TpDocOri, dbo.ControleRH.CtrlRH_Valor, 
                      dbo.contas_Receber_det.Ctr_valor_vencimento, dbo.contas_Receber_det.Ctr_duplicata, dbo.contas_Receber_det.Ctr_recibo, 
                      dbo.contas_Receber_det.Ctr_dt_vencimento, Funcionario.Fun_CPF,
                          (SELECT     TOP (1) Crp_data_pagamento
                            FROM          dbo.Contas_receber_pag
                            WHERE      (ctr_codigo_det = dbo.contas_Receber_det.ctr_codigo_det)) AS DataPag, CASE WHEN ctrlrh_tpdocori = 1001 THEN
                          (SELECT     Clientes.Cli_Nome
                            FROM          pedido INNER JOIN
                                                   Clientes ON pedido.cli_codigo = Clientes.Cli_Codigo
                            WHERE      pedido.ped_codigo = controlerh.ctrlrh_coddocori AND pedido.ped_status = 'A') ELSE CASE WHEN ctrlrh_tpdocori = 1002 THEN
                          (SELECT     Clientes.Cli_Nome
                            FROM          avulso INNER JOIN
                                                   Clientes ON avulso.cli_codigo = Clientes.Cli_Codigo
                            WHERE      avulso.avu_codigo = controlerh.ctrlrh_coddocori) ELSE CASE WHEN ctrlrh_tpdocori = 1017 THEN
                          (SELECT     Clientes.Cli_Nome
                            FROM          Ent_devolucao INNER JOIN
                                                   Clientes ON Ent_devolucao.cli_codigo = Clientes.Cli_Codigo
                            WHERE      Ent_devolucao.EDV_codigo = controlerh.ctrlrh_coddocori) ELSE CASE WHEN ctrlrh_tpdocori = 1018 THEN
                          (SELECT     Clientes.Cli_Nome
                            FROM          Saida_complementacao INNER JOIN
                                                   Clientes ON Saida_complementacao.cli_codigo = Clientes.Cli_Codigo
                            WHERE      Saida_complementacao.SCP_codigo = controlerh.ctrlrh_coddocori) END END END END AS nome, dbo.Funcionario.Fun_Nome
FROM         dbo.ControleRH INNER JOIN
                      dbo.contas_Receber_det ON dbo.ControleRH.CtrlRH_ContaRefVincDet = dbo.contas_Receber_det.ctr_codigo_det INNER JOIN
                      dbo.Funcionario ON dbo.ControleRH.Fun_Codigo = dbo.Funcionario.Fun_CPF
WHERE     (dbo.ControleRH.FechComis_Codigo =:pFechComis_Codigo)


