-- [QryMetaVenda : TADOQuery]
select * from MetaVenda  WITH (NOLOCK)  where metaVenda_codigo =:PmetaVenda_codigo

-- [QryMetaVendaDet : TADOQuery]
SELECT   metaVendaDet.*,
 CategoriaRemuneracao.CatRem_Descricao
FROM
 metaVendaDet WITH (NOLOCK)
  INNER JOIN CategoriaRemuneracao ON (metaVendaDet.CatRem_Codigo = CategoriaRemuneracao.CatRem_Codigo)
 where metaVenda_codigo = :PmetaVenda_codigo

-- [QryCategoriaDVenda : TADOQuery]
