  dbo.CategoriaVenda.CatVen_Descricao,
  dbo.MetaVendaTpVenda.MetaVenda_Codigo
FROM
  dbo.MetaVendaTpVenda WITH (NOLOCK)
  INNER JOIN dbo.CategoriaVenda ON (dbo.MetaVendaTpVenda.CatVen_Codigo = dbo.CategoriaVenda.CatVen_Codigo)
WHERE
  (dbo.MetaVendaTpVenda.MetaVenda_Codigo = :PMetavendaCodigo)

-- [QryGrupoprod : TADOQuery]
SELECT 
  dbo.GrupoProduto.GrupoProduto_Descricao
FROM
  dbo.MetaVendaGrupProd
  INNER JOIN dbo.GrupoProduto ON (dbo.MetaVendaGrupProd.GrupoProduto_Codigo = dbo.GrupoProduto.GrupoProduto_Codigo)
WHERE
  (dbo.MetaVendaGrupProd.MetaVenda_Codigo = :MetaVenda_codigo)


