-- [QryMov : TADOQuery]
SELECT dbo.NotaFiscal.NTF_Numero, dbo.NotaFiscal.NTF_Serie, dbo.NotaFiscal.NTF_Modelo, 'E' AS NTF_Tipo, dbo.NotaFiscalTroca.Pro_codnosso, dbo.NotaFiscalTroca.CodAcabamento, dbo.produtos.Pro_descricao, 
                  dbo.fornecedor.For_Nome, dbo.ProdutosFornecedores.For_codigo, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto, dbo.NotaFiscalTroca.NTFT_quantidade AS quantidade, 
                  NotaFiscalTroca.NTFT_VLUnitario AS VLUnitario, NotaFiscalTroca.NTFT_VlTotal AS VlTotal,  dbo.NotaFiscal.usr_dt_hr_criacao AS data, null as observacao
FROM     dbo.NotaFiscal INNER JOIN
                  dbo.fornecedor INNER JOIN
                  dbo.ProdutosFornecedores INNER JOIN
                  dbo.produtos ON dbo.ProdutosFornecedores.Pro_codnosso = dbo.produtos.Pro_codnosso ON dbo.fornecedor.For_codigo = dbo.ProdutosFornecedores.For_codigo INNER JOIN
                  dbo.NotaFiscalTroca ON dbo.produtos.Pro_codnosso = dbo.NotaFiscalTroca.Pro_codnosso ON dbo.NotaFiscal.NTF_Codigo = dbo.NotaFiscalTroca.NTF_Codigo


