   FORM: RltNfeAgrupadaCFOP   RltNfeAgrupadaCFOP
   ============================================================ */

-- [QryNotas : TADOQuery]
SELECT dbo.NotaFiscal.CFOP_codigo, SUM(dbo.NotaFiscal.NTF_DespAcessoria) AS despesa, SUM(dbo.NotaFiscal.NTF_VlNota) AS TOTAL, SUM(dbo.NotaFiscal.NTF_VlIPI) AS ipi, SUM(dbo.NotaFiscal.NTF_BaseSubstICMS) AS basest, 
                  SUM(dbo.NotaFiscal.NTF_VlSubstICMS) AS vl_st, SUM(dbo.NotaFiscal.NTF_VlICMS) AS vl_icms, SUM(dbo.NotaFiscal.NTF_BaseICMS) AS base_icms, SUM(dbo.NotaFiscal.NTF_VLProdutos) AS vl_produtos, 
                  SUM(dbo.NotaFiscal.NTF_Desconto) AS desconto, dbo.CFOP.CFOP_Descricao
FROM     dbo.NotaFiscal INNER JOIN
                  dbo.CFOP ON dbo.NotaFiscal.CFOP_codigo = dbo.CFOP.CFOP_codigo
GROUP BY dbo.NotaFiscal.CFOP_codigo, dbo.CFOP.CFOP_Descricao

-- [QrySoma : TADOQuery]
SELECT SUM(NTF_DespAcessoria) AS despesa, SUM(NTF_VlNota) AS TOTAL, SUM(NTF_VlIPI) AS ipi, SUM(NTF_BaseSubstICMS) AS basest, SUM(NTF_VlSubstICMS) AS vl_st, SUM(NTF_VlICMS) AS vl_icms, SUM(NTF_BaseICMS) AS base_icms, 
                  SUM(NTF_VLProdutos) AS vl_produtos, SUM(NTF_Desconto) AS desconto
FROM     dbo.NotaFiscal


