-- [Qrydiferenca : TADOQuery]
SELECT     TOP (100) PERCENT dbo.Nota_entrada.Nen_numero_nota, dbo.fornecedor.For_Nome, dbo.Nota_Entrada_Dif.NenDf_DifProd, dbo.Nota_Entrada_Dif.NenDf_DifFinc, 
                      dbo.Nota_Entrada_Dif.NenDf_DesbUsuario, dbo.Nota_Entrada_Dif.NenDf_DesbData, dbo.Nota_Entrada_Dif.NenDf_Data, 
                      dbo.Motivo_devolucao.Mod_descricao AS motivoProd, Motivo_devolucao_1.Mod_descricao AS motivoFin,  
                      dbo.Nota_entrada.Nen_dt_nota, SisUsuarios.Nome 
FROM         dbo.Nota_entrada INNER JOIN
                      dbo.Nota_Entrada_Dif ON dbo.Nota_entrada.Nen_codigo = dbo.Nota_Entrada_Dif.Nen_codigo INNER JOIN
                      dbo.fornecedor ON dbo.Nota_entrada.Nen_fornecedor = dbo.fornecedor.For_codigo LEFT OUTER JOIN
                      dbo.SisUsuarios ON dbo.Nota_Entrada_Dif.NenDf_DesbUsuario = dbo.SisUsuarios.Id LEFT OUTER JOIN
                      dbo.Motivo_devolucao ON dbo.Nota_entrada.Mod_codigo = dbo.Motivo_devolucao.Mod_codigo LEFT OUTER JOIN
                      dbo.Motivo_devolucao AS Motivo_devolucao_1 ON dbo.Nota_entrada.nen_Mod_codigo_fin = Motivo_devolucao_1.Mod_codigo
ORDER BY dbo.fornecedor.For_Nome, dbo.Nota_entrada.Nen_dt_nota, dbo.Nota_Entrada_Dif.NenDf_DesbData


