                      dbo.Orcamento_materiais_det.oma_Desconto AS Desconto,VendaAmbiente.CodAmbiente,produtos.GrupoProduto_codigo
FROM         dbo.Orcamento_materiais_det INNER JOIN
                      dbo.produtos ON dbo.Orcamento_materiais_det.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                      dbo.VendaAmbiente ON dbo.Orcamento_materiais_det.orc_codigo_pre = dbo.VendaAmbiente.VenAmb_NDocPre
AND Orcamento_materiais_det.oma_ambiente = VendaAmbiente.CodAmbiente
