SELECT Municipio.mun_nome, Municipio.mun_uf, Obras.Obr_Descricao, Obras.Obr_Endereco, Obras.Obr_numero, Obras.Obr_complemento,
 Obras.Obr_Bairro, Obras.Obr_CEP, Obras.obr_transf, Clientes.Cli_Nome, Clientes.Cli_cnpj_cpf, Clientes.Cli_IE_RG,orcamento.orc_dt_emissao as data,
 Clientes.Cli_tp_pessoa, orcamento.orc_codigo as codigo, orcamento.orc_codigo_pre as precodigo
, dbo.orcamento.orc_tl_produto AS subtotal, dbo.orcamento.orc_desc_produto AS Desconto, 
   dbo.orcamento.orc_desc_por_produto AS DescontoPorc, dbo.orcamento.orc_tl_geral_produto AS Geral
,Clientes.Cli_Fcomercial, Clientes.Cli_celular,Clientes.Cli_email,Clientes.Cli_email
FROM orcamento INNER JOIN Obras ON orcamento.Obr_Codigo = Obras.Obr_Codigo INNER JOIN
 Clientes ON orcamento.cli_codigo =Clientes.Cli_Codigo LEFT OUTER JOIN
 Municipio ON Obras.mun_codigo = Municipio.mun_codigo

-- [QryCONTAS : TADOQuery]
SELECT     dbo.Modo.Mdo_nome AS mdo_nome, dbo.contas_Receber_det.Ctr_dt_vencimento, dbo.contas_Receber_det.Ctr_valor_vencimento, 
                      CASE WHEN contas_Receber_det.Ctr_situacao = 'S' THEN 'SIM' ELSE 'NÃO' END AS situacao, dbo.contas_Receber_det.Ctr_parcela
FROM         dbo.contas_receber INNER JOIN
                      dbo.contas_Receber_det ON dbo.contas_receber.Ctr_codigo = dbo.contas_Receber_det.Ctr_codigo LEFT OUTER JOIN
                      dbo.Modo ON dbo.contas_Receber_det.Mdo_codigo = dbo.Modo.Mdo_codigo

WHERE contas_receber.Ctr_cod_documento=:CODIGO and contas_receber.tpd_codigo=1001 and contas_receber.ParSV_serie =:pParSV_serie
and contas_receber.Tcf_codigo =:pTcf_codigo
order by contas_Receber_det.ctr_dt_vencimento

