FROM   Contas_receber_pag INNER JOIN
Modo ON Contas_receber_pag.Mdo_codigo = Modo.Mdo_codigo
WHERE  (Contas_receber_pag.Ctr_codigo =:codigo) AND (Contas_receber_pag.Ctr_codigo_det =:PCtr_codigo_det)

