SELECT   dbo.produtos.Pro_unidade AS unidade, dbo.VendaProduto.CodAcabamento AS acabamento, SUM(dbo.VendaProduto.VenPro_Quantidade) AS quantidade, dbo.VendaProduto.Pro_codnosso, 
                         MAX(dbo.VendaProduto.VenPro_VlUnitario) AS vl_unitario, SUM(dbo.VendaProduto.VenPro_VlItem) AS vl_item, SUM(dbo.VendaProduto.VenPro_Vldesconto) AS VenPro_Vldesconto, dbo.produtos.GrupoProduto_codigo, 
                         dbo.GrupoProduto.GrupoProduto_ordem AS ordem, dbo.produtos.Pro_CodEspecial, AVG(dbo.VendaProduto.VenPro_VlDescontoProc) AS Desconto, CASE WHEN substring(vendaproduto.Pro_codnosso, 1, 18) 
                         = '999999999999999999' THEN vendaproduto.VenPro_PreProduto ELSE dbo.ProdutosFornecedores.ProdFor_DescricaoProduto END AS Pro_descricao_for, CASE WHEN substring(vendaproduto.Pro_codnosso, 1, 18) 
                         = '999999999999999999' THEN vendaproduto.VenPro_PreProduto ELSE produtos.Pro_descricao END AS descricao, dbo.ProdutosFornecedores.ProdFor_CodigoProduto AS Pro_Codbase
FROM            dbo.GrupoProduto INNER JOIN
                         dbo.VendaProduto INNER JOIN
                         dbo.produtos ON dbo.VendaProduto.Pro_codnosso = dbo.produtos.Pro_codnosso ON dbo.GrupoProduto.GrupoProduto_Codigo = dbo.produtos.GrupoProduto_codigo INNER JOIN
                         dbo.ProdutosFornecedores ON dbo.VendaProduto.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso
WHERE        (dbo.VendaProduto.VenPro_Quantidade > 0) and VendaProduto.ven_codigopre =:pven_codigopre
GROUP BY dbo.produtos.Pro_unidade, dbo.VendaProduto.CodAcabamento, dbo.VendaProduto.Pro_codnosso, dbo.produtos.GrupoProduto_codigo, dbo.GrupoProduto.GrupoProduto_ordem, dbo.produtos.Pro_Codbase, 
                         dbo.produtos.Pro_CodEspecial, dbo.VendaProduto.Ven_CodigoPre, dbo.produtos.Pro_descricao_for, dbo.produtos.Pro_descricao, dbo.VendaProduto.VenPro_PreProduto, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, 
                         dbo.ProdutosFornecedores.ProdFor_DescricaoProduto
ORDER BY VenPro_SeqItem, dbo.VendaProduto.Pro_codnosso

