-- [QryVendaProduto : TADOQuery]
SELECT TOP (100) PERCENT SUM(dbo.VendaProduto.VenPro_VlItem) AS valor, dbo.VendaProduto.CodAmbiente, dbo.VendaProduto.VenPro_Seq, dbo.VendaAmbiente.VenAmb_Descricao, dbo.Venda.Ven_CodigoPre
FROM     dbo.Venda INNER JOIN
                  dbo.VendaProduto ON dbo.Venda.Ven_CodigoPre = dbo.VendaProduto.Ven_CodigoPre INNER JOIN
                  dbo.VendaAmbiente ON dbo.VendaProduto.Ven_CodigoPre = dbo.VendaAmbiente.VenAmb_NDocPre AND dbo.VendaProduto.CodAmbiente = dbo.VendaAmbiente.CodAmbiente
GROUP BY dbo.VendaProduto.CodAmbiente, dbo.VendaProduto.VenPro_Seq, dbo.VendaAmbiente.VenAmb_Descricao, dbo.Venda.Ven_CodigoPre
HAVING (dbo.Venda.Ven_CodigoPre =:pVen_CodigoPre)
ORDER BY dbo.VendaProduto.VenPro_Seq

