SELECT     dbo.VendaAmbiente.VenAmb_Descricao, dbo.VendaProduto.VenPro_Seq AS SEQ, dbo.VendaProduto.VenPro_SeqItem AS seq_item, 
                       dbo.produtos.Pro_unidade AS unidade, dbo.VendaProduto.CodAcabamento AS acabamento, 
                      dbo.VendaProduto.VenPro_Quantidade AS quantidade, dbo.VendaProduto.Pro_codnosso, dbo.VendaProduto.VenPro_VlUnitario AS vl_unitario, 
                      dbo.VendaProduto.VenPro_VlItem AS vl_item, dbo.VendaProduto.VenPro_Vldesconto, dbo.VendaAmbiente.CodAmbiente, dbo.produtos.GrupoProduto_codigo, 
                      dbo.GrupoProduto.GrupoProduto_ordem AS ordem, dbo.produtos.Pro_Codbase,  dbo.produtos.Pro_CodEspecial, VenPro_VldescontoProc AS Desconto,

      case when substring(vendaproduto.Pro_codnosso, 1,18)='999999999999999999' then vendaproduto.VenPro_PreProduto else produtos.Pro_descricao_for end Pro_descricao_for,
      case when substring(vendaproduto.Pro_codnosso, 1,18)='999999999999999999' then vendaproduto.VenPro_PreProduto else produtos.Pro_descricao end descricao



,prom_codigo
,VenPro_VlPromocao
,VenPro_ProcPromocao
,VenPro_VlCadastroPromocao
,Pro_tp_peca



FROM         dbo.GrupoProduto INNER JOIN
                      dbo.VendaAmbiente INNER JOIN
                      dbo.VendaProduto ON dbo.VendaAmbiente.VenAmb_NDocPre = dbo.VendaProduto.Ven_CodigoPre AND 
                      dbo.VendaAmbiente.CodAmbiente = dbo.VendaProduto.CodAmbiente INNER JOIN
                      dbo.produtos ON dbo.VendaProduto.Pro_codnosso = dbo.produtos.Pro_codnosso ON 
                      dbo.GrupoProduto.GrupoProduto_Codigo = dbo.produtos.GrupoProduto_codigo

WHERE     (dbo.VendaAmbiente.VenAmb_TpDoc =:pVenAmb_TpDoc) and VendaProduto.ven_codigopre =:pven_codigopre and (VendaProduto.VenPro_Quantidade > 0)
order by seq,seq_item, ordem

