-- [QryVendaProduto : TADOQuery]
SELECT   distinct
 dbo.VendaProduto.Pro_codnosso, dbo.produtos.Pro_Codbase, dbo.produtos.Pro_CodEspecial, CASE WHEN substring(vendaproduto.Pro_codnosso, 1, 18) 
                         = '999999999999999999' THEN vendaproduto.VenPro_PreProduto ELSE produtos.Pro_descricao_for END AS Pro_descricao_for, CASE WHEN substring(vendaproduto.Pro_codnosso, 1, 18) 
                         = '999999999999999999' THEN vendaproduto.VenPro_PreProduto ELSE produtos.Pro_descricao END AS descricao, GED.dbo.GED.GED_Arquivo,  
						 
CASE WHEN substring(vendaproduto.Pro_codnosso, 1, 18) = '999999999999999999' then VenPro_PreProdFoto  else dbo.produtos.Pro_foto end as Pro_foto						 



FROM            dbo.VendaProduto INNER JOIN
                         dbo.produtos ON dbo.VendaProduto.Pro_codnosso = dbo.produtos.Pro_codnosso LEFT JOIN
						 Ged.dbo.GED ON produtos.Pro_CodReduzido = GED.GED_CadastroCodigo
WHERE       VendaProduto.ven_codigopre =:pven_codigopre AND (dbo.VendaProduto.VenPro_Quantidade > 0) AND (dbo.produtos.GrupoProduto_codigo = 1)

