                  dbo.OrdemServicoProduto.OrdServProd_VlItem, dbo.OrdemServicoProduto.OrdServProd_Localizacao, dbo.OrdemServicoProduto.OrdServProd_Simbolo, dbo.OrdemServicoProduto.ASTEC_Codigo, 
                  dbo.OrdemServicoProduto.OrdServProd_Aplicacao, dbo.OrdemServicoProduto.OrdServProd_Operacao, CAST(dbo.Venda.Ven_codigo AS varchar(10)) + dbo.Venda.ParSV_serie AS pedidovenda, dbo.produtos.Pro_tp_peca, 
                  dbo.produtos.Pro_descricao, dbo.produtos.Pro_unidade, dbo.produtos.Pro_Angulacao, dbo.produtos.Pro_Temp_Cor, dbo.produtos.Pro_CodEspecial, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, 
