-- [Qryordem : TADOQuery]
SELECT     dbo.fornecedor.For_Nome, dbo.ordem_compra.Ocp_codigo, dbo.ordem_compra.Ocp_dt_envio, dbo.ordem_compra.Ocp_dt_ordem, 
                      dbo.ordem_compra.Ocp_dt_limite, dbo.ordem_compra.Ocp_status, dbo.ordem_compra.Ocp_dt_prevista, 
                      dbo.ordem_compra.Ocp_Reagendamento
FROM         dbo.ordem_compra INNER JOIN
                      dbo.fornecedor ON dbo.ordem_compra.Ocp_fornecedor = dbo.fornecedor.For_codigo INNER JOIN
                      dbo.ordem_compra_det ON dbo.ordem_compra.Ocp_codigo = dbo.ordem_compra_det.Ocp_codigo
where ordem_compra.Ocp_status ='A' 
and ((  ordem_compra.Ocp_dt_prevista>=:POcp_dt_prevista1 and  ordem_compra.Ocp_dt_prevista <=:pOcp_dt_prevista2) 
or (ordem_compra.Ocp_Reagendamento >=:POcp_Reagendamento1 and ordem_compra.Ocp_Reagendamento <=:pOcp_Reagendamento2))
AND ordem_compra_det.Ocd_nota = 0  and (ordem_compra_det.ocd_recebimento = 'PARCIAL' or ordem_compra_det.ocd_recebimento is null)
GROUP BY dbo.fornecedor.For_Nome, dbo.ordem_compra.Ocp_codigo, dbo.ordem_compra.Ocp_dt_envio, dbo.ordem_compra.Ocp_dt_ordem, 
                      dbo.ordem_compra.Ocp_dt_limite, dbo.ordem_compra.Ocp_status, dbo.ordem_compra.Ocp_dt_prevista, dbo.ordem_compra.Ocp_Reagendamento
order by ordem_compra.Ocp_dt_prevista, ordem_compra.Ocp_Reagendamento


