   FORM: RltOrdemCompra   
   ============================================================ */

-- [Qryordem : TADOQuery]
SELECT     dbo.Municipio.mun_nome, dbo.Municipio.mun_uf, dbo.fornecedor.For_Nome, dbo.fornecedor.For_Endereco, dbo.fornecedor.For_numero, dbo.fornecedor.For_fone1, 
                      dbo.fornecedor.For_fone2, dbo.fornecedor.For_fax, dbo.fornecedor.For_CEP, dbo.Transportadora.Tra_Nome, dbo.ordem_compra.Ocp_obs, 
                      dbo.ordem_compra.Ocp_codigo, dbo.fornecedor.For_Bairro
,ordem_compra.Ocp_SubTotal, ordem_compra.Ocp_Desconto, ordem_compra.Ocp_Acrescimo, ordem_compra.Ocp_Total
,ordem_compra.Ocp_descricao, ordem_compra.Ocp_PagImpdesc
,(SELECT     TOP (1) Con_nome
FROM         dbo.Contatos
WHERE  Con_tpcadastro = 'TRA' AND Con_codigo = Transportadora.Tra_codigo) AS TransContato, 

(SELECT     TOP (1) Con_fone
FROM         dbo.Contatos
WHERE  Con_tpcadastro = 'TRA' AND Con_codigo = Transportadora.Tra_codigo) AS TransFone

, fornecedor.For_JuntarCodigoAcabOrdem
, ordem_compra.Ocp_EmpresaCompradora

FROM     dbo.ordem_compra INNER JOIN
                  dbo.fornecedor ON dbo.ordem_compra.Ocp_fornecedor = dbo.fornecedor.For_codigo LEFT OUTER JOIN
                  dbo.Transportadora ON dbo.ordem_compra.Ocp_transportadora = dbo.Transportadora.Tra_codigo LEFT OUTER JOIN
                  dbo.Municipio ON dbo.fornecedor.For_codcidade = dbo.Municipio.mun_codigo
where ordem_compra.Ocp_codigo =:pOcp_codigo

-- [QryOrdemDet : TADOQuery]
SELECT    ordem_compra_det.Pro_codnosso,     dbo.ordem_compra_det.Ocd_acabamento, dbo.ProdutosFornecedores.ProdFor_CodigoProduto AS Pro_Codbase, 
CASE WHEN ProdutosFornecedores.ProdFor_DescricaoCompl IS NULL 
                         THEN ProdutosFornecedores.ProdFor_DescricaoProduto ELSE ProdutosFornecedores.ProdFor_DescricaoProduto + ' ' + ProdutosFornecedores.ProdFor_DescricaoCompl END AS Pro_descricao_for, 



                         MAX(dbo.ordem_compra_det.Ocd_vl_compra) AS Ocd_vl_compra, SUM(dbo.ordem_compra_det.Ocd_vl_item) AS Ocd_vl_item, MAX(dbo.ordem_compra_det.Ocd_vl_custo) AS Ocd_vl_custo, 
                         SUM(dbo.ordem_compra_det.Ocd_quantidade_solicit) AS Ocd_quantidade_solicit, dbo.Acabamento.DescAcabamento

,  ordem_compra_det.Ocd_acabamento + '  '+   CASE WHEN acab_tipo = 'E' THEN 'Ext.:' ELSE CASE WHEN acab_tipo = 'T' THEN 'Ext. e Inter.:' ELSE '' END END + dbo.Acabamento.DescAcabamento + '  ' + CASE WHEN acab_tipo2 = 'I' THEN 'Inter.:' ELSE '' END + CASE WHEN
                          DescAcabamento2 IS NULL THEN '' ELSE DescAcabamento2 END AS descricaoacabamento

, unidades.uni_descricao
FROM            dbo.ordem_compra_det INNER JOIN
                         dbo.produtos ON dbo.ordem_compra_det.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                         dbo.unidades ON dbo.produtos.Pro_unidade = dbo.unidades.uni_codigo INNER JOIN
                         dbo.Acabamento ON dbo.ordem_compra_det.Ocd_acabamento = dbo.Acabamento.CodAcabamento INNER JOIN
                         dbo.ProdutosFornecedores ON dbo.produtos.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso
WHERE        (dbo.ordem_compra_det.Ocp_codigo =:pOcp_codigo1) AND (dbo.unidades.uni_comprimento = 0)  and (ProdFor_Padrao=1)

GROUP BY dbo.ordem_compra_det.Ocd_acabamento, dbo.ProdutosFornecedores.ProdFor_DescricaoCompl, dbo.Acabamento.DescAcabamento, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, 
                         dbo.ProdutosFornecedores.ProdFor_DescricaoProduto, acab_tipo2, acab_tipo, DescAcabamento2 , unidades.uni_descricao,ordem_compra_det.Pro_codnosso

union all

SELECT    ordem_compra_det.Pro_codnosso,ordem_compra_det.Ocd_acabamento, dbo.ProdutosFornecedores.ProdFor_CodigoProduto AS Pro_Codbase, CASE WHEN ProdutosFornecedores.ProdFor_DescricaoCompl IS NULL 
                         THEN ProdutosFornecedores.ProdFor_DescricaoProduto ELSE ProdutosFornecedores.ProdFor_DescricaoProduto + ' ' + ProdutosFornecedores.ProdFor_DescricaoCompl END AS Pro_descricao_for, 
                         dbo.ordem_compra_det.Ocd_vl_compra, dbo.ordem_compra_det.Ocd_vl_item, dbo.ordem_compra_det.Ocd_vl_custo, dbo.ordem_compra_det.Ocd_quantidade_solicit, dbo.Acabamento.DescAcabamento

,  ordem_compra_det.Ocd_acabamento + '  '+   CASE WHEN acab_tipo = 'E' THEN 'Ext.:' ELSE CASE WHEN acab_tipo = 'T' THEN 'Ext. e Inter.:' ELSE '' END END + dbo.Acabamento.DescAcabamento + '  ' + CASE WHEN acab_tipo2 = 'I' THEN 'Inter.:' ELSE '' END + CASE WHEN
                          DescAcabamento2 IS NULL THEN '' ELSE DescAcabamento2 END AS descricaoacabamento


, unidades.uni_descricao

FROM            dbo.ordem_compra_det INNER JOIN
                         dbo.produtos ON dbo.ordem_compra_det.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                         dbo.unidades ON dbo.produtos.Pro_unidade = dbo.unidades.uni_codigo INNER JOIN
                         dbo.Acabamento ON dbo.ordem_compra_det.Ocd_acabamento = dbo.Acabamento.CodAcabamento INNER JOIN
                         dbo.ProdutosFornecedores ON dbo.produtos.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso
WHERE        (dbo.ordem_compra_det.Ocp_codigo =:pOcp_codigo2) AND (dbo.unidades.uni_comprimento = 1)  and (ProdFor_Padrao=1)

ORDER BY Pro_Codbase

