                      dbo.empresa.Emp_EnderecoEntrega, dbo.empresa.Emp_NumeroEntrega, dbo.empresa.Emp_ComplementoEntrega, dbo.empresa.Emp_BairroEntrega, 
                      dbo.empresa.Emp_CepEntrega, dbo.empresa.Emp_CodigoMunicipioEntrega, dbo.empresa.Emp_EmailEntrega, dbo.empresa.Emp_EnderecoCobranca, 
                      dbo.empresa.Emp_NumeroCobranca, dbo.empresa.Emp_ComplementoCobranca, dbo.empresa.Emp_BairroCobranca, dbo.empresa.Emp_CepCobranca, 
                      dbo.empresa.Emp_CodigoMunicipioCobranca, dbo.empresa.Emp_EmailCobranca
FROM         dbo.empresa INNER JOIN
                      dbo.Municipio AS Municipio_1 ON dbo.empresa.Emp_CodigoMunicipioCobranca = Municipio_1.mun_codigo INNER JOIN
                      dbo.Municipio ON dbo.empresa.Emp_CodigoMunicipioEntrega = dbo.Municipio.mun_codigo
where .empresa.CODLANC =:pCODLANC

