-- [QryVendaOBS : TADOQuery]
SELECT dbo.ordem_compra_det.Ocp_codigo, dbo.ordem_compra_det.Pro_codnosso, dbo.ordem_compra_det.Ocd_acabamento, dbo.VendaProduto.VenPro_Obs
FROM     dbo.ordem_compra_det INNER JOIN
                  dbo.VendaProduto ON dbo.ordem_compra_det.Ocd_cod_venda = dbo.VendaProduto.Ven_CodigoPre AND dbo.ordem_compra_det.Pro_codnosso = dbo.VendaProduto.Pro_codnosso AND 
                  dbo.ordem_compra_det.Ocd_acabamento = dbo.VendaProduto.CodAcabamento
WHERE ordem_compra_det.Ocp_codigo =:pOcp_codigo and ordem_compra_det.Pro_codnosso =:pPro_codnosso and ordem_compra_det.Ocd_acabamento =:pOcd_acabamento
and (VendaProduto.VenPro_Obs IS NOT NULL)


/* ============================================================
   FORM: RltOrdemCompraGeral   
   ============================================================ */

-- [Qryordem : TADOQuery]
SELECT     TOP (100) PERCENT dbo.ordem_compra.Ocp_codigo, dbo.ordem_compra.Ocp_modo, dbo.ordem_compra_det.ocd_ped_av_fan, dbo.ordem_compra_det.Pro_codnosso,
                       dbo.ordem_compra_det.Ocd_acabamento, dbo.ordem_compra_det.Ocd_quantidade_solicit, dbo.ordem_compra_det.Ocd_destino, 
                      dbo.ordem_compra_det.Ocd_recebimento, dbo.fornecedor.For_Nome, dbo.produtos.Pro_Codbase, dbo.produtos.Pro_descricao, dbo.produtos.Pro_descricao_for, 
                      dbo.produtos.Pro_CodEspecial, CASE WHEN ordem_compra.ocp_modo = 'P' THEN
                          (SELECT     Clientes.Cli_Nome
                            FROM          pedido INNER JOIN
                                                   Clientes ON pedido.cli_codigo = Clientes.Cli_Codigo AND ordem_compra_det.ocd_ped_av_fan = pedido.ped_codigo
                            WHERE      (pedido.ped_status = 'A')) ELSE CASE WHEN ordem_compra.ocp_modo = 'A' THEN
                          (SELECT     Clientes.Cli_Nome
                            FROM          Avulso INNER JOIN
                                                   Clientes ON Avulso.cli_codigo = Clientes.Cli_Codigo AND ordem_compra_det.ocd_ped_av_fan = avulso.avu_codigo) 
                      ELSE ordem_compra_det.ocd_destino END END AS nome, CASE WHEN ordem_compra.ocp_modo = 'P' THEN
                          (SELECT     Clientes.Cli_codigo
                            FROM          pedido INNER JOIN
                                                   Clientes ON pedido.cli_codigo = Clientes.Cli_Codigo AND ordem_compra_det.ocd_ped_av_fan = pedido.ped_codigo
                            WHERE      (pedido.ped_status = 'A')) ELSE CASE WHEN ordem_compra.ocp_modo = 'A' THEN
                          (SELECT     Clientes.Cli_codigo
                            FROM          Avulso INNER JOIN
                                                   Clientes ON Avulso.cli_codigo = Clientes.Cli_Codigo AND ordem_compra_det.ocd_ped_av_fan = avulso.avu_codigo) END END AS cli_codigo, 
                      CASE WHEN ordem_compra.ocp_modo = 'P' THEN 'PROJETO' ELSE CASE WHEN ordem_compra.ocp_modo = 'A' THEN 'VENDA AVULSA' ELSE 'LANC. DIRETO' END END
                       AS tpdoc, dbo.GrupoProduto.GrupoProduto_Descricao, dbo.produtos.Pro_tp_peca, dbo.produtos.Pro_unidade, dbo.ordem_compra.Ocp_dt_limite, 
                      dbo.ordem_compra.Ocp_dt_ordem, dbo.ordem_compra.Ocp_dt_envio, dbo.ordem_compra.Ocp_status, dbo.ordem_compra.Ocp_Reagendamento, 
                      dbo.ordem_compra.Ocp_dt_prevista, dbo.ordem_compra.Ocp_Total, dbo.ordem_compra.Ocp_Desconto, dbo.ordem_compra.Ocp_Acrescimo, 
                      dbo.ordem_compra.Ocp_SubTotal, dbo.ordem_compra_det.Ocd_quantidade_pedido, dbo.ordem_compra_det.Ocd_nota, dbo.ordem_compra_det.Ocd_cod_pedido
,ordem_compra_det.Ocd_vl_compra
FROM         dbo.ordem_compra INNER JOIN
                      dbo.ordem_compra_det ON dbo.ordem_compra.Ocp_codigo = dbo.ordem_compra_det.Ocp_codigo INNER JOIN
                      dbo.produtos ON dbo.ordem_compra_det.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                      dbo.fornecedor ON dbo.produtos.For_codigo = dbo.fornecedor.For_codigo INNER JOIN
                      dbo.GrupoProduto ON dbo.produtos.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo
WHERE     (dbo.ordem_compra.Ocp_status = 'A')
ORDER BY dbo.fornecedor.For_Nome, nome


/* ============================================================
   FORM: RltPaises   RltPaises
   ============================================================ */

-- [QryPaises : TADOQuery]
