-- [Qrypedido : TADOQuery]
SELECT  dbo.pedido_compra.Pcp_codigo, dbo.pedido_compra.Pcp_pedido_venda, dbo.pedido_compra.Pcp_modo, dbo.pedido_compra.Pcp_ped_av_fan, 
                      dbo.Pedido_compra_det.Pro_codnosso, dbo.Pedido_compra_det.Pcd_acabamento, dbo.Pedido_compra_det.Pcd_quantidade_solicit, 
                      dbo.Pedido_compra_det.Pcd_saida, dbo.Pedido_compra_det.Pcd_destino, dbo.Pedido_compra_det.Pcd_recebimento, dbo.fornecedor.For_Nome, 
                      dbo.produtos.Pro_Codbase, dbo.produtos.Pro_descricao, dbo.produtos.Pro_descricao_for, dbo.produtos.Pro_CodEspecial, 
                      CASE WHEN pedido_compra.Pcp_modo = 'P' THEN
                          (SELECT     Clientes.Cli_Nome
                            FROM          pedido INNER JOIN
                                                   Clientes ON pedido.cli_codigo = Clientes.Cli_Codigo AND pedido_compra.Pcp_ped_av_fan = pedido.ped_codigo
                            WHERE      (pedido.ped_status = 'A')) ELSE CASE WHEN pedido_compra.Pcp_modo = 'A' THEN
                          (SELECT     Clientes.Cli_Nome
                            FROM          Avulso INNER JOIN
                                                   Clientes ON Avulso.cli_codigo = Clientes.Cli_Codigo AND pedido_compra.Pcp_ped_av_fan = avulso.avu_codigo) 
                      ELSE Pedido_compra_det.Pcd_destino END END AS nome, CASE WHEN pedido_compra.Pcp_modo = 'P' THEN
                          (SELECT     Clientes.Cli_codigo
                            FROM          pedido INNER JOIN
                                                   Clientes ON pedido.cli_codigo = Clientes.Cli_Codigo AND pedido_compra.Pcp_ped_av_fan = pedido.ped_codigo
                            WHERE      (pedido.ped_status = 'A')) ELSE CASE WHEN pedido_compra.Pcp_modo = 'A' THEN
                          (SELECT     Clientes.Cli_codigo
                            FROM          Avulso INNER JOIN
                                                   Clientes ON Avulso.cli_codigo = Clientes.Cli_Codigo AND pedido_compra.Pcp_ped_av_fan = avulso.avu_codigo) END END AS cli_codigo, 
                      CASE WHEN pedido_compra.Pcp_modo = 'P' THEN 'PROJETO' ELSE CASE WHEN pedido_compra.Pcp_modo = 'A' THEN 'VENDA AVULSA' ELSE 'LANC. DIRETO' END END
                       AS tpdoc, dbo.GrupoProduto.GrupoProduto_Descricao, dbo.produtos.Pro_tp_peca, dbo.produtos.Pro_unidade, pedido_compra.Pcp_dt_pedido
,  (SELECT  Ocp_codigo FROM   ordem_compra_det
    WHERE ordem_compra_det.Pro_codnosso =Pedido_compra_det.Pro_codnosso AND ordem_compra_det.Ocd_acabamento =Pedido_compra_det.Pcd_acabamento AND ordem_compra_det.Ocd_item_ped =Pedido_compra_det.Pcd_item AND Ocd_cod_pedido =Pedido_compra_det.Pcp_codigo) as ordemcodigo



FROM         dbo.pedido_compra INNER JOIN
                      dbo.Pedido_compra_det ON dbo.pedido_compra.Pcp_codigo = dbo.Pedido_compra_det.Pcp_codigo INNER JOIN
                      dbo.produtos ON dbo.Pedido_compra_det.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                      dbo.fornecedor ON dbo.produtos.For_codigo = dbo.fornecedor.For_codigo INNER JOIN
                      dbo.GrupoProduto ON dbo.produtos.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo
WHERE     (dbo.pedido_compra.Pcp_status = 'A')
ORDER BY dbo.fornecedor.For_Nome, nome


