SELECT dbo.Venda.Ven_Tipo, dbo.Venda.Ven_Situacao, dbo.Venda.Ven_codigo, dbo.Venda.Ven_DataEmissao, dbo.Clientes.Cli_Nome, dbo.VendaProduto.Pro_codnosso, dbo.VendaProduto.CodAcabamento, 
                  dbo.VendaAmbiente.VenAmb_Descricao, dbo.VendaProduto.VenPro_Seq, dbo.VendaProduto.VenPro_Quantidade, dbo.VendaDataEntrega.VenDtEnt_quantidade, dbo.VendaDataEntrega.VenDtEnt_codigo, 
                  dbo.VendaDataEntrega.VenDtEnt_DataPrevEntrega, dbo.VendaDataEntrega.VenDtEnt_data, dbo.VendaDataEntrega.VenDtEnt_HoraChegada, dbo.VendaDataEntrega.VenDtEnt_HoraSaida, dbo.VendaDataRetorno.VenDtRet_data, 
                  dbo.VendaDataRetorno.VenDtRet_quantidade, dbo.VendaDataRetorno.VenDtRet_HoraChegada, dbo.VendaDataRetorno.VenDtRet_HoraSaida, dbo.VendaAtendente.VenAten_Principal, dbo.Funcionario.Fun_Nome, 
                  dbo.produtos.Pro_descricao, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto, dbo.fornecedor.For_Nome, dbo.produtos.Pro_tp_peca
,produtos.Pro_CodEspecial
FROM     dbo.Venda INNER JOIN
                  dbo.VendaProduto ON dbo.Venda.Ven_CodigoPre = dbo.VendaProduto.Ven_CodigoPre INNER JOIN
                  dbo.Clientes ON dbo.Venda.Ven_CodVinculo = dbo.Clientes.Cli_Codigo INNER JOIN
                  dbo.VendaAmbiente ON dbo.VendaProduto.Ven_CodigoPre = dbo.VendaAmbiente.VenAmb_NDocPre AND dbo.VendaProduto.CodAmbiente = dbo.VendaAmbiente.CodAmbiente INNER JOIN
                  dbo.VendaAtendente ON dbo.Venda.Ven_CodigoPre = dbo.VendaAtendente.VenAten_NDocPre INNER JOIN
                  dbo.produtos ON dbo.VendaProduto.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                  dbo.ProdutosFornecedores ON dbo.produtos.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso INNER JOIN
                  dbo.fornecedor ON dbo.ProdutosFornecedores.For_codigo = dbo.fornecedor.For_codigo LEFT OUTER JOIN
                  dbo.Funcionario ON dbo.VendaAtendente.Fun_Codigo = dbo.Funcionario.Fun_CPF LEFT OUTER JOIN
                  dbo.VendaDataEntrega ON dbo.VendaProduto.Ven_CodigoPre = dbo.VendaDataEntrega.Ven_CodigoPre AND dbo.VendaProduto.Pro_codnosso = dbo.VendaDataEntrega.Pro_codnosso AND 
                  dbo.VendaProduto.CodAcabamento = dbo.VendaDataEntrega.CodAcabamento AND dbo.VendaProduto.CodAmbiente = dbo.VendaDataEntrega.CodAmbiente AND 
                  dbo.VendaProduto.VenPro_Seq = dbo.VendaDataEntrega.VenPro_Seq AND dbo.VendaProduto.VenPro_SeqItem = dbo.VendaDataEntrega.VenPro_SeqItem LEFT OUTER JOIN
                  dbo.VendaDataRetorno ON dbo.VendaDataEntrega.Ven_CodigoPre = dbo.VendaDataRetorno.Ven_CodigoPre AND dbo.VendaDataEntrega.Pro_codnosso = dbo.VendaDataRetorno.Pro_codnosso AND 
                  dbo.VendaDataEntrega.CodAcabamento = dbo.VendaDataRetorno.CodAcabamento AND dbo.VendaDataEntrega.CodAmbiente = dbo.VendaDataRetorno.CodAmbiente AND 
                  dbo.VendaDataEntrega.VenPro_Seq = dbo.VendaDataRetorno.VenPro_Seq AND dbo.VendaDataEntrega.VenPro_SeqItem = dbo.VendaDataRetorno.VenPro_SeqItem
WHERE  (dbo.Venda.Ven_Tipo = 'D') AND (dbo.Venda.Ven_Situacao = 'A') AND (dbo.VendaAtendente.VenAten_Principal = 1)


