-- [QryVendaProduto : TADOQuery]
SELECT     sum(dbo.VendaProduto.VenPro_Quantidade) - CASE WHEN SUM(dbo.DevolucaoProduto.DevPro_Quantidade) 
                      > 0 THEN SUM(dbo.DevolucaoProduto.DevPro_Quantidade) ELSE 0 END AS quantidade, dbo.VendaProduto.Ven_CodigoPre, dbo.VendaProduto.Pro_codnosso, 
                      dbo.VendaProduto.CodAmbiente, dbo.VendaProduto.CodAcabamento, dbo.VendaProduto.VenPro_Seq, dbo.VendaProduto.VenPro_SeqItem, 
                      dbo.VendaProduto.VenPro_Quantidade, dbo.VendaProduto.VenPro_QuantidadeOriginal, dbo.VendaProduto.VenPro_VlUnitario, dbo.VendaProduto.VenPro_VlItem, 
                      dbo.VendaProduto.VenPro_Vldesconto, dbo.VendaProduto.VenPro_VlDescontoProc, dbo.VendaProduto.VenPro_Vlimposto, dbo.VendaProduto.VenPro_ProdutoPai, 
                      dbo.VendaProduto.VenPro_ProdutoSubPai, dbo.VendaProduto.VenPro_ItemPai, dbo.VendaProduto.VenPro_ItemSubPai, dbo.VendaProduto.Ven_ValorCredito, 
                      dbo.VendaProduto.pld_codindice, dbo.Venda.Ven_codigo, dbo.Venda.ParSV_serie, dbo.produtos.Pro_Codbase, dbo.produtos.Pro_tp_peca, 
                      dbo.produtos.Pro_descricao, dbo.produtos.Pro_descricao_for, dbo.produtos.Pro_foto, dbo.produtos.Pro_unidade, dbo.produtos.Pro_CodEspecial, 
                      dbo.GrupoProduto.GrupoProduto_Descricao, dbo.GrupoProduto.GrupoProduto_ordem, dbo.VendaAmbiente.VenAmb_Descricao
FROM         dbo.Venda INNER JOIN
                      dbo.VendaProduto ON dbo.Venda.Ven_CodigoPre = dbo.VendaProduto.Ven_CodigoPre INNER JOIN
                      dbo.produtos ON dbo.VendaProduto.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                      dbo.GrupoProduto ON dbo.produtos.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo INNER JOIN
                      dbo.Pasta ON dbo.Venda.Pasta_codigo = dbo.Pasta.Pasta_codigo INNER JOIN
                      dbo.VendaAmbiente ON dbo.VendaProduto.Ven_CodigoPre = dbo.VendaAmbiente.VenAmb_NDocPre AND 
                      dbo.VendaProduto.CodAmbiente = dbo.VendaAmbiente.CodAmbiente LEFT OUTER JOIN
                      dbo.Devolucao ON dbo.Venda.Ven_CodigoPre = dbo.Devolucao.ven_codigopre and devolucao.Dev_migrado is null LEFT OUTER JOIN
                      dbo.DevolucaoProduto ON dbo.VendaProduto.Pro_codnosso = dbo.DevolucaoProduto.Pro_codnosso AND 
                      dbo.Devolucao.Dev_CodigoPre = dbo.DevolucaoProduto.Dev_CodigoPre AND dbo.VendaProduto.CodAcabamento = dbo.DevolucaoProduto.CodAcabamento AND 
                      dbo.VendaProduto.CodAmbiente = dbo.DevolucaoProduto.CodAmbiente AND dbo.VendaProduto.VenPro_Seq = dbo.DevolucaoProduto.DevPro_Seq AND 
                      dbo.VendaProduto.VenPro_SeqItem = dbo.DevolucaoProduto.DevPro_SeqItem
WHERE     (dbo.Venda.Ven_Situacao = 'A') AND (dbo.Venda.Ven_Situacao = 'A') AND (dbo.Venda.Ven_Tipo = 'P') AND (dbo.VendaAmbiente.VenAmb_TpDoc = 'PRO')
AND pasta.pasta_codigo =:ppasta_codigo 

GROUP BY  VendaProduto.VenPro_Seq, dbo.VendaAmbiente.VenAmb_Descricao, VendaProduto.VenPro_SeqItem,  dbo.GrupoProduto.GrupoProduto_ordem, dbo.VendaProduto.Ven_CodigoPre, 
                      dbo.VendaProduto.Pro_codnosso, dbo.VendaProduto.CodAmbiente, dbo.VendaProduto.CodAcabamento, dbo.VendaProduto.VenPro_Quantidade, 
                      dbo.VendaProduto.VenPro_QuantidadeOriginal, dbo.VendaProduto.VenPro_VlUnitario, dbo.VendaProduto.VenPro_VlItem, dbo.VendaProduto.VenPro_Vldesconto, 
                      dbo.VendaProduto.VenPro_VlDescontoProc, dbo.VendaProduto.VenPro_Vlimposto, dbo.VendaProduto.VenPro_ProdutoPai, dbo.VendaProduto.VenPro_ProdutoSubPai, 
                      dbo.VendaProduto.VenPro_ItemPai, dbo.VendaProduto.VenPro_ItemSubPai, dbo.VendaProduto.Ven_ValorCredito, dbo.VendaProduto.pld_codindice, 
                      dbo.Venda.Ven_codigo, dbo.Venda.ParSV_serie, dbo.produtos.Pro_Codbase, dbo.produtos.Pro_tp_peca, dbo.produtos.Pro_descricao, dbo.produtos.Pro_descricao_for, 
                      dbo.produtos.Pro_foto, dbo.produtos.Pro_unidade, dbo.produtos.Pro_CodEspecial, dbo.GrupoProduto.GrupoProduto_Descricao

