-- [Qrydevolucoes : TADOQuery]
SELECT     SUM(dbo.Devolucao.Dev_SubTotal) AS Dev_SubTotal, SUM(dbo.Devolucao.Dev_Total) AS Dev_Total, SUM(dbo.Devolucao.Dev_SubTotalProd) AS Dev_SubTotalProd, 
                      SUM(dbo.Devolucao.Dev_TotalProd) AS Dev_TotalProd, SUM(dbo.Devolucao.Dev_SubTotalServ) AS Dev_SubTotalServ, SUM(dbo.Devolucao.Dev_TotalServ) 
                      AS Dev_TotalServ, SUM(dbo.Devolucao.Dev_ValorDesagio) AS Dev_ValorDesagio
FROM         dbo.Venda INNER JOIN
                      dbo.Devolucao ON dbo.Venda.Ven_CodigoPre = dbo.Devolucao.ven_codigopre
WHERE     (dbo.Devolucao.Dev_situacao = 1) AND (dbo.Devolucao.Dev_migrado IS NULL)

and      (Ven_Situacao = 'A') AND (Ven_Tipo = 'P') and venda.pasta_codigo =:ppasta_codigo


/* ============================================================
   FORM: RltProdutoPastaSemAmbObs   RltProdutoPastaSemAmbObs
   ============================================================ */

-- [Qryvenda : TADOQuery]
SELECT Municipio.mun_nome, Municipio.mun_uf, Obras.Obr_Descricao, Obras.Obr_Endereco, Obras.Obr_numero, Obras.Obr_complemento,
 Obras.Obr_Bairro, Obras.Obr_CEP, Obras.obr_transf, Clientes.Cli_Nome, Clientes.Cli_cnpj_cpf, Clientes.Cli_IE_RG,pasta.Pasta_DtEmissao as data,
 Clientes.Cli_tp_pessoa, pasta.pasta_codigo as codigo
 ,Clientes.Cli_Fcomercial, Clientes.Cli_celular, pasta.Pasta_Descricao, clientes.cli_email
FROM pasta INNER JOIN Obras ON pasta.Obr_Codigo = Obras.Obr_Codigo INNER JOIN
 Clientes ON pasta.cli_codigo =Clientes.Cli_Codigo LEFT OUTER JOIN
 Municipio ON Obras.mun_codigo = Municipio.mun_codigo 
where pasta.pasta_codigo =:ppasta_codigo

-- [QryVendaProduto : TADOQuery]
SELECT     SUM(dbo.VendaProduto.VenPro_Quantidade) -


(SELECT     CASE WHEN SUM(dbo.DevolucaoProduto.DevPro_Quantidade) > 0 THEN SUM(dbo.DevolucaoProduto.DevPro_Quantidade) ELSE 0 END AS Expr1
FROM         dbo.Devolucao INNER JOIN
                      dbo.DevolucaoProduto ON dbo.Devolucao.Dev_CodigoPre = dbo.DevolucaoProduto.Dev_CodigoPre
WHERE     (dbo.Devolucao.Dev_migrado IS NULL) AND (dbo.Devolucao.Dev_situacao = 1) AND DEVOLUCAO.ven_codigopre = VENDA.ven_codigopre and vendaproduto.pro_codnosso = devolucaoproduto.pro_codnosso
and vendaproduto.CodAcabamento = devolucaoproduto.CodAcabamento
and vendaproduto.CodAmbiente = devolucaoproduto.CodAmbiente
and vendaproduto.VenPro_Seq = devolucaoproduto.devPro_Seq
and vendaproduto.VenPro_SeqItem = devolucaoproduto.devPro_SeqItem

 ) AS quantidade

, dbo.VendaProduto.Ven_CodigoPre, dbo.VendaProduto.Pro_codnosso, 
                      dbo.VendaProduto.CodAcabamento,  
                       dbo.VendaProduto.VenPro_VlUnitario,  
                      dbo.VendaProduto.VenPro_VlDescontoProc,  
                       dbo.VendaProduto.Ven_ValorCredito, 
                      dbo.Venda.Ven_codigo, dbo.Venda.ParSV_serie,  dbo.produtos.Pro_tp_peca, dbo.produtos.Pro_descricao, 
                       dbo.produtos.Pro_unidade, dbo.produtos.Pro_CodEspecial 

, ProdutosFornecedores.ProdFor_CodigoProduto AS Pro_Codbase
, ProdutosFornecedores.ProdFor_DescricaoProduto AS Pro_descricao_for 
, fornecedor.For_Nome

FROM     dbo.Venda INNER JOIN
                  dbo.VendaProduto ON dbo.Venda.Ven_CodigoPre = dbo.VendaProduto.Ven_CodigoPre INNER JOIN
                  dbo.produtos ON dbo.VendaProduto.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                  dbo.GrupoProduto ON dbo.produtos.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo INNER JOIN
                  dbo.Pasta ON dbo.Venda.Pasta_codigo = dbo.Pasta.Pasta_codigo INNER JOIN
                  dbo.VendaAmbiente ON dbo.VendaProduto.Ven_CodigoPre = dbo.VendaAmbiente.VenAmb_NDocPre AND dbo.VendaProduto.CodAmbiente = dbo.VendaAmbiente.CodAmbiente INNER JOIN
                  dbo.ProdutosFornecedores ON dbo.produtos.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso
				   INNER JOIN
                  dbo.fornecedor ON dbo.ProdutosFornecedores.For_codigo = dbo.fornecedor.For_codigo





WHERE     (dbo.Venda.Ven_Situacao = 'A') AND (dbo.Venda.Ven_Tipo = 'P') AND (dbo.VendaAmbiente.VenAmb_TpDoc = 'PRO') AND (dbo.Pasta.Pasta_codigo =:pPasta_codigo)  AND (dbo.ProdutosFornecedores.ProdFor_Padrao = 1)
                     
GROUP BY
Venda.Ven_CodigoPre,
dbo.VendaProduto.Ven_CodigoPre, dbo.VendaProduto.Pro_codnosso, 
                      dbo.VendaProduto.CodAcabamento,   
                       dbo.VendaProduto.VenPro_VlUnitario,   
                      dbo.VendaProduto.VenPro_VlDescontoProc, 
                       dbo.VendaProduto.Ven_ValorCredito, 
                      dbo.Venda.Ven_codigo, dbo.Venda.ParSV_serie,  dbo.produtos.Pro_tp_peca, dbo.produtos.Pro_descricao, 
                       dbo.produtos.Pro_unidade, dbo.produtos.Pro_CodEspecial 

, ProdutosFornecedores.ProdFor_CodigoProduto 
, ProdutosFornecedores.ProdFor_DescricaoProduto  
, fornecedor.For_nome
,vendaproduto.CodAmbiente
,vendaproduto.VenPro_Seq
,vendaproduto.VenPro_SeqItem

-- [Qrytotal : TADOQuery]
SELECT 
SUM(Ven_SubTotalProd) AS Ven_SubTotalProd, 
SUM(Ven_TotalProd) AS Ven_TotalProd, 
SUM(Ven_SubTotalProd - Ven_TotalProd) AS DescProd, 
case when SUM(Ven_SubTotalProd - Ven_TotalProd)> 0 then SUM(Ven_SubTotalProd - Ven_TotalProd) * 100 / SUM(Ven_SubTotalProd) else 0 end AS DescPorcProd,
SUM(Ven_SubTotalServ) AS Ven_SubTotalServ, 
SUM(Ven_TotalServ) AS Ven_TotalServ, 
SUM(Ven_SubTotalServ - Ven_TotalServ) AS DescServ, 
case when SUM(Ven_SubTotalServ - Ven_TotalServ) > 0 then SUM(Ven_SubTotalServ - Ven_TotalServ)* 100 / SUM(Ven_SubTotalServ) else 0 end AS DescProcServ,
sum(Ven_SubTotal) as Ven_SubTotal,
sum(Ven_Total) as Ven_Total,
sum (Ven_SubTotal - Ven_Total) as DescTotal,
case when SUM(Ven_SubTotal - Ven_Total) > 0 then SUM(Ven_SubTotal - Ven_Total)* 100 / SUM(Ven_SubTotal) else 0 end AS DescProcTotal

FROM         dbo.Venda
WHERE      (Ven_Situacao = 'A') AND (Ven_Tipo = 'P') and venda.pasta_codigo =:ppasta_codigo

-- [Qrydevolucoes : TADOQuery]
SELECT     SUM(dbo.Devolucao.Dev_SubTotal) AS Dev_SubTotal, SUM(dbo.Devolucao.Dev_Total) AS Dev_Total, SUM(dbo.Devolucao.Dev_SubTotalProd) AS Dev_SubTotalProd, 
                      SUM(dbo.Devolucao.Dev_TotalProd) AS Dev_TotalProd, SUM(dbo.Devolucao.Dev_SubTotalServ) AS Dev_SubTotalServ, SUM(dbo.Devolucao.Dev_TotalServ) 
                      AS Dev_TotalServ, SUM(dbo.Devolucao.Dev_ValorDesagio) AS Dev_ValorDesagio
FROM         dbo.Venda INNER JOIN
                      dbo.Devolucao ON dbo.Venda.Ven_CodigoPre = dbo.Devolucao.ven_codigopre
WHERE     (dbo.Devolucao.Dev_situacao = 1) AND (dbo.Devolucao.Dev_migrado IS NULL)

and      (Ven_Situacao = 'A') AND (Ven_Tipo = 'P') and venda.pasta_codigo =:ppasta_codigo

-- [QryObs : TADOQuery]
select  VenPro_Obs from VendaProduto where Ven_CodigoPre  =:pVen_CodigoPre and Pro_codnosso  =:pPro_codnosso and CodAcabamento =:pCodAcabamento
and VenPro_Obs is not null


