   FORM: RltPromocao   RltPromocao
   ============================================================ */

-- [QryPromocao : TADOQuery]
select * from promocao
where Promocao.Prom_Codigo =:pProm_Codigo

-- [QryPromocaoProduto : TADOQuery]
SELECT dbo.PromocaoProdutos.Pro_codnosso, dbo.PromocaoProdutos.CodAcabamento, dbo.produtos.Pro_tp_peca, dbo.produtos.Pro_descricao, dbo.ProdutosFornecedores.ProdFor_CodigoProduto, 
                  dbo.ProdutosFornecedores.ProdFor_DescricaoProduto, dbo.produtos.Pro_CodEspecial, dbo.fornecedor.For_Nome, dbo.PromocaoProdutos.PromProd_codigo, dbo.PromocaoProdutos.Prom_Codigo, 
                  dbo.PromocaoProdutos.PromProd_TerminarEstoque, dbo.PromocaoProdutos.PromProd_QuantMinimaCompra, dbo.PromocaoProdutos.PromProd_VlNormal, dbo.PromocaoProdutos.PromProd_Vlpromocional, 
                  dbo.PromocaoProdutos.PromProd_desconto, dbo.PromocaoProdutos.PromProd_LucroBruto, dbo.PromocaoProdutos.PromProd_LucroLiq,produtos.Pro_unidade
FROM     dbo.PromocaoProdutos INNER JOIN
                  dbo.produtos ON dbo.PromocaoProdutos.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                  dbo.ProdutosFornecedores ON dbo.PromocaoProdutos.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso INNER JOIN
                  dbo.fornecedor ON dbo.ProdutosFornecedores.For_codigo = dbo.fornecedor.For_codigo
where PromocaoProdutos.Prom_Codigo =:pProm_Codigo

-- [QryPromocaoProdutoEst : TADOQuery]
SELECT        dbo.PromocaoEstoque.*, dbo.Estoque_produto.Epr_estoque, dbo.EstoqueTipo.EstTp_Descricao
FROM            dbo.PromocaoEstoque INNER JOIN
                         dbo.Estoque_produto ON dbo.PromocaoEstoque.EstTp_Codigo = dbo.Estoque_produto.EstTp_Codigo AND dbo.PromocaoEstoque.Pro_codnosso = dbo.Estoque_produto.Epr_Codnosso AND 
                         dbo.PromocaoEstoque.CodAcabamento = dbo.Estoque_produto.Epr_Acabamento INNER JOIN
                         dbo.EstoqueTipo ON dbo.PromocaoEstoque.EstTp_Codigo = dbo.EstoqueTipo.EstTp_Codigo
where  prom_codigo =:pprom_codigo


/* ============================================================
   FORM: RltQuadroCargas   
   ============================================================ */

-- [QryCargaLum : TADOQuery]
SELECT     dbo.VendaAmbiente.VenAmb_TpDoc, dbo.produtos.Pro_codnosso, dbo.produtos.Pro_Codbase, dbo.VendaAmbiente.VenAmb_Descricao, 
                      dbo.VendaAmbiente.CodAmbiente, dbo.produtos.Pro_tp_peca, dbo.GrupoProduto.GrupoProduto_Descricao, dbo.produtos.Pro_descricao, 
                      dbo.produtos.Pro_descricao_for, dbo.produtos.Pro_unidade, dbo.produtos.Pro_CodEspecial, dbo.VendaProduto.VenPro_Seq, dbo.VendaProduto.VenPro_SeqItem, 
                      dbo.VendaProduto.VenPro_Item, dbo.VendaProduto.CodAcabamento, dbo.VendaProduto.VenPro_Quantidade, dbo.Obras.Obr_Descricao, dbo.Venda.Ven_CodigoPre, 
                      CASE WHEN VendaProduto.venpro_quantidade * produtos.pro_consumo > 0 THEN VendaProduto.venpro_quantidade * produtos.pro_consumo ELSE 0 END + CASE WHEN
                       VendaProduto_1.venpro_quantidade * produtos_1.pro_consumo > 0 THEN VendaProduto_1.venpro_quantidade * produtos_1.pro_consumo ELSE 0 END AS consumototal,
                       dbo.Venda.ParSV_serie,produtos.pro_consumo, produtos.Pro_VaoLivre, produtos.Pro_CorteNicho
FROM         dbo.produtos AS produtos_1 INNER JOIN
                      dbo.VendaProduto AS VendaProduto_1 ON produtos_1.Pro_codnosso = VendaProduto_1.Pro_codnosso RIGHT OUTER JOIN
                      dbo.Venda INNER JOIN
                      dbo.VendaProduto ON dbo.Venda.Ven_CodigoPre = dbo.VendaProduto.Ven_CodigoPre INNER JOIN
                      dbo.produtos ON dbo.VendaProduto.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                      dbo.VendaAmbiente ON dbo.Venda.Ven_CodigoPre = dbo.VendaAmbiente.VenAmb_NDocPre INNER JOIN
                      dbo.GrupoProduto ON dbo.produtos.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo INNER JOIN
                      dbo.Obras ON dbo.Venda.Obr_codigo = dbo.Obras.Obr_Codigo ON VendaProduto_1.Ven_CodigoPre = dbo.VendaProduto.Ven_CodigoPre AND 
                      VendaProduto_1.VenPro_Seq = dbo.VendaProduto.VenPro_Seq AND VendaProduto_1.VenPro_SeqItem = dbo.VendaProduto.VenPro_SeqItem AND 
                      VendaProduto_1.VenPro_ItemPai = dbo.VendaProduto.VenPro_Item AND VendaProduto_1.VenPro_ProdutoPai = dbo.VendaProduto.Pro_codnosso
WHERE     (dbo.VendaAmbiente.VenAmb_TpDoc = 'PRO') AND (dbo.GrupoProduto.GrupoProduto_Codigo = 1) AND (dbo.VendaProduto.VenPro_Quantidade > 0)

-- [QryMateriais : TADOQuery]
SELECT DISTINCT 
dbo.VendaProduto.Pro_codnosso, 
dbo.VendaProduto.VenPro_Seq, 
dbo.VendaProduto.VenPro_SeqItem, 
dbo.VendaProduto.CodAmbiente,
dbo.VendaProduto.VenPro_Quantidade, 
dbo.produtos.Pro_Tensao, 
dbo.produtos.Pro_TensaoBi, 
dbo.produtos.Pro_Consumo, 
dbo.produtos.Pro_tp_produto, 
dbo.produtos.Pro_tp_peca, 
dbo.produtos.Pro_Codbase, 
dbo.produtos.Pro_VaoLivre, 
dbo.produtos.Pro_Angulacao, 
dbo.produtos.Pro_Temp_Cor,
produtos.Pro_descricao,
produtos.Pro_descricao_for,
produtos.Pro_CodEspecial

FROM VendaProduto INNER JOIN
produtos ON VendaProduto.Pro_codnosso = produtos.Pro_codnosso
WHERE
  (vendaproduto.ven_codigopre =:CodPedidoPre) AND 
  (vendaproduto.venpro_seq =:venpro_seq) AND 
  (vendaproduto.venpro_seqitem =:venpro_seqitem) 
and GrupoProduto_codigo > 1
order by  produtos.Pro_tp_peca


/* ============================================================
   FORM: RltQuadroCargasNaoRel   
   ============================================================ */

-- [QryNaoRelacionado : TADOQuery]
SELECT     dbo.produtos.Pro_Consumo, dbo.produtos.Pro_Tensao, SUM(dbo.VendaProduto.VenPro_Quantidade * dbo.produtos.Pro_Consumo) AS total, 
                      dbo.produtos.Pro_codnosso, dbo.produtos.Pro_Codbase, dbo.produtos.Pro_descricao, dbo.produtos.Pro_descricao_for, dbo.produtos.Pro_CodEspecial, 
                      dbo.VendaProduto.VenPro_Quantidade
FROM         dbo.VendaProduto AS VendaProduto_1 INNER JOIN
                      dbo.produtos AS produtos_1 ON VendaProduto_1.Pro_codnosso = produtos_1.Pro_codnosso AND produtos_1.GrupoProduto_codigo = 1 RIGHT OUTER JOIN
                      dbo.Venda INNER JOIN
                      dbo.VendaProduto ON dbo.Venda.Ven_CodigoPre = dbo.VendaProduto.Ven_CodigoPre INNER JOIN
                      dbo.produtos ON dbo.VendaProduto.Pro_codnosso = dbo.produtos.Pro_codnosso ON VendaProduto_1.Ven_CodigoPre = dbo.VendaProduto.Ven_CodigoPre AND 
                      VendaProduto_1.VenPro_Seq = dbo.VendaProduto.VenPro_Seq AND VendaProduto_1.VenPro_SeqItem = dbo.VendaProduto.VenPro_SeqItem
WHERE      (dbo.produtos.GrupoProduto_codigo > 1) AND (dbo.Venda.Ven_Tipo = :ventipo) AND (VendaProduto_1.Ven_CodigoPre IS NULL)
GROUP BY dbo.produtos.Pro_codnosso, dbo.produtos.Pro_Codbase, dbo.produtos.Pro_descricao, dbo.produtos.Pro_descricao_for, dbo.produtos.Pro_CodEspecial, 
                      dbo.VendaProduto.VenPro_Quantidade, dbo.produtos.Pro_Consumo, dbo.produtos.Pro_Tensao, dbo.produtos.GrupoProduto_codigo, VendaProduto_1.Ven_CodigoPre


/* ============================================================
   FORM: RltQuantitativoAmbienteObs   RltQuantitativoAmbienteObs
   ============================================================ */

-- [Qryprodutos : TADOQuery]
SELECT TOP (100) PERCENT dbo.VendaAmbiente.VenAmb_Descricao, dbo.produtos.Pro_descricao, dbo.VendaProduto.CodAcabamento, dbo.VendaProduto.Pro_codnosso, dbo.Marca.Marca_Descricao, 
                  dbo.produtos.Pro_unidade, dbo.produtos.Pro_PesoBruto, dbo.VendaProduto.VenPro_Vldesconto, dbo.produtos.Pro_tp_produto, dbo.VendaProduto.Ven_CodigoPre, SUM(dbo.VendaProduto.VenPro_Quantidade) 
                  AS tl_quantidade, AVG(dbo.VendaProduto.VenPro_VlUnitario) AS vl_unitario, SUM(dbo.VendaProduto.VenPro_VlItem) AS tl_vl_item, dbo.ProdutosFornecedores.ProdFor_CodigoProduto AS Pro_Codbase, 
                  dbo.ProdutosFornecedores.ProdFor_DescricaoProduto AS Pro_descricao_for, dbo.produtos.Pro_CodEspecial, dbo.Estoque_produto.Epr_estoque, SUM(dbo.VendaProduto.VenPro_Quantidade) 
                  - dbo.Estoque_produto.Epr_estoque AS quant_pedir, dbo.produtos.GrupoProduto_codigo, dbo.GrupoProduto.GrupoProduto_Descricao, dbo.produtos.Pro_tp_peca, VendaProduto.CodAmbiente
,SUBSTRING(VenPro_Obs, 1, 200) as VenPro_Obs
FROM     dbo.VendaProduto INNER JOIN
                  dbo.VendaAmbiente ON dbo.VendaProduto.Ven_CodigoPre = dbo.VendaAmbiente.VenAmb_NDocPre AND dbo.VendaProduto.CodAmbiente = dbo.VendaAmbiente.CodAmbiente INNER JOIN
                  dbo.produtos ON dbo.VendaProduto.Pro_codnosso = dbo.produtos.Pro_codnosso LEFT OUTER JOIN
                  dbo.Marca ON dbo.produtos.Marca_Codigo = dbo.Marca.Marca_Codigo INNER JOIN
                  dbo.Estoque_produto ON dbo.VendaProduto.Pro_codnosso = dbo.Estoque_produto.Epr_Codnosso AND dbo.VendaProduto.CodAcabamento = dbo.Estoque_produto.Epr_Acabamento INNER JOIN
                  dbo.GrupoProduto ON dbo.produtos.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo INNER JOIN
                  dbo.ProdutosFornecedores ON dbo.produtos.Pro_codnosso = dbo.ProdutosFornecedores.Pro_codnosso
WHERE   (dbo.VendaProduto.VenPro_Quantidade > 0) AND (dbo.VendaProduto.Ven_CodigoPre =:pVen_CodigoPre) AND (dbo.Estoque_produto.EstTp_Codigo = 1) and ProdutosFornecedores.ProdFor_Padrao= 1
GROUP BY dbo.VendaAmbiente.VenAmb_Descricao, dbo.VendaProduto.CodAcabamento, dbo.VendaProduto.Pro_codnosso, dbo.Marca.Marca_Descricao, dbo.produtos.Pro_unidade, dbo.produtos.Pro_PesoBruto, 
                  dbo.VendaProduto.VenPro_Vldesconto, dbo.produtos.Pro_tp_produto, dbo.VendaProduto.Ven_CodigoPre, dbo.produtos.Pro_descricao, dbo.produtos.Pro_Codbase, dbo.produtos.Pro_descricao_for, 
                  dbo.produtos.Pro_CodEspecial, dbo.Estoque_produto.Epr_estoque, dbo.produtos.GrupoProduto_codigo, dbo.GrupoProduto.GrupoProduto_Descricao, dbo.produtos.Pro_tp_peca, 
                  dbo.ProdutosFornecedores.ProdFor_CodigoProduto, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto,VendaProduto.CodAmbiente, SUBSTRING(VenPro_Obs, 1, 200) 
ORDER BY dbo.produtos.GrupoProduto_codigo, dbo.VendaAmbiente.VenAmb_Descricao, dbo.VendaProduto.Pro_codnosso

-- [QryVENDA : TADOQuery]
SELECT dbo.venda.ven_total AS Total_venda, dbo.Venda.Ven_codigo, dbo.Venda.ParSV_serie, dbo.Venda.Ven_DataEmissao, dbo.Clientes.Cli_Nome, dbo.clientes.cli_cnpj_cpf, dbo.clientes.cli_tp_pessoa, dbo.Municipio.mun_nome, 
                      dbo.clientes.cli_ie_rg, dbo.Municipio.mun_uf, dbo.Obras.Obr_Descricao, dbo.Obras.Obr_Endereco, dbo.Obras.Obr_numero, dbo.Obras.Obr_complemento, dbo.Obras.Obr_Bairro, 
                      dbo.Obras.Obr_UF, dbo.Obras.Obr_CEP, Venda.Ven_codigopre
, venda.emp_codigo, venda.Ven_Tipo
,Clientes.Cli_celular, Clientes.Cli_Fcomercial, dbo.Clientes.Cli_Fresidencial
, venda.Ven_DataPrevEntrega, venda.Ven_TipoEntrega
FROM     dbo.Venda INNER JOIN
                  dbo.Obras ON dbo.Venda.Obr_codigo = dbo.Obras.Obr_Codigo INNER JOIN
                  dbo.Clientes ON dbo.Obras.Cli_codigo = dbo.Clientes.Cli_Codigo LEFT OUTER JOIN
                  dbo.Municipio ON dbo.Obras.mun_codigo = dbo.Municipio.mun_codigo

WHERE     (Venda.Ven_codigopre =:pven_codigopre)

-- [QryEntregue : TADOQuery]
SELECT     SUM(dbo.controle_entrega_prod.cep_quantidade_entregue) AS totalentregue
FROM        dbo.Controle_entrega INNER JOIN
                  dbo.controle_entrega_prod ON dbo.Controle_entrega.cen_codigo_pre = dbo.controle_entrega_prod.cen_codigo_pre
WHERE     (dbo.controle_entrega_prod.cep_acabamento =:pcep_acabamento) 
AND (dbo.controle_entrega_prod.Pro_codnosso =:pPro_codnosso) 
AND (dbo.Controle_entrega.cen_pedido_avulso =:pcen_pedido_avulso)
and (Controle_entrega.ParSV_serie =:pParSV_serie)

-- [QryLogo : TADOQuery]
select * from GED where CatGED_codigo = 1002 and GED_CadastroCodigo =5


/* ============================================================
   FORM: RltQuantitativoObs   RltQuantitativoObs
   ============================================================ */

-- [Qryprodutos : TADOQuery]
SELECT dbo.produtos.Pro_descricao,  dbo.VendaProduto.Pro_codnosso, dbo.produtos.Pro_unidade, dbo.produtos.Pro_PesoBruto, 
                  CASE WHEN dbo.vendaproduto.VenPro_Vldesconto IS NULL THEN 0 ELSE dbo.vendaproduto.VenPro_Vldesconto END AS VenPro_Vldesconto, dbo.produtos.Pro_tp_produto, dbo.VendaProduto.Ven_CodigoPre, 
                  SUM(dbo.VendaProduto.VenPro_Quantidade) AS tl_quantidade, AVG(dbo.VendaProduto.VenPro_VlUnitario) AS vl_unitario, SUM(dbo.VendaProduto.VenPro_VlItem) AS tl_vl_item, 
                  dbo.ProdutosFornecedores.ProdFor_CodigoProduto AS Pro_Codbase, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto AS Pro_descricao_for, dbo.produtos.Pro_CodEspecial, 
                  dbo.Estoque_produto.Epr_estoque, SUM(dbo.VendaProduto.VenPro_Quantidade) - dbo.Estoque_produto.Epr_estoque AS quant_pedir, dbo.produtos.GrupoProduto_codigo, GrupoProduto_Descricao, 
                  dbo.produtos.Pro_tp_peca, dbo.fornecedor.For_Nome + ' - ' + fornecedor.For_Sigla as For_Nome
, dbo.Acabamento.DescAcabamento + ' - ' + dbo.Acabamento.CodAcabamento AS CodAcabamento

, dbo.ValorCusto(dbo.VendaProduto.Pro_codnosso, dbo.Acabamento.CodAcabamento, DATEADD(day, - 30, dbo.Venda.Ven_DataEmissao), 
                  dbo.Venda.Ven_DataEmissao) AS valor_custo, SUM(dbo.VendaProduto.VenPro_Quantidade) * dbo.ValorCusto(dbo.VendaProduto.Pro_codnosso, dbo.Acabamento.CodAcabamento, DATEADD(day, - 30, dbo.Venda.Ven_DataEmissao), 
                  dbo.Venda.Ven_DataEmissao) AS valor_item_custo, SUBSTRING(VendaProduto.VenPro_Obs, 1, 200)  
as VenPro_Obs

FROM     dbo.ProdutosFornecedores INNER JOIN
                  dbo.fornecedor ON dbo.ProdutosFornecedores.For_codigo = dbo.fornecedor.For_codigo INNER JOIN
                  dbo.VendaProduto INNER JOIN
                  dbo.produtos ON dbo.VendaProduto.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                  dbo.Estoque_produto ON dbo.VendaProduto.Pro_codnosso = dbo.Estoque_produto.Epr_Codnosso AND dbo.VendaProduto.CodAcabamento = dbo.Estoque_produto.Epr_Acabamento INNER JOIN
                  dbo.GrupoProduto ON dbo.produtos.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo ON dbo.ProdutosFornecedores.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                  dbo.Acabamento ON dbo.VendaProduto.CodAcabamento = dbo.Acabamento.CodAcabamento INNER JOIN
                  dbo.Venda ON dbo.VendaProduto.Ven_CodigoPre = dbo.Venda.Ven_CodigoPre


WHERE Venda.emp_codigo = Estoque_produto.emp_codigo and   (dbo.VendaProduto.VenPro_Quantidade > 0) AND (dbo.VendaProduto.Ven_CodigoPre =:pVen_CodigoPre) AND (dbo.Estoque_produto.EstTp_Codigo = 1)  and ProdutosFornecedores.ProdFor_Padrao= 1
GROUP BY dbo.VendaProduto.CodAcabamento, dbo.VendaProduto.Pro_codnosso, dbo.produtos.Pro_unidade, dbo.produtos.Pro_PesoBruto, CASE WHEN dbo.vendaproduto.VenPro_Vldesconto IS NULL 
                  THEN 0 ELSE dbo.vendaproduto.VenPro_Vldesconto END, dbo.produtos.Pro_tp_produto, dbo.VendaProduto.Ven_CodigoPre, dbo.produtos.Pro_descricao, dbo.produtos.Pro_Codbase, dbo.produtos.Pro_descricao_for, 
                  dbo.produtos.Pro_CodEspecial, dbo.Estoque_produto.Epr_estoque, dbo.produtos.GrupoProduto_codigo, dbo.GrupoProduto.GrupoProduto_Descricao, dbo.produtos.Pro_tp_peca, dbo.fornecedor.For_Nome, 
                  dbo.ProdutosFornecedores.ProdFor_CodigoProduto, dbo.ProdutosFornecedores.ProdFor_DescricaoProduto,Acabamento.DescAcabamento,Acabamento.CodAcabamento,Venda.Ven_DataEmissao,fornecedor.For_Sigla,  SUBSTRING(VendaProduto.VenPro_Obs, 1, 200)  
ORDER BY fornecedor.FOR_NOME, dbo.VendaProduto.Pro_codnosso

-- [QryVENDA : TADOQuery]
SELECT dbo.Venda.Ven_codigo, dbo.Venda.ParSV_serie, dbo.Venda.Ven_DataEmissao, dbo.Clientes.Cli_Nome, dbo.clientes.cli_cnpj_cpf, dbo.clientes.cli_tp_pessoa, dbo.Municipio.mun_nome, 
                      dbo.clientes.cli_ie_rg, dbo.Municipio.mun_uf, dbo.Obras.Obr_Descricao, dbo.Obras.Obr_Endereco, dbo.Obras.Obr_numero, dbo.Obras.Obr_complemento, dbo.Obras.Obr_Bairro, 
                      dbo.Obras.Obr_UF, dbo.Obras.Obr_CEP, Venda.Ven_codigopre, venda.emp_codigo
,Clientes.Cli_celular, Clientes.Cli_Fcomercial, dbo.Clientes.Cli_Fresidencial
, Venda.ven_tipo
,venda.Ven_DataPrevEntrega, venda.Ven_TipoEntrega
FROM     dbo.Venda INNER JOIN
                  dbo.Obras ON dbo.Venda.Obr_codigo = dbo.Obras.Obr_Codigo INNER JOIN
                  dbo.Clientes ON dbo.Obras.Cli_codigo = dbo.Clientes.Cli_Codigo LEFT OUTER JOIN
                  dbo.Municipio ON dbo.Obras.mun_codigo = dbo.Municipio.mun_codigo


WHERE     (Venda.Ven_codigopre =:pven_codigopre)

-- [QryEntregue : TADOQuery]
SELECT     SUM(dbo.controle_entrega_prod.cep_quantidade_entregue) AS totalentregue
FROM        dbo.Controle_entrega INNER JOIN
                  dbo.controle_entrega_prod ON dbo.Controle_entrega.cen_codigo_pre = dbo.controle_entrega_prod.cen_codigo_pre
WHERE     (dbo.controle_entrega_prod.cep_acabamento =:pcep_acabamento) 
AND (dbo.controle_entrega_prod.Pro_codnosso =:pPro_codnosso) 
AND (dbo.Controle_entrega.cen_pedido_avulso =:pcen_pedido_avulso)
and (Controle_entrega.ParSV_serie =:pParSV_serie)


