SELECT     dbo.contas_Receber_det.Ctr_parcela, dbo.contas_receber.Ctr_cod_documento, dbo.Tipo_documento.Tpd_descricao, dbo.Tipo_documento.Tpd_codigo, 
                      dbo.contas_receber.Ctr_Desconto_vl AS Desconto_vl_parc, dbo.contas_receber.Ctr_Desconto_por AS Desconto_por_parc, dbo.contas_receber.Ctr_vinculo, 
                      dbo.contas_receber.Ctr_codigo_vinculo,
                          (SELECT     COUNT(Ctr_codigo) AS Expr1
                            FROM          dbo.contas_Receber_det AS contar
                            WHERE      (Ctr_codigo = dbo.contas_receber.Ctr_codigo)) AS TotalParcela, dbo.contas_receber.Ctr_codigo, 
                      CASE WHEN Tipo_documento.Tpd_codigo = 1001 THEN
                          (SELECT     ped_codigo_pre
                            FROM          pedido
                            WHERE      pedido.ped_codigo = contas_receber.Ctr_cod_documento AND pedido.ped_status = 'A') 
                      ELSE CASE WHEN Tipo_documento.Tpd_codigo = 1002 THEN
                          (SELECT     avu_codigo_pre
                            FROM          avulso
                            WHERE      avulso.avu_codigo = contas_receber.Ctr_cod_documento) ELSE 0 END END AS CodigoDocPre, 
                      CASE WHEN Tipo_documento.Tpd_codigo = 1001 THEN 'PRO' ELSE CASE WHEN Tipo_documento.Tpd_codigo = 1002 THEN 'AVU' ELSE 'NNN' END END AS TipoDoc, 
                      dbo.contas_Receber_det.Ctr_recibo, dbo.contas_Receber_det.Ctr_reciboImp, dbo.contas_Receber_det.Ctr_reciboImpData, 
                      dbo.contas_Receber_det.Ctr_valor_vencimento, dbo.contas_Receber_det.Ctr_dt_vencimento, dbo.contas_Receber_det.ctr_codigo_det
FROM         dbo.contas_receber INNER JOIN
                      dbo.contas_Receber_det ON dbo.contas_receber.Ctr_codigo = dbo.contas_Receber_det.Ctr_codigo INNER JOIN
                      dbo.Tipo_documento ON dbo.contas_receber.Tpd_codigo = dbo.Tipo_documento.Tpd_codigo
where Contas_receber_det.ctr_codigo_det =:Pctr_codigo_det

