                      dbo.Reserva_tecnica_GrupoProd.GrupoProduto_Codigo, dbo.Reserva_tecnica_GrupoProd.RetGProd_PorcRT
                      
FROM         dbo.Reserva_tecnica INNER JOIN
                      dbo.Reserva_tecnica_GrupoProd ON dbo.Reserva_tecnica.Ret_codigo = dbo.Reserva_tecnica_GrupoProd.Ret_codigo INNER JOIN
                      dbo.GrupoProduto ON dbo.Reserva_tecnica_GrupoProd.GrupoProduto_Codigo = dbo.GrupoProduto.GrupoProduto_Codigo

