-- [ADOQuery2 : TADOQuery]
SELECT     CASE WHEN ped_DESC_POR_materiais IS NOT NULL THEN SUM(dbo.pedido_materiais_det.pma_vl_item)                                           
                 - (SUM(dbo.pedido_materiais_det.pma_vl_item) * (ped_DESC_POR_materiais / 100)) END AS SOMA, dbo.produtos.GrupoProduto_codigo,    
                 dbo.GrupoProduto.GrupoProduto_Descricao                                                                                          
FROM         dbo.pedido INNER JOIN                                                                                                                
                 dbo.pedido_materiais_det ON dbo.pedido.ped_codigo_pre = dbo.pedido_materiais_det.ped_codigo_pre INNER JOIN                       
                 dbo.produtos ON dbo.pedido_materiais_det.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN                                     
                 dbo.GrupoProduto ON dbo.produtos.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo                                      
WHERE     dbo.pedido.ped_codigo =:codigo1                                                                                                     
GROUP BY dbo.produtos.GrupoProduto_codigo, dbo.pedido.ped_desc_por_materiais, dbo.GrupoProduto.GrupoProduto_Descricao                             

union all                                                                                                                                         

SELECT     CASE WHEN ped_DESC_POR_luminaria IS NOT NULL THEN SUM(dbo.pedido_luminaria_det.pld_vl_item)                                            
                      - (SUM(dbo.pedido_luminaria_det.pld_vl_item) * (ped_DESC_POR_luminaria / 100)) END AS SOMA, dbo.produtos.GrupoProduto_codigo,    
                      dbo.GrupoProduto.GrupoProduto_Descricao                                                                                          
     FROM         dbo.pedido AS pedidolu INNER JOIN                                                                                                    
                      dbo.pedido_luminaria_det ON pedidolu.ped_codigo_pre = dbo.pedido_luminaria_det.ped_codigo_pre INNER JOIN                         
                      dbo.produtos ON dbo.pedido_luminaria_det.Pro_codnosso = dbo.produtos.Pro_codnosso RIGHT OUTER JOIN                               
                      dbo.GrupoProduto ON dbo.produtos.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo                                      
     WHERE     pedidolu.ped_codigo =:codigo2                                                                                                         
     GROUP BY dbo.produtos.GrupoProduto_codigo, pedidolu.ped_desc_por_luminaria, dbo.GrupoProduto.GrupoProduto_Descricao                               

     union all                                                                                                                                         

     SELECT     CASE WHEN ped_DESC_POR_servico IS NOT NULL THEN SUM(dbo.pedido_servico_det.pse_vl_item) - (SUM(dbo.pedido_servico_det.pse_vl_item)     
                           * (ped_DESC_POR_servico / 100)) END AS SOMA, '1000' AS GrupoProduto_codigo, 'SERVIÇOS' AS GrupoProduto_Descricao        
     FROM         dbo.Servicos INNER JOIN                                                                                                              
                           dbo.pedido_servico_det ON dbo.Servicos.sev_cod = dbo.pedido_servico_det.Sev_cod RIGHT OUTER JOIN                            
                           dbo.pedido AS pedidose ON dbo.pedido_servico_det.ped_codigo_pre = pedidose.ped_codigo_pre                                   
     WHERE     pedidose.ped_codigo =:codigo3                                                                                                         
     GROUP BY pedidose.ped_desc_por_servico                                                                                                            
ORDER BY dbo.produtos.GrupoProduto_codigo

