-- [QryResultadoFinanceiro : TADOQuery]
SELECT DISTINCT 
  'RECEITAS' AS tipoconta,
  dbo.Plano_Contas.Pco_FixaVariavel,
  SUM(dbo.Contas_receber_pag.Crp_valor_pago) AS valor,
  dbo.Plano_Contas.Pco_descricao,
  dbo.Plano_Contas.Pco_pai,
  SUM(dbo.Contas_receber_pag.Crp_valor_pago) AS ValorPago
  FROM         dbo.contas_receber INNER JOIN
                      dbo.Contas_receber_pag ON dbo.contas_receber.Ctr_codigo = dbo.Contas_receber_pag.Ctr_codigo INNER JOIN
                      dbo.Plano_Contas ON dbo.contas_receber.Pco_codigo = dbo.Plano_Contas.Pco_codigo INNER JOIN
                      dbo.contas_Receber_det ON dbo.contas_receber.Ctr_codigo = dbo.contas_Receber_det.Ctr_codigo AND 
                      dbo.Contas_receber_pag.ctr_codigo_det = dbo.contas_Receber_det.ctr_codigo_det
WHERE
  (dbo.Contas_receber_pag.Crp_data_pagamento >=:pDatainiR AND Contas_receber_pag.Crp_data_pagamento <=:pDatafinR)  and 
(Plano_Contas.Pco_Aporte is null or  Plano_Contas.Pco_Aporte <>  'S')
AND contas_Receber_det.Ctr_situacao='S'
GROUP BY
  dbo.Plano_Contas.Pco_FixaVariavel,
  dbo.Plano_Contas.Pco_descricao,
  dbo.Plano_Contas.Pco_pai


UNION ALL

SELECT 
  'DESPESAS' AS tipoconta,
  dbo.Plano_Contas.Pco_FixaVariavel,
  SUM(dbo.Contas_apagar_pag.Cpp_valor_pago) AS valor,
  dbo.Plano_Contas.Pco_descricao,
  dbo.Plano_Contas.Pco_pai,
  SUM(dbo.Contas_apagar_pag.Cpp_valor_pago) AS ValorPago
FROM         dbo.contas_apagar INNER JOIN
                      dbo.Contas_apagar_pag ON dbo.contas_apagar.Ctp_codigo = dbo.Contas_apagar_pag.Ctp_codigo INNER JOIN
                      dbo.Plano_Contas ON dbo.contas_apagar.Pco_codigo = dbo.Plano_Contas.Pco_codigo INNER JOIN
                      dbo.contas_apagar_det ON dbo.contas_apagar.Ctp_codigo = dbo.contas_apagar_det.Ctp_codigo AND 
                      dbo.Contas_apagar_pag.ctp_codigo_det = dbo.contas_apagar_det.ctp_codigo_det
WHERE
  (Plano_Contas.Pco_FixaVariavel IS NOT NULL) AND 
  (dbo.Contas_apagar_pag.Cpp_data_pagamento >=:pDatainiP AND dbo.Contas_apagar_pag.Cpp_data_pagamento <=:pDatafinP)
  and  contas_apagar_det.Ctp_situacao='S'
GROUP BY
  dbo.Plano_Contas.Pco_FixaVariavel,
  dbo.Plano_Contas.Pco_descricao,
  dbo.Plano_Contas.Pco_pai


