-- [QrySoma : TADOQuery]
select SUM(NTF_vlnota) as Valor_Total, COUNT(ntf_numero) as Qtde
from Notafiscal INNER JOIN clientes ON notafiscal.cli_codigo = clientes.cli_codigo
where NTF_DtEmissao>= :Dataini and NTF_DtEmissao<= :Datafim

-- [QryNotas : TADOQuery]
SELECT     TOP (100) PERCENT CASE WHEN NTF_Modelo = '55' THEN 'NFe' ELSE 'NFCe' END AS modelo, dbo.NotaFiscal.NTF_Numero, dbo.NotaFiscal.NTF_DtEmissao, dbo.NotaFiscal.NTF_Situacao, dbo.NotaFiscal.Cli_Codigo, dbo.NotaFiscal.NTF_Nome, dbo.Clientes.Cli_Nome, 
                  dbo.NotaFiscal.NTF_CNPJCPF, dbo.NotaFiscal.NTF_ProtocoloNFE, dbo.NotaFiscal.NTF_VlNota, dbo.NotaFiscal.NTF_ChaveNFE, dbo.NotaFiscal.CFOP_codigo + ' - ' + dbo.NotaFiscal.NTF_NatOperacao AS NatOperacao, dbo.NotaFiscal.CFOP_codigo, 
                  dbo.NotaFiscalImportaDoc.NTFImp_DocCodigo
                    , dbo.NotaFiscalImportaDoc.NTFImp_DocTipo, dbo.NotaFiscalImportaDoc.ParSV_serie
FROM        dbo.NotaFiscal INNER JOIN
                  dbo.NotaFiscalImportaDoc ON dbo.NotaFiscal.NTF_Codigo = dbo.NotaFiscalImportaDoc.NTF_Codigo LEFT OUTER JOIN
                  dbo.Clientes ON dbo.NotaFiscal.Cli_Codigo = dbo.Clientes.Cli_Codigo



where NTF_DtEmissao>= :Dataini and NTF_DtEmissao<= :Datafim
order by NTF_numero


/* ============================================================
   FORM: RltTermoDeEentrega   RltTermoDeEentrega
   ============================================================ */

-- [QryProdutosEntregue : TADOQuery]
SELECT     dbo.controle_entrega_data.cen_codigo_pre, dbo.controle_entrega_data.Pro_codnosso, dbo.controle_entrega_data.cep_acabamento, 
                      dbo.controle_entrega_data.ced_data, dbo.controle_entrega_data.cep_tipo, dbo.controle_entrega_data.cep_operacao, dbo.controle_entrega_data.Mod_codigo, 
                      dbo.controle_entrega_data.usr_dt_hr_criacao, dbo.controle_entrega_data.usr_cod_criacao, dbo.controle_entrega_data.CodAmbiente, dbo.produtos.Pro_descricao, 
                      dbo.Controle_entrega.cen_modo, dbo.controle_entrega_data.ced_quantidade, ProdFor_CodigoProduto, ProdFor_DescricaoProduto, produtos.Pro_CodEspecial, for_nome,  controle_entrega_data.Ced_VendItem,
                          (SELECT     SUM(ced_quantidade) AS Expr2
                            FROM          dbo.controle_entrega_data AS CREDITO
                            WHERE      (Pro_codnosso = dbo.controle_entrega_data.Pro_codnosso) AND (cep_acabamento = dbo.controle_entrega_data.cep_acabamento) AND 
                                                   (cen_codigo_pre = dbo.controle_entrega_data.cen_codigo_pre) AND (ced_data = dbo.controle_entrega_data.ced_data) AND (cep_tipo = 'E' OR
                                                   cep_tipo IS NULL) AND (cep_operacao = 'E')) -
                          (SELECT     SUM(ced_quantidade) AS Expr1
                            FROM          dbo.controle_entrega_data AS DEBITO
                            WHERE      (Pro_codnosso = dbo.controle_entrega_data.Pro_codnosso) AND (cep_acabamento = dbo.controle_entrega_data.cep_acabamento) AND 
                                                   (cen_codigo_pre = dbo.controle_entrega_data.cen_codigo_pre) AND (ced_data = dbo.controle_entrega_data.ced_data) AND (cep_tipo = 'E' OR
                                                   cep_tipo IS NULL) AND (cep_operacao = 'R')) AS total, CASE Controle_entrega.cen_tipo WHEN 'P' THEN
                          (SELECT     TOP 1 .VendaAmbiente.VenAmb_Descricao
                            FROM          dbo.pedido INNER JOIN
                                                   dbo.VendaAmbiente ON dbo.pedido.ped_codigo_pre = dbo.VendaAmbiente.VenAmb_NDocPre
                            WHERE      PEDIDO.PED_STATUS = 'A' AND VendaAmbiente.VenAmb_TpDoc = 'PRO' AND VendaAmbiente.CodAmbiente = controle_entrega_data.CODAMBIENTE) 
                      ELSE
                          (SELECT     TOP 1 dbo.VendaAmbiente.VenAmb_Descricao
                            FROM          dbo.VendaAmbiente INNER JOIN
                                                   dbo.Avulso ON dbo.VendaAmbiente.VenAmb_NDocPre = dbo.Avulso.avu_codigo_pre
                            WHERE      dbo.VendaAmbiente.VenAmb_TpDoc = 'AVU' AND VendaAmbiente.CodAmbiente = controle_entrega_data.CODAMBIENTE) END AS DescAmbiente


, (SELECT     TOP (1) dbo.VendaProduto.VenPro_Obs
 FROM dbo.VendaProduto INNER JOIN
 dbo.Venda AS Venda_1 ON dbo.VendaProduto.Ven_CodigoPre = Venda_1.Ven_CodigoPre
WHERE (dbo.controle_entrega_data.Pro_codnosso = dbo.VendaProduto.Pro_codnosso) AND
(dbo.controle_entrega_data.cep_acabamento = dbo.VendaProduto.CodAcabamento) AND
 (dbo.controle_entrega_data.CodAmbiente = dbo.VendaProduto.CodAmbiente) AND (Venda_1.Ven_Situacao = 'A') AND (Venda_1.Ven_Tipo = 'P') AND
(dbo.Controle_entrega.cen_pedido_avulso = Venda_1.Ven_codigo) AND (dbo.Controle_entrega.ParSV_serie = Venda_1.ParSV_serie)) AS observacao
, produtos.Pro_unidade



FROM         dbo.controle_entrega_data INNER JOIN
                      dbo.produtos WITH (NOLOCK) ON dbo.controle_entrega_data.Pro_codnosso = dbo.produtos.Pro_codnosso INNER JOIN
					  dbo.ProdutosFornecedores ON produtos.Pro_codnosso = ProdutosFornecedores.Pro_codnosso INNER JOIN
                      dbo.Controle_entrega WITH (NOLOCK) ON dbo.controle_entrega_data.cen_codigo_pre = dbo.Controle_entrega.cen_codigo_pre
INNER JOIN fornecedor ON ProdutosFornecedores.For_codigo = fornecedor.For_codigo
WHERE
  (controle_entrega_data.cen_codigo_pre = :Pcen_codigo_pre) AND 
  (controle_entrega_data.ced_data = :Pced_Data) AND
 controle_entrega_data.cep_operacao = 'E' AND  
  (controle_entrega_data.cep_tipo = 'E'  OR  controle_entrega_data.cep_tipo is null)
order by controle_entrega_data.CodAmbiente

-- [QryTemSeq : TADOQuery]
SELECT        MAX(Ced_VendSequencia) AS sequencia
FROM            dbo.controle_entrega_data
WHERE        (cen_codigo_pre =:pcen_codigo_pre)

