-- [QryTransfProd : TADOQuery]
SELECT    dbo.Estoque_produto.EstTp_Codigo, dbo.Estoque_produto.Epr_estoque, dbo.produtos.Pro_codnosso, dbo.ProdutosFornecedores.ProdFor_CodigoProduto AS Pro_Codbase, dbo.produtos.Pro_descricao, 
                         dbo.ProdutosFornecedores.ProdFor_DescricaoProduto AS Pro_descricao_for, dbo.produtos.Pro_tp_peca, dbo.GrupoProduto.GrupoProduto_Descricao, dbo.fornecedor.For_Nome, 
                         dbo.TransferenciaEstoqueProduto.TransfEstProd_Quant, dbo.produtos.Pro_CodEspecial, dbo.Preco_Produto.Pre_Acabamento, dbo.TransferenciaEstoque.TransfEst_codigo, dbo.produtos.Pro_unidade
FROM            dbo.ProdutosFornecedores INNER JOIN
                         dbo.fornecedor ON dbo.ProdutosFornecedores.For_codigo = dbo.fornecedor.For_codigo INNER JOIN
                         dbo.Estoque_produto INNER JOIN
                         dbo.Preco_Produto ON dbo.Estoque_produto.Epr_Codnosso = dbo.Preco_Produto.Pre_Codnosso AND dbo.Estoque_produto.Epr_Acabamento = dbo.Preco_Produto.Pre_Acabamento INNER JOIN
                         dbo.produtos ON dbo.Preco_Produto.Pre_Codnosso = dbo.produtos.Pro_codnosso INNER JOIN
                         dbo.GrupoProduto ON dbo.produtos.GrupoProduto_codigo = dbo.GrupoProduto.GrupoProduto_Codigo INNER JOIN
                         dbo.TransferenciaEstoqueProduto ON dbo.Estoque_produto.Epr_Codnosso = dbo.TransferenciaEstoqueProduto.Pro_codnosso AND 
                         dbo.Estoque_produto.Epr_Acabamento = dbo.TransferenciaEstoqueProduto.CodAcabamento INNER JOIN
                         dbo.TransferenciaEstoque ON dbo.TransferenciaEstoqueProduto.TransfEst_codigo = dbo.TransferenciaEstoque.TransfEst_codigo AND dbo.Estoque_produto.EstTp_Codigo = dbo.TransferenciaEstoque.TransfEst_EstEntrada ON 
                         dbo.ProdutosFornecedores.Pro_codnosso = dbo.produtos.Pro_codnosso

WHERE (TransferenciaEstoqueProduto.TransfEst_codigo=:pTransfEst_codigo )
oRDER BY dbo.fornecedor.For_Nome

